# PASA — Photosynthetic Absorbance Spectra Analyzer, version 1.0.0


suppressPackageStartupMessages({
  library(shiny); library(bslib); library(readxl); library(dplyr); library(tidyr); library(tibble)
  library(stringr); library(ggplot2); library(gt); library(ggrepel)
  library(data.table)   # fast melt/join/resample
  library(httr)         # fetch online files
  library(googlesheets4) # read Google Sheets (public)
})
.pasa_signal_available <- function() requireNamespace("signal", quietly = TRUE)
has_signal <- .pasa_signal_available()
has_zip <- requireNamespace("zip", quietly = TRUE)
has_writexl <- requireNamespace("writexl", quietly = TRUE)
has_patchwork <- requireNamespace("patchwork", quietly = TRUE)  # Cell Growth: 2-panel plot
has_visnetwork <- requireNamespace("visNetwork", quietly = TRUE)
has_igraph <- requireNamespace("igraph", quietly = TRUE)
has_ggraph <- requireNamespace("ggraph", quietly = TRUE)
# Optional deconvolution packages are detected in the active local/locked R
# environment and are never installed by the running app. The module degrades
# gracefully without them (minpack.lm absent -> L-BFGS-B fallback without
# standard errors; signal absent -> finite-difference second-derivative seeding).
.pasa_minpack_available <- function() requireNamespace("minpack.lm", quietly = TRUE)
has_minpack <- .pasa_minpack_available()
has_decon_signal <- has_signal  # alias: 'signal' also drives Savitzky-Golay seeding
# Optional: interactive 3D waterfall overlay on the Spectra tab (client-side WebGL
# rotation, so no server re-render on drag). Absent -> the 3D toggle shows an
# install hint and the 2D plot is kept.
has_plotly <- requireNamespace("plotly", quietly = TRUE)
if (!(has_igraph && (has_visnetwork || has_ggraph)))
  message("[PASA] Neither visNetwork+igraph nor ggraph+igraph is available: Data Quality similarity will show the table only.")
if (!has_zip)
  message("[PASA] Package 'zip' not found: 'Download everything (ZIP)' will be unavailable.")
if (!has_writexl)
  message("[PASA] Package 'writexl' not found: Excel (.xlsx) export will fall back to CSV.")
if (!has_minpack)
  message("[PASA] Package 'minpack.lm' not found: Deconvolution will use the L-BFGS-B fallback (no standard errors). Install with: install.packages('minpack.lm')")
if (!has_signal)
  message("[PASA] Package 'signal' not found: Deconvolution seeding will use a finite-difference 2nd derivative. Install with: install.packages('signal')")
if (!has_plotly)
  message("[PASA] Package 'plotly' not found: the Spectra tab '3D overlay' will be unavailable. Install with: install.packages('plotly')")

.pasa_similarity_network_backend <- function(visnetwork = has_visnetwork,
                                             igraph = has_igraph,
                                             ggraph = has_ggraph) {
  if (isTRUE(visnetwork) && isTRUE(igraph)) "visNetwork"
  else if (isTRUE(igraph) && isTRUE(ggraph)) "ggraph"
  else "table"
}

# ============================================================================
# COLOR ENGINE MODULE  (pure base R: grid + grDevices)
# Computes an illustrative sRGB mapping of the selected numerical curve under
# stated CIE/D65 assumptions. The transform is physical transmittance only for
# verified decadic absorbance on the applicable optical basis.
# ============================================================================

# --- Rights-scoped CIE data and public W3C sRGB implementation constants ---
# The adapted CIE tables are deliberately stored outside this author-created R
# source so their CC BY-SA 4.0 scope remains explicit. See data/CIE_DATA_NOTICE.md
# for attribution, DOIs, source checksums, sampling/rounding details, changes,
# and the no-endorsement statement. No standards text is reproduced here.
.pasa_source_root <- local({
  root <- NULL
  function() {
    if (!is.null(root)) return(root)
    candidates <- character(0)
    env_root <- Sys.getenv("PASA_APP_DIR", unset = "")
    if (nzchar(env_root)) candidates <- c(candidates, env_root)
    for (i in rev(seq_len(sys.nframe()))) {
      fr <- sys.frame(i)
      for (nm in c("ofile", "file")) {
        value <- tryCatch(get(nm, envir = fr, inherits = FALSE),
                          error = function(e) NULL)
        if (is.character(value) && length(value) == 1L && nzchar(value) &&
            file.exists(value)) {
          candidates <- c(candidates, dirname(value))
        }
      }
    }
    args <- commandArgs(trailingOnly = FALSE)
    script_arg <- grep("^--file=", args, value = TRUE)
    if (length(script_arg))
      candidates <- c(candidates, dirname(sub("^--file=", "", script_arg[1])))
    candidates <- unique(c(candidates, getwd()))
    for (candidate in candidates) {
      candidate <- tryCatch(normalizePath(candidate, winslash = "/", mustWork = FALSE),
                            error = function(e) NA_character_)
      if (length(candidate) == 1L && !is.na(candidate) &&
          file.exists(file.path(candidate, "PASA.R"))) {
        root <<- candidate
        return(root)
      }
    }
    stop("Cannot locate PASA.R and its required local data directory. Set PASA_APP_DIR to the source_snapshot directory.",
         call. = FALSE)
  }
})

.pasa_load_color_table <- function(filename, expected_columns) {
  path <- file.path(.pasa_source_root(), "data", filename)
  if (!file.exists(path))
    stop(sprintf("Required PASA color data file is missing: %s", path), call. = FALSE)
  tab <- utils::read.csv(path, check.names = FALSE, stringsAsFactors = FALSE)
  if (!identical(names(tab), expected_columns))
    stop(sprintf("Unexpected columns in %s; expected %s.", filename,
                 paste(expected_columns, collapse = ", ")), call. = FALSE)
  tab[] <- lapply(tab, function(x) suppressWarnings(as.numeric(x)))
  expected_nm <- seq(380, 780, by = 10)
  if (nrow(tab) != length(expected_nm) ||
      !identical(as.numeric(tab[[1]]), as.numeric(expected_nm)) ||
      any(!is.finite(as.matrix(tab))) || any(as.matrix(tab[-1]) < 0))
    stop(sprintf("Invalid or altered PASA color data in %s.", filename), call. = FALSE)
  tab
}

.cie <- .pasa_load_color_table(
  "CIE_1931_2deg_380_780_10nm.csv",
  c("wavelength_nm", "x_bar", "y_bar", "z_bar")
)
names(.cie) <- c("nm", "x", "y", "z")
.d65 <- .pasa_load_color_table(
  "CIE_D65_380_780_10nm.csv",
  c("wavelength_nm", "relative_spd")
)
names(.d65) <- c("nm", "p")

# Public implementation reference: W3C CSS Color 4, sample color-conversion
# code, https://www.w3.org/TR/css-color-4/#color-conversion-code (accessed
# 2026-09-01). These exact rational coefficients convert D65-referenced XYZ to
# linear-light sRGB; the companding constants at the call site use the same W3C
# implementation. This citation is an implementation reference, not copied
# standards text and not an endorsement by W3C.
.W3C_XYZ_D65_TO_LINEAR_SRGB <- rbind(
  c(12831 / 3959,       -329 / 214,      -1974 / 3959),
  c(-851781 / 878810, 1648619 / 878810, 36519 / 878810),
  c(705 / 12673,       -2585 / 12673,     705 / 667)
)

# --- illuminant SPD builder: returns power on the .cie$nm grid ---
illuminant_spd <- function(illum=c("D65","fluor","shade","green_led")){
  illum <- match.arg(illum)
  grid <- .cie$nm
  base <- stats::approx(.d65$nm, .d65$p, xout=grid, rule=2)$y
  if(illum=="D65")   return(base)
  if(illum=="shade") # indirect daylight ~ cooler, slightly bluer: boost short/blue, attenuate long/red
    return(base * (1 + 0.0009*(560-grid)))
  if(illum=="fluor"){ # cool-white fluorescent: continuous phosphor + Hg lines
    cont <- base*0.55
    line <- function(c,w,h) h*exp(-((grid-c)^2)/(2*w^2))
    spikes <- line(405,3,18)+line(436,3,55)+line(546,3,75)+line(578,4,35)+
      line(488,8,12)+line(611,6,25)
    return(cont + spikes)
  }
  if(illum=="green_led") # narrow green LED ~525 nm, ~32 nm FWHM
    return(100*exp(-((grid-525)^2)/(2*(32/2.355)^2)) + 0.5)
}

# --- core: absorbance spectrum -> illustrative D65/CIE sRGB mapping ---
# nm, A: numeric vectors (any range; will be interpolated to 380-780)
# target_OD_Qy: if not NA, rescale a selected numerical reference feature to this
# rendering target. If A has been normalized upstream, the units are arbitrary.
#
# "No Qy band" guard (added for carotenoid-type samples, e.g. zeaxanthin):
# Reference rescaling can use the peak inside the configured Qy window
# (default 660-690 nm). For some curves that window contains only a small
# numerical feature relative to the overall maximum. Rescaling that small value
# to the target then multiplies the larger features
# by a huge factor, driving the numerical transform (10^-value) toward zero,
# so the color stops responding to the control. When the Qy-window peak is a
# negligible fraction (< QY_FALLBACK_FRAC) of the global peak we look for an
# intermediate reference before the global maximum: if the carotenoid
# blue reference window meets its fractional gate (peak >= CAR_FALLBACK_FRAC of the global
# peak) we scale on that window peak, which is a more localized numerical reference than a global maximum
# at an analysis-range edge. Only when neither Qy nor carotenoid qualifies do we scale
# by the GLOBAL peak. The 2% Qy and 10% blue-region thresholds are operational
# rendering heuristics, not validated biological or detection cutoffs.
#
# The function attaches attr(result, "qy_fallback") = TRUE/FALSE (and a small
# diagnostic list in attr "qy_diag") so the UI can show a stable warning ONLY
# for samples that actually fell back. Callers that ignore attributes and use
# the hex string directly are unaffected.
QY_FALLBACK_FRAC <- 0.02   # Qy-window peak must be >= 2% of global peak
# Intermediate blue-window reference. When a sample does not meet the Qy
# reference-window gate, do not jump straight to the global maximum; if the configured
# blue window meets its fractional gate we scale
# on THAT instead, and fall back to global only when neither Qy nor carotenoid
# qualifies. The 10% bar (vs. the 2% Qy bar) is an operational rendering heuristic.
CAR_FALLBACK_FRAC <- 0.10  # carotenoid-window peak must be >= 10% of global peak
SPECTRUM_BLANK_SNR    <- 8       # peak/noise below this => weak, noisy (caveat)
SPECTRUM_BLANK_OD_EPS <- 5e-4    # absolute backstop for a flat/zero spectrum
SPECTRUM_LOW_PEAK_OD  <- 0.15    # pre-rescale peak below this AU => weak-signal caveat even when noise is low
spectrum_to_hex <- function(nm, A, target_OD_Qy=NA, qy_range=c(660,690),
                            car_range=NULL, car_frac_min=CAR_FALLBACK_FRAC,
                            illum="D65", absorbance_units=TRUE){
  if (length(target_OD_Qy) != 1L || (!is.na(target_OD_Qy) && (!is.finite(target_OD_Qy) || target_OD_Qy <= 0)))
    stop("Enter a finite positive color-rendering target, or select unrescaled values.")
  A <- as.numeric(A); nm <- as.numeric(nm)
  ok <- is.finite(nm) & is.finite(A); nm <- nm[ok]; A <- A[ok]
  requested_target <- if (length(target_OD_Qy) == 1L && is.finite(target_OD_Qy))
                        as.numeric(target_OD_Qy) else NA_real_
  coverage_min_nm <- if (length(nm)) min(nm) else NA_real_
  coverage_max_nm <- if (length(nm)) max(nm) else NA_real_
  # The color integral is evaluated on 380--780 nm. When the available curve
  # starts later or ends earlier, approx(rule=2) below explicitly holds the
  # nearest endpoint value flat. Archive the two affected wavelength spans so
  # every consumer can disclose that numerical assumption.
  extrapolated_low_nm  <- if (is.finite(coverage_min_nm)) max(0, coverage_min_nm - 380) else NA_real_
  extrapolated_high_nm <- if (is.finite(coverage_max_nm)) max(0, 780 - coverage_max_nm) else NA_real_
  effective_target <- NA_real_
  qy_fallback  <- FALSE
  car_fallback <- FALSE
  qy_diag <- list(qy_peak=NA_real_, global_peak=NA_real_, frac=NA_real_,
                  qy_nm=NA_real_, global_nm=NA_real_,
                  car_peak=NA_real_, car_nm=NA_real_, car_frac=NA_real_)
  if(length(nm) < 2){
    out <- "#dddddd"
    attr(out, "qy_fallback")  <- FALSE
    attr(out, "car_fallback") <- FALSE
    attr(out, "near_blank")   <- FALSE
    attr(out, "low_signal")   <- FALSE
    attr(out, "color_conf")   <- NA_real_
    attr(out, "snr")          <- NA_real_
    attr(out, "peak_abs")     <- if (length(A)) suppressWarnings(max(A, na.rm = TRUE)) else NA_real_
    attr(out, "requested_target") <- requested_target
    attr(out, "effective_target") <- NA_real_
    attr(out, "coverage_min_nm") <- coverage_min_nm
    attr(out, "coverage_max_nm") <- coverage_max_nm
    attr(out, "extrapolated_low_nm") <- 0
    attr(out, "extrapolated_high_nm") <- 0
    attr(out, "qy_diag") <- qy_diag
    return(out)
  }
  # Numerical-floor guard: a curve whose maximum does not exceed the operational
  # epsilon is rendered neutral gray rather than being amplified. This is not a
  # blank classification, pigment-presence test, or instrument detection limit.
  # A separate low-signal advisory uses a DER-SNR-style numerical noise proxy.
  # SPECTRUM_BLANK_SNR, SPECTRUM_BLANK_OD_EPS, and SPECTRUM_LOW_PEAK_OD are shared
  # top-level constants. Even when noise is low, the target-OD
  # rescale amplifies a faint signal heavily (a nominally pigment-free prep may show only a faint co-purified-
  # contaminant band), so a faint peak is flagged independently of SNR.
  .der_snr_sigma <- function(y){
    y <- y[is.finite(y)]; n <- length(y)
    if (n < 5) return(NA_real_)
    i <- 3:(n - 2)
    s <- suppressWarnings(stats::mad((2 * y[i] - y[i - 2] - y[i + 2]) / sqrt(6)))
    if (is.finite(s)) s else NA_real_
  }
  peak_abs <- suppressWarnings(max(A, na.rm = TRUE))
  noise_sd <- .der_snr_sigma(A)
  # Curves above the numerical floor remain renderable. A low-signal flag discloses
  # when the illustrative target rescale amplifies a faint or noise-sensitive feature.
  snr <- if (is.finite(noise_sd) && noise_sd > 0 && is.finite(peak_abs)) peak_abs / noise_sd else NA_real_
  is_flat_blank <- !is.finite(peak_abs) || peak_abs <= if (isTRUE(absorbance_units)) SPECTRUM_BLANK_OD_EPS else 0
  is_low_signal <- !is_flat_blank &&
                   ((is.finite(snr) && snr < SPECTRUM_BLANK_SNR) ||
                    (isTRUE(absorbance_units) && is.finite(peak_abs) && peak_abs < SPECTRUM_LOW_PEAK_OD))
  color_conf <- 1
  if (isTRUE(is_flat_blank)) {
    out <- "#e6e6e6"
    attr(out, "qy_fallback")  <- FALSE
    attr(out, "car_fallback") <- FALSE
    attr(out, "near_blank")   <- TRUE
    attr(out, "low_signal")   <- FALSE
    attr(out, "color_conf")   <- NA_real_
    attr(out, "snr")          <- snr
    attr(out, "peak_abs")     <- peak_abs
    attr(out, "requested_target") <- requested_target
    attr(out, "effective_target") <- NA_real_
    attr(out, "coverage_min_nm") <- coverage_min_nm
    attr(out, "coverage_max_nm") <- coverage_max_nm
    # The neutral numerical-floor swatch bypasses the 380--780 interpolation,
    # therefore no flat endpoint span was actually used for this result.
    attr(out, "extrapolated_low_nm") <- 0
    attr(out, "extrapolated_high_nm") <- 0
    attr(out, "qy_diag") <- qy_diag
    return(out)
  }
  if(!is.na(target_OD_Qy)){
    inq <- nm>=qy_range[1] & nm<=qy_range[2]
    pk_qy   <- if(any(inq)) max(A[inq], na.rm=TRUE) else NA_real_
    pk_glob <- max(A, na.rm=TRUE)
    # Record diagnostics for the UI warning.
    qy_diag$qy_peak     <- if(is.finite(pk_qy)) pk_qy else NA_real_
    qy_diag$global_peak <- if(is.finite(pk_glob)) pk_glob else NA_real_
    if(is.finite(pk_qy) && is.finite(pk_glob) && any(inq)){
      qy_diag$qy_nm <- nm[inq][ which.max(A[inq]) ]
    }
    if(is.finite(pk_glob)) qy_diag$global_nm <- nm[ which.max(A) ]
    if(is.finite(pk_qy) && is.finite(pk_glob) && pk_glob > 0){
      qy_diag$frac <- pk_qy / pk_glob
    }
    # Blue-window peak (only if a range was supplied). Used as an
    # intermediate numerical reference when the Qy-window gate is not met.
    # This choice does not establish pigment identity or physical superiority.
    pk_car <- NA_real_
    if(!is.null(car_range) && length(car_range) >= 2 && all(is.finite(car_range))){
      inc <- nm >= min(car_range) & nm <= max(car_range)
      if(any(inc)){
        pk_car <- max(A[inc], na.rm=TRUE)
        if(is.finite(pk_car)){
          qy_diag$car_peak <- pk_car
          qy_diag$car_nm   <- nm[inc][ which.max(A[inc]) ]
          if(is.finite(pk_glob) && pk_glob > 0) qy_diag$car_frac <- pk_car / pk_glob
        }
      }
    }
    # Reference-selection order: Qy -> carotenoid -> global. The Qy and carotenoid
    # branches use operational fractional-peak gates; passing a gate establishes only
    # a qualifying numerical reference feature, not pigment identity or biological
    # authenticity. The global maximum is the final fallback. qy_fallback == TRUE
    # means "global"; car_fallback == TRUE is the middle tier.
    qy_ok  <- is.finite(pk_qy)  && pk_qy  > 0 &&
              is.finite(pk_glob) && pk_glob > 0 &&
              is.finite(qy_diag$frac) && qy_diag$frac >= QY_FALLBACK_FRAC
    car_ok <- is.finite(pk_car) && pk_car > 0 &&
              is.finite(pk_glob) && pk_glob > 0 &&
              is.finite(qy_diag$car_frac) && qy_diag$car_frac >= car_frac_min
    if(qy_ok){
      pk <- pk_qy
    } else if(car_ok){
      pk <- pk_car; car_fallback <- TRUE
    } else {
      pk <- pk_glob
      if(is.finite(pk_glob) && pk_glob > 0) qy_fallback <- TRUE
    }
    # Target-OD rescaling can visually amplify a weak or endpoint-dominated feature.
    # The operational confidence adjustment below uses peak height and a numerical
    # noise proxy, then caps weak maxima near an observed edge. Such maxima are
    # ambiguous: they may reflect truncation, slope, scattering/background, or a
    # genuine edge feature. Desaturation is therefore a rendering safeguard, not a
    # pigment-presence decision or a calibrated uncertainty measure.
    color_conf <- 1
    if (isTRUE(is_low_signal)) {
      c_peak <- if (is.finite(peak_abs)) min(1, peak_abs / SPECTRUM_LOW_PEAK_OD) else 0
      c_snr  <- if (is.finite(snr))      min(1, snr / SPECTRUM_BLANK_SNR)        else 0
      # Combine only the condition(s) that actually triggered the low-signal
      # state. Including a non-triggering component in max() made every
      # clean-but-faint curve retain confidence 1 (and therefore no attenuation),
      # even though it was explicitly labeled low signal.
      .conf_parts <- c(if (isTRUE(absorbance_units) && is.finite(peak_abs) && peak_abs < SPECTRUM_LOW_PEAK_OD) c_peak,
                       if (is.finite(snr) && snr < SPECTRUM_BLANK_SNR) c_snr)
      color_conf <- if (length(.conf_parts)) max(.conf_parts) else 1
    }
    if (isTRUE(is_low_signal) && is.finite(qy_diag$global_nm) && length(nm) >= 2) {
      rngnm <- range(nm)
      if (qy_diag$global_nm <= rngnm[1] + 10 || qy_diag$global_nm >= rngnm[2] - 10)
        color_conf <- min(color_conf, 0.15)   # operational cap for an ambiguous weak edge maximum
    }
    if(is.finite(pk) && pk>0) {
      effective_target <- requested_target * color_conf
      A <- A * (effective_target / pk)
    }
  }
  nm_fine <- seq(380, 780, by = 1)
  Ai <- stats::approx(nm, A, xout = nm_fine, rule = 2)$y
  Ai[!is.finite(Ai)] <- 0; Ai[Ai < 0] <- 0
  # The imported values are already absorbance on their acquisition basis.
  # No additional optical-path multiplier is applied.
  Tr <- 10^(-Ai)
  P  <- stats::approx(.d65$nm, .d65$p, xout = nm_fine, rule = 2)$y
  if(illum != "D65"){
    # NOTE: non-D65 illuminants are illustrative only. The XYZ->sRGB matrix and
    # gamma below assume a D65 white point, and no chromatic-adaptation transform
    # (e.g. Bradford) is applied, so a neutral sample under a colored source will
    # not map to sRGB neutral. The shipped app renders under D65 (the sole call
    # site hardcodes illum="D65"); these branches exist for the documented API only.
    P_base <- illuminant_spd(illum)
    # re-interpolate the illuminant to the fine grid
    P <- stats::approx(.cie$nm, P_base, xout = nm_fine, rule = 2)$y
  }
  S  <- P * Tr
  cie_x_fine <- stats::approx(.cie$nm, .cie$x, xout = nm_fine, rule = 2)$y
  cie_y_fine <- stats::approx(.cie$nm, .cie$y, xout = nm_fine, rule = 2)$y
  cie_z_fine <- stats::approx(.cie$nm, .cie$z, xout = nm_fine, rule = 2)$y
  N  <- sum(P * cie_y_fine)
  X  <- sum(S * cie_x_fine) / N
  Y  <- sum(S * cie_y_fine) / N
  Z  <- sum(S * cie_z_fine) / N
  lin <- drop(.W3C_XYZ_D65_TO_LINEAR_SRGB %*% c(X, Y, Z))
  lin <- pmax(pmin(lin, 1), 0)
  # W3C CSS Color 4 linear-light sRGB -> encoded sRGB transfer function.
  srgb <- ifelse(lin<=0.0031308, 12.92*lin, 1.055*lin^(1/2.4)-0.055)
  srgb <- pmax(pmin(srgb,1),0)
  out <- grDevices::rgb(srgb[1],srgb[2],srgb[3])
  # Carry the fallback decision + diagnostics so the Sample Color tab can show
  # a stable warning for this specific sample (and only when it fell back).
  attr(out, "qy_fallback")  <- qy_fallback
  attr(out, "car_fallback") <- car_fallback
  attr(out, "near_blank")   <- FALSE
  attr(out, "low_signal")   <- isTRUE(is_low_signal)
  attr(out, "color_conf")   <- color_conf
  attr(out, "snr")          <- snr
  attr(out, "peak_abs")     <- peak_abs
  attr(out, "requested_target") <- requested_target
  attr(out, "effective_target") <- effective_target
  attr(out, "coverage_min_nm") <- coverage_min_nm
  attr(out, "coverage_max_nm") <- coverage_max_nm
  attr(out, "extrapolated_low_nm") <- extrapolated_low_nm
  attr(out, "extrapolated_high_nm") <- extrapolated_high_nm
  attr(out, "qy_diag") <- qy_diag
  out
}

.color_low_signal_msg <- function(pk, snr, requested_target, effective_target, color_conf, absorbance_units = TRUE) {
  low_snr    <- is.finite(snr) && snr < SPECTRUM_BLANK_SNR
  faint_peak <- isTRUE(absorbance_units) && is.finite(pk) && pk < SPECTRUM_LOW_PEAK_OD
  rescaled   <- is.finite(requested_target)        # target-OD mode; NA in unrescaled mode
  pk_txt  <- if (is.finite(pk))  sprintf(if (isTRUE(absorbance_units)) " (%.3g AU)" else " (%.3g normalized units)", pk)  else ""
  snr_txt <- if (is.finite(snr)) sprintf("%.1f", snr) else "low"
  header <- if (low_snr) "Weak, noisy signal. " else "Faint (low-absorbance) signal. "
  cond <- if (low_snr && faint_peak)
            sprintf("This sample's peak absorbance is very low%s and close to its spectral noise (peak-to-noise ≈ %s).", pk_txt, snr_txt)
          else if (low_snr)
            sprintf("This sample's signal is close to its spectral noise (peak-to-noise ≈ %s).", snr_txt)
          else
            sprintf("This sample's peak absorbance is very low%s, although its signal-to-noise is adequate (peak-to-noise ≈ %s).", pk_txt, snr_txt)
  render_clause <- if (rescaled) {
            .rq <- formatC(requested_target, digits = 4, format = "fg")
            .ef <- if (is.finite(effective_target)) formatC(effective_target, digits = 4, format = "fg") else "unavailable"
            .cf <- if (is.finite(color_conf)) formatC(color_conf, digits = 3, format = "fg") else "unavailable"
            sprintf(" The requested numerical target was %s; the low-signal safeguard used effective target %s (rendering confidence %s). This attenuation is an operational visualization safeguard, not a calibrated uncertainty estimate, so interpret the hue cautiously:", .rq, .ef, .cf)
          }
          else
            " The illustrative color uses the unrescaled final analysis curve, but the hue rests on a weak feature, so interpret it cautiously:"
  list(header = header,
       body = paste0(cond, render_clause, " this numerical warning does not establish pigment presence or absence."))
}

.color_coverage_summary <- function(coverage_min_nm, coverage_max_nm,
                                    extrapolated_low_nm, extrapolated_high_nm) {
  if (!is.finite(coverage_min_nm) || !is.finite(coverage_max_nm)) return("coverage unavailable")
  base <- sprintf("finite input coverage %.4g--%.4g nm", coverage_min_nm, coverage_max_nm)
  lo <- if (is.finite(extrapolated_low_nm)) extrapolated_low_nm else 0
  hi <- if (is.finite(extrapolated_high_nm)) extrapolated_high_nm else 0
  if (lo > 0 || hi > 0)
    paste0(base, sprintf("; flat endpoint extrapolation over %.4g nm below coverage and %.4g nm above coverage", lo, hi))
  else paste0(base, "; no endpoint extrapolation within 380--780 nm")
}

.darken <- function(hex, amt){
  c <- grDevices::col2rgb(hex)/255; c <- c*(1-amt)
  grDevices::rgb(c[1],c[2],c[3])
}

# Data-driven scene renderers are loaded with the bundled interface helpers below.

# Shared, durable rendering metadata for the comparison table and ZIP. Each
# row reports the numerical target that was requested, the target effectively
# used after any low-signal attenuation, input coverage, and any 380--780 nm
# span filled by flat endpoint holding.
.color_rendering_metadata_df <- function(items) {
  if (is.null(items) || !length(items)) return(data.frame())
  .chr <- function(x, default = NA_character_) {
    if (is.null(x) || !length(x) || is.na(x[[1]])) default else as.character(x[[1]])
  }
  .num <- function(x) {
    z <- suppressWarnings(as.numeric(if (is.null(x) || !length(x)) NA else x[[1]]))
    if (length(z) && is.finite(z)) z else NA_real_
  }
  .lg <- function(x) isTRUE(if (is.null(x) || !length(x)) FALSE else x[[1]])
  rows <- lapply(items, function(it) {
    qy_fb <- .lg(it$qy_fallback %||% it$fallback)
    car_fb <- .lg(it$car_fallback)
    near <- .lg(it$near_blank)
    req <- .num(it$requested_target); eff <- .num(it$effective_target)
    lo <- .num(it$extrapolated_low_nm); hi <- .num(it$extrapolated_high_nm)
    ref <- if (near) "numerical_floor_neutral_gray"
           else if (!is.finite(req)) "unrescaled_final_analysis_curve"
           else if (qy_fb) "global_maximum"
           else if (car_fb) "blue_reference_window"
           else "Qy_reference_window"
    data.frame(
      sample = .chr(it$sample), status = .chr(it$status, "available"),
      hex = .chr(it$hex), reference_basis = ref,
      requested_target = req, effective_target = eff,
      color_conf = .num(it$color_conf), low_signal = .lg(it$low_signal),
      near_blank = near, coverage_min_nm = .num(it$coverage_min_nm),
      coverage_max_nm = .num(it$coverage_max_nm),
      extrapolated_low_nm = lo, extrapolated_high_nm = hi,
      flat_extrapolated_visible_span_nm = if (is.finite(lo) && is.finite(hi)) lo + hi else NA_real_,
      normalized = .lg(it$normalized),
      normalization_method = .chr(it$normalization_method, "none"),
      effective_analysis_od_object_hash = .chr(it$object_hash),
      stringsAsFactors = FALSE)
  })
  do.call(rbind, rows)
}

