    )),
    HTML('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 26 22" width="26" height="22" style="vertical-align:middle;margin-right:6px;" aria-hidden="true"><line class="logo-axis" x1="0" y1="0" x2="0" y2="20"/><line class="logo-axis" x1="0" y1="20" x2="26" y2="20"/><polyline points="0,18 3,17 5,16 7,14 9,10 11,6 12,4 13,6 14,9 15,12 16,10 17,7 18,5 19,7 20,12 21,16 23,17 26,18" fill="none" stroke="#007bc2" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round"/></svg>'),
    tags$span(class = "pasa-logo", title = "PASA — Photosynthetic Absorbance Spectra Analyzer",
      tags$span(class = "pasa-ini", "P"), tags$span(class = "pasa-rest", "hotosynthetic "),
