# ---------- Built-in synthetic demo data (illustrative only) ----------
.pasa_with_local_seed <- function(seed, code) {
  had_seed <- exists(".Random.seed", envir = .GlobalEnv, inherits = FALSE)
  if (had_seed) old_seed <- get(".Random.seed", envir = .GlobalEnv, inherits = FALSE)
  on.exit({
    if (had_seed) assign(".Random.seed", old_seed, envir = .GlobalEnv)
    else if (exists(".Random.seed", envir = .GlobalEnv, inherits = FALSE))
      rm(".Random.seed", envir = .GlobalEnv)
  }, add = TRUE)
  set.seed(seed)
  force(code)
}
builtin_demo_data <- function() {
  .pasa_with_local_seed(7, {
    nm <- seq(350, 750, by = 0.5)
    gauss <- function(x, mu, sigma, h) h * exp(-((x - mu)^2) / (2 * sigma^2))
    scatter <- function(h) {
      s <- (750 / nm)^4
      h * (s - min(s)) / (max(s) - min(s))
    }
    curve <- function(scale = 1, qy = 0.92, pbs = 0.30, car = 0.34, bx = 0.78,
                      car_sh = 0.22, scat = 0.12, noise = 0.0035, qy_mu = 678) {
      v <- scatter(scat) +
           gauss(nm, 437, 16, bx) +
           gauss(nm, 415, 12, 0.30 * bx) +
           gauss(nm, 463, 14, car) +
           gauss(nm, 488, 16, car_sh) +
           gauss(nm, 625, 20, pbs) +
           gauss(nm, qy_mu, 11, qy) +
           gauss(nm, 350, 40, 0.05) +
           stats::rnorm(length(nm), 0, noise)
      pmax(0, scale * v)
    }
    tibble::tibble(
      nm = nm,
      Ctrl       = curve(scale = 1.00, qy = 0.95, pbs = 0.30, bx = 0.80, qy_mu = 678),
      `Sample A` = curve(scale = 0.92, qy = 0.88, pbs = 0.26, bx = 0.74, qy_mu = 677),
      `Sample B` = curve(scale = 0.85, qy = 0.70, pbs = 0.48, bx = 0.70, qy_mu = 679, car = 0.30)
    )
  })
}

# ---------- PDF table helper (base R: grid + grDevices, no extra deps) ----------
# Renders a character matrix (or data frame) as a grid-based table onto a PDF device.
# Each page fits max_rows rows. landscape: pass width/height in the pdf() call externally.
.pasa_pdf_number <- function(v, digits = 6L) {
  if (is.na(v)) return(NA_character_)
  if (!is.finite(v)) return(format(v))
  if (v == 0) return("0")
  trimws(formatC(v, format = "g", digits = digits, decimal.mark = "."))
}

.pasa_open_pdf <- function(file, width = 11, height = 8.5) {
  if (!isTRUE(capabilities("cairo")))
    stop("PDF export requires R with Cairo graphics support. Use CSV, Excel or PNG export, or install an R build with Cairo support.", call. = FALSE)
  tryCatch(grDevices::cairo_pdf(filename = file, width = width, height = height,
                                family = "sans"),
           error = function(e) stop("Could not open the Unicode PDF device: ",
                                     conditionMessage(e), call. = FALSE))
  invisible(TRUE)
}

grid_table_pdf <- function(df, file, title = "", subtitle = "",
                           max_rows = 40, width = 11, height = 8.5, max_cols = 12) {
  df <- as.data.frame(df, stringsAsFactors = FALSE, check.names = FALSE)
  .pasa_open_pdf(file, width = width, height = height)
  on.exit(grDevices::dev.off(), add = TRUE)
  grid::grid.newpage()
  max_rows <- max(1L, as.integer(max_rows)); max_cols <- max(2L, as.integer(max_cols))
  if (!ncol(df)) df <- data.frame(Note = "No columns available")
  groups <- if (ncol(df) <= max_cols) list(seq_len(ncol(df))) else
    lapply(split(seq.int(2L, ncol(df)), ceiling(seq_len(ncol(df)-1L)/(max_cols-1L))), function(z) c(1L,z))
  page <- 0L; font <- 8
  wrap <- function(x, n) {
    if (is.na(x)) return("")
    # Break very long identifiers as well as prose, without a fixed 20-character cap.
    words <- strsplit(as.character(x), "[[:space:]]+")[[1L]]
    words <- unlist(lapply(words, function(w) {
      if (!nzchar(w)) return("")
      starts <- seq.int(1L,nchar(w),by=n)
      substring(w,starts,pmin(starts+n-1L,nchar(w)))
    }),use.names=FALSE)
    paste(strwrap(paste(words,collapse=" "),width=n),collapse="\n")
  }
  for (cols in groups) {
    vals <- lapply(df[cols],function(x) if(is.numeric(x))vapply(x,.pasa_pdf_number,character(1)) else as.character(x))
    m <- rbind(names(df)[cols],as.matrix(as.data.frame(vals,check.names=FALSE)))
    w <- (width-.7)/length(cols)
    grid::pushViewport(grid::viewport(gp=grid::gpar(fontsize=font)))
    char_w <- grid::convertWidth(grid::stringWidth("M"),"inches",valueOnly=TRUE)
    grid::popViewport()
    nw <- max(4L,floor((w-.14)/char_w))
    cache <- unique(as.vector(m)); wrapped <- vapply(cache,wrap,character(1),n=nw)
    m[] <- wrapped[match(as.vector(m),cache)]
    lines <- matrix(vapply(strsplit(as.vector(m),"\n",fixed=TRUE),length,integer(1)),nrow=nrow(m))
    heights <- pmax(.21,apply(lines,1L,max)*font*1.18/72+.08)
    remaining <- seq_len(nrow(df))+1L
    repeat {
      page <- page+1L; if(page>1L)grid::grid.newpage()
      grid::grid.text(paste0(title,if(page>1L)" (continued)" else ""),x=.04,y=.97,just=c("left","top"),gp=grid::gpar(fontsize=13,fontface="bold"))
      if(nzchar(subtitle)) grid::grid.text(paste(strwrap(subtitle,145),collapse="\n"),x=.04,y=.92,just=c("left","top"),gp=grid::gpar(fontsize=7.5))
      rows <- 1L; available <- height*.76
      while(length(remaining)&&length(rows)<=max_rows&&sum(heights[c(rows,remaining[1L])])<=available){rows<-c(rows,remaining[1L]);remaining<-remaining[-1L]}
      if(length(rows)==1L&&length(remaining)){rows<-c(rows,remaining[1L]);remaining<-remaining[-1L]}
      scale <- min(1,available/sum(heights[rows])); top <- .84
      for (r in rows) {
        h <- heights[r]*scale/height
        x <- .04+(seq_along(cols)-.5)*.92/length(cols)
        grid::grid.rect(x=x,y=top-h/2,width=.92/length(cols),height=h,gp=grid::gpar(fill=if(r==1L)"#e8eef4" else "white",col="#c8cdd2"))
        grid::grid.text(m[r,],x=x,y=top-h/2,gp=grid::gpar(fontsize=font*scale,lineheight=1.18,fontface=if(r==1L)"bold" else "plain"))
        top <- top-h
      }
      grid::grid.text(paste("Page",page),x=.96,y=.025,just="right",gp=grid::gpar(fontsize=7))
      if(!length(remaining))break
    }
  }
  invisible(TRUE)
}

# Preserve endpoints and local extrema when simplifying only the on-screen plot.
# Quantitative tables and exported plots continue to use all processed points.
.pasa_display_curves <- function(df, max_total = 120000L, per_trace = 2000L) {
  if (!is.data.frame(df) || nrow(df) <= max_total) return(df)
  groups <- split(seq_len(nrow(df)),interaction(df$sample,df$.plot_run,drop=TRUE))
  cap <- max(4L,min(per_trace,floor(max_total/max(1L,length(groups)))))
  keep <- unlist(lapply(groups,function(ii) {
    if(length(ii)<=cap)return(ii)
    bins <- split(ii,ceiling(seq_along(ii)/(length(ii)/max(1L,floor((cap-2L)/2L)))))
    unique(c(ii[1L],unlist(lapply(bins,function(j) {
      good <- j[is.finite(df$val_smooth[j])]
      if(!length(good))return(j[1L])
      good[c(which.min(df$val_smooth[good]),which.max(df$val_smooth[good]))]
    }),use.names=FALSE),tail(ii,1L)))
  }),use.names=FALSE)
  ans <- df[sort(unique(keep)),,drop=FALSE]
  attr(ans,"pasa_display_reduced") <- nrow(ans)<nrow(df)
  ans
}

.decon_overlay_ggplot <- function(fit, show_scatter = FALSE, pres = NULL, headline = "") {
  if (is.null(pres)) pres <- .decon_presentation(fit)
  if (!length(headline) || is.na(headline[1])) headline <- ""
  .sub_lines <- c(pres$overlay_subtitle, as.character(headline)[1])
  .sub_lines <- .sub_lines[nzchar(.sub_lines)]
  .sub <- if (length(.sub_lines)) paste(.sub_lines, collapse = "\n") else NULL
  b  <- fit$best
  # display_role "none": there is no fit to draw. Render the typed disclosure as the plot itself rather than erroring
  # out with a NULL subscript -- the "no selected K + no display fit" state must still RENDER on every surface.
  if (is.null(b) || is.null(b$nm) || !length(b$nm)) {
    return(ggplot2::ggplot() +
             ggplot2::annotate("text", x = 0, y = 0, label = pres$display_note,
                               size = 3.6, colour = "#8a1c1c", fontface = "bold") +
             ggplot2::labs(title = pres$overlay_title, subtitle = .sub) +
             ggplot2::theme_void(base_size = 12) +
             ggplot2::theme(plot.title = ggplot2::element_text(face = "bold", size = 11),
                            plot.subtitle = ggplot2::element_text(colour = "#8a1c1c", face = "bold", size = 9)))
  }
  nm <- b$nm
  df_obs <- data.frame(nm = nm, val = b$observed)
  df_fit <- data.frame(nm = nm, val = b$fitted)
  K <- nrow(b$components)
  comp_df <- do.call(rbind, lapply(seq_len(K), function(k) {
    p <- b$params[((k - 1L) * 4L + 1L):((k - 1L) * 4L + 4L)]
    data.frame(nm = nm,
               val = pvoigt_one(nm, p[1], p[2], p[3], p[4]),
               comp = paste0("Comp ", k, sprintf(" (\u03bc=%.1f nm)", p[2])))
  }))
  ttl <- pres$overlay_title
  # Optional overlay of the removed empirical baseline (on the plotted axes).
  scat_df <- NULL
  if (isTRUE(show_scatter) && !is.null(fit$scatter) &&
      !is.null(fit$scatter$curve_disp) &&
      length(fit$scatter$curve_disp) == length(nm)) {
    scat_df <- data.frame(nm = nm, val = as.numeric(fit$scatter$curve_disp))
    ttl <- paste0(ttl, "; removed empirical baseline (brown dashed)")
  }
  p <- ggplot2::ggplot() +
    ggplot2::geom_line(data = comp_df,
                       ggplot2::aes(nm, val, color = comp),
                       linewidth = 0.6, linetype = "22") +
    ggplot2::geom_point(data = df_obs, ggplot2::aes(nm, val),
                        color = "gray45", size = 0.5, alpha = 0.5) +
    ggplot2::geom_line(data = df_fit, ggplot2::aes(nm, val),
                       color = "#007bc2", linewidth = 1.0)
  if (!is.null(scat_df))
    p <- p + ggplot2::geom_line(data = scat_df, ggplot2::aes(nm, val),
                                color = "#8a4b00", linewidth = 0.8, linetype = "longdash")
  p <- p +
    ggplot2::labs(x = "Wavelength (nm)", y = "Processed value",
                  title = ttl, subtitle = .sub) +
    ggplot2::theme_minimal(base_size = 12) +
    ggplot2::theme(legend.position = "bottom",
                   legend.title = ggplot2::element_blank(),
                   plot.title = ggplot2::element_text(face = "bold", size = 11))
  # The not-selected disclosure is typographically distinct from the (optional) status headline beneath it.
  if (nzchar(pres$overlay_subtitle))
    p <- p + ggplot2::theme(plot.subtitle = ggplot2::element_text(colour = "#8a1c1c", face = "bold", size = 9))
  p
}

.decon_resid_ggplot <- function(fit) {
  b <- fit$best
  g <- b$gof
  df <- data.frame(nm = b$nm, resid = b$residual)
  ggplot2::ggplot(df, ggplot2::aes(nm, resid)) +
    ggplot2::geom_hline(yintercept = 0, color = "gray60", linewidth = 0.4) +
    ggplot2::geom_line(color = "#b35a00", linewidth = 0.5) +
    ggplot2::labs(x = "Wavelength (nm)", y = "Residual (obs - fit)",
                  title = sprintf("Residuals  |  RMSE = %.4g, R\u00b2 = %.4f",
                                  g$rmse, g$r2)) +
    ggplot2::theme_minimal(base_size = 12) +
    ggplot2::theme(plot.title = ggplot2::element_text(face = "bold", size = 11))
}

.decon_ic_min_idx <- function(cmp, col) {           # row index of the min, or NA_integer_ (never integer(0))
  if (is.null(cmp) || !is.data.frame(cmp) || !col %in% names(cmp)) return(NA_integer_)
  v <- suppressWarnings(as.numeric(cmp[[col]]))
  if (!length(v) || all(!is.finite(v))) return(NA_integer_)
  v[!is.finite(v)] <- NA_real_
  as.integer(which.min(v))                          # which.min ignores NA; finite-restricted above
}
.decon_ic_argmin_K <- function(cmp, col) {          # the K minimizing a column, or NA_integer_
  i <- .decon_ic_min_idx(cmp, col)
  if (is.na(i) || is.null(cmp$K)) NA_integer_ else as.integer(cmp$K[i])
}
# Criterion-specific guard-adjusted selection. `comparison$admissible` contains
# the chosen criterion's finiteness decision, so cross-criterion aic/bic/aicc
# comparisons must rebuild finiteness from the column being compared while using
# the shared optimizer and operational-resolution predicates.
.decon_ic_admissible_min_idx <- function(cmp, col) {
  if (is.null(cmp) || !is.data.frame(cmp) || !col %in% names(cmp)) return(NA_integer_)
  v <- suppressWarnings(as.numeric(cmp[[col]])); ok <- is.finite(v)
  typed <- FALSE
  if ("optimizer_accepted" %in% names(cmp)) {
    z <- as.logical(cmp$optimizer_accepted); ok <- ok & !is.na(z) & z; typed <- TRUE
  }
  if ("split" %in% names(cmp)) {
    z <- as.logical(cmp$split); ok <- ok & !is.na(z) & !z; typed <- TRUE
  }
  if (!typed && "admissible" %in% names(cmp)) {
    z <- as.logical(cmp$admissible); ok <- ok & !is.na(z) & z
  }
  idx <- which(ok)
  if (!length(idx)) NA_integer_ else as.integer(idx[which.min(v[idx])])
}
.decon_ic_admissible_K <- function(cmp, col) {
  i <- .decon_ic_admissible_min_idx(cmp, col)
  if (is.na(i) || is.null(cmp$K)) NA_integer_ else as.integer(cmp$K[i])
}
.decon_fmt_K <- function(k) if (length(k) == 1L && is.finite(k)) sprintf("%d", as.integer(k)) else "n/a"
.decon_ic_selection_summary <- function(cmp, cols = c("aic", "bic", "aicc")) {
  if (is.null(cmp) || !is.data.frame(cmp) || !nrow(cmp)) return("")
  cols <- cols[cols %in% names(cmp)]
  if (!length(cols)) return("")
  paste(vapply(cols, function(col) sprintf("%s raw -> K = %s; admissible -> K = %s",
    .decon_ic_display_name(col), .decon_fmt_K(.decon_ic_argmin_K(cmp, col)),
    .decon_fmt_K(.decon_ic_admissible_K(cmp, col))), character(1)), collapse = " | ")
}

# Build the K-selection comparison data.frame with dual score-family markers.
.decon_comparison_df <- function(fit, include_legacy_fields = FALSE) {
  cmp <- fit$comparison
  has_aicc <- "aicc" %in% names(cmp)
  # NA-safe argmins: .decon_ic_min_idx returns NA_integer_ (never integer(0)) when a
  # criterion is undefined, so `mark_at` yields a length-1 FALSE instead of throwing
  # "argument is of length zero" on `if (i == integer(0))`.
  ai <- .decon_ic_min_idx(cmp, "aic"); bi <- .decon_ic_min_idx(cmp, "bic")
  ci <- if (has_aicc) .decon_ic_min_idx(cmp, "aicc") else NA_integer_
  mark_at <- function(i, w) length(w) == 1L && !is.na(w) && i == w
  sel_k <- suppressWarnings(as.integer(fit$best_K))
  raw_min <- vapply(seq_len(nrow(cmp)), function(i) {
    marks <- c(if (mark_at(i, ai)) "AIC-like", if (mark_at(i, bi)) "BIC-like",
               if (has_aicc && mark_at(i, ci)) "AICc-like")
    if (length(marks)) paste0("<- ", paste(marks, collapse = "+")) else ""
  }, character(1))
  is_sel <- vapply(seq_len(nrow(cmp)), function(i)
    length(sel_k) == 1L && !is.na(sel_k) && length(cmp$K[i]) == 1L && as.integer(cmp$K[i]) == sel_k, logical(1))
  adm_col <- if ("admissible" %in% names(cmp)) ifelse(as.logical(cmp$admissible), "yes", "no") else rep(NA_character_, nrow(cmp))
  excl_col <- if ("exclusion_reason" %in% names(cmp)) ifelse(is.na(cmp$exclusion_reason), "", as.character(cmp$exclusion_reason)) else rep("", nrow(cmp))
  rho_col <- if ("rho_lag1" %in% names(cmp)) round(cmp$rho_lag1, 3) else NA_real_
  out <- data.frame(K = cmp$K, n_params = cmp$n_params,
                    `R-squared` = round(cmp$r2, 5), RMSE = signif(cmp$rmse, 4),
                    check.names = FALSE)
  out[["AIC-like plug-in score"]] <- round(cmp$aic, 2)
  out[["BIC-like plug-in score"]] <- round(cmp$bic, 2)
  if (has_aicc) out[["AICc-like plug-in score"]] <- round(cmp$aicc, 2)
  if (isTRUE(include_legacy_fields)) {
    # Compatibility machine fields. New presentation labels above are the
    # authoritative human-readable names; these aliases preserve parsers that
    # consume the lowercase schema.
    out$aic <- cmp$aic
    out$bic <- cmp$bic
    if (has_aicc) out$aicc <- cmp$aicc
    out$score_field_compatibility_note <-
      "aic/bic/aicc are compatibility aliases for the corresponding non-classical AIC-like/BIC-like/AICc-like plug-in scores"
  }
  if ("n_eff" %in% names(cmp)) out$`n_eff` <- round(cmp$n_eff, 1)
  out$`rho(lag1)` <- rho_col
  out$`Raw criterion min` <- raw_min                       # which criteria this K is the RAW argmin of (transparency)
  out$Admissible <- adm_col
  out$Selected <- ifelse(is_sel, "* reported", "")         # ONLY the admissibly-selected/reported K (empty when none)
  out$exclusion_reason <- excl_col
  if ("finite_criterion"      %in% names(cmp)) out$finite_criterion      <- as.logical(cmp$finite_criterion)
  if ("optimizer_accepted"    %in% names(cmp)) out$optimizer_accepted    <- as.logical(cmp$optimizer_accepted)
  if ("split"                 %in% names(cmp)) out$split                 <- as.logical(cmp$split)
  if ("optim_convergence_code" %in% names(cmp)) out$optim_convergence_code <- suppressWarnings(as.integer(cmp$optim_convergence_code))
  out
}

.decon_center_oow_suffix <- function(mu_nm, nm_measured) {
  mu_nm <- suppressWarnings(as.numeric(mu_nm))
  nmv   <- suppressWarnings(as.numeric(nm_measured)); nmv <- nmv[is.finite(nmv)]
  if (length(nmv) < 2L) return(rep("", length(mu_nm)))
  lo <- min(nmv); hi <- max(nmv)
  ifelse(is.finite(mu_nm) & (mu_nm < lo | mu_nm > hi), " (outside measured range)", "")
}

# Build the fitted-components data.frame from a labeled-components data.frame. `nm_measured` (the fit's
# measured wavelength grid, fit$best$nm) drives the Lens-A out-of-range center flag; NULL keeps the
# unqualified center for callers without the axis.
.decon_components_df <- function(comp, nm_measured = NULL) {
  fmt <- function(val, se, digits = 3) {
    v <- ifelse(is.finite(val), formatC(val, format = "f", digits = digits), "-")
    s <- ifelse(is.finite(se),  formatC(se,  format = "f", digits = digits), "-")
    paste0(v, " +/- ", s)
  }
  data.frame(
    Component = comp$component,
    Band      = ifelse(is.na(comp$band), "-", comp$band),
    `Center (nm)` = paste0(fmt(comp$mu_nm, comp$mu_se, 2),
                           .decon_center_oow_suffix(comp$mu_nm, nm_measured)),
    `FWHM (nm)`   = fmt(comp$fwhm,  comp$fwhm_se, 2),
    Amplitude     = fmt(comp$amp,   comp$amp_se, 4),
    `eta (shared)` = fmt(comp$eta,   comp$eta_se, 3),
    `Area (in-window)` = ifelse(is.finite(comp$area),
                           formatC(comp$area, format = "g", digits = 4), "-"),
    `Full-profile area` = if (!is.null(comp$area_analytic_se))
                            fmt(comp$area_analytic, comp$area_analytic_se, 4)
                          else ifelse(is.finite(comp$area_analytic),
                                      formatC(comp$area_analytic, format = "g", digits = 4), "-"),
    `Area %`      = ifelse(is.finite(comp$area_frac),
                           paste0(formatC(100 * comp$area_frac, format = "f", digits = 1), "%"), "-"),
    check.names = FALSE
  )
}

.decon_pdf_table_grob <- function(df, base_size = 9, max_rows = 12L, max_cols = 6L) {
  max_rows <- max(1L, as.integer(max_rows))
  max_cols <- max(2L, as.integer(max_cols))
  page_inches <- grDevices::dev.size("in")
  if (!is.data.frame(df)) df <- as.data.frame(df, check.names = FALSE)
  if (!ncol(df)) return(invisible(TRUE))
  # Keep all cells, repeating the identifier when a table spans column groups.
  groups <- if (ncol(df) <= max_cols) list(seq_len(ncol(df))) else
    lapply(split(seq.int(2L, ncol(df)), ceiling(seq_len(ncol(df) - 1L) / (max_cols - 1L))),
           function(cols) c(1L, cols))
  wrap_cell <- function(x, width = 20L) {
    if (is.na(x)) return("")
    words <- unlist(strsplit(as.character(x), "[[:space:]]+"))
    words <- unlist(lapply(words, function(word) {
      if (!nchar(word)) return("")
      starts <- seq.int(1L, nchar(word), by = width)
      substring(word, starts, pmin(starts + width - 1L, nchar(word)))
    }))
    if (!length(words)) return("")
    paste(strwrap(paste(words, collapse = " "), width = width), collapse = "\n")
  }
  page <- 0L
  for (cols in groups) {
    values <- lapply(df[cols], function(col) {
      if (is.numeric(col)) vapply(col, .pasa_pdf_number, character(1)) else as.character(col)
    })
    m <- rbind(names(df)[cols], as.matrix(as.data.frame(values, check.names = FALSE)))
    chars <- unique(unlist(strsplit(paste(m, collapse = ""), "", fixed = TRUE)))
    grid::pushViewport(grid::viewport(gp = grid::gpar(fontsize = base_size, fontface = "bold")))
    widest_char <- max(c(0, grid::convertWidth(grid::stringWidth(chars), "inches", valueOnly = TRUE)))
    grid::popViewport()
    cell_inches <- 0.92 * page_inches[1L] / length(cols) - 0.10
    wrap_width <- if (widest_char > 0) max(1L, min(20L, floor(cell_inches / widest_char))) else 20L
    m[] <- vapply(as.vector(m), wrap_cell, character(1), width = wrap_width)
    # grid's line pitch differs from a simple font-size multiple. Measure the
    # actual grobs so long cells remain inside their row after page scaling.
    row_height <- vapply(seq_len(nrow(m)), function(r) {
      heights <- vapply(m[r, ], function(txt) grid::convertHeight(
        grid::grobHeight(grid::textGrob(txt, gp = grid::gpar(
          fontsize = base_size, lineheight = 1.15,
          fontface = if (r == 1L) "bold" else "plain"))), "npc", valueOnly = TRUE), numeric(1))
      max(0.04, max(heights) + 0.012)
    }, numeric(1))
    remaining <- seq_len(nrow(df)) + 1L
    repeat {
      page <- page + 1L
      if (page > 1L) {
        grid::grid.newpage()
        grid::grid.text("Table continued", y = 0.95,
                        gp = grid::gpar(fontsize = 13, fontface = "bold"))
      }
      rows <- 1L
      while (length(remaining) && length(rows) <= max_rows &&
             sum(row_height[c(rows, remaining[1L])]) <= 0.78) {
        rows <- c(rows, remaining[1L]); remaining <- remaining[-1L]
      }
      # Exceptionally tall cells retain their text on a dedicated scaled page.
      if (length(rows) == 1L && length(remaining)) {
        rows <- c(rows, remaining[1L]); remaining <- remaining[-1L]
      }
      scale <- min(1, 0.78 / sum(row_height[rows]))
      top <- 0.86; w <- 0.92 / length(cols)
      # Measure every wrapped line on the actual device, including bold headers.
      # Wide glyphs must not spill into the next cell.
      grid::pushViewport(grid::viewport(gp = grid::gpar(fontsize = base_size * scale,
                                                       fontface = "bold")))
      text_lines <- unlist(strsplit(as.vector(m[rows, , drop = FALSE]), "\n", fixed = TRUE))
      widest <- max(c(0, grid::convertWidth(grid::stringWidth(text_lines), "inches", valueOnly = TRUE)))
      grid::popViewport()
      text_scale <- if (widest > 0) min(1, (w * page_inches[1L] - 0.10) / widest) else 1
      for (r in rows) {
        h <- row_height[r] * scale
        for (j in seq_along(cols)) {
          x <- 0.04 + (j - 0.5) * w
          grid::grid.rect(x = x, y = top - h / 2, width = w, height = h,
                          gp = grid::gpar(fill = if (r == 1L) "#e8eef4" else "white", col = "#c8cdd2"))
          grid::grid.text(m[r, j], x = x, y = top - h / 2,
                          gp = grid::gpar(fontsize = base_size * scale * text_scale, lineheight = 1.15,
                                          fontface = if (r == 1L) "bold" else "plain"))
        }
        top <- top - h
      }
      if (!length(remaining)) break
    }
  }
  invisible(TRUE)
}
.decon_render_pdf <- function(file, fit, labeled, headline = "",
                              criterion = "aic", notes_text = character(0),
                              context_text = character(0), pres = NULL) {
  if (is.null(pres)) pres <- .decon_presentation(fit)
  .pasa_open_pdf(file, width = 11, height = 8.5)
  on.exit(grDevices::dev.off(), add = TRUE)
  tryCatch({
    # Lead with a context page (what this shows, input provenance, and the
    # Advanced-fit-settings values) so the PDF is self-documenting.
    if (length(context_text)) {
      grid::grid.newpage()
      grid::grid.text("Deconvolution — analysis context", x = 0.5, y = 0.95,
                      gp = grid::gpar(fontsize = 13, fontface = "bold"))
      wrapped_ctx <- unlist(lapply(context_text,
                                   function(s) if (!nzchar(s)) "" else if (startsWith(s, "  ")) s else strwrap(s, width = 108)))
      if (length(wrapped_ctx) > 46) wrapped_ctx <- c(wrapped_ctx[1:45], "...")
      grid::grid.text(paste(wrapped_ctx, collapse = "\n"),
                      x = 0.04, y = 0.90, just = c("left", "top"),
                      gp = grid::gpar(fontsize = 8.5, lineheight = 1.3))
    }
    .boot_lines <- .decon_bootstrap_text(fit)
    if (length(.boot_lines)) {
      grid::grid.newpage()
      grid::grid.text("Bootstrap counts and denominators", x = 0.5, y = 0.95,
                     gp = grid::gpar(fontsize = 13, fontface = "bold"))
      .bl <- unlist(lapply(.boot_lines, strwrap, width = 105))
      grid::grid.text(paste(.bl, collapse = "\n"), x = 0.04, y = 0.88, just = c("left", "top"),
                     gp = grid::gpar(fontsize = 10, lineheight = 1.35))
      grid::grid.text("The complete per-draw record is included in the text and ZIP exports.",
                     x = 0.04, y = 0.10, just = c("left", "bottom"), gp = grid::gpar(fontsize = 9))
    }
    p1 <- .decon_overlay_ggplot(fit, show_scatter = !is.null(fit$scatter), pres = pres, headline = headline)
    print(p1)
    if (!is.null(fit$best)) print(.decon_resid_ggplot(fit))
    cmp_df <- .decon_comparison_df(fit)
    grid::grid.newpage()
    grid::grid.text("K-selection comparison", x = 0.5, y = 0.95,
                    gp = grid::gpar(fontsize = 13, fontface = "bold"))
    .decon_pdf_table_grob(cmp_df, base_size = 9)
    comp_df <- if (is.null(fit$best)) NULL
               else .decon_components_df(labeled$components, nm_measured = fit$best$nm)   # Lens A: flag out-of-range centers
    grid::grid.newpage()
    grid::grid.text(pres$component_title, x = 0.5, y = 0.95,
                    gp = grid::gpar(fontsize = 13, fontface = "bold"))
    .cap_lines <- strwrap(pres$table_caption, width = 120)
    if (length(.cap_lines) > 2L) .cap_lines <- c(.cap_lines[1:2], "...")
    grid::grid.text(paste(.cap_lines, collapse = "\n"), x = 0.5, y = 0.925,
                    gp = grid::gpar(fontsize = 8, lineheight = 1.2,
                                    col = if (identical(pres$display_role, "selected")) "gray25" else "#8a1c1c"))
    if (is.null(comp_df))
      grid::grid.text(paste(strwrap(pres$display_note, width = 90), collapse = "\n"),
                      x = 0.5, y = 0.55, gp = grid::gpar(fontsize = 11, fontface = "bold", col = "#8a1c1c"))
    else .decon_pdf_table_grob(comp_df, base_size = 8)
    grid::grid.newpage()
    grid::grid.text("Interpretation notes", x = 0.5, y = 0.95,
                    gp = grid::gpar(fontsize = 13, fontface = "bold"))
    if (!length(notes_text)) notes_text <- "(no interpretation notes for this fit)"
    wrapped <- unlist(lapply(notes_text, function(s) strwrap(s, width = 110)))
    if (length(wrapped) > 52) wrapped <- c(wrapped[1:51], "...")
    grid::grid.text(paste(wrapped, collapse = "\n"),
                    x = 0.04, y = 0.90, just = c("left", "top"),
                    gp = grid::gpar(fontsize = 8, lineheight = 1.25))
  }, error = function(e) {
    grid::grid.newpage()
    grid::grid.text(paste("PDF error:", conditionMessage(e)),
                    x = 0.5, y = 0.5, gp = grid::gpar(fontsize = 10, col = "red"))
  })
}

# Recursively walk an htmltools tag/shiny.tag.list and concatenate all of its
# text nodes into a single trimmed string. Used to turn each interpretation-note
# div (which the renderUI builds with nested tags + .tip_icon) into plain text
# for the PDF export and the Copy-Entire-Tab summary, so those reuse the SAME
# reactive that drives the on-screen notes and never drift from it.
.decon_tags_to_text <- function(tag) {
  if (is.null(tag)) return("")
  if (is.character(tag)) return(paste(tag, collapse = " "))
  if (is.numeric(tag) || is.logical(tag)) return(paste(as.character(tag), collapse = " "))
  if (inherits(tag, "shiny.tag")) {
    kids <- tag$children
    if (is.null(kids)) return("")
    return(trimws(paste(vapply(kids, .decon_tags_to_text, character(1)), collapse = " ")))
  }
  if (is.list(tag)) {
    return(trimws(paste(vapply(tag, .decon_tags_to_text, character(1)), collapse = " ")))
  }
  ""
}


.pasa_sha256_file <- function(path) toupper(unname(tools::sha256sum(path)))

# A member basename is SAFE iff it is a plain filename: no directory component, no ".."/".", no path
# separator, no control byte, nonempty. Rejects traversal ("../x"), nesting ("a/b"), and NUL/control.
.pasa_zip_safe_member <- function(name) {
  if (length(name) != 1L || is.na(name) || !nzchar(name)) return(FALSE)
  if (name %in% c(".", "..")) return(FALSE)
  if (grepl("[/\\\\]", name)) return(FALSE)        # no path separator (forward or back slash)
  if (grepl("[[:cntrl:]]", name)) return(FALSE)    # no control chars / embedded NUL
  identical(basename(name), name)
}

