.pasa_zip_assert_required <- function(manifest_df, required_registry) {
  if (is.null(required_registry) || !is.data.frame(required_registry))
    stop("complete-export required-member registry is missing")
  need_cols <- c("contract_id", "member", "applicable", "required")
  if (!all(need_cols %in% names(required_registry)))
    stop("complete-export registry is malformed")
  rr <- required_registry[required_registry$applicable %in% TRUE &
                            required_registry$required %in% TRUE, , drop = FALSE]
  if (!nrow(rr) || anyDuplicated(rr$member) ||
      any(!vapply(rr$member, .pasa_zip_safe_member, logical(1))))
    stop("complete-export registry is empty, duplicated, or unsafe")
  if (is.null(manifest_df) || !is.data.frame(manifest_df) ||
      !all(c("member", "status") %in% names(manifest_df)))
    stop("complete-export manifest is missing or malformed")
  for (m in rr$member) {
    hit <- which(manifest_df$member == m)
    if (length(hit) != 1L)
      stop(sprintf("complete export refused: required member '%s' has %d manifest rows", m, length(hit)))
    if (!identical(as.character(manifest_df$status[hit]), "included")) {
      why <- if ("reason" %in% names(manifest_df)) as.character(manifest_df$reason[hit]) else ""
      stop(sprintf("complete export refused: required member '%s' is %s%s", m,
                   as.character(manifest_df$status[hit]),
                   if (nzchar(why)) paste0(" (", why, ")") else ""))
    }
  }
  invisible(TRUE)
}

# Default archiver primitives (the real 'zip' package). Return NULL if the package is absent; a
# caller/test may inject substitutes to force a failure path.
.pasa_zip_default_zipr <- function() if (isTRUE(has_zip))
  zip::zipr else NULL
.pasa_zip_default_ziplist <- function() if (isTRUE(has_zip))
  zip::zip_list else NULL
.pasa_zip_default_unzip <- function() function(zf, exdir) {
  {
      if (isTRUE(has_zip) && "unzip" %in% getNamespaceExports("zip"))
        zip::unzip(zf, exdir = exdir) else utils::unzip(zf, exdir = exdir)
    }
}

# Reopen a FINISHED archive and CONTENT-verify it: the member set must equal names(expect), the central
# directory must be readable/unduplicated with the right count, and every member carrying a non-NA
# expected SHA-256 must -- after EXTRACTION -- hash to exactly that value (content, not size). `expect`
# is a named character vector basename -> SHA (NA = present-only, e.g. manifest.csv cannot hash itself).
# Throws on any violation.
.pasa_zip_verify <- function(zfile, expect, ziplist_fn, unzip_fn) {
  zl   <- ziplist_fn(zfile)
  got  <- basename(as.character(zl$filename))
  want <- names(expect)
  if (!setequal(got, want))
    stop(sprintf("ZIP verify failed: archive members {%s} != intended {%s}",
                 paste(sort(setdiff(got, want)), collapse = ","),
                 paste(sort(setdiff(want, got)), collapse = ",")))
  if (nrow(zl) != length(want) || anyDuplicated(got) || any(is.na(zl$uncompressed_size)))
    stop("ZIP verify failed: central directory unreadable, duplicated, or wrong member count")
  exdir <- tempfile("zver_"); dir.create(exdir, showWarnings = FALSE)
  on.exit(unlink(exdir, recursive = TRUE, force = TRUE), add = TRUE)
  unzip_fn(zfile, exdir)
  for (bn in want) {
    xf <- file.path(exdir, bn)
    if (!file.exists(xf))
      stop(sprintf("ZIP content verify: member '%s' missing after extraction", bn))
    exp <- expect[[bn]]
    if (!is.na(exp) && !identical(.pasa_sha256_file(xf), exp))
      stop(sprintf("ZIP content verify: member '%s' SHA-256 mismatch (archive corrupted the payload)", bn))
  }
  invisible(TRUE)
}

# Independent post-download completeness verifier. Unlike the generic content
# verifier above, this explicitly rejects an
# EXPORT_ERROR archive, reads the embedded required-member registry and ledger,
# verifies every member hash, and opens each supported artifact type.
.pasa_png_header_ok <- function(path) {
  con <- file(path, "rb")
  on.exit(close(con), add = TRUE)
  h <- readBin(con, "raw", n = 24L)
  if (length(h) < 24L ||
      !identical(as.integer(h[1:8]), c(137L, 80L, 78L, 71L, 13L, 10L, 26L, 10L)) ||
      !identical(rawToChar(h[13:16]), "IHDR")) return(FALSE)
  be32 <- function(x) sum(as.numeric(as.integer(x)) * c(256^3, 256^2, 256, 1))
  width <- be32(h[17:20]); height <- be32(h[21:24])
  is.finite(width) && width > 0 && is.finite(height) && height > 0
}
.pasa_zip_verify_complete <- function(zfile, ziplist_fn = NULL, unzip_fn = NULL,
                                      open_members = TRUE) {
  if (is.null(ziplist_fn)) ziplist_fn <- .pasa_zip_default_ziplist()
  if (is.null(unzip_fn)) unzip_fn <- .pasa_zip_default_unzip()
  if (is.null(ziplist_fn) || is.null(unzip_fn)) stop("ZIP verifier is unavailable")
  zl <- ziplist_fn(zfile); got <- basename(as.character(zl$filename))
  if ("EXPORT_ERROR.txt" %in% got)
    stop("complete-export verification refused an EXPORT_ERROR archive")
  core <- c("manifest.csv", "complete_export_contract.csv", "PASA_state.txt")
  miss_core <- setdiff(core, got)
  if (length(miss_core)) stop("complete-export archive lacks: ", paste(miss_core, collapse = ", "))
  ex <- tempfile("complete_verify_"); dir.create(ex, recursive = TRUE)
  on.exit(unlink(ex, recursive = TRUE, force = TRUE), add = TRUE)
  unzip_fn(zfile, ex)
  md <- utils::read.csv(file.path(ex, "manifest.csv"), stringsAsFactors = FALSE,
                        check.names = FALSE, na.strings = character(0))
  rr <- utils::read.csv(file.path(ex, "complete_export_contract.csv"), stringsAsFactors = FALSE,
                        check.names = FALSE)
  .pasa_zip_assert_required(md, rr)
  incl <- md[md$status == "included", , drop = FALSE]
  actual_payload <- setdiff(got, "manifest.csv")
  if (!setequal(actual_payload, incl$member) || anyDuplicated(got))
    stop("complete-export manifest does not exactly account for archive payloads")
  for (i in seq_len(nrow(incl))) {
    p <- file.path(ex, incl$member[i])
    if (!file.exists(p) || !identical(.pasa_sha256_file(p), as.character(incl$sha256[i])))
      stop(sprintf("complete-export member '%s' failed SHA-256 verification", incl$member[i]))
    if (isTRUE(open_members)) {
      ext <- tolower(tools::file_ext(p))
      ok <- tryCatch({
        if (ext == "csv") utils::read.csv(p, stringsAsFactors = FALSE, check.names = FALSE)
        else if (ext %in% c("txt", "tsv")) readLines(p, warn = FALSE, n = 5L)
        else if (ext == "png") {
          if (!isTRUE(.pasa_png_header_ok(p))) stop("invalid PNG signature or IHDR dimensions")
        } else if (ext == "xlsx") {
          if (!requireNamespace("readxl", quietly = TRUE)) stop("package 'readxl' is required to open XLSX members")
          readxl::excel_sheets(p)
        } else if (ext == "pdf") {
          con <- file(p, "rb")
          sig <- readBin(con, "raw", 5L); close(con)
          if (!identical(rawToChar(sig), "%PDF-")) stop("invalid PDF signature")
        } else file.info(p)$size > 0
        TRUE
      }, error = function(e) FALSE)
      if (!isTRUE(ok)) stop(sprintf("complete-export member '%s' could not be opened", incl$member[i]))
    }
  }
  st <- readLines(file.path(ex, "PASA_state.txt"), warn = FALSE)
  if (!any(st == "state_schema_version=4") ||
      !all(c("[SETTINGS]", "[SIDEBAR_DATA]", "[GROWTH_DATA]", "[DECON_BLANK_DATA]") %in% st))
    stop("bundled snapshot is not the full schema-4 state")
  list(ok = TRUE, members = sort(got), manifest = md, registry = rr,
       snapshot_lines = st)
}

# Build + verify a single-member truthful EXPORT_ERROR archive and deliver it to `out_file`, through the
# SAME staged-build -> reopen -> content-verify -> copy gateway the normal archive uses (never a zip
# written straight to the response, never text under a .zip MIME). If the error archive itself cannot be
# built or verified (the "both archivers failed" terminal case) it RAISES, so the download fails VISIBLY
# rather than serving unverified/corrupt bytes.
.pasa_zip_error_archive <- function(msg, out_file, zipr_fn, ziplist_fn, unzip_fn) {
  if (is.null(zipr_fn) || is.null(ziplist_fn) || is.null(unzip_fn))
    stop("ZIP export failed and no archiver is available to write a truthful error archive")
  etmp <- tempfile("zerr_"); dir.create(etmp, showWarnings = FALSE)
  on.exit(unlink(etmp, recursive = TRUE, force = TRUE), add = TRUE)
  ef <- file.path(etmp, "EXPORT_ERROR.txt")
  writeLines(paste0("Export failed: ", msg), ef)
  expect <- stats::setNames(.pasa_sha256_file(ef), "EXPORT_ERROR.txt")
  etz <- tempfile(fileext = ".zip"); on.exit(unlink(etz, force = TRUE), add = TRUE)
  zipr_fn(zipfile = etz, files = ef, recurse = FALSE, include_directories = FALSE)
  .pasa_zip_verify(etz, expect, ziplist_fn, unzip_fn)
  if (!file.copy(etz, out_file, overwrite = TRUE))
    stop("verified error archive could not be delivered")
  invisible(TRUE)
}

# The single finalize entry point. `paths` = full paths of the physical members (NOT manifest.csv).
# `manifest_df` = the ledger (member,status,reason,bytes,sha256). Enforces the pre-archive invariants
# (safe + unique basenames; included <-> physical HASH bijection; skipped/FAILED strictly non-physical
# with a reason), writes manifest.csv, STAGES the archive, CONTENT-verifies it (reopen + extract + per-
# member SHA-256), and only then delivers it. On ANY failure it falls back to a verified EXPORT_ERROR
# archive; a double failure RAISES (visible download failure, never ZIP MIME over invalid bytes).
.pasa_zip_finalize <- function(paths, manifest_df, out_file, staging_dir,
                               required_registry,
                               zipr_fn = NULL, ziplist_fn = NULL, unzip_fn = NULL) {
  if (is.null(zipr_fn))    zipr_fn    <- .pasa_zip_default_zipr()
  if (is.null(ziplist_fn)) ziplist_fn <- .pasa_zip_default_ziplist()
  if (is.null(unzip_fn))   unzip_fn   <- .pasa_zip_default_unzip()
  if (is.null(zipr_fn) || is.null(ziplist_fn))
    stop("Package 'zip' is required for ZIP export. Install with: install.packages('zip')")
  tryCatch({
    md <- manifest_df
    if (is.null(md) || !is.data.frame(md)) stop("manifest is missing")
    for (col in c("member", "status", "reason", "bytes", "sha256"))
      if (!col %in% names(md)) stop(sprintf("manifest missing column '%s'", col))
    .pasa_zip_assert_required(md, required_registry)
    .rr <- required_registry[required_registry$applicable %in% TRUE, , drop = FALSE]
    .mi <- match(md$member, .rr$member)
    md$contract_id <- ifelse(is.na(.mi), "supplementary", .rr$contract_id[.mi])
    md$required <- !is.na(.mi) & .rr$required[.mi] %in% TRUE
    phys_bn <- basename(paths)
    # (1) safe, unique member basenames -- catches duplicate / colliding / unsafe names before archiving
    if (anyDuplicated(phys_bn))
      stop(sprintf("duplicate member basename in archive: %s",
                   paste(unique(phys_bn[duplicated(phys_bn)]), collapse = ",")))
    unsafe <- phys_bn[!vapply(phys_bn, .pasa_zip_safe_member, logical(1))]
    if (length(unsafe)) stop(sprintf("unsafe member name(s): %s", paste(unsafe, collapse = ",")))
    if ("manifest.csv" %in% phys_bn) stop("manifest.csv must not be supplied as a physical member")
    # (2) included <-> physical hash bijection; skipped/FAILED strictly non-physical with a reason
    incl <- md[md$status == "included", , drop = FALSE]
    if (any(!md$status %in% c("included", "not_applicable", "skipped", "FAILED"))) stop("unknown manifest status")
    np   <- md[md$status %in% c("not_applicable", "skipped", "FAILED"), , drop = FALSE]
    if (!setequal(incl$member, phys_bn))
      stop(sprintf("included rows {%s} != physical members {%s}",
                   paste(sort(setdiff(incl$member, phys_bn)), collapse = ","),
                   paste(sort(setdiff(phys_bn, incl$member)), collapse = ",")))
    if (any(is.na(incl$sha256) | !nzchar(incl$sha256)))
      stop("an 'included' member has no recorded SHA-256")
    if (nrow(np)) {
      if (any(np$member %in% phys_bn)) stop("a skipped/FAILED member is physically present (must be absent)")
      if (any(is.na(np$reason) | !nzchar(np$reason))) stop("a skipped/FAILED row has an empty reason")
    }
    # recorded hashes must still match the staged files (nothing mutated between add-time and finalize)
    for (i in seq_len(nrow(incl))) {
      p <- paths[match(incl$member[i], phys_bn)]
      if (!identical(.pasa_sha256_file(p), incl$sha256[i]))
        stop(sprintf("staged member '%s' changed after hashing", incl$member[i]))
    }
    # (3) write the ledger (formula-injection sanitized for the CSV body only; hashes verified above)
    p_manifest <- file.path(staging_dir, "manifest.csv")
    md_out <- if (exists(".sanitize_df_for_csv", mode = "function")) .sanitize_df_for_csv(md) else md
    utils::write.csv(md_out, p_manifest, row.names = FALSE)
    if (!file.exists(p_manifest) || is.na(file.info(p_manifest)$size) || file.info(p_manifest)$size <= 0)
      stop("manifest.csv could not be written; refusing to finalize an archive without its ledger")
    # (4) STAGE the archive, then CONTENT-verify every member against the ledger before delivery
    all_paths <- c(paths, p_manifest)
    expect <- stats::setNames(c(incl$sha256[match(phys_bn, incl$member)], NA_character_),
                              c(phys_bn, "manifest.csv"))
    ztmp <- tempfile(fileext = ".zip"); on.exit(unlink(ztmp, force = TRUE), add = TRUE)
    zipr_fn(zipfile = ztmp, files = all_paths, recurse = FALSE, include_directories = FALSE)
    .pasa_zip_verify(ztmp, expect, ziplist_fn, unzip_fn)
    if (!file.copy(ztmp, out_file, overwrite = TRUE))
      stop("verified archive could not be delivered")
    invisible(TRUE)
  }, error = function(e)
    .pasa_zip_error_archive(conditionMessage(e), out_file, zipr_fn, ziplist_fn, unzip_fn))
}

# Keep two checkbox inputs synchronized without duplicating observer bodies.
.sync_checkbox_pair <- function(input, session, left, right) {
  for (ids in list(c(left, right), c(right, left))) local({
    from <- ids[[1]]; to <- ids[[2]]
    shiny::observeEvent(input[[from]], {
      value <- isTRUE(input[[from]])
      if (!identical(value, isTRUE(input[[to]])))
        shiny::updateCheckboxInput(session, to, value = value)
    }, ignoreInit = TRUE, domain = session)
  })
  invisible(NULL)
}

# Return TRUE only when a valid scalar probe target is materially different from
# its mounted mirror. Equality guards prevent the numeric input and range slider
# from indefinitely echoing stale updates back through each other's observers.
.pasa_probe_sync_needed <- function(target, current, tolerance = 1e-12) {
  target <- suppressWarnings(as.numeric(target))
  current <- suppressWarnings(as.numeric(current))
  if (length(target) != 1L || !is.finite(target)) return(FALSE)
  if (length(current) != 1L || !is.finite(current)) return(TRUE)
  abs(target - current) > tolerance * max(1, abs(target), abs(current))
}

# Classify an analysis-range update without overwriting an already valid probe
# wavelength. Slider bounds always refresh, but an explicit value is sent to both
# mirrors only when the numeric entry is missing, invalid, or outside the range.
.pasa_probe_range_target <- function(current, range) {
  range <- suppressWarnings(as.numeric(range))
  if (length(range) != 2L || any(!is.finite(range)) || range[[1L]] > range[[2L]])
    stop("probe range must contain two ordered finite values")
  current <- suppressWarnings(as.numeric(current))
  if (length(current) == 1L && is.finite(current) &&
      current >= range[[1L]] && current <= range[[2L]]) {
    return(list(value = current, replace = FALSE))
  }
  value <- if (length(current) == 1L && is.finite(current))
    min(max(current, range[[1L]]), range[[2L]]) else mean(range)
  list(value = value, replace = TRUE)
}

# Pure decoder: validation and application consume the same typed identities.
.pasa_decode_growth_snapshot <- function(lines, limits, legacy_settings = list()) {
  legacy <- isTRUE(attr(lines, "legacy_growth_manual", exact = TRUE)) ||
    isTRUE(attr(lines, "snapshot_schema_version", exact = TRUE) %in% 1:3)
  lines <- sub("\r$", "", as.character(lines))
  # An old all-missing series is tabs, not a disposable blank separator.
  lines <- lines[!grepl("^\\s*#", lines) &
                   (nzchar(trimws(lines)) | grepl("\t", lines, fixed = TRUE))]
  if (!length(lines)) stop("the growth section is empty")
  is_kv <- grepl("^[A-Za-z_][A-Za-z0-9_]*=", lines)
  kv <- list()
  for (ln in lines[is_kv]) {
    pos <- regexpr("=", ln, fixed = TRUE)
    key <- substr(ln, 1L, pos - 1L)
    if (key %in% names(kv)) stop("duplicate growth key: ", key)
    kv[[key]] <- substr(ln, pos + 1L, nchar(ln))
  }
  rows <- lines[!is_kv]
  split_cells <- function(row) {
    z <- strsplit(paste0(row, "\t."), "\t", fixed = TRUE)[[1L]]
    z[-length(z)] # retain every trailing missing field
  }
  cells <- lapply(rows, split_cells)
  mode <- if (is.null(kv$mode)) "manual" else tolower(trimws(kv$mode))
  if (!(mode %in% c("manual", "sidebar"))) stop("unknown growth mode: ", mode)
  allowed <- if (mode == "manual") c("mode", "unit", "interval", "nrep", "ntech", "ntp")
             else c("mode", "unit", "interval", "nrep", "tracking_wl", "growth_map_us",
                    grep("^map_R[0-9]+$", names(kv), value = TRUE))
  unknown <- setdiff(names(kv), allowed)
  if (length(unknown)) stop("unknown growth key(s): ", paste(unknown, collapse = ", "))
  # The documented legacy alias is one row per biological replicate. Snapshot
  # settings may supply dimensions; never borrow them from the current UI.
  if (legacy) {
    for (key in c("nrep", "ntech", "ntp", "unit", "interval")) {
      old <- legacy_settings[[paste0("growth_", key)]]
      if (is.null(kv[[key]]) && !is.null(old)) kv[[key]] <- old
    }
    if (is.null(kv$ntech)) kv$ntech <- "1"
    if (is.null(kv$nrep) && length(cells)) kv$nrep <- as.character(length(cells))
    widths <- lengths(cells)
    if (is.null(kv$ntp) && length(widths) && length(unique(widths)) == 1L)
      kv$ntp <- as.character(widths[1L])
  }
  integer_field <- function(key, lower, upper) {
    raw <- kv[[key]]
    if (is.null(raw) || length(raw) != 1L || !grepl("^[0-9]+$", trimws(raw)))
      stop("growth ", key, " must be an explicit integer")
    value <- suppressWarnings(as.numeric(raw))
    if (!is.finite(value) || value < lower || value > upper)
      stop("growth ", key, " is outside ", lower, "..", upper)
    as.integer(value)
  }
  nrep <- integer_field("nrep", 1L, limits$nrep)
  unit <- if (is.null(kv$unit)) "Days" else kv$unit
  if (!(unit %in% c("Days", "Hours"))) stop("unknown growth time unit: ", unit)
  interval <- suppressWarnings(as.numeric(if (is.null(kv$interval)) "1" else kv$interval))
  if (length(interval) != 1L || !is.finite(interval) || interval <= 0)
    stop("growth interval must be finite and positive")
  out <- list(mode = mode, unit = unit, interval = interval, nrep = nrep,
              ntech = NULL, ntp = NULL, values = list(), maps = list(), tracking_wl = NULL)
  if (mode == "manual") {
    ntech <- integer_field("ntech", 1L, limits$ntech)
    ntp <- integer_field("ntp", 2L, limits$ntp)
    if (as.numeric(nrep) * ntech * ntp > limits$cells) stop("growth grid exceeds its cell limit")
    if (length(cells) != nrep * ntech)
      stop("growth matrix has ", length(cells), " rows; expected ", nrep * ntech,
           ". Missing series must retain their row.")
    if (any(lengths(cells) != ntp)) stop("each growth row must contain exactly ", ntp, " timepoint fields")
    matrix_values <- matrix(NA_real_, nrow = nrep * ntech, ncol = ntp)
    for (r in seq_along(cells)) {
      raw <- trimws(cells[[r]])
      missing <- raw %in% c("", "NA")
      numeric <- suppressWarnings(as.numeric(raw))
      if (any(!missing & !is.finite(numeric)))
        stop("growth row ", r, " contains a nonnumeric or nonfinite OD value")
      numeric[missing] <- NA_real_
      matrix_values[r, ] <- numeric
    }
    for (i in seq_len(nrep)) for (t in seq_len(ntech)) for (j in seq_len(ntp)) {
      id <- if (ntech > 1L) sprintf("growth_od_%d_%d_%d", i, t, j)
            else sprintf("growth_od_%d_%d", i, j)
      out$values[[id]] <- matrix_values[(i - 1L) * ntech + t, j]
    }
    out$ntech <- ntech; out$ntp <- ntp; out$matrix <- matrix_values
  } else {
    if (length(rows)) stop("growth data from loaded spectra cannot contain a manual matrix")
    if (!is.null(kv$tracking_wl) && nzchar(kv$tracking_wl)) {
      wl <- suppressWarnings(as.numeric(kv$tracking_wl))
      if (length(wl) != 1L || !is.finite(wl) || wl < 100 || wl > 4000)
        stop("growth tracking wavelength must be finite and within 100..4000 nm")
      out$tracking_wl <- wl
    }
    if (!is.null(kv$growth_map_us) && !identical(kv$growth_map_us, "1"))
      stop("unknown growth sample-map encoding")
    for (key in grep("^map_R[0-9]+$", names(kv), value = TRUE)) {
      i <- suppressWarnings(as.numeric(sub("^map_R", "", key)))
      if (!is.finite(i) || i < 1 || i > nrep || !identical(key, paste0("map_R", as.integer(i))))
        stop("growth mapping refers to an invalid replicate: ", key)
      sep <- if (!is.null(kv$growth_map_us) || grepl("\x1f", kv[[key]], fixed = TRUE)) "\x1f" else ","
      map <- strsplit(kv[[key]], sep, fixed = TRUE)[[1L]]
      if (identical(sep, ",")) map <- trimws(map) # old comma-separated format
      out$maps[[key]] <- map[nzchar(map)]
    }
    # Absence means an explicitly empty mapping when replacing a snapshot.
    for (i in seq_len(nrep)) if (is.null(out$maps[[paste0("map_R", i)]]))
      out$maps[[paste0("map_R", i)]] <- character(0)
  }
  class(out) <- c("pasa_growth_snapshot", "list")
  out
}

# Restoration owns its scheduled work. Closing the session never reads a
# reactive value; callbacks check this plain state before entering Shiny code.
.pasa_restore_callbacks <- function(session) {
  state <- new.env(parent = emptyenv())
  state$closed <- FALSE; state$generation <- 0L; state$next_id <- 0L
  state$cancel <- list()
  alive <- function() !isTRUE(state$closed)
  reset <- function() {
    state$generation <- state$generation + 1L
    old <- state$cancel; state$cancel <- list()
    for (cancel in old) if (is.function(cancel)) tryCatch(cancel(), error = function(e) NULL)
    invisible()
  }
  guard <- function(callback) {
    generation <- state$generation
    function(...) {
      if (!alive() || !identical(generation, state$generation)) return(invisible())
      shiny::withReactiveDomain(session, callback(...))
    }
  }
  schedule <- function(callback, delay = 0.25) {
    if (!alive()) return(invisible())
    state$next_id <- state$next_id + 1L; id <- as.character(state$next_id)
    run <- guard(function() { state$cancel[[id]] <- NULL; callback() })
    if (requireNamespace("later", quietly = TRUE)) state$cancel[[id]] <- later::later(run, delay = delay)
    else run()
    invisible()
  }
  close <- function() { state$closed <- TRUE; reset(); invisible() }
  session$onSessionEnded(close)
  list(alive = alive, guard = guard, schedule = schedule, reset = reset, close = close,
       pending_count = function() length(state$cancel))
}

# ---------- Server ----------
server <- function(input, output, session){
  .restore_callbacks <- .pasa_restore_callbacks(session)
  .run_io <- .pasa_io_runner(session)

  similarity_network_backend <- .pasa_similarity_network_backend()

  # Welcome and onboarding are display-only; analysis state is kept separate.
  output$pasa_data_preview <- renderTable({
    df <- dat_value(); req(df)
    utils::head(df[, seq_len(min(ncol(df), 7L)), drop=FALSE], 8L)
  }, digits=4, striped=TRUE, bordered=FALSE, spacing="s")
  output$pasa_data_preview_note <- renderUI({
    df <- dat_value()
    if (is.null(df)) return(p("Your loaded table will appear here. No data have been loaded yet."))
    p(sprintf("%s wavelength rows and %s sample columns. Showing the first 8 rows and up to 6 samples.", nrow(df), max(0L,ncol(df)-1L)))
  })
  output$pasa_analysis_summary <- renderUI({
    if (is.null(dat_value())) return(NULL)
    rng <- suppressWarnings(as.numeric(input$analysis_nm))
    range_label <- if(length(rng)==2L && all(is.finite(rng))) paste0(paste(format(rng,trim=TRUE),collapse="–")," nm") else "Choose a range"
    div(class="pasa-analysis-strip",
      span(strong("Samples selected"), length(input$samples %||% character())),
      span(strong("Wavelength range"),range_label),
      span(strong("Baseline correction"),if(isTRUE(input$apply_baseline))"On" else "Off"),
      span(strong("Normalization"),pasa_normalization_label(input$norm_method, input$norm_band,
        input$norm_target, input$norm_ref_nm, input$apply_baseline)))
  })
  output$pasa_spectrum_readout <- renderUI({
    if (is.null(dat_value())) return(tagList(h2("Read your spectra"),p("Load data to see the curves and the settings used to draw them.")))
    rng <- suppressWarnings(as.numeric(input$analysis_nm))
    range_label <- if(length(rng)==2L && all(is.finite(rng))) paste0(paste(format(rng,trim=TRUE),collapse="–")," nm") else "Not set"
    tagList(h2("Current view"),tags$dl(
      tags$dt("Selected samples"),tags$dd(length(input$samples %||% character())),
      tags$dt("Wavelength range"),tags$dd(range_label),
      tags$dt("Normalization"),tags$dd(pasa_normalization_label(input$norm_method, input$norm_band,
        input$norm_target, input$norm_ref_nm, input$apply_baseline))),
      tags$hr(),p(if (identical(input$norm_method %||% "none","none") || !isTRUE(input$apply_baseline))
        "Read peak positions and curve heights together. The display retains differences in signal magnitude."
        else "Normalization changes the scale of each curve. Use this view to compare spectral shape; use raw band areas when magnitude matters."),
      tags$button(type="button",class="btn btn-outline-primary",onclick="window.PasaShell.navigate('Data Quality');","Compare and check spectra"))
  })

  output$nqc_threshold_warn <- renderUI({
    issues <- .noise_threshold_state(input)$issues
    if (!length(issues)) return(NULL)
    div(class = "alert alert-warning", role = "alert", paste(c("Noise classification is paused.", issues), collapse = " "))
  })


  default_bands <- list(qy=c(660,690), pbs=c(600,650), car=c(430,520), bx=c(420,460))
  
  # Holds the auto-detected wavelength-axis summary for the post-load banner.
  detected_meta <- reactiveVal(NULL)
  loaded_source <- reactiveVal(NULL)
  pending_samples_restore <- reactiveVal(NULL)
  sample_restore_apply_env <- new.env(parent = emptyenv())
  sample_restore_apply_env$token <- 0L
  restore_selection_provenance <- reactiveVal(NA_character_)
  pending_decon_sample_restore <- reactiveVal(NULL)
  restore_txn <- reactiveVal(0L)
  last_good_dat <- reactiveVal(NULL)
  
  path_debounced <- debounce(reactive({ input$path }), 600)
  sheet_state <- reactiveVal(NULL)
  sheet_cache <- new.env(parent = emptyenv())
  sheet_job <- NULL
  sheet_request <- 0L
  .sheet_source <- function() {
    src <- input$data_source %||% "auto"
    upload <- if (src != "url") input$file else NULL
    value <- if (isTruthy(upload$datapath)) upload$datapath else input$path
    if (!isTruthy(value)) return(NULL)
    auth <- .pasa_authorize_source(value, upload, session)
    if (!isTRUE(auth$ok)) return(NULL)
    remote <- identical(auth$route, "remote")
    name <- if (isTruthy(upload$name)) upload$name else sub("[?#].*$", "", value)
    extension <- tolower(tools::file_ext(name))
    if (!extension %in% c("xlsx", "xls") && !(remote && (is_gsheet(value) || is_onedrive(value)))) return(NULL)
    metadata <- if (!remote) file.info(auth$path)[, c("size", "mtime"), drop = FALSE] else NULL
    list(path = auth$path, remote = remote,
         key = digest::digest(list(auth$path, metadata), algo = "sha256"))
  }
  .inspect_sheets <- function(spec) {
    if (is.null(spec)) return(invisible())
    if (!is.null(sheet_job)) sheet_job$cancel()
    sheet_request <<- sheet_request + 1L; request <- sheet_request
    if (exists(spec$key, envir = sheet_cache, inherits = FALSE)) {
      sheet_state(get(spec$key, envir = sheet_cache)); return(invisible())
    }
    sheet_state(list(key = spec$key, state = "loading"))
    sheet_job <<- .run_io("sheets", spec, budget = .input_deadline_secs(),
      on_result = function(value, deadline) {
        if (request != sheet_request) return(invisible())
        result <- if (inherits(value, "pasa_sheet_list_error"))
          list(key = spec$key, state = "error", error = value$error) else
          list(key = spec$key, state = "ready", sheets = as.character(value))
        if (identical(result$state, "ready")) assign(spec$key, result, envir = sheet_cache)
        sheet_state(result)
      }, on_error = function(message) {
        if (request == sheet_request) sheet_state(list(key = spec$key, state = "error", error = message))
      })
  }
  # Permission is bound to the immutable source captured by this explicit click.
  observeEvent(input$inspect_url, { .inspect_sheets(.sheet_source()) }, ignoreInit = TRUE)
  observeEvent(list(input$file, input$data_source, path_debounced()), {
    spec <- .sheet_source()
    if (!is.null(spec) && !spec$remote) .inspect_sheets(spec)
  }, ignoreInit = TRUE)
  output$sheet_ui <- renderUI({
    spec <- .sheet_source()
    if (is.null(spec)) return(NULL)
    current <- sheet_state()
    ready <- !is.null(current) && identical(current$key, spec$key)
    if (ready && identical(current$state, "ready") && length(current$sheets)) {
      # Values use a prefix so a sheet named "1" or "2024" cannot become an index.
      choices <- stats::setNames(paste0("name:", current$sheets), current$sheets)
      selected <- if (isTruthy(input$sheet) && input$sheet %in% choices) input$sheet else choices[[1L]]
      return(selectInput("sheet", "Sheet", choices = choices, selected = selected))
    }
    tagList(
      selectInput("sheet", "Sheet", choices = c("First sheet" = "index:1"), selected = "index:1"),
      actionButton("inspect_url", if (ready && identical(current$state, "error")) "Retry sheet inspection" else "Inspect sheets",
                   class = "btn-outline-secondary btn-sm"),
      if (ready && identical(current$state, "loading")) tags$small("Reading sheet names in the background…")
      else if (ready && identical(current$state, "error"))
        div(class = "pasa-advisory-box pasa-advisory-warn", "Sheet inspection failed. ", current$error,
            " Load data will use the first sheet until inspection succeeds.")
      else tags$small("Inspect to choose a worksheet, or load the first sheet. Pasting a URL does not fetch it.")
    )
  })

  # Flag for demo mode: TRUE = load synthetic demo, FALSE = load from file/URL
  demo_flag <- reactiveVal(FALSE)
  # Update source identity before the shared load observer runs. Explicit
  # priority prevents the demo click from racing the data-commit branch.
  observeEvent(input$load_demo, { demo_flag(TRUE) }, ignoreInit = TRUE, priority = 10)
  observeEvent(input$load,      { demo_flag(FALSE) }, ignoreInit = TRUE, priority = 10)

  # Session-snapshot data injection. When the user loads a saved
  # session and ticks 'Input data', the parsed SIDEBAR_DATA TSV is converted to
  # a data.frame and stashed here. dat() prefers this value (when non-NULL) and
  # the bump_token re-triggers the eventReactive so the controls refresh exactly
  # as if a real file had been loaded. Loading a real file or the demo clears
  # the injected value so it doesn't override the new source.
  state_injected_data <- reactiveVal(NULL)
  state_injected_bump <- reactiveVal(0L)
  # When a snapshot restore applies BOTH Settings and Input data, the data load
  # must NOT auto-reset the analysis-range / baseline / probe slider VALUES (that
  # would clobber the just-restored settings). This flag tells .apply_loaded_data
  # to refresh slider bounds only and leave the restored values intact.
  state_keep_ranges <- reactiveVal(FALSE)
  observeEvent(input$load,      { state_injected_data(NULL) }, ignoreInit = TRUE)
  observeEvent(input$load_demo, { state_injected_data(NULL) }, ignoreInit = TRUE)

  .PROV_IDS <- c("analysis_nm", "baseline_method", "baseline_nm", "smooth",
                 "resample_on", "grid_step", "dilution", "norm_method",
                 "norm_target", "organism")
  .PROV_FACTORY <- list(analysis_nm = c(350, 750), baseline_method = "single_nm",
                        baseline_nm = 750, smooth = "none", resample_on = FALSE,
                        grid_step = 1, dilution = 1, norm_method = "none",
                        norm_target = 1, organism = "cyano")
  prov <- do.call(reactiveValues,
                  stats::setNames(as.list(rep("default", length(.PROV_IDS))), .PROV_IDS))
  .prov_last <- new.env(parent = emptyenv())      # id -> value last written programmatically (persistent; pristine detection)
  .prov_pending <- new.env(parent = emptyenv())
  .prov_same <- function(a, b) isTRUE(all.equal(a, b, tolerance = 1e-9))
  .prov_mark <- function(id, value, state) {
    if (!id %in% .PROV_IDS) return(invisible())
    assign(id, value, envir = .prov_last)
    prov[[id]] <- state
    cur <- tryCatch(shiny::isolate(input[[id]]), error = function(e) NULL)
    if (is.null(cur) || !.prov_same(cur, value)) assign(id, value, envir = .prov_pending)
    invisible()
  }
  .prov_tag <- function(id) {
    st <- prov[[id]] %||% "default"
    switch(st,
           default  = " (default)",
           auto     = " (auto-detected)",
           user     = " (user-set)",
           restored = " (restored)",
           " (default)")
  }
  # One echo-guarded change-observer per tracked control. ignoreInit so a widget's
  # very first appearance does not itself read as a user edit.
  lapply(.PROV_IDS, function(.id) {
    local({
      id <- .id
      observeEvent(input[[id]], {
        newv <- input[[id]]
        if (exists(id, envir = .prov_pending, inherits = FALSE) &&
            .prov_same(get(id, envir = .prov_pending, inherits = FALSE), newv)) {
          rm(list = id, envir = .prov_pending); return()               # the one expected echo of our own write
        }
        last <- if (exists(id, envir = .prov_last, inherits = FALSE))
                  get(id, envir = .prov_last, inherits = FALSE) else NULL
        # A change to the factory value counts as "user" UNLESS the control is still PRISTINE (`default`, never
        # programmatically written) -- that lone case is a widget-creation echo of the factory value. Once the control
        # has been auto-derived / restored / user-set, a deliberate reset to the factory value IS a user action.
        if (identical(prov[[id]] %||% "default", "default") && is.null(last) &&
            .prov_same(.PROV_FACTORY[[id]], newv)) return()             # pristine widget-creation factory echo
        prov[[id]] <- "user"
      }, ignoreInit = TRUE)
    })
  })

  .snap_norm_hdr <- function(h) sub("^'", "", h)
  .parse_sidebar_data_block <- function(lines) {
    if (!length(lines)) return(NULL)
    keep <- lines[!grepl("^\\s*#", lines) & nzchar(trimws(lines))]
    if (length(keep) < 2L) return(NULL)
    hdr <- strsplit(keep[1], "\t", fixed = TRUE)[[1]]
    hdr <- .snap_norm_hdr(hdr)
    if (length(hdr) < 2L) return(NULL)
    body <- keep[-1]
    rows <- strsplit(body, "\t", fixed = TRUE)
    ncol_h <- length(hdr)
    rows <- lapply(rows, function(r) {
      if (length(r) < ncol_h) r <- c(r, rep(NA_character_, ncol_h - length(r)))
      else if (length(r) > ncol_h) r <- r[seq_len(ncol_h)]
      r
    })
    mat <- do.call(rbind, rows)
    df <- as.data.frame(mat, stringsAsFactors = FALSE)
    names(df) <- hdr
    # Coerce all columns to numeric. nm + every sample column must be numeric
    # for the downstream pipeline to work.
    df[] <- lapply(df, function(col) suppressWarnings(as.numeric(col)))
    df <- df[is.finite(df$nm), , drop = FALSE]
    if (nrow(df) < 2L || length(unique(df$nm)) < 2L) return(NULL)
    original <- df$nm
    for (name in setdiff(names(df), "nm")) df[[name]][!is.finite(df[[name]])] <- NA_real_
    df <- tibble::as_tibble(df[order(df$nm), , drop = FALSE])
    attr(df, "orig_first") <- original[[1L]]
    attr(df, "orig_last") <- tail(original, 1L)
    attr(df, "orig_monotonic") <- all(diff(original) >= 0) || all(diff(original) <= 0)
    df
  }

  # Helper: after a data.frame becomes the active dataset, run the same
  # auto-detection + slider-refresh routine the file-load path uses. Extracted
  # so the snapshot-injection path can reuse it without duplicating logic.
  .apply_loaded_data <- function(df, reset_values = TRUE) {
    if (is.null(df) || !is.data.frame(df) || !"nm" %in% names(df)) return(invisible())
    meta <- describe_axis(df$nm,
                          original_first = attr(df, "orig_first") %||% df$nm[1],
                          original_last  = attr(df, "orig_last")  %||% df$nm[nrow(df)],
                          original_monotonic = attr(df, "orig_monotonic"))
    meta$n_samples <- max(0L, ncol(df) - 1L)
    detected_meta(meta)
    nm_min <- floor(min(df$nm, na.rm = TRUE)); nm_max <- ceiling(max(df$nm, na.rm = TRUE))
    rng <- sort(c(max(350, nm_min), min(750, nm_max)))
    if (isTRUE(reset_values)) {
      updateSliderInput(session, "analysis_nm", min = nm_min, max = nm_max,
                        value = c(nm_min, nm_max), step = 1)  # default to the FULL available range on load
      .prov_mark("analysis_nm", c(nm_min, nm_max), "auto")
      { .bwb <- .baseline_win_bounds(nm_min, nm_max)
        updateSliderInput(session, "baseline_win", min = .bwb$min, max = .bwb$max, value = .bwb$value, step = 1) }
      updateSliderInput(session, "probe_slider", min = rng[1], max = rng[2],
                        value = min(max(680, rng[1]), rng[2]))
    } else {
      # Restore path: refresh slider BOUNDS only so the just-restored values are
      # kept (and merely clamped into the new data's range if needed).
      updateSliderInput(session, "analysis_nm",  min = nm_min,          max = nm_max, step = 1)
      { .bwb <- .baseline_win_bounds(nm_min, nm_max)
        updateSliderInput(session, "baseline_win", min = .bwb$min, max = .bwb$max, step = 1) }
      updateSliderInput(session, "probe_slider", min = rng[1],           max = rng[2])
    }
    for (id in c("qy", "pbs", "car", "bx")) updateSliderInput(session, id, min = nm_min, max = nm_max)
    invisible()
  }

  .REMOTE_ASYNC_MIN_BYTES <- 2 * 1024^2   # local files at/under 2 MiB read synchronously (fast); larger go off-worker
  dat_value   <- reactiveVal(NULL)   # the committed active dataset, or NULL before the first successful load
  dat_err     <- reactiveVal(NULL)   # a no-data message to surface when a load fails AND there is no last-good
  dat_loading <- reactiveVal(FALSE)  # TRUE while an off-worker read is in flight
  controls_ready <- reactiveVal(FALSE) # one-way first-success latch: later data commits must not remount all controls
  pasa_onboarding_server(input, output, session,
    data_ready = reactive(isTRUE(controls_ready())),
    has_data = reactive(!is.null(dat_value())))
  load_env <- new.env(parent = emptyenv())
  load_env$gen <- 0L; load_env$done_gen <- -1L; load_env$mirai <- NULL; load_env$holds_task <- FALSE; load_env$active <- FALSE
  load_env$release <- NULL
  load_env$stop_state <- "IDLE"

  dat <- reactive({ e <- dat_err(); if (!is.null(e)) validate(need(FALSE, e)); req(dat_value()) })

  .load_keep_or_err <- function(msg) {
    prev <- isolate(last_good_dat())
    if (!is.null(prev)) showNotification(paste0(msg, " Keeping the previously loaded dataset."), type = "error", duration = 14, session = session)
    else dat_err(msg)
    invisible()
  }

  # Apply structural, input-limit, deadline, and C0 validation atomically, keeping
  # the last good dataset on refusal, then refresh the axis banner and sliders and commit.
  # This gate runs on the main thread, never the worker.
  # `src_name` labels messages; `src_prov` is the sanitized provenance stored for the snapshot; `deadline` /
  # `raw_bytes` are the load context resolved before the read.
  .dat_commit <- function(df, src_name, src_prov, deadline, raw_bytes) {
    if (inherits(df, "pasa_load_error")) { .load_keep_or_err(sprintf("Could not load '%s': %s.", src_name, attr(df, "msg"))); return(invisible()) }
    .struct_ok <- is.data.frame(df) && "nm" %in% names(df) && ncol(df) >= 2L &&
                  any(is.finite(suppressWarnings(as.numeric(df[["nm"]]))))
    if (!isTRUE(.struct_ok)) { .load_keep_or_err(sprintf("Could not load '%s': it is not a valid spectral table (needs a wavelength column and at least one sample column).", src_name)); return(invisible()) }
    .lim <- .input_limits_check(df, raw_bytes = raw_bytes)
    if (!isTRUE(.lim$ok)) { .load_keep_or_err(sprintf("This dataset was not loaded: %s. Reduce it (fewer samples, fewer rows, or a narrower range) and try again.", .lim$reason)); return(invisible()) }
    if (Sys.time() > deadline) { .load_keep_or_err(sprintf("This dataset was not loaded: it exceeded the %.0f-second load time limit.", .input_deadline_secs())); return(invisible()) }
    .c0off <- .c0_offending(names(df), "column (sample) names in the loaded file")
    if (!is.null(.c0off)) { .load_keep_or_err(.c0off$message); return(invisible()) }
    meta <- describe_axis(df$nm, original_first = attr(df, "orig_first"),
                          original_last = attr(df, "orig_last"), original_monotonic = attr(df, "orig_monotonic"))
    meta$n_samples <- max(0L, ncol(df) - 1L)
    na_cols <- attr(df, "na_cols")
    if (length(na_cols))
      showNotification(sprintf("%d column(s) could not be read as numbers and are blank: %s. Check the delimiter and decimal format (comma vs dot).",
                               length(na_cols), paste(na_cols, collapse = ", ")), type = "warning", duration = 12, session = session)
    .nm_reloc <- attr(df, "nm_relocated")
    if (length(.nm_reloc) == 1L && !is.na(.nm_reloc))
      showNotification(sprintf("The first column was not a numeric wavelength axis, so column '%s' was used as the wavelength (nm) axis. If that is wrong, put the wavelength column first.",
                               .nm_reloc), type = "warning", duration = 12, session = session)
    nm_min <- floor(min(df$nm, na.rm=TRUE)); nm_max <- ceiling(max(df$nm, na.rm=TRUE))
    updateSliderInput(session,"analysis_nm", min=nm_min, max=nm_max, value=c(nm_min, nm_max), step=1)
    .prov_mark("analysis_nm", c(nm_min, nm_max), "auto")
    { .bwb <- .baseline_win_bounds(nm_min, nm_max)
      updateSliderInput(session,"baseline_win", min=.bwb$min, max=.bwb$max, value=.bwb$value, step=1) }
    for(id in c("qy","pbs","car","bx")) updateSliderInput(session,id, min=nm_min, max=nm_max)
    rng <- sort(c(max(350,nm_min), min(750,nm_max)))
    updateSliderInput(session,"probe_slider", min=rng[1], max=rng[2], value=min(max(680,rng[1]), rng[2]))
    loaded_source(src_prov)
    last_good_dat(df); dat_err(NULL); dat_value(df); detected_meta(meta); controls_ready(TRUE)
    invisible()
  }

  .load_release_current <- function() {
    if (!is.null(load_env$release)) {
      tok <- load_env$release
      ok <- isTRUE(tryCatch({ tok(); TRUE }, error = function(e) FALSE))
      load_env$release <- NULL
      if (!isTRUE(ok)) {
        load_env$stop_state <- "RELEASE_PENDING_OWNERSHIP_RETAINED"
        .pasa_orphan_enroll(NULL, tok, task_id = "load_bg_release")
        return(invisible(FALSE))
      }
    }
    load_env$holds_task <- FALSE
    invisible(TRUE)
  }
  .LOAD_REAP_MAX <- 20L; .LOAD_REAP_DELAY <- 0.25
  .load_reap_handle <- function(h, rel) {
    if (is.null(h)) { if (is.function(rel)) rel(); return(invisible()) }
    tries <- 0L
    reap <- function() {
      if (identical(.pasa_task_stop_once(h), "TERMINAL_CONFIRMED")) {
        if (identical(load_env$mirai, h)) { load_env$mirai <- NULL; load_env$active <- FALSE }
        load_env$stop_state <- "STOP_CONFIRMED"; load_env$holds_task <- FALSE
        # RELEASE_PENDING on a faulting token: hand it to the durable reaper rather than losing it.
        if (is.function(rel) && !isTRUE(tryCatch({ rel(); TRUE }, error = function(e) FALSE))) {
          load_env$stop_state <- "RELEASE_PENDING_OWNERSHIP_RETAINED"; load_env$holds_task <- TRUE
          .pasa_orphan_enroll(NULL, rel, task_id = "load_bg_release")
        }
        return(invisible())
      }
      tries <<- tries + 1L
      if (tries >= .LOAD_REAP_MAX) {
        # Durable handoff: enroll the CAPTURED {handle, one-shot token} in the PROCESS-GLOBAL orphan registry rather than
        # merely returning from this session-scoped closure (whose env may vanish when the session ends), so a
        # possibly-live task is never left unowned with no reaper. The global reaper releases the slot exactly once when
        # the handle is proven terminal.
        load_env$stop_state <- "STOP_FAILED_OWNERSHIP_RETAINED_HANDED_OFF"
        .pasa_orphan_enroll(h, rel, task_id = "load_bg", attempts = tries)
        return(invisible())
      }
      later::later(reap, delay = .LOAD_REAP_DELAY)
    }
    later::later(reap, delay = .LOAD_REAP_DELAY)
    invisible()
  }
  .stop_load_bg <- function() {
    if (is.function(load_env$cancel)) {
      cancel <- load_env$cancel; load_env$cancel <- NULL
      stopped <- isTRUE(cancel())
      load_env$mirai <- NULL; load_env$release <- NULL
      load_env$active <- FALSE; load_env$holds_task <- FALSE
      load_env$stop_state <- if (stopped) "STOP_CONFIRMED" else "STOP_HANDED_TO_DURABLE_REAPER"
      return(invisible(stopped))
    }
    h <- load_env$mirai; rel <- load_env$release
    if (!is.null(h)) {
      obs <- .pasa_task_stop_once(h)
      if (!identical(obs, "TERMINAL_CONFIRMED")) {
        load_env$stop_state <- if (identical(obs, "STOP_FAULT")) "STOP_FAILED_OWNERSHIP_RETAINED"
                               else                              "STOP_REQUESTED_OWNERSHIP_RETAINED"
        .load_reap_handle(h, rel)                 # captured handle + token: releases the slot once when proven terminal
        return(invisible(FALSE))
      }
      load_env$mirai <- NULL                       # PROVEN terminal
    }
    load_env$stop_state <- "STOP_CONFIRMED"; load_env$active <- FALSE
    .load_release_current()                        # release the slot exactly once (idempotent one-shot token)
    invisible(TRUE)
  }
  session$onSessionEnded(function() .stop_load_bg())

  .launch_load_bg <- function(gen, use_file, path, ext, sh, deadline, src_name, src_prov, raw_bytes, heavy) {
    load_env$active <- TRUE
    finish <- function(df, execution_deadline = deadline) {
      if (!identical(load_env$gen, gen) || identical(load_env$done_gen, gen)) return(invisible())
      load_env$active <- FALSE; dat_loading(FALSE)
      load_env$mirai <- NULL; load_env$release <- NULL; load_env$cancel <- NULL; load_env$holds_task <- FALSE
      tryCatch(shiny::withReactiveDomain(session,
        .dat_commit(df, src_name, src_prov, execution_deadline, raw_bytes)),
        error = function(e) .load_keep_or_err(paste("The file could not be loaded:", conditionMessage(e))))
      load_env$done_gen <- gen
      invisible()
    }
    if (!isTRUE(heavy)) return(finish(.load_spectra_worker(use_file, path, ext, sheet = sh, deadline = deadline)))
    dat_loading(TRUE)
    job <- .run_io("load", list(use_file = use_file, path = path, ext = ext, sheet = sh),
      budget = .input_deadline_secs(), on_result = finish,
      on_error = function(message) finish(structure(list(), class = "pasa_load_error", msg = message), Sys.time() + 1))
    if (!is.null(job)) {
      load_env$mirai <- job$handle; load_env$release <- job$cleanup; load_env$cancel <- job$cancel
    }
    invisible()
  }

  # The state_injected_bump dependency lets a successful snapshot injection re-fire this load without a new click.
  observeEvent(list(input$load, input$load_demo, state_injected_bump()), {
    load_env$gen <- load_env$gen + 1L; gen <- load_env$gen   # a new load SUPERSEDES any in-flight read
    .stop_load_bg(); dat_loading(FALSE)

    inj <- state_injected_data()
    if (is.null(inj)) { pending_samples_restore(NULL); pending_decon_sample_restore(NULL) }
    if (!is.null(inj)) {
      .apply_loaded_data(inj, reset_values = !isTRUE(isolate(state_keep_ranges())))
      state_keep_ranges(FALSE)   # one-shot: only the restore that set it is affected
      loaded_source("Restored session data")
      last_good_dat(inj); dat_err(NULL); dat_value(inj); controls_ready(TRUE); return(invisible())   # in-memory -> commit synchronously
    }
    if (isTRUE(demo_flag())) {
      df <- builtin_demo_data()
      meta <- describe_axis(df$nm, original_first = df$nm[1], original_last = df$nm[nrow(df)])
      meta$n_samples <- ncol(df) - 1L
      detected_meta(meta)
      nm_min <- floor(min(df$nm)); nm_max <- ceiling(max(df$nm))
      updateSliderInput(session,"analysis_nm", min=nm_min, max=nm_max, value=c(nm_min, nm_max), step=1)
      .prov_mark("analysis_nm", c(nm_min, nm_max), "auto")
      updateSliderInput(session,"baseline_win", min=max(720,nm_min), max=nm_max,
                        value=c(max(720, min(nm_max-5,745)), min(nm_max,750)), step=1)
      for(id in c("qy","pbs","car","bx")) updateSliderInput(session,id, min=nm_min, max=nm_max)
      rng <- sort(c(max(350,nm_min), min(750,nm_max)))
      updateSliderInput(session,"probe_slider", min=rng[1], max=rng[2], value=min(max(680,rng[1]), rng[2]))
      loaded_source("Built-in synthetic demo dataset (no external file)")
      last_good_dat(df); dat_err(NULL); dat_value(df); controls_ready(TRUE); return(invisible())   # in-memory -> commit synchronously
    }
    # Respect the Data-source toggle so a stale upload does not override a URL (or vice versa); fall back to the
    # file-then-path priority if the toggle is unset (an older saved session).
    src <- input$data_source %||% "auto"
    use_file <- if (src == "local") isTruthy(input$file$datapath)
                else if (src == "url") FALSE
                else isTruthy(input$file$datapath)          # auto
    use_path <- if (src == "url") isTruthy(input$path)
                else if (src == "local") FALSE
                else (!use_file && isTruthy(input$path))     # auto
    if (!(use_file || use_path)) {
      .nosrc <- if (src == "url") "Enter a URL or path, then click Load data." else "Choose a file, then click Load data."
      .load_keep_or_err(.nosrc); return(invisible())
    }
    path <- if (use_file) input$file$datapath else input$path
    .source_auth <- .pasa_authorize_source(path,
      upload = if (use_file) input$file else NULL, session = session)
    if (!isTRUE(.source_auth$ok)) { .load_keep_or_err(.source_auth$reason); return(invisible()) }
    path <- .source_auth$path
    use_file <- identical(.source_auth$route, "upload") || (use_file && identical(.source_auth$route, "desktop"))
    sh <- if (isTruthy(input$sheet)) input$sheet else "index:1"
    sh <- if (startsWith(sh, "name:")) substring(sh, 6L) else if (identical(sh, "index:1")) 1L else sh
    deadline <- Sys.time() + .input_deadline_secs()
    pre_ext <- if (identical(path, input$file$datapath)) tolower(tools::file_ext(input$file$name)) else tolower(tools::file_ext(path))
    src_name <- if (use_file) input$file$name else input$path
    src_prov <- if (use_file) input$file$name else .sanitize_url_provenance(input$path)
    raw_bytes <- if (use_file) suppressWarnings(file.info(input$file$datapath)$size)
                 else if (is.character(path) && length(path) == 1L && file.exists(path)) suppressWarnings(file.info(path)$size)
                 else NA_real_
    heavy <- identical(.source_auth$route, "remote") || (is.finite(raw_bytes) && raw_bytes > .REMOTE_ASYNC_MIN_BYTES)   # URL / large -> off-worker
    .launch_load_bg(gen, use_file, path, pre_ext, sh, deadline, src_name, src_prov, raw_bytes, heavy)
  }, ignoreInit=TRUE)
  
  # Read-only 'detected' banner shown under the analysis-range slider after load.
  output$detected_info <- renderUI({
    m <- detected_meta()
    if(is.null(m) || !isTRUE(m$ok)) return(NULL)
    fmt <- function(x) format(round(x, 4), trim = TRUE, scientific = FALSE)
    order_txt <- if(isTRUE(m$nonmonotonic)) "non-monotonic (auto-sorted ascending)" else if(isTRUE(m$descending)) "descending (auto-sorted ascending)" else "ascending"
    step_txt  <- if(isTRUE(m$irregular)) paste0("~", fmt(m$step), " nm (irregular spacing)")
                 else paste0(fmt(m$step), " nm")
    div(class = "detected-info",
      tags$strong("Detected: "),
      sprintf("%s\u2013%s nm \u00B7 step %s \u00B7 %d points \u00B7 %d sample%s \u00B7 source order %s",
              fmt(m$min), fmt(m$max), step_txt, m$n,
              m$n_samples, if(m$n_samples == 1L) "" else "s", order_txt)
    )
  })
  
  output$controls_ui <- renderUI({
    req(isTRUE(controls_ready()))
    pasa_controls_layout(tagList(
      # Show the analysis range only after data are loaded. The section also
      # hosts the organism selector and sample-type toggle.
      h4_tip("Analysis range & pigment system", "Restrict processing to a wavelength interval, choose an organism/pigment-system preset, and declare the sample class. These choices control configurable wavelength-window labels and defaults; they do not establish pigment identity."),

      tags$div(style="font-weight:600;margin:4px 0 2px;", "Wavelength range"),
      with_tip(sliderInput("analysis_nm","Use only this \u03bb-range", min=300, max=800, value=c(350,750), step=1),
               "Restricts the reported analysis curves, metrics, AUC, normalization, peaks, plots and processed exports to this wavelength interval. Baseline lookup is the documented exception: it searches the full loaded source and may use measured points outside this range. A single-nm request uses the nearest eligible native measured node; a window median requires at least three eligible native measured points. Per-sample requested/effective baseline details are archived in Metrics exports."),
      tags$div(style="font-weight:600;margin:10px 0 2px;", "Organism / pigment system"),
      with_tip(selectInput("organism", NULL, choices = .ORGANISM_CHOICES, selected = "cyano"),
               "Loads configurable starting wavelength windows and labels for the declared organism class. Selecting a preset overwrites the band sliders below; PASA does not verify pigment composition or molecular identity. Scope: these presets do not cover Chl c/d/f systems."),
      conditionalPanel("input.organism != 'plants'",
        tags$div(style="font-weight:600;margin:10px 0 2px;", "Sample type"),
        uiOutput("sample_type_ui")
      ),

      tags$hr(),
      h4_tip("Samples", "Select samples for analysis-dependent plots and calculations. Exception: Per-sample QC inventories all loaded columns; deselected columns are explicitly Not evaluated for analysis-dependent diagnostics, while raw-file and high-correlation candidate checks remain visible."),
      div(class="btn-group", role="group",
        actionButton("select_all","Select all", class="btn-sm btn-outline-primary"),
        actionButton("clear_all","Clear", class="btn-sm btn-outline-secondary")
      ),
      uiOutput("samples_ui"),

      # Spectra display and curve-style controls are defined in the Spectra tab.

      tags$hr(),
      # ---- Bands (nm) ----
      h4_tip("Bands (nm)", "Define wavelength windows for reported spectral regions. AUC and peak metrics are computed within these ranges. The displayed labels adapt to the organism + sample type; they do not establish molecular identity."),
      uiOutput("qy_slider_ui"),
      uiOutput("band3_label"),
      uiOutput("band3_slider_ui"),
      uiOutput("chlb_qy_slider_ui"),
      uiOutput("pe_slider_ui"),
      with_tip(sliderInput("car","Carotenoid", min=350, max=750, value=c(430,520), step=1),
               "Carotenoid absorption window. Default 430\u2013520 nm. Covers \u03b2-carotene (~450 nm), zeaxanthin (~490 nm) and related species. Note: 430\u2013460 nm overlaps the Soret/Bx band; adjust both windows if needed for your pigment system."),
      with_tip(sliderInput("bx","Soret / Bx", min=350, max=750, value=c(420,460), step=1),
               "Chlorophyll Soret (B) band: the strong blue absorption region. Default 420\u2013460 nm. Relative Soret and Qy amplitudes depend on pigment composition, solvent or protein environment, path length, concentration, blanking, and instrument response; PASA assumes no universal Soret/Qy ratio. Note partial overlap with the carotenoid band at 430\u2013460 nm."),
      actionButton("reset_bands","Reset Bands to Defaults", class="btn-sm btn-outline-secondary"),
      uiOutput("band_overlap_notice"),

      # Probe and peak controls are defined in the Spectra tab.

      tags$hr(),
      h4_tip("Baseline", "Baseline correction subtracts one assumed additive reference value. It may reduce offset but does not prove that the reference wavelength is absorption-free or remove wavelength-dependent background."),
      with_tip(checkboxInput("apply_baseline", "Apply baseline correction", value=TRUE),
               "When unchecked, spectra and raw-basis AUC use the uploaded values before PASA baseline subtraction. Normalization is disabled and baseline-residual QC is not evaluated. The illustrative D65/CIE sRGB mapping remains available from the final unbaselined analysis curve."),
      conditionalPanel("input.apply_baseline",
        # Method selector with inline info for each choice
        tags$div(style="margin-bottom:4px;",
          radioButtons("baseline_method", NULL,
                       choiceNames = list(
                         HTML("Single nm <span title=\"The entered wavelength is a request. PASA subtracts the value at the nearest eligible native measured node in the full loaded source, which may be outside the selected analysis range; requested and effective wavelengths are archived. The result remains sensitive to noise, blank mismatch, residual absorption, and wavelength-dependent background.\" class=\"info-tip\" style=\"cursor:help;margin-left:4px;font-size:0.85em;\">\u24d8</span>"),
                         HTML("Window median baseline <span title=\"Subtracts the median only when at least three eligible native measured points occur in the requested window of the full loaded source. Those points may be outside the selected analysis range. Requested/effective bounds, point count, statistic, and outside-range use are archived.\" class=\"info-tip\" style=\"cursor:help;margin-left:4px;font-size:0.85em;\">\u24d8</span>")
                       ),
                       # NOTE: the internal choiceValue stays "window_min" for state/round-trip
                       # and server-logic compatibility; only the user-visible label is the median.
                       choiceValues = list("single_nm", "window_min"),
                       selected = "single_nm", inline = TRUE)
        ),
        uiOutput("baseline_input_error"),
        # Single nm controls — info delivered via tooltip icons, no permanent alert box
        conditionalPanel("input.baseline_method == 'single_nm'",
          with_tip(numericInput("baseline_nm","Baseline @ nm", value=750, min=350, max=750, step=1),
                   "Single nm: this is the requested reference. PASA subtracts the value at the nearest eligible native measured node in the full loaded source, which may differ from the request and may lie outside the selected analysis range. Requested/effective wavelengths and outside-range use are archived. Choose a study-justified low-analyte reference; 750 nm is an operational starting value, not a universal absorption-free wavelength."
          )
          # Inline warnings for <730 nm are shown as server-side showNotification()
        ),
        # Window median controls — info delivered via tooltip icons, no permanent alert box
        conditionalPanel("input.baseline_method == 'window_min'",
          with_tip(sliderInput("baseline_win","Baseline window (nm)", min=720, max=750, value=c(745,750), step=1),
                   "Window median: subtracts the median only when at least three eligible native measured points occur in this requested window of the full loaded source. The effective measured bounds, point count, statistic, and any use outside the selected analysis range are archived. A window with fewer than three eligible points is refused and is not relocated. Choose a study-justified region expected to be approximately flat and low in analyte absorption."
          )
          # Inline warnings for <730 nm lower bound are shown as server-side showNotification()
        ),
      ),
      
      tags$hr(),
      # ---- Signal conditioning: groups Resampling + Smoothing (related but
      # distinct operations) under one section heading. ----
      h4_tip("Signal conditioning", "Operations that condition the raw signal before metrics: resampling puts every sample on a common wavelength grid (linear interpolation when up-sampling, integral-based bin averaging when down-sampling). Down-sampling only targets full-range trapezoidal-area preservation when source-range, coverage, and bin-edge conditions permit; arbitrary band AUC can change. Smoothing reduces random noise on the same axis. They are different steps but belong to the same family."),
      tags$div(style="font-weight:600;margin:4px 0 2px;", "Resampling"),
      with_tip(checkboxInput("resample_on","Resample to fixed grid", value=FALSE),
               "Optionally puts samples onto a common evenly-spaced wavelength axis. A finer/equal target uses linear interpolation (estimated values, not new measurements); a coarser target uses integral-based bin averaging. Binning targets full-range trapezoidal-area preservation when coverage, range, and edge-bin conditions permit, but arbitrary band AUC can change when bins straddle band boundaries."),
      with_tip(numericInput("grid_step","Grid step (nm)", value=1, min=0.1, step=0.1),
               "Spacing between grid points in nm. Smaller values preserve more detail; 1 nm is standard."),
      tags$div(style="font-weight:600;margin:10px 0 2px;",
               "Smoothing", .tip_icon("Optional display/processed-basis filtering after resampling. It affects the displayed processed curve and outputs that explicitly use the smoothed or normalized basis. Similarity, noise QC, and deconvolution use their documented native or internal paths and are not governed by this display toggle. Savitzky–Golay and moving-average settings can shift, broaden, or distort features; inspect sensitivity.")),
      radioButtons("smooth", NULL,
                   choiceNames = list(
                     HTML("None <span title=\"No smoothing applied. Use this when the data is already low-noise or when you want to inspect raw features. All downstream metrics use the unsmoothed signal.\" class=\"info-tip\" style=\"cursor:help;margin-left:4px;font-size:0.85em;\">\u24d8</span>"),
                     HTML("Savitzky\u2013Golay <span title=\"Fits a local polynomial over a moving window. Under suitable window/order settings it can retain local feature shape better than a same-width boxcar, but it can still shift, broaden, or distort features; inspect sensitivity.\" class=\"info-tip\" style=\"cursor:help;margin-left:4px;font-size:0.85em;\">\u24d8</span>"),
                     HTML("Moving avg <span title=\"Boxcar filter: replaces each point with the mean of n surrounding points. Simple and fast, but broadens peaks slightly and does not preserve peak positions as well as Savitzky\u2013Golay. Useful when peak sharpness is less important than a smooth baseline.\" class=\"info-tip\" style=\"cursor:help;margin-left:4px;font-size:0.85em;\">\u24d8</span>")
                   ),
                   choiceValues = list("none", "sgolay", "moving_average"),
                   selected = "none", inline = TRUE),
      conditionalPanel("input.smooth == 'sgolay'",
        with_tip(sliderInput("sg_n","Savitzky\u2013Golay: window (pts)", min=1, max=20, value=11, step=1),
                 "Savitzky\u2013Golay smoothing fits a local polynomial over a moving window. Under suitable settings it can retain local feature shape better than a same-width boxcar, but window, order, and grid choice can shift, broaden, or distort features. Inspect sensitivity."),
        with_tip(sliderInput("sg_p","SG polynomial degree", min=2, max=5, value=3, step=1, ticks=FALSE),
                 "Polynomial degree for the Savitzky\u2013Golay filter. Higher p (e.g. 4\u20135) preserves narrower features; lower p (e.g. 2\u20133) smooths more aggressively. The window n must be > p and odd; the app enforces this automatically.")
      ),
      conditionalPanel("input.smooth == 'moving_average'",
        with_tip(sliderInput("ma_k","Moving avg: window (pts)", min=1, max=20, value=7, step=1),
                 "Moving average (boxcar) filter: replaces each point with the mean of n surrounding points. Simple and fast, but broadens peaks slightly and does not preserve peak positions as well as Savitzky\u2013Golay. Useful when peak sharpness is less important than a smooth baseline.")
      ),
      
      tags$hr(),
      h4_tip("Scaling / Normalization",
             "The dilution factor applies the entered nominal scale. It represents an undiluted-equivalent absorbance scale only under the documented linear-response, blank/reference, path-length, unit, matrix, preprocessing, and instrument assumptions; it is not an absolute concentration correction. Normalization removes a uniform multiplicative scale and sacrifices amplitude information; it does not identify the physical cause of that scale. Normalization is applied after baseline correction."),
      with_tip(numericInput("dilution","Global dilution correction factor", value=1, min=0.0001, step=0.1),
               "Multiplies measured absorbance by this nominal scale factor for every sample without an individual factor. A factor equal to the recorded dilution gives an undiluted-equivalent absorbance scale only when Beer–Lambert linearity, blank treatment, path length, matrix, and instrument response are appropriate and matched; it does not recover concentration or correct scattering/non-linearity. Values <=0 are treated as 1.\n\nWhen normalization is active, it rescales each curve, so the factor's amplitude effect is no longer visible in the Spectra graph. The factor is still applied to absorbance values reported in Metrics (OD-at-peak, AUC)."),
      tags$details(style="margin:2px 0 6px;",
        tags$summary(style="cursor:pointer;font-size:0.9em;",
          "Individual dilution correction factor",
          .tip_icon("Optional per-sample override of the Global dilution correction factor. Opens a row for each checked sample; a finite value > 0 replaces the global factor for that sample only, while a blank (or ≤0) row falls back to the global factor. Use it when samples were diluted by different amounts.")),
        div(style="padding:4px 2px 0;", uiOutput("per_sample_dilution_ui"))),
      with_tip(selectInput("norm_method","Normalization", .NORM_METHOD_CHOICES, selected="none"),
               "Normalization method applied after baseline correction and smoothing. Baseline correction must be enabled (conservative default) — multiplicative normalization is offset-SENSITIVE, so on raw OD still carrying a baseline offset it is biased and is blocked; it is valid on already-corrected data (see the Help note). Max \u2192 target scales the spectral maximum to the target. Value@\u03bb scales the value at a reference wavelength. Total area normalizes by the whole-spectrum AUC. Band peak / Band AUC normalize by a single band\u2019s peak or area. Because normalization is applied after final smoothing, the reported normalized band peak exactly equals the target value."),
      with_tip(numericInput("norm_target","Target value", value=1, min=.Machine$double.xmin, step=0.1),
               "All spectra are scaled so the chosen reference equals this value. Conventional target is 1 for ratio comparisons. Must be finite and strictly greater than 0; zero and negative targets are refused. Note: 'Total area \u2192 target' makes total AUC constant; band-ratio normalization-independence holds only for multiplicative methods."),
      conditionalPanel("input.norm_method == 'ref_nm_to'",
                       numericInput("norm_ref_nm","Reference λ (nm)", value=680, step=1)
      ),
      uiOutput("norm_band_ui"),

      tags$hr(),
      h4("Export / Download"),
      # Choose the table/text data format used by the data download buttons.
      with_tip(radioButtons("dl_data_fmt", "Data file format",
                  c("CSV"="csv", "Excel (.xlsx)"="xlsx", "Tab-text (.txt)"="txt"),
                  selected="csv", inline=TRUE),
               "Format for the processed-data, metrics and QC downloads. CSV and TXT are UTF-8 with BOM so symbols display correctly in Excel."),
      # Processed data: wide layout (one column per sample), split into pre- and
      # post-normalization so neither set of columns crowds out the other.
      tags$div(style="font-weight:600;margin:6px 0 2px;", "Processed data (wide)"),
      div(class="d-grid gap-2",
        downloadButton("dl_processed_pre",  "Pre-norm values",  class="btn-sm btn-outline-primary"),
        conditionalPanel("input.norm_method != 'none'",
          downloadButton("dl_processed_post", "Post-norm values", class="btn-sm btn-outline-primary")
        )
      ),
      # Tab-specific downloads live with their outputs: Metrics provides
      # XLSX/PDF; Spectra provides PDF/image; Band AUC provides per-chart
      # PDF/image; and Data Quality provides the QC report. Processed-data
      # downloads stay in this Analysis settings block; the session-snapshot
      # download is the header Save session button.
      tags$br(),
      # Session snapshot \u2014 synced pair (Analysis settings + Summary tab). The state
      # file written into the ZIP, and the header Save session download,
      # both honor these two checkboxes.
      tags$h5(
        "Session snapshot ",
        .tip_icon("A session snapshot is a single text file (PASA_state.txt) capturing the current analysis. Tick which sections to include, then click Save session in the header. Reload later by setting 'Data source' on the Input data tab to 'Import session' and uploading the file. Download everything (ZIP) always includes a full snapshot, regardless of these standalone-export checkboxes."),
        style="margin:6px 0 4px;"
      ),
      div(style="display:flex;flex-wrap:nowrap;gap:18px;margin-bottom:6px;align-items:center;",
        tags$div(style="flex:0 0 auto;margin:0;",
          with_tip(checkboxInput("snapshot_include_settings", "Settings", value=TRUE),
                   "Include all analysis / display / QC settings in the session snapshot, so the analysis can be reproduced after reload.")),
        tags$div(style="flex:0 0 auto;margin:0;",
          with_tip(checkboxInput("snapshot_include_data",     "Input data", value=TRUE),
                   "Include the active wide table, Cell Growth entries/mappings, and measured deconvolution blank (or an explicit no-blank marker) in the standalone snapshot."))),
      p(class="text-muted", "Use Save session or Export in the header to download your work."),
    ))
  })
  
  output$samples_ui <- renderUI({
    req(dat()); nm_col <- names(dat())[1]; choices <- setdiff(names(dat()), nm_col)
    # A combined data+settings restore already carries its intended selection in
    # pending_samples_restore(). Seed the remounted widget from that value in the
    # same render, but isolate it so setting/clearing the one-shot pending state
    # cannot itself trigger another remount. The existing observer below remains
    # the sole owner of clearing the pending value and recording provenance.
    pending <- isolate(pending_samples_restore())
    pending_txn <- if (is.null(pending)) NULL else attr(pending, "restore_txn")
    pending_live <- !is.null(pending) &&
      (is.null(pending_txn) || identical(pending_txn, isolate(restore_txn())))
    pending_has_selection <- isTRUE(pending_live) &&
      (length(pending) > 0L || isTRUE(attr(pending, "explicit_empty")))
    current <- if (pending_has_selection) pending else isolate(input$samples)
    selected <- .samples_selection_after_data_change(current, choices)
    checkboxGroupInput("samples", NULL, choices=choices, selected=selected)
  })
  observeEvent(list(pending_samples_restore(), dat()), {
    ps <- pending_samples_restore()
    sample_restore_apply_env$token <- sample_restore_apply_env$token + 1L
    .token <- sample_restore_apply_env$token
    if (is.null(ps)) return()
    if (!is.null(attr(ps, "restore_txn")) && !identical(attr(ps, "restore_txn"), isolate(restore_txn()))) {
      pending_samples_restore(NULL); return()
    }
    if (!length(ps) && !isTRUE(attr(ps, "explicit_empty"))) return()
    d <- tryCatch(dat(), error = function(e) NULL); if (is.null(d)) return()
    choices <- setdiff(names(d), names(d)[1])
    keep <- intersect(as.character(ps), choices)
    .explicit_empty <- !length(ps) && isTRUE(attr(ps, "explicit_empty"))
    .available <- .explicit_empty || length(keep) > 0L
    .target <- if (.explicit_empty) character(0) else if (length(keep)) keep else choices
    .prov <- if (.available) "restored" else "replaced_on_restore"
    if (!.available) {
      .n_un <- length(ps)
      showNotification(
        sprintf("%d restored sample selection%s %s unavailable in the loaded data and %s replaced by the current default (all samples).",
                .n_un, if (.n_un == 1L) "" else "s",
                if (.n_un == 1L) "was" else "were", if (.n_un == 1L) "was" else "were"),
        type = "warning", duration = 8)
    }
    # A renderUI replacement and updateCheckboxGroupInput can share one Shiny
    # flush. Clearing the pending value immediately made the update disappear if
    # the browser had not mounted the replacement checkbox group yet. Retry until
    # the browser echoes the exact target; only then consume the one-shot state.
    .attempt <- new.env(parent = emptyenv()); .attempt$n <- 0L
    .retry <- function() {
      if (!.restore_callbacks$alive()) return(invisible())
      if (!identical(.token, sample_restore_apply_env$token)) return(invisible())
      .live <- isolate(pending_samples_restore())
      if (is.null(.live)) return(invisible())
      .live_txn <- attr(.live, "restore_txn")
      if (!is.null(.live_txn) && !identical(.live_txn, isolate(restore_txn()))) {
        pending_samples_restore(NULL); return(invisible())
      }
      .cur <- isolate(input$samples)
      .confirmed <- if (!length(.target)) !isTruthy(.cur) else
        identical(as.character(.cur), as.character(.target))
      if (.confirmed) {
        restore_selection_provenance(.prov)
        pending_samples_restore(NULL)
        return(invisible())
      }
      updateCheckboxGroupInput(session, "samples", choices = choices, selected = .target)
      .attempt$n <- .attempt$n + 1L
      if (.attempt$n < 120L && requireNamespace("later", quietly = TRUE)) {
        .restore_callbacks$schedule(.retry, delay = 0.25)
      } else {
        pending_samples_restore(NULL)
        showNotification("Sample selection restore was not confirmed by the browser; check the selected samples before continuing.", type = "warning", duration = 12)
      }
      invisible()
    }
    session$onFlushed(.restore_callbacks$guard(function() .retry()), once = TRUE)
  }, ignoreNULL = FALSE, priority = -100)
  observeEvent(input$select_all, { req(dat()); nm_col <- names(dat())[1]
  updateCheckboxGroupInput(session,"samples", selected=setdiff(names(dat()), nm_col)) })
  observeEvent(input$clear_all, { updateCheckboxGroupInput(session,"samples", selected=character(0)) })

  # noise_qc_spar on the Data Quality tab is the single source of truth.

  # State-load workflow. When the user uploads a state file, parse it,
  # show a modal listing only the sections present, and apply on confirm.
  state_loaded <- reactiveVal(NULL)
  restored_dil <- reactiveVal(list())
  growth_cell_state <- reactiveVal(list())
  .growth_cell_state_set <- function(values) {
    if (is.null(values) || !length(values) || is.null(names(values))) return(invisible())
    current <- isolate(growth_cell_state())
    changed <- FALSE
    for (id in names(values)) {
      value <- suppressWarnings(as.numeric(values[[id]]))
      value <- if (length(value) == 1L && is.finite(value)) value else NA_real_
      old <- current[[id]]
      same <- length(old) == 1L &&
        ((is.na(old) && is.na(value)) || isTRUE(all.equal(old, value, tolerance = 0)))
      if (!same) {
        current[[id]] <- value
        changed <- TRUE
      }
    }
    if (changed) growth_cell_state(current)
    invisible()
  }
  dilution_restore_apply_env <- new.env(parent = emptyenv())
  dilution_restore_apply_env$key <- NULL
  dilution_restore_apply_env$attempt <- 0L
  dilution_restore_apply_env$stable <- 0L
  # Settings belonging to the dynamically inserted Deconvolution tab cannot be
  # updated before that tab exists. Retain their serialized values until the
  # mounted browser controls echo the restored state.
  pending_decon_settings_restore <- reactiveVal(NULL)
  decon_settings_restore_generation <- reactiveVal(0L)
  decon_restore_apply_env <- new.env(parent = emptyenv())
  decon_restore_apply_env$token <- 0L
  session$onSessionEnded(function() {
    decon_restore_apply_env$token <- decon_restore_apply_env$token + 1L
  })
  pending_growth_settings_restore <- reactiveVal(NULL)
  pending_spectral_settings_restore <- reactiveVal(NULL)
  restored_spectral_preset_choice <- reactiveVal(NULL)
  growth_restore_generation <- reactiveVal(0L)
  pending_growth_restore <- reactiveVal(NULL)
  # A newly requested dataset supersedes delayed writers from a prior restore.
  observeEvent(list(input$load, input$load_demo), {
    .restore_callbacks$reset()
    restore_txn(isolate(restore_txn()) + 1L)
    growth_restore_generation(isolate(growth_restore_generation()) + 1L)
    pending_growth_restore(NULL); pending_growth_settings_restore(NULL)
    pending_spectral_settings_restore(NULL)
    restored_spectral_preset_choice(NULL)
    pending_samples_restore(NULL); pending_decon_sample_restore(NULL)
    pending_decon_settings_restore(NULL)
  }, ignoreInit = TRUE, priority = 20)
 # browser security intentionally prevents code from
  # repopulating a fileInput.  A measured blank restored from a snapshot is
  # therefore held as typed in-session data and consumed by decon_blank_df().
  # A subsequent real upload clears/replaces this value.  Keeping this separate
  # from scalar Settings makes selective restore and atomic validation explicit.
  restored_decon_blank <- reactiveVal(list(active = FALSE, data = NULL))
  observeEvent(input$state_load, {
    req(input$state_load$datapath)
    .sz <- suppressWarnings(as.numeric(input$state_load$size))
    if (is.finite(.sz) && .sz > STATE_LIMITS$raw_bytes) {
      showNotification(sprintf("Snapshot rejected: it exceeds the %.0f MiB size limit (no state was loaded).",
                               STATE_LIMITS$raw_bytes / 1024 / 1024), type = "error", duration = 14)
      return(invisible())
    }
    txt <- tryCatch(readLines(input$state_load$datapath, warn = FALSE, encoding = "UTF-8", n = STATE_LIMITS$max_lines + 2L),
                    error = function(e) NULL)
    if (is.null(txt)) { showNotification("Snapshot rejected: the file could not be read.", type = "error", duration = 10); return(invisible()) }
    .vs <- .validate_snapshot_structure(txt)
    if (!isTRUE(.vs$ok)) {
      showNotification(paste0("Snapshot rejected — ", paste(.vs$errors, collapse = "; "), ". No state was loaded."),
                       type = "error", duration = 16)
      return(invisible())
    }
    parsed <- parse_state_text(txt)
    state_loaded(parsed)
    have_set    <- !is.null(parsed$SETTINGS)
    have_data   <- !is.null(parsed$SIDEBAR_DATA) && length(parsed$SIDEBAR_DATA) > 1
    have_growth <- !is.null(parsed$GROWTH_DATA)  && length(parsed$GROWTH_DATA)  > 0
    have_blank  <- !is.null(parsed$DECON_BLANK_DATA)
    showModal(modalDialog(
      title = "Apply saved session",
      p("Select which sections from the uploaded session snapshot to apply:"),
      if (have_set)    checkboxInput("state_apply_settings", "Settings",         value = TRUE),
      if (have_data)   checkboxInput("state_apply_data",     "Input data",       value = TRUE),
      if (have_growth) checkboxInput("state_apply_growth",   "Cell Growth data", value = TRUE),
      if (have_blank)  checkboxInput("state_apply_blank",    "Measured deconvolution blank", value = TRUE),
      if (!have_set && !have_data && !have_growth && !have_blank)
        div(em("No recognized sections found in this file.")),
      if (have_data) div(class = "text-muted", style = "font-size:0.85em; margin-top:8px;",
        em("Input data from the snapshot will be loaded on the Input data tab as the active dataset. The wavelength range and band sliders will be re-detected from it.")),
      footer = tagList(
        modalButton("Cancel"),
        actionButton("state_apply_confirm", "Apply selected", class = "btn-primary")
      ),
      easyClose = TRUE
    ))
  })

