      e("radio", "metrics_layout","qc_view"),
      # WRITTEN for readability but NOT auto-restored (restoring fires a clobbering observer; the underlying
      # windows/numerics round-trip directly): the preset label, the decon sample-class apply-on-select.
      e("none", "preset",             restore = "skip_clobber_preset"),
      e("none", "decon_sample_class", restore = "skip_clobber_decon_class")
    )
  })
  .snap_reg_ids <- function(r) .SNAPSHOT_SETTINGS_REGISTRY$key[.SNAPSHOT_SETTINGS_REGISTRY$route == r]
  .snap_default  <- function(key) { i <- match(key, .SNAPSHOT_SETTINGS_REGISTRY$key)
                                     if (is.na(i)) NULL else .SNAPSHOT_SETTINGS_REGISTRY$default[[i]] }
  .snap_bounds   <- function(key) { i <- match(key, .SNAPSHOT_SETTINGS_REGISTRY$key); if (is.na(i)) NULL else .SNAPSHOT_SETTINGS_REGISTRY$bounds[[i]] }
  .snap_excluded <- function() .SNAPSHOT_EXCLUSION_REASONS

