  .registry_reset_plan <- function(session) {
    reg <- .SNAPSHOT_SETTINGS_REGISTRY
    for (i in seq_len(nrow(reg))) {
      key <- reg$key[i]; route <- reg$route[i]
      if (route %in% c("none", "excluded", "dilution_family")) next
      d <- .snap_default(key)
      op  <- reg$reset[[i]]
      res <- if (is.function(op)) op(session, key, d) else list(pv = NULL)
      if (!is.null(res$pv)) .prov_mark(key, res$pv, "default")
    }
    invisible()
  }

  # Helper: dispatch a single key=value setting to the correct update*Input.
  # Returns TRUE if a known control was updated, FALSE if the key has no
  # mapping in the current UI (silently ignored for forward/backward compat).
  .apply_one_setting <- function(session, key, val) {
    if (is.null(val) || is.na(val)) return(FALSE)
    reg <- .SNAPSHOT_SETTINGS_REGISTRY
    if (grepl("^dil_", key)) return(isTRUE(.SNAP_ROUTE_OPS$dilution_family$apply(session, key, val)))
    i <- match(key, reg$key)
    if (!is.na(i)) { op <- reg$apply[[i]]; if (is.function(op)) return(isTRUE(op(session, key, val))) }
    # A bare composite range key (<key>_lo / <key>_hi) is not a registry key; .apply_settings reassembles the pair into
    # the single range key above, so a lone _lo/_hi line is a no-op here (forward/backward compat).
    FALSE
  }

  # Apply all settings in a parsed key/value list. Handles paired _lo/_hi keys
  # for range sliders (analysis_nm, baseline_win) by combining them first.
  .apply_settings <- function(session, kv) {
    if (is.null(kv)) kv <- list()
    # Normalize accepted snapshot depth aliases while preserving the saved
    # k_max under the tested/advanced policy.
    if (!is.null(kv$decon_depth))
      kv$decon_depth <- .decon_depth_migrate(kv$decon_depth, kv$decon_kmax %||% NA_real_)
    .restore_callbacks$reset()
    .txn <- isolate(restore_txn()) + 1L
    restore_txn(.txn)
    restored_spectral_preset_choice(list(
      organism = kv$organism %||% .snap_default("organism"),
      sample_type = kv$sample_type %||% .snap_default("sample_type")))
    # A new Settings transaction supersedes any delayed growth writer from an
    # earlier snapshot.  Invalidate that callback before resetting controls;
    # a selected GROWTH_DATA section immediately establishes its own fresh
    # generation below.
    pending_growth_restore(NULL)
    pending_spectral_settings_restore(NULL)
    growth_restore_generation(isolate(growth_restore_generation()) + 1L)
    .decon_restore_gen <- isolate(decon_settings_restore_generation()) + 1L
    decon_settings_restore_generation(.decon_restore_gen)
    tryCatch(.registry_reset_plan(session), error = function(e) NULL)
    tryCatch({
      prev_dil_ids <- unlist(.dil_ids(isolate(if (isTruthy(input$samples)) input$samples else character(0))))
      for (.did in prev_dil_ids) updateNumericInput(session, .did, value = NA)
    }, error = function(e) NULL)
    restored_dil(list())
    pending_decon_settings_restore(NULL)
    pending_growth_settings_restore(NULL)
    pending_samples_restore(NULL)
    pending_decon_sample_restore(NULL)
    if (is.null(kv[["analysis_nm"]]) && (!is.null(kv[["analysis_nm_lo"]]) || !is.null(kv[["analysis_nm_hi"]]))) {
      lo <- suppressWarnings(as.numeric(kv[["analysis_nm_lo"]]))
      hi <- suppressWarnings(as.numeric(kv[["analysis_nm_hi"]]))
      if (isTRUE(is.finite(lo)) && isTRUE(is.finite(hi))) kv$analysis_nm <- paste0(lo, ",", hi)
    }
    if (is.null(kv[["baseline_win"]]) && (!is.null(kv[["baseline_win_lo"]]) || !is.null(kv[["baseline_win_hi"]]))) {
      lo <- suppressWarnings(as.numeric(kv[["baseline_win_lo"]]))
      hi <- suppressWarnings(as.numeric(kv[["baseline_win_hi"]]))
      if (isTRUE(is.finite(lo)) && isTRUE(is.finite(hi))) kv$baseline_win <- paste0(lo, ",", hi)
    }
    for (bs in c("qy","pbs","chlb_qy","pe","car","bx")) {
      lo <- kv[[paste0(bs,"_lo")]]; hi <- kv[[paste0(bs,"_hi")]]
      if (is.null(kv[[bs]]) && (!is.null(lo) || !is.null(hi))) {
        lo <- suppressWarnings(as.numeric(lo)); hi <- suppressWarnings(as.numeric(hi))
        if (isTRUE(is.finite(lo)) && isTRUE(is.finite(hi))) kv[[bs]] <- paste0(lo, ",", hi)   # length-safe (a lone _lo -> numeric(0))
      }
    }
    .stamp <- function(v) { attr(v, "restore_txn") <- .txn; v }
    if (!is.null(kv$samples_json)) {
      selj <- tryCatch(as.character(jsonlite::parse_json(kv$samples_json, simplifyVector = TRUE)), error = function(e) NULL)
      if (!is.null(selj)) {
        selj <- selj[nzchar(selj)]
        pending_samples_restore(.stamp(if (length(selj)) selj else structure(character(0), explicit_empty = TRUE)))
      }
    } else if (!is.null(kv$samples)) {
      sel <- strsplit(kv$samples, "", fixed = TRUE)[[1]]
      sel <- sel[nzchar(sel)]
      pending_samples_restore(.stamp(if (length(sel)) sel else structure(character(0), explicit_empty = TRUE)))
    }
    if (!is.null(kv$decon_sample) && nzchar(kv$decon_sample))
      pending_decon_sample_restore(.stamp(kv$decon_sample))
    else
      pending_decon_sample_restore(structure("", restore_txn = .txn, reset_to_default = TRUE))
    for (k in names(kv)) {
      tryCatch(.apply_one_setting(session, k, kv[[k]]),
               error = function(e) FALSE)
    }
    .decon_keys <- setdiff(names(kv)[grepl("^decon_", names(kv))],
                           c("decon_sample", "decon_sample_class"))
    if (length(.decon_keys))
      pending_decon_settings_restore(list(
        generation = .decon_restore_gen,
        restore_txn = .txn,
        values = kv[.decon_keys]))
    .growth_keys <- names(kv)[grepl("^growth_", names(kv))]
    if (length(.growth_keys))
      pending_growth_settings_restore(list(
        restore_txn = .txn,
        values = kv[.growth_keys]))
    # The first successful data load mounts the Analysis settings controls after this handler has
    # sent its initial updates. Organism/sample-type echoes can subsequently
    # redraw band controls and apply their presets. Keep selected spectral
    # settings until those mounted controls acknowledge stable consumed values.
    .spectral_keys <- intersect(names(kv), c(
      "organism", "sample_type", "analysis_nm", "qy", "pbs", "chlb_qy",
      "pe", "car", "bx", "baseline_method", "baseline_nm", "baseline_win",
      "apply_baseline", "smooth", "sg_n", "sg_p", "ma_k", "resample_on",
      "grid_step", "dilution", "norm_method", "norm_target", "norm_ref_nm",
      "norm_band"))
    .spectral_values <- kv[.spectral_keys]
    # These two reset defaults also participate when omitted by an older
    # snapshot, so an intermediate factory echo cannot end preset protection.
    .spectral_values$organism <- kv$organism %||% .snap_default("organism")
    .spectral_values$sample_type <- kv$sample_type %||% .snap_default("sample_type")
    pending_spectral_settings_restore(list(restore_txn = .txn,
                                           values = .spectral_values))
    if (isTRUE(isolate(input$advanced_mode)) && exists("sync_decon_sample", inherits = TRUE))
      tryCatch(sync_decon_sample(), error = function(e) NULL)
    invisible()
  }

  observeEvent(list(pending_spectral_settings_restore(), controls_ready()), {
    pending <- pending_spectral_settings_restore()
    if (is.null(pending) || !isTRUE(controls_ready())) return()
    txn <- pending$restore_txn
    keys <- names(pending$values)
    reg <- .SNAPSHOT_SETTINGS_REGISTRY
    targets <- lapply(keys, function(key) {
      i <- match(key, reg$key)
      reg$parse[[i]](pending$values[[key]])
    })
    names(targets) <- keys
    keys <- keys[!vapply(targets, is.null, logical(1))]
    # Hidden conditional panels keep their bindings, whereas these optional
    # renderUI controls do not exist for every pigment/normalization choice.
    # A legacy saved inactive value must not hold the transaction open.
    desired <- function(key) targets[[key]] %||% isolate(input[[key]]) %||% .snap_default(key)
    org <- desired("organism"); sample_type <- desired("sample_type")
    norm_method <- desired("norm_method")
    if (!org %in% c("green", "plants")) keys <- setdiff(keys, "chlb_qy")
    if (!(identical(org, "red") && identical(sample_type, "cells"))) keys <- setdiff(keys, "pe")
    if (identical(org, "plants")) keys <- setdiff(keys, "sample_type")
    if (!norm_method %in% c("band_peak_to", "band_auc_to") ||
        !nzchar(as.character(targets$norm_band %||% ""))) keys <- setdiff(keys, "norm_band")
    targets <- targets[keys]
    if (!length(keys)) { pending_spectral_settings_restore(NULL); return() }
    attempt <- new.env(parent = emptyenv())
    attempt$n <- 0L; attempt$stable <- 0L
    ack <- paste0("spectral:", txn)
    retry <- function() {
      if (!.restore_callbacks$alive()) return(invisible())
      live <- isolate(pending_spectral_settings_restore())
      if (is.null(live) || !identical(live$restore_txn, txn) ||
          !identical(isolate(restore_txn()), txn)) return(invisible())
      confirmed <- vapply(keys, function(key) {
        current <- isolate(input[[key]])
        echoed <- isolate(input[[paste0("pasa_spectral_ack_", key)]])
        identical(echoed, ack) &&
          isTRUE(all.equal(unname(current), unname(targets[[key]]),
                           tolerance = 0, check.attributes = FALSE))
      }, logical(1))
      attempt$stable <- if (all(confirmed)) attempt$stable + 1L else 0L
      if (attempt$stable >= 4L) {
        pending_spectral_settings_restore(NULL)
        return(invisible())
      }
      attempt$n <- attempt$n + 1L
      if (attempt$n > 120L) {
        pending_spectral_settings_restore(NULL)
        showNotification("Some restored spectral settings could not be confirmed by the browser; check the visible settings before analysis.",
                         type = "warning", duration = 12)
        return(invisible())
      }
      for (key in keys) {
        session$sendCustomMessage("pasa_restore_input_echo", list(
          id = key, value = unname(targets[[key]]), only_if_changed = TRUE,
          ack_id = paste0("pasa_spectral_ack_", key), ack_value = ack))
      }
      .restore_callbacks$schedule(retry, delay = 0.25)
      invisible()
    }
    session$onFlushed(.restore_callbacks$guard(retry), once = TRUE)
  }, ignoreNULL = FALSE)

  # Apply a [GROWTH_DATA] block. The first lines are mode/unit/interval/nrep,
  # then either an OD matrix (mode=manual) or map_R# lines (mode=sidebar).
  #
  # The manual OD grid (output$growth_manual_grid) is a renderUI that
  # depends on input$growth_nrep + input$growth_ntp. When we update those scalars
  # the grid is re-rendered \u2014 but only AFTER a full client-server round trip:
  # (1) we push nrep/ntp -> client, (2) client echoes new input values back, (3)
  # renderUI invalidates and re-emits the table, (4) the new numericInputs are
  # mounted on the client and only THEN echo their existence back to the server.
  # Poll for up to about 30 seconds (120 attempts at 0.25 seconds),
  # writing OD values only once the grid input slots are visible to the server.
  .apply_growth <- function(session, lines) {
    # Decode before any mutation. Selected-section preflight passes this same
    # typed object, so application cannot reinterpret missing rows differently.
    decoded <- if (inherits(lines, "pasa_growth_snapshot")) lines else
      .pasa_decode_growth_snapshot(lines, STATE_LIMITS$growth)
    if (!.restore_callbacks$alive()) return(invisible())
    .restore_gen <- isolate(growth_restore_generation()) + 1L
    growth_restore_generation(.restore_gen)
    pending_growth_restore(NULL)
    mode <- decoded$mode; nrep <- decoded$nrep
    ntp <- decoded$ntp; ntech <- decoded$ntech
    kv <- list(unit = decoded$unit, interval = decoded$interval)
    .growth_manual_value <- identical(mode, "manual")
    .growth_interval_value <- decoded$interval
    .push_growth_scalar <- function(id, value, update) {
      current <- isolate(input[[id]])
      if (!isTRUE(all.equal(unname(current), unname(value), tolerance = 0,
                            check.attributes = FALSE)))
        tryCatch(update(), error = function(e) NULL)
      if (length(value) == 1L && !is.na(value))
        tryCatch(session$sendCustomMessage(
          "pasa_restore_input_echo", list(id = id, value = unname(value),
                                          only_if_changed = TRUE)),
          error = function(e) NULL)
      invisible()
    }
    # The whole Cell Growth body is renderUI. Re-send each shape/value scalar
    # on every bounded retry so a late body remount cannot restore factory
    # defaults after the snapshot transaction has already applied once.
    .push_growth_scalars <- function() {
      .push_growth_scalar("growth_manual", .growth_manual_value,
        function() updateCheckboxInput(session, "growth_manual", value = .growth_manual_value))
      if (!is.null(kv$unit))
        .push_growth_scalar("growth_unit", kv$unit,
          function() updateRadioButtons(session, "growth_unit", selected = kv$unit))
      if (is.finite(.growth_interval_value))
        .push_growth_scalar("growth_interval", .growth_interval_value,
          function() updateNumericInput(session, "growth_interval", value = .growth_interval_value))
      if (is.finite(nrep))
        .push_growth_scalar("growth_nrep", nrep,
          function() updateNumericInput(session, "growth_nrep", value = nrep))
      if (.growth_manual_value) {
        if (is.finite(ntp))
          .push_growth_scalar("growth_ntp", ntp,
            function() updateNumericInput(session, "growth_ntp", value = ntp))
        .push_growth_scalar("growth_ntech", ntech,
          function() updateNumericInput(session, "growth_ntech", value = ntech))
      }
      invisible()
    }
    .push_growth_scalars()
    if (identical(mode, "manual")) {
      .state_values <- decoded$values
      .growth_cell_state_set(.state_values)
      pending_growth_restore(list(
        generation = .restore_gen,
        restore_txn = isolate(restore_txn()),
        values = .state_values,
        scalars = list(growth_manual = TRUE, growth_unit = decoded$unit,
                       growth_interval = decoded$interval, growth_nrep = nrep,
                       growth_ntech = ntech, growth_ntp = ntp)))
      # Polling write: try every ~250 ms for up to about 30 s. Each attempt checks
      # whether (a) the server-side reactive values for nrep/ntp have updated
      # AND (b) the LAST grid input slot exists (renderUI rendered, client echoed).
      write_grid <- function() {
        if (!length(.state_values)) return(0L)
        n_written <- 0L
        wr <- function(id, v) tryCatch({
          current <- suppressWarnings(as.numeric(isolate(input[[id]])))
          same <- if (is.finite(v)) length(current) == 1L &&
            isTRUE(all.equal(current, unname(v), tolerance = 0)) else
            !length(current) || (length(current) == 1L && !is.finite(current))
          if (!same) updateNumericInput(session, id, value = v)
          session$sendCustomMessage(
            "pasa_restore_input_echo",
            list(id = id, value = if (is.finite(v)) unname(v) else NULL,
                 only_if_changed = TRUE))
          n_written <<- n_written + 1L
        }, error = function(e) NULL)
        for (.id in names(.state_values)) wr(.id, .state_values[[.id]])
        n_written
      }
      attempts <- new.env()
      attempts$n <- 0L
      attempts$done <- FALSE
      attempts$stable <- 0L
      retry <- function() {
        if (!.restore_callbacks$alive()) return(invisible())
        if (attempts$done) return(invisible())
        .live_restore <- isolate(pending_growth_restore())
        if (is.null(.live_restore) ||
            !identical(.live_restore$generation, .restore_gen) ||
            !identical(isolate(growth_restore_generation()), .restore_gen) ||
            !identical(.live_restore$restore_txn, isolate(restore_txn()))) {
          attempts$done <- TRUE
          return(invisible())
        }
        attempts$n <- attempts$n + 1L
        .push_growth_scalars()
        # Wait for the target grid dimensions to echo. Cell writes are retried;
        # before mount they are harmless no-ops, and after mount their exact
        # values must echo for four consecutive checks before pending state clears.
        cur_nrep <- suppressWarnings(as.integer(isolate(session$input[["growth_nrep"]])))
        cur_ntp  <- suppressWarnings(as.integer(isolate(session$input[["growth_ntp"]])))
        cur_ntech <- suppressWarnings(as.integer(isolate(session$input[["growth_ntech"]])))
        cur_interval <- suppressWarnings(as.numeric(isolate(session$input[["growth_interval"]])))
        cur_unit <- as.character(isolate(session$input[["growth_unit"]]) %||% "")
        scalars_ready <- isTRUE(
          identical(isTRUE(isolate(session$input[["growth_manual"]])), .growth_manual_value) &&
          is.finite(cur_nrep) && identical(cur_nrep, as.integer(nrep)) &&
          is.finite(cur_ntp) && identical(cur_ntp, as.integer(ntp)) &&
          is.finite(cur_ntech) && identical(cur_ntech, as.integer(ntech)) &&
          (is.null(kv$unit) || identical(cur_unit, as.character(kv$unit))) &&
          (!is.finite(.growth_interval_value) ||
             isTRUE(all.equal(cur_interval, .growth_interval_value, tolerance = 0))))
        if (scalars_ready) {
          write_grid()
          .matches <- if (!length(.state_values)) TRUE else
            all(vapply(names(.state_values), function(.id) {
              .cur <- suppressWarnings(as.numeric(isolate(session$input[[.id]])))
              .target <- suppressWarnings(as.numeric(.state_values[[.id]]))
              if (length(.target) == 1L && is.finite(.target))
                length(.cur) == 1L && is.finite(.cur) &&
                  isTRUE(all.equal(.cur, .target, tolerance = 0))
              else is.null(isolate(session$input[[.id]])) ||
                !length(.cur) || !is.finite(.cur)
            }, logical(1)))
          .sample_pending <- isolate(pending_samples_restore())
          .same_txn_sample_pending <- !is.null(.sample_pending) &&
            identical(attr(.sample_pending, "restore_txn", exact = TRUE),
                      .live_restore$restore_txn)
          attempts$stable <- if (.matches && !.same_txn_sample_pending)
            attempts$stable + 1L else 0L
          # Require four consecutive echoes (~1 s) so a later renderUI rebuild
          # cannot wipe values after the first successful update.
          if (attempts$stable >= 4L) {
            pending_growth_restore(NULL)
            attempts$done <- TRUE
            return(invisible())
          }
        }
        if (attempts$n < 120L && requireNamespace("later", quietly = TRUE)) {
          .restore_callbacks$schedule(retry, delay = 0.25)
        } else {
          attempts$done <- TRUE
          pending_growth_restore(NULL)
          # An unconfirmed target must not revive from the remount cache later.
          .live_values <- lapply(names(.state_values), function(id) {
            value <- suppressWarnings(as.numeric(isolate(session$input[[id]])))
            if (length(value) == 1L && is.finite(value)) value else NA_real_
          })
          names(.live_values) <- names(.state_values)
          .growth_cell_state_set(.live_values)
          showNotification("Cell Growth restore was not confirmed by the browser; check the grid before continuing.", type = "warning", duration = 12)
        }
      }
      # First attempt fires immediately on next event-loop tick.
      if (requireNamespace("later", quietly = TRUE)) {
        .restore_callbacks$schedule(retry, delay = 0.25)
      } else {
        # Fallback: synchronous best-effort.
        write_grid()
      }
    } else {
      # mode = sidebar -> tracking wavelength + replicate->sample mapping.
      pending_growth_restore(list(
        generation = .restore_gen, restore_txn = isolate(restore_txn()), values = list(),
        scalars = list(growth_manual = FALSE, growth_unit = decoded$unit,
                       growth_interval = decoded$interval, growth_nrep = nrep)))
      if (!is.null(decoded$tracking_wl))
        updateSliderInput(session, "growth_wl", value = decoded$tracking_wl)
      maps <- decoded$maps
      apply_maps <- function() {
        for (mk in names(maps)) {
          i <- as.integer(sub("^map_R", "", mk))
          updateSelectizeInput(session, paste0("growth_map_", i), selected = maps[[mk]])
        }
      }
      # Same retry pattern for replicate->sample selectizeInputs.
      m_attempts <- new.env(); m_attempts$n <- 0L; m_attempts$done <- FALSE; m_attempts$stable <- 0L
      m_retry <- function() {
        if (!.restore_callbacks$alive()) return(invisible())
        if (m_attempts$done) return(invisible())
        if (!identical(isolate(growth_restore_generation()), .restore_gen)) {
          m_attempts$done <- TRUE
          return(invisible())
        }
        m_attempts$n <- m_attempts$n + 1L
        .push_growth_scalars()
        cur_nrep <- suppressWarnings(as.integer(isolate(session$input[["growth_nrep"]])))
        scalars_ready <- isTRUE(is.finite(cur_nrep) && identical(cur_nrep, nrep) &&
          !isTRUE(isolate(session$input[["growth_manual"]])))
        if (scalars_ready) {
          apply_maps()
          matches <- all(vapply(names(maps), function(mk) {
            id <- paste0("growth_map_", sub("^map_R", "", mk))
            identical(as.character(isolate(session$input[[id]])), as.character(maps[[mk]]))
          }, logical(1)))
          m_attempts$stable <- if (matches) m_attempts$stable + 1L else 0L
          if (m_attempts$stable >= 4L) {
            pending_growth_restore(NULL)
            m_attempts$done <- TRUE; return(invisible())
          }
        }
        if (m_attempts$n >= 120L) {
          m_attempts$done <- TRUE
          pending_growth_restore(NULL)
          showNotification("Cell Growth sample mappings were not confirmed by the browser; check the mapping for each replicate.", type = "warning", duration = 12)
          return(invisible())
        }
        if (requireNamespace("later", quietly = TRUE)) {
          .restore_callbacks$schedule(m_retry, delay = 0.25)
        }
      }
      if (length(maps)) {
        if (requireNamespace("later", quietly = TRUE)) {
          .restore_callbacks$schedule(m_retry, delay = 0.25)
        } else {
          apply_maps()
        }
      }
    }
    invisible()
  }

  observeEvent(input$state_apply_confirm, {
    parsed <- state_loaded()
    if (is.null(parsed)) { removeModal(); return(invisible()) }
    .sel <- c(if (isTRUE(input$state_apply_settings)) "SETTINGS",
              if (isTRUE(input$state_apply_data))     "SIDEBAR_DATA",
              if (isTRUE(input$state_apply_growth))   "GROWTH_DATA",
              if (isTRUE(input$state_apply_blank))    "DECON_BLANK_DATA")
    .pf <- .validate_snapshot(parsed, .sel)
    if (!isTRUE(.pf$ok)) {
      removeModal()
      showNotification(
        HTML(paste0("<b>Session not restored — the snapshot failed validation, so nothing was changed:</b><br>",
                    paste0("• ", htmltools::htmlEscape(.pf$errors), collapse = "<br>"))),
        type = "error", duration = 18)
      return(invisible())
    }
    .restore_callbacks$reset()
    pending_growth_restore(NULL); pending_growth_settings_restore(NULL)
    pending_spectral_settings_restore(NULL)
    pending_samples_restore(NULL); pending_decon_sample_restore(NULL)
    pending_decon_settings_restore(NULL)
    growth_restore_generation(isolate(growth_restore_generation()) + 1L)
    if (!(isTRUE(input$state_apply_settings) && !is.null(parsed$SETTINGS)))
      restore_txn(isolate(restore_txn()) + 1L)
    applied <- character(0)
    did_settings <- FALSE
    if (isTRUE(input$state_apply_settings) && !is.null(parsed$SETTINGS)) {
      kv <- .pf$prepared$settings
      .apply_settings(session, kv)
      did_settings <- TRUE
      applied <- c(applied, if (length(kv)) paste0("Settings (", length(kv), " keys)")
                            else "Settings (reset to defaults; no assignments in the snapshot)")
    }
    if (isTRUE(input$state_apply_growth) && !is.null(parsed$GROWTH_DATA)) {
      .apply_growth(session, .pf$prepared$growth)
      applied <- c(applied, "Cell Growth data")
    }
    if (isTRUE(input$state_apply_blank) && !is.null(parsed$DECON_BLANK_DATA)) {
      # Parsing is guaranteed by the all-sections preflight above.  The active
      # marker distinguishes an explicit `mode=none` replacement (clear the old
      # blank) from no blank section selected (preserve the current source).
      .bd <- .pf$prepared$blank
      restored_decon_blank(list(active = TRUE, data = .bd,
        upload_token = .decon_blank_upload_token(isolate(input$decon_scatter_blank))))
      .legacy_hash <- !is.null(.bd) && isTRUE(attr(.bd, "content_sha256_legacy_crlf", exact = TRUE))
      applied <- c(applied, if (is.null(.bd)) "Measured deconvolution blank (cleared)"
                            else paste0(sprintf("Measured deconvolution blank (%d points)", nrow(.bd)),
                                        if (.legacy_hash)
                                          " - legacy Windows CRLF hash accepted; the next export uses canonical LF"
                                        else ""))
    }
    if (isTRUE(input$state_apply_data) && !is.null(parsed$SIDEBAR_DATA)) {
      df_inj <- .pf$prepared$data
      if (!is.null(df_inj) && nrow(df_inj) > 0L && ncol(df_inj) >= 2L) {
        # Clear demo flag so dat() doesn't fall through to builtin_demo_data on
        # the next change of an unrelated input that happens to invalidate it.
        demo_flag(FALSE)
        state_injected_data(df_inj)
        # If Settings were ALSO restored in this same apply, tell the imminent data
        # load to keep the restored analysis-range / baseline / probe values (refresh
        # bounds only) instead of auto-resetting them from the new data's range.
        if (did_settings) state_keep_ranges(TRUE)
        # Bump the token to fire the dat() eventReactive (which then runs
        # .apply_loaded_data() and refreshes sliders + detected banner).
        state_injected_bump(isolate(state_injected_bump()) + 1L)
        applied <- c(applied, sprintf("Input data (%d points, %d samples)",
                                      nrow(df_inj), ncol(df_inj) - 1L))
      } else {
        showNotification(
          "Could not parse the [SIDEBAR_DATA] block from this snapshot \u2014 input data was not loaded.",
          type = "warning", duration = 8)
      }
    }
    removeModal()
    if (length(applied)) {
      .saved_methods <- parse_settings_block(parsed$SETTINGS)$numerical_methods_version
      .current_methods <- if (exists("PASA_METHODS_VERSION", inherits = TRUE))
        as.character(get("PASA_METHODS_VERSION", inherits = TRUE)) else NULL
      if (length(.current_methods) == 1L &&
          (is.null(.saved_methods) || !identical(as.character(.saved_methods), .current_methods))) {
        .origin <- if (is.null(.saved_methods)) "This snapshot does not identify its numerical methods version."
                   else paste0("This snapshot records numerical methods ", .saved_methods, ".")
        showNotification(paste(.origin, "Saved session content was accepted; results are recomputed with current corrected methods", .current_methods),
                         type = "message", duration = 14)
      }
      showNotification(paste0("Applied: ", paste(applied, collapse = ", "), "."),
                       type = "message", duration = 6)
    }
  }, ignoreInit = TRUE)

  # ==========================================================================
  # ADAPTIVE BAND ENGINE  — single source of truth for the active band set.
  # Every downstream feature (plot highlights, metrics ratios, OD-at-peak, AUC
  # tab, peaks/normalization selectors, QC, exports, ZIP) derives from band_set().
  # Effective sample type is forced to "protein" for plants (no toggle).
  # ==========================================================================
  eff_sample_type <- reactive({
    org <- if (isTruthy(input$organism)) input$organism else "cyano"
    if (identical(org, "plants")) return("protein")
    st <- if (isTruthy(input$sample_type)) input$sample_type else "protein"
    if (identical(st, "iso_pbp") && !(org %in% c("cyano", "red"))) return("protein")
    if (st %in% c("protein", "cells", "iso_pbp")) st else "protein"
  })

  output$sample_type_ui <- renderUI({
    org <- if (isTruthy(input$organism)) input$organism else "cyano"
    cur <- isolate(if (isTruthy(input$sample_type)) input$sample_type else "protein")
    show_iso <- org %in% c("cyano", "red")
    tip_style <- "cursor:help;margin-left:4px;font-size:0.85em;"
    names_list <- list(
      HTML(paste0("Protein sample <span title=\"Purified proteins or isolated thylakoid membranes (TM). The 600–650 nm band is interpreted as the chlorophyll Q",
                  "x / vibronic shoulder. Use this for purified pigment-protein complexes, isolated thylakoids, or any sample without intact phycobilisomes.\" class=\"info-tip\" style=\"",
                  tip_style, "\">ⓘ</span>")))
    vals_list <- list("protein")
    if (show_iso) {
      names_list <- c(names_list, list(
        HTML(paste0("Isolated phycobiliprotein <span title=\"A purified / isolated phycobiliprotein (e.g. phycocyanin, allophycocyanin), NOT whole cells. The 600–650 nm band is read as 'Phycobiliprotein' absorption (phycocyanin ~620 nm, allophycocyanin ~650 nm) rather than 'PBS' — the app does not assume an assembled phycobilisome, does not identify which phycobiliprotein, and does not quantify it. The Cell Growth tab stays locked (whole cells only); the phycoerythrin band is not auto-added.\" class=\"info-tip\" style=\"",
                    tip_style, "\">ⓘ</span>"))))
      vals_list <- c(vals_list, list("iso_pbp"))
    }
    names_list <- c(names_list, list(
      HTML(paste0("Cells / Lysate <span title=\"Whole cells or broken cells / lysate that still contain intact phycobilisomes. For cyanobacteria and red algae the 600–650 nm band is read as the phycobilisome (PBS) band. Selecting this also unlocks the Cell Growth tab.\" class=\"info-tip\" style=\"",
                  tip_style, "\">ⓘ</span>"))))
    vals_list <- c(vals_list, list("cells"))
    sel <- if (cur %in% unlist(vals_list)) cur else "protein"
    radioButtons("sample_type", NULL, choiceNames = names_list,
                 choiceValues = vals_list, selected = sel, inline = TRUE)
  })

  # ---- Band identity (labels + which bands are active) ----
  # Depends ONLY on organism + sample type, NEVER on slider values. This is what
  # the band-slider renderUIs read, so dragging a slider does not re-render (and
  # reset) the slider. band_set() builds on top of this and adds the live
  # from/to window values for downstream metrics/plots/exports.
  band_labels <- reactive({
    org <- if (isTruthy(input$organism)) input$organism else "cyano"
    st  <- eff_sample_type()
    has_chlb <- org %in% c("green", "plants")
    has_pe   <- identical(org, "red") && identical(st, "cells")
    band3_is_pbs     <- identical(st, "cells")   && org %in% c("cyano", "red")
    band3_is_iso_pbp <- identical(st, "iso_pbp") && org %in% c("cyano", "red")
    band3_label  <- if (band3_is_pbs) "PBS" else if (band3_is_iso_pbp) "Phycobiliprotein" else "Chl a Qx / Vibronic Band"
    band3_ui     <- if (band3_is_pbs) "PBS" else if (band3_is_iso_pbp) "Phycobiliprotein" else HTML("Chl <i>a</i> Q<sub>x</sub> / Vibronic Band")
    band3_tip    <- if (band3_is_pbs)
      "Phycobilisome (PBS) band: phycobiliproteins absorb here (phycocyanin ~620 nm, allophycocyanin ~650 nm). Default 600–650 nm. Read as PBS only for whole cells / lysate of cyanobacteria and red algae, where intact phycobilisomes are present."
    else if (band3_is_iso_pbp)
      "Phycobiliprotein band (600–650 nm): for an isolated phycobiliprotein this window reflects primarily phycocyanin (~620 nm) / allophycocyanin (~650 nm) absorption. Labeled 'Phycobiliprotein' — NOT 'PBS' (no assembled phycobilisome is assumed) and NOT a specific pigment identity (the app does not identify which phycobiliprotein, and does not quantify it)."
    else
      "Chlorophyll a Qx / vibronic band (600–650 nm). For purified protein / thylakoid-membrane samples (and all green-algae / plant samples) this 600–650 nm window is the Chl a Qx / vibronic shoulder, not phycobilisome (PBS) absorption."
    qy_label <- if (has_chlb) "Chl a Qy" else "Qy"
    qy_ui    <- if (has_chlb) HTML("Chl <i>a</i> Q<sub>y</sub>") else "Qy"
    qy_tip   <- if (has_chlb)
      "Chlorophyll a Qy analysis window: configurable 660–690 nm starting range. It is renamed Chl a Qy because the green-algae and plant presets report Chl b Qy in a separate configurable window; neither label establishes pigment identity."
    else
      "Chlorophyll Qy analysis window: configurable 660–690 nm starting range. Qy absorbance can be a study-specific relative descriptor when path length, dilution, baseline, sample matrix, and instrument are controlled; it is not chlorophyll concentration without an applicable absorption coefficient and verified measurement conditions. Whole-cell and thylakoid spectra require additional caution because package/flattening effects and scattering can distort apparent spectra."
    list(
      has_chlb = has_chlb, has_pe = has_pe, band3_is_pbs = band3_is_pbs,
      band3_is_iso_pbp = band3_is_iso_pbp,
      qy   = list(band=qy_label,    ui=qy_ui,    tip=qy_tip,    default=c(660,690)),
      pbs  = list(band=band3_label, ui=band3_ui, tip=band3_tip, default=c(600,650)),
      chlb = list(band="Chl b Qy",  ui=HTML("Chl <i>b</i> Q<sub>y</sub>"),
                  tip="Chlorophyll b Qy analysis window: a configurable 640–657 nm starting range for the green-algae and plant presets. PhotochemCAD provides reference solution spectra showing Chl b blue-shifted relative to Chl a; it does not validate this window for a user's sample conditions. The window overlaps 600–650 nm over 640–650 nm, so those AUCs are not additive there and the label does not establish pigment identity.",
                  default=c(640,657)),
      pe   = list(band="Phycoerythrin (PE)", ui="Phycoerythrin (PE)",
                  tip="Phycoerythrin (PE) analysis window: configurable 490–570 nm starting range shown for the red-algae Cells/Lysate preset. The window label does not establish PE identity or quantify it.",
                  default=c(490,570)),
      car  = list(band="Carotenoid", ui="Carotenoid",
                  tip="Carotenoid absorption window. Default 430–520 nm. Covers β-carotene (~450 nm), zeaxanthin (~490 nm). Note 430–460 nm overlaps the Soret/Bx band.",
                  default=c(430,520)),
      bx   = list(band="Soret / Bx", ui="Soret / Bx",
                  tip="Chlorophyll Soret (B) band: the strong blue absorption region. Default 420–460 nm. Relative Soret and Qy amplitudes depend on pigment composition, solvent or protein environment, path length, concentration, blanking, and instrument response; PASA assumes no universal Soret/Qy ratio.",
                  default=c(420,460))
    )
  })

  band_set <- reactive({
    L <- band_labels()
    mk <- function(key, slider, from, to) c(L[[key]], list(slider=slider, from=from, to=to))
    rows <- list(
      mk("qy",  "qy",  input$qy[1],  input$qy[2]),
      mk("pbs", "pbs", input$pbs[1], input$pbs[2])
    )
    if (L$has_chlb) rows <- c(rows, list(mk("chlb", "chlb_qy", input$chlb_qy[1], input$chlb_qy[2])))
    if (L$has_pe)   rows <- c(rows, list(mk("pe",   "pe",      input$pe[1],      input$pe[2])))
    rows <- c(rows, list(
      mk("car", "car", input$car[1], input$car[2]),
      mk("bx",  "bx",  input$bx[1],  input$bx[2])))

    ord  <- order(vapply(rows, function(r) r$default[1], numeric(1)))
    rows <- rows[ord]
    tibble::tibble(
      band       = vapply(rows, function(r) r$band, character(1)),
      from       = vapply(rows, function(r) as.numeric(if (is.null(r$from)) r$default[1] else r$from), numeric(1)),
      to         = vapply(rows, function(r) as.numeric(if (is.null(r$to))   r$default[2] else r$to),   numeric(1)),
      slider     = vapply(rows, function(r) r$slider, character(1)),
      default_lo = vapply(rows, function(r) r$default[1], numeric(1)),
      default_hi = vapply(rows, function(r) r$default[2], numeric(1)),
      ui_label   = I(lapply(rows, function(r) r$ui)),
      tip        = vapply(rows, function(r) r$tip, character(1))
    )
  })

  # Active 600-650 band label (back-compat shim for older references).
  band3_meta <- reactive({
    bs <- band_set(); row <- bs[bs$slider == "pbs", , drop = FALSE]
    lbl <- if (nrow(row)) row$band[1] else "PBS"
    list(label = lbl, short = lbl, win = c(input$pbs[1], input$pbs[2]))
  })
  qy_band_label <- reactive({
    bs <- band_set(); row <- bs[bs$slider == "qy", , drop = FALSE]
    if (nrow(row)) row$band[1] else "Qy"
  })

  # Apply-on-select: organism OR sample-type change snaps all band sliders.
  observeEvent(list(input$organism, input$sample_type), {
    restored <- isolate(restored_spectral_preset_choice())
    if (!is.null(restored)) {
      pending <- isolate(pending_spectral_settings_restore())
      same_pair <- identical(input$organism, restored$organism) &&
        (identical(input$organism, "plants") ||
           identical(input$sample_type, restored$sample_type))
      # Programmatic first-mount echoes can arrive after stable callbacks have
      # completed. Only an actual change from the restored choice pair applies
      # a new preset; the explicit Reset Bands button remains independent.
      if (!is.null(pending) || !isTruthy(input$organism) ||
          !isTruthy(input$sample_type) || same_pair) return(invisible())
      restored_spectral_preset_choice(NULL)
    }
    updateSliderInput(session, "bx",  value=c(420,460))
    updateSliderInput(session, "car", value=c(430,520))
    updateSliderInput(session, "qy",  value=c(660,690))
    updateSliderInput(session, "pbs", value=c(600,650))
    updateSliderInput(session, "chlb_qy", value=c(640,657))
    updateSliderInput(session, "pe",  value=c(490,570))
  }, ignoreInit=TRUE)

  # Deconvolution "Sample class" preset: apply-on-select (mirrors the organism ->
  # band-slider preset above). Overwrites the fit-setting controls with the
  # class's STARTING defaults; the user can then adjust any of them. Not fired on
  # init (the control defaults already match the default "complexes" class).
  observeEvent(input$decon_sample_class, {
    p <- DECON_CLASS_PRESETS[[input$decon_sample_class]]
    if (is.null(p)) return(NULL)
    updateNumericInput(session, "decon_fwhm_min", value = p$fwhm_min)
    updateNumericInput(session, "decon_fwhm_max", value = p$fwhm_max)
    updateNumericInput(session, "decon_seed_win", value = p$seed_nm)
    updateNumericInput(session, "decon_red_clip", value = p$red_clip)
    updateNumericInput(session, "decon_kmax",     value = p$kmax)
    updateNumericInput(session, "decon_mu_tol",   value = p$mu_tol)
    updateRadioButtons(session, "decon_criterion", selected = p$criterion)
    updateCheckboxInput(session, "decon_scatter_on", value = p$scatter)
    # Only surface the toast when the Deconvolution tab is actually in use, so the
    # sample_type-driven auto-suggest does not pop a decon message otherwise.
    if (isTRUE(input$advanced_mode))
      showNotification(sprintf("Deconvolution defaults loaded for “%s” (adjust any control as needed).",
                               p$label), type = "message", duration = 5)
  }, ignoreInit = TRUE)

  # Auto-suggest the deconvolution Sample class from the Analysis-settings Sample type
  # (Protein -> Purified complexes, Cells / Lysate -> Cells / thylakoids). Pure
  # pigments is manual-only. Updating the selector fires the apply observer above.
  observeEvent(input$sample_type, {
    suggested <- .decon_class_from_sample_type(input$sample_type)
    if (!identical(input$decon_sample_class, suggested))
      updateSelectInput(session, "decon_sample_class", selected = suggested)
  }, ignoreInit = TRUE)

  output$band3_label <- renderUI({ NULL })

  # Dynamic band sliders: labels & tooltips come from band_labels(), which
  # depends ONLY on organism + sample type. They therefore do NOT re-render when
  # the user drags a slider, so a slider's value is never snapped back to default
  # mid-edit. (band_set() reads the live from/to values for downstream use.)
  .spectral_band_seed <- function(key, default) {
    pending <- isolate(pending_spectral_settings_restore())
    if (!is.null(pending) && identical(pending$restore_txn, isolate(restore_txn())) &&
        !is.null(pending$values[[key]])) {
      i <- match(key, .SNAPSHOT_SETTINGS_REGISTRY$key)
      value <- .SNAPSHOT_SETTINGS_REGISTRY$parse[[i]](pending$values[[key]])
    } else value <- isolate(input[[key]])
    value <- suppressWarnings(as.numeric(value))
    if (length(value) == 2L && all(is.finite(value))) value else default
  }
