    with_tip(sliderInput("qy", L$qy$ui, min=350, max=750, value=.spectral_band_seed("qy", c(660,690)), step=1), L$qy$tip)
  })
  output$band3_slider_ui <- renderUI({
    L <- band_labels()
    with_tip(sliderInput("pbs", L$pbs$ui, min=350, max=750, value=.spectral_band_seed("pbs", c(600,650)), step=1), L$pbs$tip)
