  # ---- Generic export column-name helper ----
  # Internal/stable column tokens use "Qy" and "PBS"; swap to active band labels
  # immediately before display AND export so display == export.
  rename_pbs_cols <- function(df) {
    s  <- band3_meta()$label
    ql <- qy_band_label()
    if (!identical(s, "PBS")) {
      old <- c("Qy/PBS (AUC)", "OD at PBS peak (baseline-corr., pre-norm)")
      new <- c(sprintf("%s/%s (AUC)", ql, s), sprintf("OD at %s peak (baseline-corr., pre-norm)", s))
      for (i in seq_along(old)) { idx <- match(old[i], names(df)); if (!is.na(idx)) names(df)[idx] <- new[i] }
    }
    if (!identical(ql, "Qy")) {
      remap <- c(
        "Qy/Car (AUC)" = sprintf("%s/Car (AUC)", ql),
        "Qy/PBS (AUC)" = sprintf("%s/PBS (AUC)", ql),
        "Qy/Bx (AUC)"  = sprintf("%s/Bx (AUC)",  ql),
        "Qy/Car (peak, pre-norm)" = sprintf("%s/Car (peak, pre-norm)", ql),
        "OD at Qy peak (baseline-corr., pre-norm)" = sprintf("OD at %s peak (baseline-corr., pre-norm)", ql)
      )
      for (oldn in names(remap)) { idx <- match(oldn, names(df)); if (!is.na(idx)) names(df)[idx] <- remap[[oldn]] }
    }
    df
  }

  bands_react <- reactive({
    req(dat())
    bs <- band_set()
    tibble(band = bs$band, from = bs$from, to = bs$to)
  })

  # FYI notice under the Reset Bands button: flag the first pair of band ranges
  # that overlap. "fully" when one range contains the other, otherwise "partially".
  output$band_overlap_notice <- renderUI({
    req(dat())
    b <- bands_react()
    if (is.null(b) || nrow(b) < 2) return(NULL)
    for (i in seq_len(nrow(b) - 1L)) {
      for (j in (i + 1L):nrow(b)) {
        lo_i <- b$from[i]; hi_i <- b$to[i]
        lo_j <- b$from[j]; hi_j <- b$to[j]
        if (any(is.na(c(lo_i, hi_i, lo_j, hi_j)))) next
        if (lo_i <= hi_j && lo_j <= hi_i) {
          kind <- if ((lo_i <= lo_j && hi_j <= hi_i) ||
                      (lo_j <= lo_i && hi_i <= hi_j)) "fully" else "partially"
          return(div(style = "color:var(--pasa-warn-fg); font-size:0.85em; margin-top:4px;",
                     sprintf("FYI: Band %s and %s %s overlap.", b$band[i], b$band[j], kind)))
        }
      }
    }
    NULL
  })

  # ---- Shared sample color map ----------------------------------------------
  # ONE named character vector (names = sample names, values = hex) built once
  # from the FULL sample list so every chart colors a given sample identically.
  # Sorting the sample names before assigning palette colors keeps the mapping
  # stable regardless of selection order. Reused by the Spectra curves plot and
  # the Band AUC radar (and available for the Data Quality network later).
  sample_color_map <- reactive({
    req(dat())
    nm_col   <- names(dat())[1]
    all_samp <- sort(unique(setdiff(names(dat()), nm_col)))
    if (length(all_samp) == 0) return(stats::setNames(character(0), character(0)))
    cols <- curve_palette(input$palette %||% "okabe", length(all_samp), dark = is_dark())
    stats::setNames(cols, all_samp)
  })

  BAND_RATIO_LOD_K <- 3
  safe_ratio_fn <- function(a, b, den_peak = NULL, sigma = NULL, lod_k = BAND_RATIO_LOD_K){
    a <- suppressWarnings(as.numeric(a)); b <- suppressWarnings(as.numeric(b))
    out <- a / b
    out[!is.finite(out)] <- NA_real_
    out[is.finite(b) & b <= 0] <- NA_real_    # non-positive denominator
    out[is.finite(a) & a <  0] <- NA_real_    # negative numerator
    if (!is.null(den_peak) && !is.null(sigma)) {
      dp <- suppressWarnings(as.numeric(den_peak)); sg <- suppressWarnings(as.numeric(sigma))
      out[is.finite(dp) & is.finite(sg) & sg > 0 & dp < lod_k * sg] <- NA_real_  # below LOD
    }
    out
  }
  # Per-sample DER-SNR spectral-noise sigma from the pre-norm curve, for the LOD
  # guard above (same estimator the noise screen / near-blank guard use).
  .sample_sigma <- function(res, samples){
    vapply(samples, function(s){
      rr <- res[res$sample == s, , drop = FALSE]
      if (!nrow(rr)) return(NA_real_)
      v <- if (".decon_native_base" %in% names(rr)) rr$.decon_native_base[[1]] else rr$.val_smooth_pre[[1]]
      v <- as.numeric(v); v <- v[is.finite(v)]; n <- length(v)
      if (n < 5) return(NA_real_)
      i <- 3:(n - 2)
      sg <- suppressWarnings(stats::mad((2 * v[i] - v[i - 2] - v[i + 2]) / sqrt(6)))
      # sigma == 0 (a perfectly flat / over-interpolated region) is NOT "clean" -- it means
      # the screen cannot be evaluated; return NA so safe_ratio_fn leaves the ratio unscreened
      # rather than treating a zero threshold as an automatic pass.
      if (is.finite(sg) && sg > 0) sg else NA_real_
    }, numeric(1))
  }
  # Per-sample value of `col` for band `lbl`, aligned to a sample vector.
  .band_val_by_sample <- function(res, lbl, col, samples){
    sub <- res[res$band == lbl, c("sample", col), drop = FALSE]
    sub <- sub[!duplicated(sub$sample), , drop = FALSE]
    v <- sub[[col]][match(samples, sub$sample)]
    as.numeric(v)
  }
  band_ratio_tbl <- function(res){
    bs <- band_set()
    qy_lbl    <- bs$band[bs$slider == "qy"][1]
    band3_lbl <- bs$band[bs$slider == "pbs"][1]
    samples   <- unique(res$sample)
    auc_Qy  <- .band_val_by_sample(res, qy_lbl,        "auc", samples)
    auc_PBS <- .band_val_by_sample(res, band3_lbl,     "auc", samples)
    auc_Car <- .band_val_by_sample(res, "Carotenoid",  "auc", samples)
    auc_Bx  <- .band_val_by_sample(res, "Soret / Bx",  "auc", samples)
    auc_PE  <- .band_val_by_sample(res, "Phycoerythrin (PE)", "auc", samples)
    auc_Chlb<- .band_val_by_sample(res, "Chl b Qy",    "auc", samples)
    pk_Qy   <- .band_val_by_sample(res, qy_lbl,        "peak_val_pre", samples)
    pk_Car  <- .band_val_by_sample(res, "Carotenoid",  "peak_val_pre", samples)
    pk_PBS  <- .band_val_by_sample(res, band3_lbl,     "peak_val_pre", samples)
    pk_Bx   <- .band_val_by_sample(res, "Soret / Bx",  "peak_val_pre", samples)
    pk_PE   <- .band_val_by_sample(res, "Phycoerythrin (PE)", "peak_val_pre", samples)
    pk_Chlb <- .band_val_by_sample(res, "Chl b Qy",    "peak_val_pre", samples)
    sig     <- .sample_sigma(res, samples)   # per-sample DER-SNR noise for the LOD guard
    out <- tibble::tibble(
      sample = samples,
      `Qy/Car (AUC)` = round(safe_ratio_fn(auc_Qy, auc_Car, pk_Car, sig), 3),
      `Qy/PBS (AUC)` = round(safe_ratio_fn(auc_Qy, auc_PBS, pk_PBS, sig), 3),
      `Qy/Bx (AUC)`  = round(safe_ratio_fn(auc_Qy, auc_Bx,  pk_Bx,  sig), 3),
      `Qy/Car (peak, pre-norm)` = round(safe_ratio_fn(pk_Qy, pk_Car, pk_Car, sig), 3)
    )
    if (any(!is.na(auc_PE)))   out[["Qy/PE (AUC)"]] <- round(safe_ratio_fn(auc_Qy, auc_PE, pk_PE, sig), 3)
    if (any(!is.na(auc_Chlb))) out[["Chl a Qy/Chl b Qy (AUC)"]] <- round(safe_ratio_fn(auc_Qy, auc_Chlb, pk_Chlb, sig), 3)
    out
  }
  band_odpeak_tbl <- function(res){
    bs <- band_set()
    qy_lbl    <- bs$band[bs$slider == "qy"][1]
    band3_lbl <- bs$band[bs$slider == "pbs"][1]
    samples   <- unique(res$sample)
    rd <- function(lbl) round(.band_val_by_sample(res, lbl, "peak_val_pre", samples), 4)
    out <- tibble::tibble(
      sample = samples,
      `OD at Qy peak (baseline-corr., pre-norm)`         = rd(qy_lbl),
      `OD at Soret/Bx peak (baseline-corr., pre-norm)`   = rd("Soret / Bx"),
      `OD at Carotenoid peak (baseline-corr., pre-norm)` = rd("Carotenoid"),
      `OD at PBS peak (baseline-corr., pre-norm)`        = rd(band3_lbl)
    )
    pe <- rd("Phycoerythrin (PE)"); chlb <- rd("Chl b Qy")
    if (any(!is.na(pe)))   out[["OD at Phycoerythrin (PE) peak (baseline-corr., pre-norm)"]] <- pe
    if (any(!is.na(chlb))) out[["OD at Chl b Qy peak (baseline-corr., pre-norm)"]] <- chlb
    out
  }

  output$norm_band_ui <- renderUI({
