    if (isTRUE(dark) && identical(input$appearance_mode, "midnight")) {
      return(ggplot2::theme(
        plot.background=ggplot2::element_rect(fill="#050e1a", color=NA),
        panel.background=ggplot2::element_rect(fill="#050e1a", color=NA),
        legend.background=ggplot2::element_rect(fill="#050e1a", color=NA),
        legend.key=ggplot2::element_rect(fill="#050e1a", color=NA),
        text=ggplot2::element_text(color="#d0d8e8"),
        axis.text=ggplot2::element_text(color="#a8b8ce"),
        axis.ticks=ggplot2::element_line(color="#52718d"),
        panel.grid=ggplot2::element_line(color="#1a3355"),
        strip.background=ggplot2::element_rect(fill="#071120", color=NA),
        strip.text=ggplot2::element_text(color="#f0f4fa")))
    }
    if (dark) {
      ggplot2::theme(
        plot.background   = ggplot2::element_rect(fill = "#1d1f21", color = NA),
        panel.background  = ggplot2::element_rect(fill = "#1d1f21", color = NA),
        legend.background = ggplot2::element_rect(fill = "#1d1f21", color = NA),
        text              = ggplot2::element_text(color = "#e8e8e8"),
        axis.text         = ggplot2::element_text(color = "#c0c0c0"),
        axis.ticks        = ggplot2::element_line(color = "#555555"),
        strip.background  = ggplot2::element_rect(fill = "#27292b", color = NA),
        strip.text        = ggplot2::element_text(color = "#e8e8e8")
      )
    } else {
      ggplot2::theme(
        plot.background   = ggplot2::element_rect(fill = "white", color = NA),
