  }
  # Aggressive light-theme override applied to every plot saved into the ZIP
  # (except the similarity network, which has its own handling). This explicitly
  # overrides every text element a plot may have baked-in with dark-theme colors,
  # so exported PNGs are always legible on a white background.
  #
  # The override sets axis.title and axis.text to black so that
  # plots which render axes (spectra, AUC bar, QC charts) get strong contrast on
  # the white background. To prevent this from resurrecting axes that a plot
  # deliberately blanked (e.g. theme_void() radar, cuvette, similarity), the
  # save_plot() helper detects pre-existing element_blank() axes and re-applies
  # them AFTER the override.
  theme_light_override <- ggplot2::theme(
    plot.background   = ggplot2::element_rect(fill = "white", color = NA),
    panel.background  = ggplot2::element_rect(fill = "white", color = NA),
    legend.background = ggplot2::element_rect(fill = "white", color = NA),
    legend.box.background = ggplot2::element_rect(fill = "white", color = NA),
    legend.key        = ggplot2::element_rect(fill = "white", color = NA),
    strip.background  = ggplot2::element_rect(fill = "#f5f5f5", color = NA),
    text              = ggplot2::element_text(color = "black"),
    title             = ggplot2::element_text(color = "black"),
    plot.title        = ggplot2::element_text(color = "black"),
    plot.subtitle     = ggplot2::element_text(color = "#222222"),
    plot.caption      = ggplot2::element_text(color = "#444444"),
    axis.title        = ggplot2::element_text(color = "black"),
    axis.title.x      = ggplot2::element_text(color = "black"),
    axis.title.y      = ggplot2::element_text(color = "black"),
    axis.text         = ggplot2::element_text(color = "black"),
    axis.text.x       = ggplot2::element_text(color = "black"),
    axis.text.y       = ggplot2::element_text(color = "black"),
    legend.title      = ggplot2::element_text(color = "black"),
    legend.text       = ggplot2::element_text(color = "black"),
    strip.text        = ggplot2::element_text(color = "black")
  )

  # Return a theme that re-blanks any axis element which was
  # blank on the source plot. Run AFTER theme_light_override so the override's
  # forced-black axis text does not resurrect axes the source plot deliberately
  # blanks (radar, cuvette, similarity ggraph). Safe on any ggplot; if no
  # blanks are present, returns an empty theme().
  .preserve_blank_axes <- function(p) {
    blanks <- list()
    src_theme <- tryCatch(p$theme, error = function(e) NULL)
    if (is.null(src_theme) || !length(src_theme)) return(ggplot2::theme())
    axis_keys <- c("axis.title", "axis.title.x", "axis.title.y",
                   "axis.text",  "axis.text.x",  "axis.text.y",
                   "axis.ticks", "axis.ticks.x", "axis.ticks.y",
                   "axis.line",  "axis.line.x",  "axis.line.y")
    for (k in axis_keys) {
      el <- src_theme[[k]]
      if (inherits(el, "element_blank")) blanks[[k]] <- ggplot2::element_blank()
    }
    if (!length(blanks)) return(ggplot2::theme())
    do.call(ggplot2::theme, blanks)
  }

  # ==========================================================================
  # State-file helpers (\u00a79): export current settings + data into a single
  # human-readable AND machine-parseable .txt. The [SETTINGS] block uses
  # key=value lines (one per setting) so parse_settings_block() can round-trip
  # every value back into the UI via update*Input() on load.
  #
  # Format (all sections optional; only present when the corresponding section
  # is requested and data is available):
  #
  #   # PASA state file
  #   # Generated: <timestamp>
  #   # To reload: open the app, set 'Data source' on the Input data tab to 'Import session',
  #   # upload this file, then pick the sections you want to restore in the dialog.
  #
  #   [SETTINGS]
  #   analysis_nm_lo=400
  #   analysis_nm_hi=750
  #   ...one key=value per line, scalars as-is, vectors comma-joined...
  #
  #   [GROWTH_DATA]
  #   mode=manual               # manual | sidebar
  #   unit=Days                 # only for both
  #   interval=1                # only for both
  #   nrep=3                    # only for both
  #   ntp=7                     # only for manual
  #   tracking_wl=750           # only for sidebar
  #   map_R1=Sample A,Sample B  # only for sidebar (one per replicate)
  #   ## values: tab-separated, one replicate per row, only for manual
  #   0.078\t0.086\t0.164\t...
  #
  #   [SIDEBAR_DATA]
  #   ## source: <filename or "pasted" or "demo">
  #   <tab-separated wide table, header row first>
  # ==========================================================================

  # NOTE: the settings that round-trip are the SINGLE source of truth in
  # build_settings_block()'s `vals` list (save) and .apply_one_setting()'s typed
  # id lists (restore). The active widget is `line_pattern`, which persists via
  # `vals` and those typed id lists. Update `vals`, the restore lists, and
  # parse_settings_block()
  # together whenever the UI gains a new persistent control.

  .c0_offending <- function(x, field = "value") {
    x <- as.character(x)
    bad_i <- which(grepl("[\x01-\x1F\x7F]", x, perl = TRUE)) # C0 and DEL only
    if (!length(bad_i)) return(NULL)
    i <- bad_i[1]; cps <- utf8ToInt(x[i]); ctrl <- cps[cps < 0x20L | cps == 0x7FL]
    nm <- function(cp) switch(as.character(cp), "9"="TAB","10"="LF","13"="CR","31"="US","0"="NUL","127"="DEL",
                              paste0("C0-0x", sprintf("%02X", cp)))
    classes <- unique(vapply(ctrl, nm, character(1)))
    list(field = field, index = i, n_bad = length(bad_i), classes = classes,
         message = sprintf("Refused: the %s contains disallowed control character(s) [%s] (entry #%d of %d affected). Control characters (tab, newline, unit separator, etc.) are not permitted in names. The value is REFUSED, not silently altered, so no two distinct names can collapse into one — rename the entry and retry.",
                           field, paste(classes, collapse = ", "), i, length(bad_i)))
  }
  # Raise the shared, classed refusal condition (callers catch `pasa_c0_refusal` to show the typed error /
  # write a truthful export-error artifact instead of a partial/normalized file).
  .c0_refuse <- function(off) stop(structure(
    class = c("pasa_c0_refusal", "error", "condition"),
    list(message = off$message, field = off$field, classes = off$classes, index = off$index)))
  .state_neutralize_formula <- function(x) paste0("'", as.character(x))
  # Encode an arbitrary scalar/vector value for a key=value line. Character values are validated for C0
  # controls by the CALLER (build_settings_block gate) before we get here; this is a defensive tripwire so
  # a C0 value can never silently reach the section-marker grammar (it REFUSES, never normalizes).
  # Lists, NULLs and a length-1 NA of ANY type are skipped (the line is dropped); logicals -> TRUE/FALSE;
  # numeric vectors -> comma-joined.
  .encode_setting_value <- function(v) {
    if (is.null(v)) return(NA_character_)
    if (is.list(v))  return(NA_character_)
    if (length(v) == 0) return("")
    if (length(v) == 1L && is.na(v)) return(NA_character_)
    if (is.logical(v))   return(if (length(v) == 1) as.character(isTRUE(v[[1]])) else paste(as.character(as.logical(v)), collapse = ","))
    if (is.numeric(v))   return(paste(sprintf("%.17g", v), collapse = ","))
    off <- .c0_offending(v, "setting value"); if (!is.null(off)) .c0_refuse(off)
    paste(as.character(v), collapse = ",")
  }
  .state_samples_json <- function(samps) {
    s <- if (is.null(samps)) character(0) else as.character(samps)
    off <- .c0_offending(s, "sample names"); if (!is.null(off)) .c0_refuse(off)
    as.character(jsonlite::toJSON(unname(s), auto_unbox = FALSE))
  }

