    metrics_page_prev = "Metrics table page navigation",
    metrics_page_next = "Metrics table page navigation",
    growth_apply_paste = "apply pasted growth input action",
    decon_cancel = "cancel active deconvolution action",
    pasa_welcome_open = "welcome navigation action",
    pasa_welcome_tour = "guided introduction action",
    pasa_tour_restart = "guided tour action",
    pasa_tour_client_ready = "browser onboarding handshake",
    pasa_tour_state = "onboarding preference, never an analysis setting",
    pasa_tour_navigate = "guided tour navigation action",
    `pasa-tour-chapter` = "tour chapter navigation selector; progress is stored separately from analysis snapshots",
    `cuv_grid_page` = "transient sample-color scene pagination; all numerical sample data are preserved separately",
    sim_edge_range        = "data-dependent dynamic display filter (min/max derived from the loaded network's edge weights; re-derived on load, not an analysis parameter)",
    preset                = "restoring the preset dropdown fires the preset observer, which clobbers the individually-restored custom band windows; the band windows round-trip directly instead (label is cosmetic)",
    decon_sample_class    = "restoring it fires the apply-on-select observer and clobbers the individually-restored FWHM/seed/k_max; those numerics round-trip directly instead",
    file                  = "the file upload itself is data, serialized as [SIDEBAR_DATA], not a setting",
    path                  = "the URL/path is provenance (## source), not a reproducible setting; re-entered by the user",
    load = "action button", load_demo = "action button", data_source = "transient source toggle",
    sheet                 = "per-file worksheet selector; tied to the uploaded file, not a persistent setting",
    state_apply_settings = "restore-dialog control", state_apply_data = "restore-dialog control", state_apply_growth = "restore-dialog control",
    state_apply_blank    = "restore-dialog control",
    state_load                       = "the session-snapshot UPLOAD control (a fileInput); the uploaded snapshot is data/action, not a setting",
    decon_scatter_blank              = "measured blank / turbidity-curve UPLOAD (a fileInput) inside the Advanced-Mode Deconvolution tab; its parsed numeric contents are serialized in [DECON_BLANK_DATA], while the upload control itself is transient data rather than a scalar setting",
    snapshot_include_settings        = "snapshot EXPORT dialog toggle (which sections to write), not an analysis setting",
    snapshot_include_data            = "snapshot EXPORT dialog toggle (which sections to write), not an analysis setting",
    snapshot_include_settings_summary= "Summary-tab mirror of snapshot_include_settings (bidirectionally synced); export toggle, not a setting",
    snapshot_include_data_summary    = "Summary-tab mirror of snapshot_include_data (bidirectionally synced); export toggle, not a setting",
    cuv_sample                       = "Sample-Color PREVIEW selector; choices are re-derived from the loaded samples, and it only picks which sample's swatch is shown (color is deterministic given settings), so it is display-navigation, not an analysis parameter",
    probe_step                       = "the +/- STEP SIZE for the probe-wavelength stepper (a UI convenience); it changes nothing in the analysis or the rendered output, only how far one click moves probe_nm",
    share_y                          = "facet-only 'share Y axis' display toggle; an observer resets it to FALSE on any change of `overlay`, so restoring it directly is clobbered when overlay is also restored (same class as `preset`/`decon_sample_class`) -- excluded rather than add pending-restore machinery for a cosmetic facet toggle",
    samples            = "the sample selection is stored via samples_json and restored through pending_samples_restore with replaced_on_restore provenance, not the settings registry",
    peak_bands         = "cosmetic band-peak annotation selection (checkboxGroupInput); its choices are re-derived from the loaded data + organism, and it only chooses which band peaks are MARKED on the plot -- it changes no computed metric/AUC/export, so the analytical result is identical regardless of which labels are ticked (contrast norm_band, which DOES drive normalization and IS round-tripped)",
    growth_wl_num      = "numeric-entry MIRROR of the growth_wl slider (a round-tripped scalar_slider setting); the two are kept bidirectionally in sync, so restoring growth_wl restores this value",
    growth_paste_data  = "transient manual growth-curve paste field (raw input DATA, not a setting); when used it rides the data-injection path, exactly like an uploaded file",
    probe_slider       = "drag-slider MIRROR of the probe_nm numeric setting (a round-tripped numeric); the two are bidirectionally synced (observeEvent probe_slider->probe_nm and back), so restoring probe_nm restores this",
    fb_comment         = "Feedback-tab comment textarea; transient form input cleared on submit (updateTextAreaInput ''), not an analysis setting",
    fb_consent         = "Feedback-tab pre-submit acknowledgment; transient local gate reset after successful submission, not an analysis setting",
    auc_what_shows     = "a 'What this shows' help-text disclosure (pasa_disclosure); its open/closed value is NEVER read by any logic -- it only shows/hides an explanatory panel, so it has no effect on any computed result",
    lbl_point_opts     = "container disclosure that shows/hides the nested peak-point label options (lbl_curve/lbl_band/lbl_nm/lbl_val, which ARE individually round-tripped); its open/closed value is never read by logic -- cosmetic",
    appearance         = "client-side THEME selector (tags$select); persists for the current browser tab/session in sessionStorage 'spectra_appearance' and reports the effective mode via input$appearance_mode -- a per-browser display preference, not part of the analysis snapshot (the snapshot's theme is theme_mode)",
    dark_mode          = "hidden bslib light/dark toggle fallback (input_dark_mode, renders as the <bslib-input-dark-mode> web component); read only by is_dark() to theme the plots -- a per-browser DISPLAY preference like `appearance`, not part of the analysis snapshot (the snapshot's theme is theme_mode)",
    metrics_tsv_data   = "hidden (display:none) data-shuttle textarea that carries the Metrics-table TSV to the copy-to-clipboard JS; a DOM conduit, not a user setting",
    decon_tsv_data     = "hidden (display:none) data-shuttle textarea that carries the deconvolution-table TSV to the copy/PDF JS; a DOM conduit, not a user setting"
    )
  local({
    .clash <- intersect(names(.SNAPSHOT_EXCLUSION_REASONS), .SNAPSHOT_SETTINGS_REGISTRY$key[.SNAPSHOT_SETTINGS_REGISTRY$route != "none"])
    if (length(.clash)) stop(sprintf("Actively routed snapshot key(s) are also excluded: %s", paste(.clash, collapse = ", ")))
    invisible()
  })
  .SNAPSHOT_SETTINGS_REGISTRY <- local({
    reg <- .SNAPSHOT_SETTINGS_REGISTRY
    ns_keys <- names(.SNAPSHOT_EXCLUSION_REASONS)[!(names(.SNAPSHOT_EXCLUSION_REASONS) %in% reg$key)]
    add <- data.frame(
      key     = c("dil_", ns_keys),
      route   = c("dilution_family", rep("excluded", length(ns_keys))),
      restore = c("dynamic_family",  rep("excluded", length(ns_keys))),
      stringsAsFactors = FALSE)
    add$default <- rep(list(NULL), nrow(add))
    rbind(reg, add)
  })

  # Build the [SETTINGS] block (without the header line) as character vector.
  # Captures CURRENT input values \u2014 defaults are emitted alongside user changes
  # because the input object already reflects defaults until the user changes them.
  build_settings_block <- function(input) {
    `%||%` <- function(a, b) if (is.null(a) || length(a) == 0 || all(is.na(a))) b else a
    .emit <- function(k, val) { enc <- .encode_setting_value(val); if (is.na(enc)) character(0) else paste0(k, "=", enc) }
    reg <- .SNAPSHOT_SETTINGS_REGISTRY
    out <- character(0)
    .snap_notes <- character(0)
    .snap_note  <- function(keys, errs)
      paste0("# NOTE: ", paste(keys, collapse = " + "), " NOT written to this snapshot — ",
             paste(unique(errs), collapse = "; "),
             " — writing it would make the whole file unreadable, so this control keeps its current value on restore.")
    .key_of <- function(ln) trimws(sub("=.*$", "", ln))
    # When Advanced Mode is off, its dynamically inserted controls do not exist
    # in the browser. During a restore, their transaction-bound staged values are
    # therefore authoritative until the mounted controls acknowledge them.
    # Serializing those values preserves save -> restore -> save while the
    # optional tab remains hidden.
    .pending_decon <- tryCatch(isolate(pending_decon_settings_restore()),
                               error = function(e) NULL)
    .pending_decon_values <- if (!is.null(.pending_decon) &&
      identical(.pending_decon$restore_txn, isolate(restore_txn())) &&
      identical(.pending_decon$generation,
                isolate(decon_settings_restore_generation())))
      .pending_decon$values else list()
    .pending_spectral <- tryCatch(isolate(pending_spectral_settings_restore()),
                                  error = function(e) NULL)
    .pending_spectral_values <- if (!is.null(.pending_spectral) &&
      identical(.pending_spectral$restore_txn, isolate(restore_txn())))
      .pending_spectral$values else list()
    .growth_effective <- .snapshot_growth_scalars(input)
    for (.i in seq_len(nrow(reg))) {
      .wop <- reg$write[[.i]]
      if (!is.function(.wop)) next
      .key <- reg$key[.i]
      .pending_raw <- .pending_spectral_values[[.key]] %||% .pending_decon_values[[.key]]
      .pending_typed <- .growth_effective[[.key]]
      if (!is.null(.pending_raw)) {
        .pop <- reg$parse[[.i]]
        .pending_typed <- tryCatch(
          if (is.function(.pop)) .pop(.pending_raw) else .pending_raw,
          error = function(e) NULL)
      }
      .ln <- if (!is.null(.pending_typed))
               .wop(.key, stats::setNames(list(.pending_typed), .key), .emit)
             else .wop(.key, input, .emit)
      if (!length(.ln)) next
      .vr <- tryCatch(.validate_snapshot_settings(.ln),
                      error = function(e) list(ok = FALSE, errors = conditionMessage(e)))
      if (isTRUE(.vr$ok)) out <- c(out, .ln)
      else .snap_notes <- c(.snap_notes, .snap_note(.key, .vr$errors))
    }
    .app_sha <- tryCatch(RELEASE_ID$app_sha256(),        error = function(e) NA_character_)
    .mod_sha <- tryCatch(RELEASE_ID$module_sha256(),     error = function(e) NA_character_)
    .frz_sha <- tryCatch(RELEASE_ID$execution_freeze_sha256(), error = function(e) NA_character_)
    .lck_sha <- tryCatch(RELEASE_ID$dependency_lock_sha256(), error = function(e) NA_character_)
    .pub_sha <- tryCatch(RELEASE_ID$public_bundle_sha256(),   error = function(e) NA_character_)
    out <- c(out,
      .emit("samples_json", .state_samples_json(input$samples)),
      .emit("app_version", PASA_VERSION),
      .emit("numerical_methods_version", PASA_METHODS_VERSION),
      if (!is.na(.app_sha) && nzchar(.app_sha)) .emit("app_sha256",        .app_sha) else character(0),
      if (!is.na(.mod_sha) && nzchar(.mod_sha)) .emit("module_sha256",     .mod_sha) else character(0),
      .emit("provenance_schema_version", PASA_PROVENANCE_SCHEMA),
      if (!is.na(.frz_sha) && nzchar(.frz_sha)) .emit(PASA_EXEC_FREEZE_FIELD,  .frz_sha) else character(0),
      if (!is.na(.frz_sha) && nzchar(.frz_sha)) .emit(PASA_EXEC_FREEZE_LEGACY, .frz_sha) else character(0),
      if (!is.na(.lck_sha) && nzchar(.lck_sha)) .emit("dependency_lock_sha256", .lck_sha) else character(0),
      if (!is.na(.pub_sha) && nzchar(.pub_sha)) .emit("public_bundle_sha256",   .pub_sha) else character(0),
      .emit("software_versions", paste0("R ", as.character(getRversion()),
                                        "; shiny ", as.character(utils::packageVersion("shiny")),
                                        "; PASA ", PASA_VERSION)))
    # ReactiveValues does not guarantee that names(input) enumerates every
    # dynamically mounted dilution control. Derive the exact current IDs from
    # the selected samples instead; this also excludes stale controls belonging
    # to samples that were subsequently deselected.
    dil_ids <- tryCatch(unname(.dil_ids(
      if (isTruthy(input$samples)) input$samples else character(0))),
      error = function(e) character(0))
    for (id in dil_ids) {
      v <- suppressWarnings(as.numeric(input[[id]]))
      if (length(v) == 1L && is.finite(v) && v > 0)
        out <- c(out, paste0(id, "=", .encode_setting_value(v)))
    }
 # Stage 2 of the gate checks cross-field relations spanning two registry rows, which stage 1 cannot see. A violated
    # relation drops BOTH of its keys -- restoring only one half would silently install a lopsided range.
    .kvnum <- function(k) { i <- which(.key_of(out) == k)
                            if (!length(i)) NA_real_ else suppressWarnings(as.numeric(sub("^[^=]*=", "", out[i[1]]))) }
    for (.rel in .SNAPSHOT_RELATIONS) {
      .lo <- .kvnum(.rel$lo); .hi <- .kvnum(.rel$hi)
      if (is.finite(.lo) && is.finite(.hi) && .lo > .hi) {
        .snap_notes <- c(.snap_notes, .snap_note(c(.rel$lo, .rel$hi),
                          sprintf("%s=%s must be <= %s=%s (%s)", .rel$lo, .lo, .rel$hi, .hi, .rel$why)))
        out <- out[!(.key_of(out) %in% c(.rel$lo, .rel$hi))]
      }
    }
    # Stage 3 of the gate: final self-check on the ASSEMBLED block (registry rows + provenance keys + dynamic dil_ lines),
    # so the guarantee is about the FILE, not about the rows in isolation. Whatever the reader still rejects is dropped by
    # key; the sweep is bounded and terminates (each pass either removes >= 1 line or stops).
    for (.pass in seq_len(16L)) {
      .vr <- tryCatch(.validate_snapshot_settings(out),
                      error = function(e) list(ok = FALSE, errors = conditionMessage(e)))
      if (isTRUE(.vr$ok)) break
      .bad <- unique(gsub("^'|'$", "", unlist(regmatches(.vr$errors, gregexpr("'[^']*'", .vr$errors)))))
      .bad <- intersect(.bad[nzchar(.bad)], unique(c(.key_of(out), sub("_(lo|hi)$", "", .key_of(out)))))
      .hit <- .key_of(out) %in% .bad | sub("_(lo|hi)$", "", .key_of(out)) %in% .bad
      if (!any(.hit)) { .snap_notes <- c(.snap_notes, .snap_note("(block)", .vr$errors)); break }
      .snap_notes <- c(.snap_notes, .snap_note(unique(.key_of(out)[.hit]), .vr$errors))
      out <- out[!.hit]
    }
    c(.snap_notes, out)
  }

  # Parse the [SETTINGS] block (vector of key=value lines, # and blank lines
  # ignored) into a named list of character values. Type coercion is the
  # caller's responsibility (they know which updateInput type to use).
  parse_settings_block <- function(lines) {
    if (is.null(lines) || !length(lines)) return(list())
    keep <- !grepl("^\\s*#", lines) & nzchar(trimws(lines))
    lines <- lines[keep]
    out <- list()
    for (ln in lines) {
      if (!grepl("=", ln, fixed = TRUE)) next
      i  <- regexpr("=", ln, fixed = TRUE)
      k  <- trimws(substr(ln, 1, i - 1))
      v  <- substr(ln, i + 1, nchar(ln))
      if (!nzchar(k)) next
      out[[k]] <- v
    }
    out
  }

  .snapshot_growth_scalars <- function(input) {
    integer_value <- function(id, default, lo, hi) {
      v <- suppressWarnings(as.integer(input[[id]]))
      if (length(v) != 1L || !is.finite(v)) v <- default
      max(lo, min(hi, v))
    }
    interval <- suppressWarnings(as.numeric(input$growth_interval))
    if (length(interval) != 1L || !is.finite(interval) || interval <= 0) interval <- 1
    list(growth_nrep = integer_value("growth_nrep", 1L, 1L, 10L),
         growth_ntp = integer_value("growth_ntp", 7L, 2L, 30L),
         growth_ntech = integer_value("growth_ntech", 1L, 1L, 6L), growth_interval = interval)
  }

  # Build the [GROWTH_DATA] block as a character vector.
  # Captures mode + scalars + either the manual replicate\u00d7timepoint matrix
  # (mode=manual) or the replicate\u2192sample mapping + tracking wavelength
  # (mode=sidebar).
  build_growth_block <- function(input) {
    `%||%` <- function(a, b) if (is.null(a) || length(a) == 0 || all(is.na(a))) b else a
    manual_on <- isTRUE(input$growth_manual)
    mode <- if (manual_on) "manual" else "sidebar"
    .effective <- .snapshot_growth_scalars(input)
    .g_eff_nrep <- .effective$growth_nrep
    lines <- c(
      paste0("mode=", mode),
      paste0("unit=", input$growth_unit %||% "Days"),
      paste0("interval=", .encode_setting_value(.effective$growth_interval)),
      paste0("nrep=", .g_eff_nrep)
    )
    if (manual_on) {
      ntp   <- .effective$growth_ntp
      nrep  <- .g_eff_nrep
      ntech <- .effective$growth_ntech
      if (!is.finite(ntech) || ntech < 1L) ntech <- 1L
      if (is.finite(ntp) && is.finite(nrep) && ntp > 0 && nrep > 0) {
        lines <- c(lines, paste0("ntp=", ntp), paste0("ntech=", ntech))
        .cell_state <- isolate(growth_cell_state())
        safe_cell <- function(id){
          # A mounted input is the newest authoritative value. The cache is a
          # fallback for the short interval in which renderUI has unmounted the
          # cell; it must not mask a finite live value with an older NA.
          live <- suppressWarnings(as.numeric(input[[id]]))
          cached <- if (id %in% names(.cell_state))
            suppressWarnings(as.numeric(.cell_state[[id]])) else NA_real_
          v <- if (length(live) == 1L && is.finite(live)) live else cached
          if (length(v) == 1L && is.finite(v)) sprintf("%.17g", v) else "NA" }
        if (ntech > 1L) {
          lines <- c(lines, "## values: tab-separated, one BIOLOGICAL×TECHNICAL series per row (biological-major)")
          for (i in seq_len(nrep)) for (t in seq_len(ntech)) {
            row_vals <- vapply(seq_len(ntp), function(j) safe_cell(paste0("growth_od_", i, "_", t, "_", j)), character(1))
            lines <- c(lines, paste(row_vals, collapse = "\t"))
          }
        } else {
          lines <- c(lines, "## values: tab-separated, one replicate per row")
          for (i in seq_len(nrep)) {
            row_vals <- vapply(seq_len(ntp), function(j) safe_cell(paste0("growth_od_", i, "_", j)), character(1))
            lines <- c(lines, paste(row_vals, collapse = "\t"))
          }
        }
      }
    } else {
      lines <- c(lines, paste0("tracking_wl=", input$growth_wl %||% ""))
      lines <- c(lines, "growth_map_us=1")
      nrep <- .g_eff_nrep
      if (is.finite(nrep) && nrep > 0) {
        for (i in seq_len(nrep)) {
          samps <- input[[paste0("growth_map_", i)]]
          if (length(samps)) {
            lines <- c(lines, paste0("map_R", i, "=", paste(samps, collapse = "\x1f")))
          }
        }
      }
    }
    lines
  }

  # Build the [SIDEBAR_DATA] block as a character vector. Emits the currently
  # active wide table (whether it came from a file, URL, paste, or built-in
  # demo), with a comment line noting the source.
  build_sidebar_data_block <- function(input) {
    df <- tryCatch(dat(), error = function(e) NULL)
    if (is.null(df) || !is.data.frame(df) || nrow(df) == 0) return(character(0))
    ls_src <- tryCatch(loaded_source(), error = function(e) NULL)
    src <- if (isTruthy(ls_src)) ls_src
           else if (isTRUE(tryCatch(demo_flag(), error = function(e) FALSE))) "demo"
           else if (isTruthy(input$file$name)) input$file$name
           else if (isTruthy(input$path))     .sanitize_url_provenance(input$path)
           else "pasted"
    .off <- .c0_offending(names(df), "column (sample) names"); if (!is.null(.off)) .c0_refuse(.off)
    hdr  <- paste(vapply(names(df), .state_neutralize_formula, character(1)), collapse = "\t")
    if (any(!is.finite(df$nm))) stop("Cannot save a non-finite wavelength axis.")
    .cols17 <- lapply(df, function(col) {
      v <- suppressWarnings(as.numeric(col))
      ifelse(is.finite(v), sprintf("%.17g", v), "NA")
    })
    body <- do.call(paste, c(.cols17, sep = "\t"))
    c(paste0("## source: ", src), hdr, body)
  }

 # canonical measured-blank serialization. A COMPLETE
  # session must retain the actual numeric curve, not only the checkbox that
  # enables local baseline correction.  The canonical content hash protects the
  # two-column values independently of the surrounding state file.
  .decon_blank_canonical_lines <- function(df) {
    if (is.null(df) || !is.data.frame(df) || !all(c("nm", "val") %in% names(df)))
      stop("measured blank is not a two-column nm/value table")
    nm <- suppressWarnings(as.numeric(df$nm)); val <- suppressWarnings(as.numeric(df$val))
    ok <- is.finite(nm) & is.finite(val)
    nm <- nm[ok]; val <- val[ok]
    if (length(nm) < 2L || length(unique(nm)) < 2L)
      stop("measured blank needs at least two distinct finite wavelengths")
    c("nm\tblank_od", paste(sprintf("%.17g", nm), sprintf("%.17g", val), sep = "\t"))
  }
  .decon_blank_content_sha256 <- function(df)
    .pasa_sha256_lines(.decon_blank_canonical_lines(df))

  build_decon_blank_block <- function() {
    d <- .decon_blank_state_data(decon_blank_state())
    if (is.null(d) || !is.data.frame(d) || !nrow(d)) return("mode=none")
    nm <- as.numeric(d$nm); val <- as.numeric(d$val)
    d <- data.frame(nm = nm, val = val, stringsAsFactors = FALSE)
    src <- attr(decon_blank_df(), "source_name", exact = TRUE)
    if (is.null(src) || !length(src) || is.na(src[1]) || !nzchar(src[1])) src <- "measured_blank"
    src <- basename(as.character(src[1]))
    c("mode=measured_blank",
      paste0("name_json=", as.character(jsonlite::toJSON(src, auto_unbox = TRUE))),
      paste0("content_sha256=", .decon_blank_content_sha256(d)),
      .decon_blank_canonical_lines(d))
  }

  .parse_decon_blank_block <- function(lines) {
    keep <- lines[!grepl("^\\s*#", lines) & nzchar(trimws(lines))]
    if (!length(keep)) stop("the [DECON_BLANK_DATA] block is empty")
    kv_lines <- keep[grepl("^[A-Za-z_][A-Za-z0-9_]*=", keep)]
    kv <- list()
    for (ln in kv_lines) {
      i <- regexpr("=", ln, fixed = TRUE); k <- substr(ln, 1L, i - 1L)
      if (!is.null(kv[[k]])) stop(sprintf("duplicate measured-blank key '%s'", k))
      kv[[k]] <- substr(ln, i + 1L, nchar(ln))
    }
    mode <- as.character(kv$mode %||% "")
    if (identical(mode, "none")) {
      extra <- setdiff(keep, "mode=none")
      if (length(extra)) stop("mode=none measured-blank block contains unexpected data")
      return(NULL)
    }
    if (!identical(mode, "measured_blank")) stop("measured-blank mode must be 'none' or 'measured_blank'")
    hdr <- which(keep == "nm\tblank_od")
    if (length(hdr) != 1L) stop("measured-blank block needs exactly one 'nm<TAB>blank_od' header")
    rows <- keep[seq.int(hdr + 1L, length(keep))]
    if (hdr == length(keep) || length(rows) < 2L) stop("measured-blank block has fewer than two data rows")
    if (length(rows) > STATE_LIMITS$max_rows)
      stop(sprintf("measured-blank block has %d rows; limit is %d", length(rows), STATE_LIMITS$max_rows))
    if (any(grepl("^[A-Za-z_][A-Za-z0-9_]*=", rows)))
      stop("measured-blank metadata must precede the data header")
    parts <- strsplit(rows, "\t", fixed = TRUE)
    widths <- vapply(parts, length, integer(1))
    if (any(widths != 2L)) stop("every measured-blank data row must have exactly two tab-separated fields")
    nm <- suppressWarnings(as.numeric(vapply(parts, `[`, character(1), 1L)))
    val <- suppressWarnings(as.numeric(vapply(parts, `[`, character(1), 2L)))
    if (any(!is.finite(nm)) || any(!is.finite(val))) stop("measured-blank values must all be finite numbers")
    if (length(unique(nm)) < 2L) stop("measured blank needs at least two distinct wavelengths")
    d <- data.frame(nm = nm, val = val, stringsAsFactors = FALSE)
    declared <- toupper(as.character(kv$content_sha256 %||% ""))
    if (!grepl("^[0-9A-F]{64}$", declared)) stop("measured-blank content_sha256 is missing or malformed")
    observed <- .decon_blank_content_sha256(d)
    legacy_crlf <- .pasa_sha256_lines_legacy_crlf(.decon_blank_canonical_lines(d))
    legacy_accepted <- !identical(declared, observed) && identical(declared, legacy_crlf)
    if (!identical(declared, observed) && !legacy_accepted)
      stop("measured-blank content hash does not match its numeric rows")
    src <- "measured_blank"
    if (!is.null(kv$name_json)) {
      src <- tryCatch(as.character(jsonlite::parse_json(kv$name_json, simplifyVector = TRUE))[1], error = function(e) NA_character_)
      if (is.na(src) || !nzchar(src)) stop("measured-blank name_json is invalid")
      if (!is.null(.c0_offending(src, "measured-blank name"))) stop("measured-blank name contains a control character")
      src <- basename(src)
    }
    attr(d, "source_name") <- src
    attr(d, "content_sha256") <- observed
    attr(d, "content_sha256_imported") <- declared
    attr(d, "content_sha256_legacy_crlf") <- legacy_accepted
    d
  }

  .validate_snapshot_blank <- function(lines) {
    err <- tryCatch({ .parse_decon_blank_block(lines); NULL }, error = function(e) conditionMessage(e))
    list(ok = is.null(err), errors = if (is.null(err)) character(0) else err)
  }

  build_state_text <- function(include_settings = TRUE, include_data = TRUE) {
    lines <- c(
      "# PASA state file",
      paste0("# Generated: ", format(Sys.time(), "%Y-%m-%d %H:%M:%S")),
      "# To reload: open the app, set 'Data source' on the Input data tab to 'Import session',",
      "# upload this file, then pick the sections you want to restore in the dialog.",
      "state_schema_version=4"
    )
    .keep_c0 <- function(e) { if (inherits(e, c("pasa_c0_refusal", "pasa_decon_blank_refusal"))) stop(e); character(0) }  # preserve invalid-data refusals instead of silently omitting state sections
    if (isTRUE(include_settings)) {
      sett <- tryCatch(build_settings_block(input), error = .keep_c0)
      if (length(sett)) lines <- c(lines, "", "[SETTINGS]", sett)
    }
    if (isTRUE(include_data)) {
      sb <- tryCatch(build_sidebar_data_block(input), error = .keep_c0)
      if (length(sb)) lines <- c(lines, "", "[SIDEBAR_DATA]", sb)
      gblk <- build_growth_block(input)
      .pasa_decode_growth_snapshot(gblk, STATE_LIMITS$growth) # fail export rather than omit or corrupt growth data
      if (length(gblk)) lines <- c(lines, "", "[GROWTH_DATA]", gblk)
      # The section is emitted even when no blank is active (`mode=none`).  That
      # explicit absence is required for replacement semantics: importing B
      # after A must clear A's blank and equal a fresh import of B.
      bblk <- tryCatch(build_decon_blank_block(), error = .keep_c0)
      if (length(bblk)) lines <- c(lines, "", "[DECON_BLANK_DATA]", bblk)
    }
    paste(lines, collapse = "\n")
  }

  # Split the raw file into named sections. Section headers are lines of the
  # form [NAME]. Comment lines (starting with #) and blank lines are kept inside
  # each section so callers can decide how to interpret them.
  parse_state_text <- function(txt) {
    if (is.null(txt) || !length(txt)) return(list())
    lines <- if (length(txt) == 1) strsplit(txt, "\n", fixed = TRUE)[[1]] else txt
    out <- list(); cur <- NULL; buf <- character(0)
    flush <- function() if (!is.null(cur)) out[[cur]] <<- buf
    for (ln in lines) {
      if (grepl("^\\[.+\\]$", ln)) {
        flush(); cur <- sub("^\\[(.+)\\]$", "\\1", ln); buf <- character(0)
      } else if (!is.null(cur)) buf <- c(buf, ln)
    }
    flush()
    # Back-compat: older state files used [SAMPLES_DATA] / [GROWTH_MANUAL].
    # Surface them under the new section names so downstream code only has to
    # handle one set of keys.
    if (is.null(out$SIDEBAR_DATA) && !is.null(out$SAMPLES_DATA))  out$SIDEBAR_DATA <- out$SAMPLES_DATA
    if (is.null(out$GROWTH_DATA)  && !is.null(out$GROWTH_MANUAL)) {
      gm <- out$GROWTH_MANUAL
      # Wrap legacy manual paste as new-format block (mode=manual + raw rows).
      out$GROWTH_DATA <- c("mode=manual",
                           "## values: tab-separated, one replicate per row",
                           gm)
      attr(out$GROWTH_DATA, "legacy_growth_manual") <- TRUE
    }
    if (!is.null(out$GROWTH_DATA)) {
      sv <- grep("^state_schema_version=", lines, value = TRUE)
      if (length(sv) == 1L) attr(out$GROWTH_DATA, "snapshot_schema_version") <-
        suppressWarnings(as.integer(sub("^state_schema_version=", "", sv)))
    }
    out
  }

  STATE_LIMITS <- local({
    il <- INPUT_LIMITS
    g_nrep <- 10L; g_ntech <- 6L; g_ntp <- 30L; g_cells <- g_nrep * g_ntech * g_ntp   # 1800
    # line cap: max data rows + 1 header + max growth rows + every registry/dynamic setting key + section
    # headers/comments slack. A generous but FINITE ceiling so a crafted file cannot exhaust memory.
    max_settings_keys <- nrow(.SNAPSHOT_SETTINGS_REGISTRY) + 512L   # registry + dynamic dil_* + provenance
    max_lines <- (2L * il$max_rows) + g_cells + max_settings_keys + 80L
    list(schema = "PASA-STATE-LIMITS-1",
         raw_bytes = il$raw_bytes, max_lines = max_lines,
         max_rows = il$max_rows, max_cols = il$max_cols, max_cells = il$max_cells,
         growth = list(nrep = g_nrep, ntech = g_ntech, ntp = g_ntp, cells = g_cells),
         sections = c("SETTINGS", "SIDEBAR_DATA", "GROWTH_DATA", "DECON_BLANK_DATA"),
         section_aliases = c(SAMPLES_DATA = "SIDEBAR_DATA", GROWTH_MANUAL = "GROWTH_DATA"),
         supported_schema_versions = 1:4, max_sections_each = 1L)
  })

  .validate_snapshot_structure <- function(txt) {
    errs <- character(0)
    n <- length(txt)
    if (n > STATE_LIMITS$max_lines + 1L)
      errs <- c(errs, sprintf("the snapshot exceeds the %d-line structural limit", STATE_LIMITS$max_lines))
    hdr <- grep("^\\[.+\\]$", txt, value = TRUE)
    raw_secs <- sub("^\\[(.+)\\]$", "\\1", hdr)
    canon <- ifelse(raw_secs %in% names(STATE_LIMITS$section_aliases),
                    STATE_LIMITS$section_aliases[raw_secs], raw_secs)
    unk <- setdiff(canon, STATE_LIMITS$sections)
    if (length(unk)) errs <- c(errs, sprintf("unknown section(s): %s", paste(unique(unk), collapse = ", ")))
    dup <- unique(canon[duplicated(canon)])
    if (length(dup)) errs <- c(errs, sprintf("duplicate section(s) (a legacy + current alias for the same section counts as duplicate): %s", paste(dup, collapse = ", ")))
    sv_line <- grep("^state_schema_version=", txt, value = TRUE)
    if (!length(sv_line)) errs <- c(errs, "the snapshot is missing its required state_schema_version")
    else if (length(sv_line) > 1L) errs <- c(errs, "the snapshot declares state_schema_version more than once")
    else {
      sv_raw <- trimws(sub("^state_schema_version=", "", sv_line[1]))
      if (!grepl("^[0-9]+$", sv_raw)) errs <- c(errs, sprintf("state_schema_version '%s' is not an integer", sv_raw))
      else if (!(as.integer(sv_raw) %in% STATE_LIMITS$supported_schema_versions))
        errs <- c(errs, sprintf("unsupported snapshot schema version %s (supported: %s)",
                                sv_raw, paste(range(STATE_LIMITS$supported_schema_versions), collapse = "-")))
    }
    list(ok = length(errs) == 0L, errors = errs, sections = unique(canon))
  }


  .SNAPSHOT_SETTINGS_REGISTRY <- local({
    .thr_reason <- paste("the production numericInput declares min=0 and no maximum; this is a FLAG threshold, so an",
                         "arbitrarily large value only suppresses the flag and cannot corrupt a measurement or fit.",
                         "An invented ceiling would be stricter than the live control and would false-refuse a",
                         "legitimately saved session.")
    bounds <- list(
    growth_nrep  = list(kind = "num", min = 1,   max = 10, whole = TRUE),
    growth_ntech = list(kind = "num", min = 1,   max = 6, whole = TRUE),
    growth_ntp   = list(kind = "num", min = 2,   max = 30, whole = TRUE),
    dilution     = list(kind = "num", min = 1e-6, max = 1e9),   # global dilution factor: finite, strictly positive
    grid_step    = list(kind = "num", min = 1e-6, max = 4000),  # resample grid step (nm): finite, positive
    norm_target  = list(kind = "num", min = .Machine$double.xmin, max = 1e12),  # scaling reference must be finite and strictly positive
    norm_ref_nm  = list(kind = "num", min = 100,  max = 4000),
    baseline_nm  = list(kind = "num", min = 100,  max = 4000),
    decon_kmin   = list(kind = "num", min = 1,    max = 20),
    decon_kmax   = list(kind = "num", min = 1,    max = 20),
    line_width          = list(kind = "num", min = 0.3, max = 3),
    x_axis_intensity    = list(kind = "num", min = 0,   max = 1),
    y_axis_intensity    = list(kind = "num", min = 0,   max = 1),
    gridline_intensity  = list(kind = "num", min = 0,   max = 1),
    decon_mu_tol        = list(kind = "num", min = 1,   max = 40),
    band_fill_intensity      = list(kind = "num", min = 0,    max = 1),
    growth_phase_alpha       = list(kind = "num", min = 0,    max = 1),
    spectra_3d_opacity       = list(kind = "num", min = 0.1,  max = 1),
    spectra_3d_probe_opacity = list(kind = "num", min = 0.05, max = 1),
    sg_n                     = list(kind = "num", min = 1,    max = 20),
    sg_p                     = list(kind = "num", min = 2,    max = 5),
    ma_k                     = list(kind = "num", min = 1,    max = 20),
    spectra_3d_res           = list(kind = "num", min = 40,   max = 4000),
    spectra_3d_export_scale  = list(kind = "num", min = 1,    max = 8),
    sim_pair_budget          = list(kind = "num", min = 0,    max = length(.SIM_BUDGET_TRACE_STOPS) - 1L),
    growth_wl                = list(kind = "num", min = 100,  max = 4000),
    decon_fwhm_min       = list(kind = "num", min = 1,   max = 60),
    decon_fwhm_max       = list(kind = "num", min = 5,   max = 200),
    decon_seed_win       = list(kind = "num", min = 7,   max = 41,  whole = TRUE),
    decon_red_clip       = list(kind = "num", min = 650, max = 1000),
    decon_scatter_start  = list(kind = "num", min = 300, max = 900),
    decon_scatter_end    = list(kind = "num", min = 300, max = 1000),
    decon_scatter_fixb   = list(kind = "num", min = 0,   max = 4.5),
    #   wavelength probes and display geometry
    probe_nm             = list(kind = "num", min = 300, max = 900),
    spectra_3d_label_dist = list(kind = "num", min = 0,  max = 300),
    #   QC FRACTIONS -- the two the UI itself caps at 1, plus the correlation cutoff
    nqc_frac_caution     = list(kind = "num", min = 0,   max = 1),
    nqc_frac_fail        = list(kind = "num", min = 0,   max = 1),
    qc_dup_cor           = list(kind = "num", min = 0,   max = 1),
    #   FLAG THRESHOLDS. Their numericInputs declare `min = 0` and NO maximum, and raising one only makes the flag
    #   fire less often -- it cannot corrupt a measurement or a fit. Declaring an invented ceiling here would be a
    #   stricter validator than the live control and would false-refuse a legitimately saved session, so the upper
    #   side is explicitly unbounded WITH .thr_reason (defined above) rather than left as a silent null.
    qc_baseline_tol      = list(kind = "num", min = 0, max = Inf, max_reason = .thr_reason),
    qc_sat_thresh        = list(kind = "num", min = 0, max = Inf, max_reason = .thr_reason),
    nqc_global_caution   = list(kind = "num", min = 0, max = Inf, max_reason = .thr_reason),
    nqc_global_fail      = list(kind = "num", min = 0, max = Inf, max_reason = .thr_reason),
    nqc_tail_caution     = list(kind = "num", min = 0, max = Inf, max_reason = .thr_reason),
    nqc_tail_fail        = list(kind = "num", min = 0, max = Inf, max_reason = .thr_reason),
    nqc_local_caution    = list(kind = "num", min = 0, max = Inf, max_reason = .thr_reason),
    nqc_local_fail       = list(kind = "num", min = 0, max = Inf, max_reason = .thr_reason),
    #   color-rendering target OD: the numericInput declares min=0.01 and no maximum. A larger target only scales
    #   the rendered swatch; it is a display target, not a measured absorbance.
    cuv_od               = list(kind = "num", min = 0.01, max = Inf,
                                max_reason = paste("the production numericInput declares min=0.01 and no maximum;",
                                                   "this is a color-RENDERING target, not a measured absorbance, so a",
                                                   "larger value only scales the displayed swatch.")),
    #   growth grid spacing: any finite positive value; fractional intervals are
    #   retained because spacing is expressed in the user's chosen time unit.
    growth_interval      = list(kind = "num", min = 0.001, max = Inf,
                                max_reason = paste("the production numericInput declares min=0.001, step=0.1 and no maximum;",
                                                   "the spacing is expressed in the user's own chosen time unit, so no",
                                                   "universal ceiling exists.")),
    # wavelength range sliders: two finite endpoints, lo<=hi, within the spectrometer band (nm)
    analysis_nm  = list(kind = "range", min = 100, max = 4000),
    baseline_win = list(kind = "range", min = 100, max = 4000),
    qy = list(kind = "range", min = 100, max = 4000), pbs = list(kind = "range", min = 100, max = 4000),
    chlb_qy = list(kind = "range", min = 100, max = 4000), pe = list(kind = "range", min = 100, max = 4000),
    car = list(kind = "range", min = 100, max = 4000), bx = list(kind = "range", min = 100, max = 4000)
    )
    reg <- .SNAPSHOT_SETTINGS_REGISTRY
    .orphan <- setdiff(names(bounds), reg$key)
    if (length(.orphan)) stop(sprintf("Typed snapshot bound(s) exist for non-registry key(s): %s", paste(.orphan, collapse = ", ")))
    .sliderkeys <- reg$key[reg$route %in% c("scalar_slider", "range_slider")]
    .unbounded  <- setdiff(.sliderkeys, names(bounds))
    if (length(.unbounded)) stop(sprintf("Slider key(s) have a bounded UI domain but no typed snapshot bound: %s", paste(.unbounded, collapse = ", ")))
    .numkeys   <- reg$key[reg$route == "numeric"]
    .num_unb   <- setdiff(.numkeys, names(bounds))
    if (length(.num_unb)) stop(sprintf("Numeric key(s) have no typed snapshot bound: %s", paste(.num_unb, collapse = ", ")))
    .no_reason <- Filter(Negate(is.null), lapply(.numkeys, function(k) {
      b <- bounds[[k]]
      bad <- c(if (!is.finite(b$min %||% NA_real_) && !nzchar(b$min_reason %||% "")) "min",
               if (!is.finite(b$max %||% NA_real_) && !nzchar(b$max_reason %||% "")) "max")
      if (length(bad)) sprintf("%s (%s)", k, paste(bad, collapse = "+")) else NULL }))
    if (length(.no_reason))
      stop(sprintf("Numeric key(s) have an infinite bound and no documented unbounded reason: %s",
                   paste(unlist(.no_reason), collapse = ", ")))
    attr(reg, "bounds") <- bounds
    reg
  })

  .SNAP_ROUTE_OPS <- local({
    tf_decode <- function(v) { lv <- toupper(trimws(v))
      if (lv %in% c("TRUE","T","1","YES")) TRUE else if (lv %in% c("FALSE","F","0","NO","")) FALSE else NA }
    mk <- function(parse, validate, write, apply, reset)
      list(parse = parse, validate = validate, write = write, apply = apply, reset = reset)
    # --- numeric-scalar family (scalar_slider uses updateSliderInput; numeric uses updateNumericInput) ---
    num_validate <- function(k, v, ctx) {
      num <- suppressWarnings(as.numeric(v)); b <- ctx$bounds
      if (!is.finite(num)) return(sprintf("setting '%s' is not a finite number ('%s')", k, v))
      if (!is.null(b) && identical(b$kind, "num")) {
        if (num < b$min || num > b$max) return(sprintf("setting '%s'=%s is outside the allowed range [%s, %s]", k, v, b$min, b$max))
        if (isTRUE(b$nonzero) && num == 0)  return(sprintf("setting '%s'=%s must be a non-zero number", k, v))
        if (isTRUE(b$whole) && num != round(num))
          return(sprintf("setting '%s'=%s must be a whole number", k, v)) }
      character(0)
    }
    enum_validate <- function(k, v, ctx) { ch <- ctx$choices
      if (!is.null(ch) && length(ch) && !(v %in% ch))
        sprintf("setting '%s'='%s' is not a valid choice (allowed: %s)", k, v, paste(ch, collapse = ", ")) else character(0) }
    tf_validate <- function(k, v, ctx)
      if (!(toupper(trimws(v)) %in% c("TRUE","FALSE","T","F","0","1","YES","NO",""))) sprintf("setting '%s'='%s' is not a valid true/false value", k, v) else character(0)
    scalar_write <- function(k, input, emit) emit(k, input[[k]])
    list(
      range_slider = mk(
        parse    = function(v) { z <- suppressWarnings(as.numeric(strsplit(v, ",", fixed = TRUE)[[1]])); if (length(z) >= 2 && all(is.finite(z[1:2]))) z[1:2] else NULL },
        validate = function(k, v, ctx) sprintf("setting '%s' is a range and must be provided as '%s_lo' and '%s_hi', not a bare value ('%s')", k, k, k, v),
        write    = function(k, input, emit) { v <- input[[k]]; if (is.null(v) || length(v) < 2) v <- c(NA, NA); c(emit(paste0(k,"_lo"), v[1]), emit(paste0(k,"_hi"), v[2])) },
        apply    = function(session, k, val) { z <- suppressWarnings(as.numeric(strsplit(val, ",", fixed = TRUE)[[1]]))
                     if (length(z) >= 2 && all(is.finite(z[1:2]))) { updateSliderInput(session, k, value = z[1:2]); .prov_mark(k, z[1:2], "restored"); TRUE } else FALSE },
        reset    = function(session, k, d) { if (length(d) >= 2) { updateSliderInput(session, k, value = d[1:2]); list(pv = d[1:2]) } else list(pv = NULL) }),
      scalar_slider = mk(
        parse    = function(v) { z <- suppressWarnings(as.numeric(v)); if (is.finite(z)) z else NULL },
        validate = num_validate, write = scalar_write,
        apply    = function(session, k, val) { z <- suppressWarnings(as.numeric(val)); if (is.finite(z)) { updateSliderInput(session, k, value = z); TRUE } else FALSE },
        reset    = function(session, k, d) { updateSliderInput(session, k, value = d); list(pv = d) }),
      numeric = mk(
        parse    = function(v) { z <- suppressWarnings(as.numeric(v)); if (is.finite(z)) z else NULL },
        validate = num_validate, write = scalar_write,
        apply    = function(session, k, val) { z <- suppressWarnings(as.numeric(val)); if (is.finite(z)) { updateNumericInput(session, k, value = z); .prov_mark(k, z, "restored"); TRUE } else FALSE },
        reset    = function(session, k, d) { updateNumericInput(session, k, value = d); list(pv = d) }),
      checkbox = mk(
        parse = tf_decode, validate = tf_validate, write = scalar_write,
        apply = function(session, k, val) { v <- tf_decode(val); if (!is.na(v)) { updateCheckboxInput(session, k, value = v); .prov_mark(k, v, "restored"); TRUE } else FALSE },
        reset = function(session, k, d) { updateCheckboxInput(session, k, value = isTRUE(d)); list(pv = isTRUE(d)) }),
      select = mk(
        parse = function(v) v, validate = enum_validate, write = scalar_write,
        apply = function(session, k, val) { updateSelectInput(session, k, selected = val); .prov_mark(k, val, "restored"); TRUE },
        reset = function(session, k, d) { updateSelectInput(session, k, selected = d); list(pv = d) }),
      radio = mk(
        parse = function(v) v, validate = enum_validate, write = scalar_write,
        apply = function(session, k, val) { updateRadioButtons(session, k, selected = val); .prov_mark(k, val, "restored"); TRUE },
        reset = function(session, k, d) { updateRadioButtons(session, k, selected = d); list(pv = d) }),
      text = mk(
        parse = function(v) v, validate = function(k, v, ctx) character(0), write = scalar_write,
        apply = function(session, k, val) { updateTextInput(session, k, value = val); TRUE },
        reset = function(session, k, d) { updateTextInput(session, k, value = d); list(pv = d) }),
      advanced_mode = mk(
        parse = tf_decode, validate = tf_validate, write = scalar_write,
        apply = function(session, k, val) { v <- tf_decode(val); if (!is.na(v)) { updateCheckboxInput(session, "advanced_mode", value = v); TRUE } else FALSE },
        reset = function(session, k, d) { updateCheckboxInput(session, k, value = isTRUE(d)); list(pv = isTRUE(d)) }),
      dilution_family = mk(
        parse = function(v) { z <- suppressWarnings(as.numeric(v)); if (is.finite(z) && z > 0) z else NULL },
        validate = function(k, v, ctx) { num <- suppressWarnings(as.numeric(v)); if (!is.finite(num) || num <= 0) sprintf("dilution '%s'='%s' must be a finite positive number", k, v) else character(0) },
        write = function(k, input, emit) emit(k, input[[k]]),
        apply = function(session, k, val) { v <- suppressWarnings(as.numeric(val)); if (is.finite(v) && v > 0) { cur <- restored_dil(); cur[[k]] <- v; restored_dil(cur); updateNumericInput(session, k, value = v); TRUE } else FALSE },
        reset = function(session, k, d) list(pv = NULL)),
      # excluded rows: never written or reset; the validator REJECTS an excluded key that appears in a snapshot
      # (an action/data/transient input is not a restorable parameter).
      excluded = mk(parse = function(v) NULL,
                    validate = function(k, v, ctx) sprintf("setting '%s' is not a restorable parameter (an excluded action/data/transient input) and must not appear in a snapshot", k),
                    write = function(k, input, emit) character(0), apply = function(session, k, val) FALSE, reset = function(session, k, d) list(pv = NULL)),
      none     = mk(parse = function(v) NULL, validate = function(k, v, ctx) character(0), write = function(k, input, emit) emit(k, input[[k]]), apply = function(session, k, val) FALSE, reset = function(session, k, d) list(pv = NULL))
    )
  })

  .SNAPSHOT_SETTINGS_REGISTRY <- local({
    reg <- .SNAPSHOT_SETTINGS_REGISTRY
    b_attr <- attr(reg, "bounds", exact = TRUE); if (is.null(b_attr)) b_attr <- list()
    harvested <- local({
      html <- tryCatch(htmltools::renderTags(ui)$html, error = function(e) "")
      out <- list()
      for (blk in regmatches(html, gregexpr('(?s)<select\\b[^>]*\\bid="([^"]+)"[^>]*>(.*?)</select>', html, perl = TRUE))[[1]]) {
        id  <- sub('(?s).*?\\bid="([^"]+)".*', '\\1', blk, perl = TRUE)
        opt <- regmatches(blk, gregexpr('<option[^>]*\\bvalue="([^"]*)"', blk, perl = TRUE))[[1]]
        v   <- sub('.*value="([^"]*)"', '\\1', opt); if (length(v)) out[[id]] <- unique(v)
      }
      for (tag in regmatches(html, gregexpr('<input\\b[^>]*type="radio"[^>]*>', html, perl = TRUE))[[1]]) {
        if (!grepl('name="', tag) || !grepl('value="', tag)) next
        nm <- sub('.*name="([^"]*)".*', '\\1', tag); vl <- sub('.*value="([^"]*)".*', '\\1', tag)
        out[[nm]] <- unique(c(out[[nm]], vl))
      }
      out[["organism"]]    <- unname(.ORGANISM_CHOICES)      # fixed renderUI domains (not in the static ui)
      out[["norm_method"]] <- unname(.NORM_METHOD_CHOICES)
      out
    })
    .type_of <- function(route) switch(route,
      range_slider = "numeric2", scalar_slider = , numeric = "numeric",
      checkbox = , advanced_mode = "logical", select = , radio = "enum",
      text = "character", none = "provenance",
      dilution_family = "numeric_family", excluded = "excluded", "unknown")
    reg$type       <- vapply(reg$route, .type_of, character(1))
    reg$choices    <- lapply(reg$key, function(k) harvested[[k]])            # NULL where no static domain
    # The Deconvolution tab is inserted dynamically, so its two current radio
    # values are not present in the static UI harvest. Seed them explicitly;
    # legacy values remain valid at the file-validation boundary and are
    # normalized by .apply_settings() before any widget is updated.
    .di <- match("decon_depth", reg$key)
    if (!is.na(.di)) reg$choices[[.di]] <- unique(c("tested", "advanced",
      reg$choices[[.di]], DECON_DEPTH_SNAPSHOT_ALIASES))
    reg$bounds     <- lapply(reg$key, function(k) b_attr[[k]])               # NULL where unbounded
    .op <- function(field) lapply(reg$route, function(r) { o <- .SNAP_ROUTE_OPS[[r]]; if (is.null(o)) NULL else o[[field]] })
    reg$parse      <- .op("parse")
    reg$validate   <- .op("validate")   # ACTUAL value-validators (consumed by .validate_snapshot_settings)
    reg$write      <- .op("write")      # ACTUAL encoders (consumed by build_settings_block)
    reg$apply      <- .op("apply")
    reg$reset      <- .op("reset")      # ACTUAL reset ops (consumed by .registry_reset_plan)
    reg$provenance <- ifelse(reg$key %in% .PROV_IDS, "event", "value")
    reg$exclusion_reason <- vapply(reg$key, function(k)
      if (k %in% names(.SNAPSHOT_EXCLUSION_REASONS)) unname(.SNAPSHOT_EXCLUSION_REASONS[[k]]) else NA_character_, character(1))
    attr(reg, "bounds") <- NULL   # column is now the single source
    reg
  })
  local({
    reg <- .SNAPSHOT_SETTINGS_REGISTRY
    for (col in c("key","route","default","type","choices","bounds","parse","validate","write","apply","reset","provenance","exclusion_reason"))
      if (!col %in% names(reg)) stop(sprintf("Snapshot registry is missing generated column '%s'", col))
    known_routes <- c("range_slider","scalar_slider","numeric","checkbox","select","radio","text","advanced_mode","none","dilution_family","excluded")
    .bad <- setdiff(unique(reg$route), known_routes)
    if (length(.bad)) stop(sprintf("Snapshot registry route(s) have no generated handler: %s", paste(.bad, collapse = ", ")))
    .gi    <- function(k) match(k, reg$key)
    .vjudge <- function(k, v) { i <- .gi(k); e <- reg$validate[[i]](k, v, list(bounds = .snap_bounds(k), choices = reg$choices[[i]])); length(e) && nzchar(e[1]) }   # TRUE == rejected
    .emitT  <- function(k, v) if (is.null(v) || (length(v) == 1L && is.na(v))) character(0) else paste0(k, "=", v)
    .props <- c(
      .vjudge("line_width", "-5"),                                     # scalar bound rejects out-of-range
      !.vjudge("line_width", "1.5"),                                   # scalar bound accepts in-range
      isTRUE(all.equal(reg$parse[[.gi("line_width")]]("1.5"), 1.5)),   # scalar parse decodes
      .vjudge("qy", "bad"),                                            # bare range key rejected
      .vjudge("organism", "zzz"),                                      # enum choice rejects unknown
      !.vjudge("organism", "cyano"),                                   # enum choice accepts valid
      .vjudge("file", "x"),                                            # excluded key rejected in a snapshot
      !( { e <- .SNAP_ROUTE_OPS$dilution_family$validate("dil_S1", "2",  NULL); length(e) && nzchar(e[1]) } ),  # dilution family accepts a positive value
      (  { e <- .SNAP_ROUTE_OPS$dilution_family$validate("dil_S1", "-1", NULL); length(e) && nzchar(e[1]) } ),  # dilution family rejects a non-positive value
      identical(reg$write[[.gi("qy")]]("qy", list(qy = c(660, 690)), .emitT), c("qy_lo=660", "qy_hi=690")),   # range write emits _lo/_hi
      identical(reg$write[[.gi("file")]]("file", list(file = "x"), .emitT), character(0)))                    # excluded write emits nothing
    if (!all(.props)) stop(sprintf("Snapshot registry handler propagation self-test failed at check(s): %s", paste(which(!.props), collapse = ", ")))
    # PROPAGATION check: the co-located `choices` column IS the validator's domain source. Prove it is populated by
    # asserting the harvested/fixed domains landed in the column (a static select whose domain was resolved, plus the
    # two fixed renderUI domains). A row-count / handler mutation is caught above; a choices mutation flows straight
    # into the validator (which reads reg$choices), so it cannot silently diverge. renderUI-only controls
    # (theme_mode/baseline_method/smooth/... and sample_type/decon_sample/norm_band) have no static domain by design
    # and are validated structurally -- exactly as before.
    for (k in c("organism","norm_method")) {
      ch <- reg$choices[[match(k, reg$key)]]
      if (is.null(ch) || !length(ch)) stop(sprintf("Fixed snapshot choice domain is not co-located for '%s'", k))
    }
    if (!any(vapply(reg$choices, function(x) length(x) > 0L, logical(1))))
      stop("No static choice domain is co-located in the snapshot registry choices column")
    invisible()
  })

  .SNAPSHOT_RELATIONS <- list(
    list(lo = "decon_kmin",         hi = "decon_kmax",         why = "component-count range is reversed"),
    list(lo = "decon_fwhm_min",     hi = "decon_fwhm_max",     why = "band-width (FWHM) window is reversed"),
    list(lo = "decon_scatter_start",hi = "decon_scatter_end",  why = "scattering tail-fit window is reversed"),
    list(lo = "nqc_global_caution", hi = "nqc_global_fail",    why = "global CAUTION threshold is above its FAIL threshold"),
    list(lo = "nqc_tail_caution",   hi = "nqc_tail_fail",      why = "tail CAUTION threshold is above its FAIL threshold"),
    list(lo = "nqc_local_caution",  hi = "nqc_local_fail",     why = "local CAUTION threshold is above its FAIL threshold"),
    list(lo = "nqc_frac_caution",   hi = "nqc_frac_fail",      why = "fraction CAUTION threshold is above its FAIL threshold")
  )

  .validate_snapshot_settings <- function(setting_lines) {
    errs <- character(0); reg <- .SNAPSHOT_SETTINGS_REGISTRY
    prov_keys  <- c("state_schema_version", "samples_json", "app_version", "numerical_methods_version", "software_versions", "samples",
                    "provenance_schema_version",
                    "app_sha256", "module_sha256", PASA_EXEC_FREEZE_FIELD, PASA_EXEC_FREEZE_LEGACY,
                    "dependency_lock_sha256", "public_bundle_sha256")
    range_keys <- .snap_reg_ids("range_slider")
    keep <- !grepl("^\\s*#", setting_lines) & nzchar(trimws(setting_lines))
    kv <- list(); seen <- character(0); dupd <- character(0)
    for (ln in setting_lines[keep]) {
      if (!grepl("=", ln, fixed = TRUE)) next
      i <- regexpr("=", ln, fixed = TRUE); k <- trimws(substr(ln, 1, i - 1)); v <- substr(ln, i + 1, nchar(ln))
      if (!nzchar(k)) next
      if (k %in% seen) dupd <- c(dupd, k) else { seen <- c(seen, k); kv[[k]] <- v }
    }
    if (length(dupd)) errs <- c(errs, sprintf("duplicate setting key(s): %s", paste(unique(dupd), collapse = ", ")))
    is_range_part <- function(k) grepl("_(lo|hi)$", k) && sub("_(lo|hi)$", "", k) %in% range_keys
    for (k in names(kv)) {
      v <- kv[[k]]
      known <- k %in% reg$key || k %in% prov_keys || grepl("^dil_", k) || is_range_part(k)
      if (!known) { errs <- c(errs, sprintf("unsupported (unknown) setting key '%s'", k)); next }
      if (!is.null(.c0_offending(v, k))) { errs <- c(errs, sprintf("setting '%s' value contains a control character", k)); next }
      if (grepl("^dil_", k)) {
        err <- .SNAP_ROUTE_OPS$dilution_family$validate(k, v, NULL)
        if (length(err) && nzchar(err[1])) errs <- c(errs, err)
        next
      }
      if (identical(k, "samples_json")) {
        vj <- tryCatch(jsonlite::parse_json(v, simplifyVector = TRUE), error = function(e) NULL)
        if (is.null(vj)) errs <- c(errs, "samples_json is not valid JSON")
        else { ids <- as.character(unlist(vj))
          if (!is.null(.c0_offending(ids, "samples_json ids"))) errs <- c(errs, "samples_json contains an id with a control character")
          else if (length(ids) && anyDuplicated(ids) > 0L) errs <- c(errs, "samples_json contains duplicate sample ids") }
        next
      }
      .ri <- if (k %in% reg$key) match(k, reg$key) else NA_integer_
      if (is.na(.ri)) next    # provenance / range-part handled below (no registry row)
      vop <- reg$validate[[.ri]]
      if (is.function(vop)) {
        err <- vop(k, v, list(bounds = .snap_bounds(k), choices = reg$choices[[.ri]]))
        if (length(err) && nzchar(err[1])) errs <- c(errs, err)
      }
    }
    for (rk in range_keys) {
      lo <- kv[[paste0(rk, "_lo")]]; hi <- kv[[paste0(rk, "_hi")]]
      if (is.null(lo) && is.null(hi)) next
      if (is.null(lo) || is.null(hi)) { errs <- c(errs, sprintf("range '%s' is incomplete (needs both _lo and _hi)", rk)); next }
      lon <- suppressWarnings(as.numeric(lo)); hin <- suppressWarnings(as.numeric(hi))
      if (!is.finite(lon) || !is.finite(hin)) { errs <- c(errs, sprintf("range '%s' has a non-finite endpoint", rk)); next }
      if (lon > hin) errs <- c(errs, sprintf("range '%s' is reversed (lo %s > hi %s)", rk, lon, hin))
      b <- .snap_bounds(rk)
      if (!is.null(b) && (lon < b$min || hin > b$max))
        errs <- c(errs, sprintf("range '%s' [%s, %s] is outside the allowed domain [%s, %s]", rk, lon, hin, b$min, b$max))
    }
    .rel_num <- function(key) { v <- kv[[key]]; if (is.null(v)) NA_real_ else suppressWarnings(as.numeric(v)) }
    for (rel in .SNAPSHOT_RELATIONS) {
      lo <- .rel_num(rel$lo); hi <- .rel_num(rel$hi)
      if (is.finite(lo) && is.finite(hi) && lo > hi)
        errs <- c(errs, sprintf("%s=%s must be <= %s=%s (%s)", rel$lo, kv[[rel$lo]], rel$hi, kv[[rel$hi]], rel$why))
    }
    list(ok = length(errs) == 0L, errors = errs, kv = kv)
  }

  .validate_snapshot_data <- function(lines) {
    keep <- lines[!grepl("^\\s*#", lines) & nzchar(trimws(lines))]
    if (length(keep) < 2L) return(list(ok = FALSE, errors = "the [SIDEBAR_DATA] block has a header but no data rows"))
    hdr <- strsplit(keep[1], "\t", fixed = TRUE)[[1]]; ncol_h <- length(hdr)
    if (ncol_h < 2L) return(list(ok = FALSE, errors = "the data header needs a wavelength column plus at least one sample"))
    errs <- character(0)
    hdr_norm <- .snap_norm_hdr(hdr)
    if (!is.null(.c0_offending(hdr_norm, "data column names")))
      errs <- c(errs, "a data column header contains a control character")
    .dh <- unique(hdr_norm[duplicated(hdr_norm)])
    if (length(.dh)) errs <- c(errs, sprintf("duplicate column header(s): %s", paste(.dh, collapse = ", ")))
    if (ncol_h > STATE_LIMITS$max_cols + 1L)
      errs <- c(errs, sprintf("too many columns (%d; limit is %d samples + 1 wavelength)", ncol_h, STATE_LIMITS$max_cols))
    body <- keep[-1]
    if (length(body) > STATE_LIMITS$max_rows)
      errs <- c(errs, sprintf("too many data rows (%d > %d)", length(body), STATE_LIMITS$max_rows))
    if (as.numeric(length(body)) * ncol_h > STATE_LIMITS$max_cells)
      errs <- c(errs, sprintf("too many cells (%.0f > %g)", as.numeric(length(body)) * ncol_h, STATE_LIMITS$max_cells))
    widths <- vapply(strsplit(body, "\t", fixed = TRUE), length, integer(1))
    bad <- which(widths != ncol_h)
    if (length(bad))
      errs <- c(errs, sprintf("%d data row(s) do not have exactly %d fields (rows are never padded or truncated; first offender is data row %d with %d field(s))",
                              length(bad), ncol_h, bad[1], widths[bad[1]]))
    else {
      parts <- strsplit(body, "\t", fixed = TRUE)
      nm <- suppressWarnings(as.numeric(vapply(parts, `[`, character(1), 1L)))
      if (any(!is.finite(nm)))
        errs <- c(errs, "the wavelength axis contains a non-finite (NA/NaN/Inf) value; the restored axis must be entirely finite")
      else if (length(unique(nm)) < 2L)
        errs <- c(errs, "the wavelength axis has fewer than two distinct finite values")
      samp <- unlist(lapply(parts, function(r) if (length(r) > 1L) r[-1L] else character(0)), use.names = FALSE)
      nonmiss <- samp[nzchar(trimws(samp)) & !tolower(trimws(samp)) %in% c("na", "nan", "inf", "+inf", "-inf")]
      if (length(nonmiss) && any(!is.finite(suppressWarnings(as.numeric(nonmiss)))))
        errs <- c(errs, "one or more spectral (sample) values are not finite numbers; the restored table must contain only finite numeric absorbance values (blank or 'NA' allowed as missing)")
    }
    if (length(errs) == 0L) {
      .pr <- tryCatch(.parse_sidebar_data_block(lines), error = function(e) e)
      if (inherits(.pr, "error"))
        errs <- c(errs, sprintf("the data block cannot be parsed by the applier: %s", conditionMessage(.pr)))
      else if (is.null(.pr) || !is.data.frame(.pr) || nrow(.pr) < 2L || ncol(.pr) < 2L)
        errs <- c(errs, "the data block does not parse into a usable table (empty or degenerate after parsing)")
    }
    list(ok = length(errs) == 0L, errors = errs)
  }

  .validate_snapshot_growth <- function(lines, legacy_settings = list()) {
    tryCatch({
      decoded <- .pasa_decode_growth_snapshot(lines, STATE_LIMITS$growth, legacy_settings)
      list(ok = TRUE, errors = character(0), decoded = decoded)
    }, error = function(e) list(ok = FALSE, errors = conditionMessage(e), decoded = NULL))
  }

  .validate_snapshot <- function(parsed, selected) {
    errs <- character(0); prepared <- list()
    settings <- if (!is.null(parsed$SETTINGS)) parse_settings_block(parsed$SETTINGS) else list()
    if ("SETTINGS" %in% selected && !is.null(parsed$SETTINGS)) {
      v <- .validate_snapshot_settings(parsed$SETTINGS)
      if (!v$ok) errs <- c(errs, paste0("Settings — ", v$errors)) else prepared$settings <- settings
    }
    if ("SIDEBAR_DATA" %in% selected && !is.null(parsed$SIDEBAR_DATA)) {
      v <- .validate_snapshot_data(parsed$SIDEBAR_DATA)
      if (!v$ok) errs <- c(errs, paste0("Input data — ", v$errors)) else
        prepared$data <- .parse_sidebar_data_block(parsed$SIDEBAR_DATA)
    }
    if ("GROWTH_DATA" %in% selected && !is.null(parsed$GROWTH_DATA)) {
      v <- .validate_snapshot_growth(parsed$GROWTH_DATA, settings)
      if (!v$ok) errs <- c(errs, paste0("Cell Growth — ", v$errors)) else {
        prepared$growth <- v$decoded
        if ("SETTINGS" %in% selected && !is.null(parsed$SETTINGS)) {
          expected <- list(growth_manual = identical(v$decoded$mode, "manual"),
                           growth_nrep = v$decoded$nrep, growth_interval = v$decoded$interval,
                           growth_unit = v$decoded$unit)
          if (identical(v$decoded$mode, "manual")) {
            expected$growth_ntech <- v$decoded$ntech; expected$growth_ntp <- v$decoded$ntp
          }
          for (key in intersect(names(expected), names(settings))) {
            value <- expected[[key]]; raw <- settings[[key]]
            same <- if (is.logical(value)) {
                      .i <- match(key, .SNAPSHOT_SETTINGS_REGISTRY$key)
                      .parse <- .SNAPSHOT_SETTINGS_REGISTRY$parse[[.i]]
                      isTRUE(tryCatch(identical(.parse(raw), value), error = function(e) FALSE))
                    }
                    else if (is.numeric(value)) isTRUE(all.equal(suppressWarnings(as.numeric(raw)), as.numeric(value), tolerance = 0))
                    else identical(raw, value)
            if (!same) errs <- c(errs, paste0("Settings and Cell Growth disagree on ", key))
          }
        }
      }
    }
    if ("DECON_BLANK_DATA" %in% selected && !is.null(parsed$DECON_BLANK_DATA)) {
      v <- .validate_snapshot_blank(parsed$DECON_BLANK_DATA)
      if (!v$ok) errs <- c(errs, paste0("Measured blank — ", v$errors)) else
        prepared$blank <- .parse_decon_blank_block(parsed$DECON_BLANK_DATA)
    }
    list(ok = length(errs) == 0L, errors = errs, prepared = prepared)
  }

  analysis_range <- reactive({ req(input$analysis_nm); sort(input$analysis_nm) })
  resample_step  <- reactive({ .effective_resample_step(input$resample_on, input$grid_step) })

  observeEvent(list(input$resample_on, input$grid_step, input$analysis_nm, input$samples, detected_meta()), {
    removeNotification("spectral_resampling_applied")
    if (!isTRUE(input$resample_on)) return(NULL)
    current_results <- tryCatch(results_core(), error = function(e) NULL)
    if (!.spectra_resample_notice_allowed(current_results)) return(NULL)
    meta <- detected_meta()
    ns <- if (!is.null(meta) && isTRUE(meta$ok)) suppressWarnings(as.numeric(meta$step)) else NA_real_
    st <- .eff_resample_state(input$resample_on, input$grid_step, input$analysis_nm, ns)
    if (!isTRUE(st$applied)) return(NULL)
    ts <- st$effective_step
    method <- st$method
    ns_txt <- if (is.finite(ns)) sprintf("%g nm", ns) else "unknown"
    ts_txt <- paste0(sprintf("%g nm", ts),
                     if (isTRUE(st$clamped))
                       sprintf(" (requested %g nm is below the 1e-06 nm floor and was clamped up)", st$requested_step)
                     else if (isTRUE(st$regridded))
                       sprintf(" (requested %g nm; the analysis range is not an exact multiple of it, so the realized node spacing is what is used)", st$requested_step)
                     else "")
    if (identical(method, "bin")) {
      head_txt <- "Down-sampling \u2192 integral-based bin averaging"
      body_txt <- paste0("Native step ", ns_txt, " \u2192 target ", ts_txt,
                         ". Each output point is the trapezoidal-integral average over its centered bin (node \u00b1 step/2). This targets full-range area preservation when coverage/range/edge conditions permit; arbitrary band AUC can change at bin boundaries.")
    } else {
      head_txt <- "Up-sampling \u2192 linear interpolation"
      body_txt <- paste0("Native step ", ns_txt, " \u2192 target ", ts_txt,
                         ". Values are linearly interpolated onto the uniform grid.")
    }
    showNotification(
      ui = HTML(paste0(
        "<div class='pasa-adv-info-box' style='border-left:4px solid;padding:6px 10px;'>",
        "<b class='pasa-adv-info'>", htmltools::htmlEscape(head_txt), "</b><br>",
        "<span>", htmltools::htmlEscape(body_txt), "</span></div>")),
      type = "message", duration = 6, closeButton = TRUE, id = "spectral_resampling_applied")
  }, ignoreInit = TRUE)
  # Dilution guard: never allow 0 or negative.
  safe_dilution  <- reactive({
    v <- suppressWarnings(tryCatch(as.numeric(input$dilution),
                                   error = function(e) NA_real_))
    if (length(v) != 1L || !is.finite(v) || v <= 0) 1 else v
  })

  output$per_sample_dilution_ui <- renderUI({
    samps <- if (isTruthy(input$samples)) input$samples else character(0)
    if (!length(samps))
      return(div(class="text-muted", style="font-size:0.82em;",
                 em("Check at least one sample to set individual dilution factors.")))
    ids  <- .dil_ids(samps)
    gdef <- safe_dilution()
    rd   <- isolate(restored_dil())
    rows <- lapply(names(ids), function(s){
      id  <- ids[[s]]
      cur <- isolate({
        rv <- if (!is.null(rd) && id %in% names(rd)) rd[[id]] else NULL
        .dilution_restore_initial(input[[id]], rv)
      })
      div(style="display:flex;align-items:center;gap:8px;margin:2px 0;",
          div(style="flex:1;font-size:0.8em;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;", title=s, s),
          div(style="flex:0 0 96px;",
              numericInput(id, label=NULL, value=cur, min=0.0001, step=0.1, width="96px")))
    })
    tagList(
      div(style="font-size:0.78em;opacity:0.8;margin-bottom:2px;",
          sprintf("Blank = use global (%g).", gdef)),
      rows)
  })

  # Named numeric vector sample -> per-sample factor, containing ONLY the samples
  # with a finite, > 0 override. NULL when none is set (so process_wide_table
  # simply uses the global factor everywhere).
  per_sample_dilution <- reactive({
    samps <- if (isTruthy(input$samples)) input$samples else character(0)
    if (!length(samps)) return(NULL)
    ids <- .dil_ids(samps)
    vals <- vapply(names(ids), function(s){
      v <- suppressWarnings(as.numeric(input[[ ids[[s]] ]]))
      if (length(v) == 1L && is.finite(v) && v > 0) v else NA_real_
    }, numeric(1))
    vals <- vals[is.finite(vals)]
    if (length(vals)) vals else NULL
  })


  # Probe sync
  observeEvent(analysis_range(), {
    req(dat()); rng <- analysis_range()
    target <- .pasa_probe_range_target(input$probe_nm, rng)
    if (isTRUE(target$replace)) {
      updateSliderInput(session,"probe_slider", min=rng[1], max=rng[2], value=target$value)
      updateNumericInput(session,"probe_nm", value=target$value)
    } else {
      # Omitting value is intentional: a callback queued with an older in-range
      # value must not clobber a later user edit while the bounds are unchanged.
      updateSliderInput(session,"probe_slider", min=rng[1], max=rng[2])
    }
  }, ignoreInit=TRUE)
  observeEvent(input$probe_step, {
    st <- as.numeric(input$probe_step); if(is.finite(st) && st>0) updateSliderInput(session,"probe_slider", step=st)
  }, ignoreInit=TRUE)
  observeEvent(input$probe_slider, {
    val <- suppressWarnings(as.numeric(input$probe_slider))
    if (.pasa_probe_sync_needed(val, input$probe_nm))
      updateNumericInput(session,"probe_nm", value=val)
  }, ignoreInit=TRUE)
  observeEvent(input$probe_nm, {
    req(dat()); rng <- analysis_range(); raw <- suppressWarnings(as.numeric(input$probe_nm))
    if (length(raw) != 1L || !is.finite(raw)) return()
    val <- min(max(raw, rng[1]), rng[2])
    if (.pasa_probe_sync_needed(val, raw))
      updateNumericInput(session,"probe_nm", value=val)
    if (.pasa_probe_sync_needed(val, input$probe_slider))
      updateSliderInput(session,"probe_slider", value=val)
  }, ignoreInit=TRUE)

  baseline_native_range <- reactive({
    req(dat())
    nm <- suppressWarnings(as.numeric(dat()[[1]]))
    nm <- nm[is.finite(nm)]
    req(length(nm))
    range(nm)
  })
  observeEvent(baseline_native_range(), {
    rng <- baseline_native_range()
    # input$baseline_nm may be NULL before UI initializes; as.numeric(NULL)
    # yields numeric(0), making is.finite() return logical(0) and crashing if().
    cur_raw <- input$baseline_nm
    cur <- suppressWarnings(as.numeric(if (is.null(cur_raw) || length(cur_raw) == 0) NA else cur_raw))
    if (length(cur) != 1L || !is.finite(cur)) cur <- rng[2]
    clamped <- min(max(cur, rng[1]), rng[2])
    updateNumericInput(session, "baseline_nm", min=rng[1], max=rng[2], value=clamped)
    # Warn only when the (clamped) baseline is < 730 nm (Single nm mode threshold)
    if(isTRUE(input$apply_baseline) && isTruthy(input$baseline_method) &&
       input$baseline_method == "single_nm" && clamped < 730){
      showNotification(
        paste0("Operational warning: baseline wavelength ", round(clamped, 1),
               " nm is below 730 nm and may intersect analyte absorption. ",
               "Use a study-justified reference for the sample, blank, matrix, and instrument."),
        type = "warning", duration = 8, id = "baseline_nm_warn")
    }
  }, ignoreInit=FALSE)
  observeEvent(input$baseline_nm, {
    rng <- baseline_native_range()
    val_raw <- input$baseline_nm
    val <- suppressWarnings(as.numeric(if (is.null(val_raw) || length(val_raw) == 0) NA else val_raw))
    if(length(val) != 1L || !is.finite(val)) return()
    clamped <- min(max(val, rng[1]), rng[2])
    if(!isTRUE(all.equal(clamped, val))) updateNumericInput(session, "baseline_nm", value=clamped)
    # Warn only when selected nm < 730 nm (Single nm mode)
    if(isTRUE(input$apply_baseline) && isTruthy(input$baseline_method) &&
       input$baseline_method == "single_nm" && clamped < 730){
      showNotification(
        paste0("Operational warning: baseline @ ", round(clamped, 1),
               " nm is below 730 nm and may intersect analyte absorption. ",
               "Use a study-justified reference for the sample, blank, matrix, and instrument."),
        type = "warning", duration = 8, id = "baseline_nm_warn")
    }
  }, ignoreInit=TRUE)
  # Warn when Window median mode is selected and the lower bound (or any selected value) < 730 nm
  observeEvent(list(input$baseline_win, input$baseline_method), {
    if (!isTRUE(input$apply_baseline)) return()
    if (!isTruthy(input$baseline_method) || input$baseline_method != "window_min") return()
    bw <- input$baseline_win
    if (is.null(bw) || length(bw) < 2) return()
    selected_min <- min(bw)
    if (is.finite(selected_min) && selected_min < 730) {
      showNotification(
        paste0("Operational warning: baseline window lower bound ", round(selected_min, 1),
               " nm is below 730 nm and may intersect analyte absorption. ",
               "Use a study-justified reference window for the sample, blank, matrix, and instrument."),
        type = "warning", duration = 8, id = "baseline_win_warn")
    }
  }, ignoreInit = TRUE)

  # When the user selects a
  # normalization method while baseline correction is off, show a prominent
  # warning notification AND silently reset norm_method to "none", because
  # normalizing unbaselined OD is scientifically invalid — the baseline
  # offset enters the normalization factor and corrupts spectral ratios.
  observeEvent(list(input$norm_method, input$apply_baseline), {
    if (!isTRUE(input$apply_baseline) &&
        isTruthy(input$norm_method) && input$norm_method != "none") {
      showNotification(
        tagList(
          tags$b("Activate baseline correction before normalizing."),
          " Normalization applied to raw (unbaselined) OD incorporates the ",
          "instrument offset into the scaling factor, producing scientifically ",
          "invalid results. Enable ‘Apply baseline correction’ first, or keep ",
          "Normalization set to None."
        ),
        type = "warning", duration = 10, id = "norm_no_baseline_warn")
      updateSelectInput(session, "norm_method", selected = "none")
    }
  }, ignoreInit = TRUE)

  processing_status <- reactive({
    req(dat())
    r <- results_core()
    list(issues = attr(r, "processing_issues", exact = TRUE), failures = .pasa_processing_failures(r), rows = nrow(r))
  })
  output$processing_input_status <- renderUI({
    st <- processing_status()
    if (!length(st$issues)) return(NULL)
    div(class = "alert alert-danger", role = "alert",
      tags$b("Analysis needs attention. "), paste(unname(st$issues), collapse = " "))
  })
  output$baseline_input_error <- renderUI({
    st <- processing_status(); ids <- intersect(names(st$issues), c("baseline_nm", "baseline_win", "baseline_method"))
    if (!length(ids)) return(NULL)
    div(class = "text-danger", role = "alert", paste(st$issues[ids], collapse = " "))
  })
  output$processing_failure_table <- renderTable({
    f <- processing_status()$failures
    if (!nrow(f)) return(NULL)
    setNames(f, c("Sample", "Failed step", "Cause"))
  })
  # Empty copied text as soon as settings become invalid; do not retain old metrics.
  observe({
    st <- processing_status()
    if (length(st$issues) || !st$rows) session$sendCustomMessage("update_metrics_tsv", list(value = ""))
  })

  .processing_sample_cache <- fastmap::fastmap()
  processing_arguments <- debounce(reactive({
    req(dat())
    eff_norm_method <- if (isTRUE(input$apply_baseline)) input$norm_method else "none"
    list(
      df_wide=dat(), bands=bands_react(), analysis_range=input$analysis_nm,
      baseline_method=input$baseline_method, baseline_nm=input$baseline_nm, baseline_window=input$baseline_win,
      smoothing_method=input$smooth, sgolay_n=input$sg_n, sgolay_p=input$sg_p, ma_k=input$ma_k,
      sample_keep=if (is.null(input$samples)) character(0) else input$samples, dilution_factor=safe_dilution(), clamp_zero=FALSE,
      per_sample_dilution=per_sample_dilution(),
      norm_method=eff_norm_method, norm_target=input$norm_target,
      norm_ref_nm=if (isTRUE(input$apply_baseline) && identical(eff_norm_method, "ref_nm_to")) input$norm_ref_nm
                  else if (isTruthy(input$norm_ref_nm)) input$norm_ref_nm else 680,
      norm_band=if (isTruthy(input$norm_band)) input$norm_band else NULL,
      resample_step=if (isTRUE(input$resample_on)) {
        v <- suppressWarnings(as.numeric(input$grid_step))
        if (length(v) != 1L || !is.finite(v) || v <= 0) NaN else resample_step()
      } else NA_real_,
      apply_baseline=isTRUE(input$apply_baseline), sample_cache=.processing_sample_cache
    )
  }), 600)
  results_core <- reactive({ do.call(process_wide_table, processing_arguments()) })

  # Each acknowledged dilution retires independently: subsequent user edits
  # must never be overwritten while a different field is still mounting.
  observe({
    rd <- restored_dil()
    if (is.null(rd) || !length(rd) || is.null(names(rd))) {
      dilution_restore_apply_env$key <- NULL
      dilution_restore_apply_env$attempt <- 0L
      return()
    }
    if (!isTRUE(controls_ready()) || is.null(dat_value()) || !is.null(pending_samples_restore())) return()
    selected <- intersect(input$samples %||% character(), setdiff(names(dat_value()), "nm"))
    available_ids <- unname(.dil_ids(selected))
    pending <- rd[intersect(names(rd), available_ids)]
    if (length(pending) != length(rd)) {
      showNotification("Dilution overrides for samples absent from the current selection were skipped.",
                       type = "message", duration = 6, session = session)
      restored_dil(pending)
      return()
    }
    ids <- names(pending)
    echoed <- vapply(ids, function(id) {
      v <- suppressWarnings(as.numeric(input[[id]]))
      target <- suppressWarnings(as.numeric(pending[[id]]))
      length(v) == 1L && length(target) == 1L && is.finite(v) &&
        is.finite(target) && isTRUE(all.equal(v, target, tolerance = 0))
    }, logical(1))
    if (any(echoed)) {
      restored_dil(pending[!echoed])
      return()
    }
    key <- paste(ids, collapse = "|")
    if (!identical(dilution_restore_apply_env$key, key)) {
      dilution_restore_apply_env$key <- key
      dilution_restore_apply_env$attempt <- 0L
    }
    for (id in ids) {
      target <- suppressWarnings(as.numeric(pending[[id]]))
      updateNumericInput(session, id, value = target)
      session$sendCustomMessage("pasa_restore_input_echo", list(id = id, value = target))
    }
    dilution_restore_apply_env$attempt <- dilution_restore_apply_env$attempt + 1L
    if (dilution_restore_apply_env$attempt <= 120L) shiny::invalidateLater(250, session)
    else {
      showNotification("Some per-sample dilution controls did not confirm restoration. Check their displayed values.",
                       type = "warning", duration = 8, session = session)
      restored_dil(list())
    }
  })

  auc_basis <- reactive({
    b <- input$auc_basis %||% "normalized"
    if (!b %in% c("raw","baseline","smoothed","normalized")) b <- "normalized"
    if (!isTRUE(input$apply_baseline) && b %in% c("baseline","smoothed","normalized")) {
      # Without baseline correction only the raw (dilution-scaled) curve is
      # distinct; base/smooth/norm all collapse onto the un-baselined curve.
      if (b == "baseline") b <- "raw"
    }
    b
  })

  # results(): pick the selected-basis AUC into `auc`/`total_auc` so every
  # consumer (Metrics table, Band-AUC charts, band ratios, LOD/LOQ guard) uses it.
  results <- reactive({
    res <- results_core()
    .issues <- attr(res, "processing_issues", exact = TRUE)
    validate(need(!length(.issues), paste(unname(.issues), collapse = " ")))
    validate(need(nrow(res) > 0L, "No sample could be processed. See the sample failure table."))
    basis <- auc_basis()
    aucsel <- switch(basis, raw=res$auc_raw, baseline=res$auc_base,
                     smoothed=res$auc_smooth, res$auc_norm)
    totsel <- switch(basis, raw=res$total_auc_raw, baseline=res$total_auc_base,
                     smoothed=res$total_auc_smooth, res$total_auc_norm)
    res$auc <- aucsel
    res$total_auc <- totsel
    if ("peak_nm" %in% names(res)) {
      .no_auc <- !is.finite(res$auc)
      if (any(.no_auc)) {
        res$peak_nm[.no_auc] <- NA_real_
        if ("peak_val_post" %in% names(res)) res$peak_val_post[.no_auc] <- NA_real_
        if ("peak_val_pre"  %in% names(res)) res$peak_val_pre[.no_auc]  <- NA_real_
      }
    }
    res
  })

  auc_basis_label <- reactive({
    .eff <- tryCatch(.metrics_eff_summary(results()), error = function(e) NULL)
    .nmn <- tryCatch(dat()[[1]], error = function(e) NULL)
    .sme <- tryCatch(.is_smooth_effective(input$smooth, input, .analysis_grid_len(input, .nmn)), error = function(e) NULL)
    .auc_basis_label_text(auc_basis(), input$apply_baseline, input$smooth, input$norm_method, eff = .eff, smooth_effective = .sme)
  })
  output$auc_basis_disclosure <- renderUI({
    req(results_core())
    extra <- if (.auc_norm_is_effective(auc_basis(), input$apply_baseline, input$norm_method,
                                        tryCatch(.metrics_eff_summary(results()), error = function(e) NULL)))
      " Normalized AUC compares relative distribution/shape (share of total only for unit-area normalization) after removing a uniform multiplicative scale. It sacrifices absolute amplitude and does not prove that concentration or path length caused the original scale difference." else ""
    basis_grid <- switch(auc_basis(),
      raw = "Raw AUC uses native measured wavelength coordinates; display resampling is not an input.",
      baseline = "Baseline-corrected AUC uses native measured wavelength coordinates; display resampling is not an input.",
      smoothed = "Smoothed AUC uses the processed-grid curve and is resolution-dependent; resampling is optional.",
      normalized = "Normalized AUC uses the processed-grid curve and is resolution-dependent; resampling is optional.")
    div(style="font-size:0.85em;padding:6px 10px;border-left:3px solid var(--pasa-info-fg);margin:4px 0 8px;background:rgba(13,110,253,0.06);border-radius:4px;",
        tags$b("AUC basis: "),
        sprintf("Band AUCs and AUC ratios below are computed on %s. %s The separate raw (pre-baseline) AUC column is retained for provenance.", auc_basis_label(), basis_grid),
        extra)
  })

  observeEvent(tryCatch(results(), error = function(e) NULL), {
    res <- tryCatch(results(), error = function(e) NULL)
    if (is.null(res) || !nrow(res)) { removeNotification("spectral_processing_refused"); return() }
    rows <- res[!duplicated(res$sample), , drop = FALSE]
    notes <- character(0)
    for (i in seq_len(nrow(rows))) {
      if (isTRUE(rows$resample_refused[i])) notes <- c(notes, paste0(rows$sample[i],
        ": bin averaging refused because native coverage has an internal gap. Processed plots and processed AUC are unavailable; native AUC and similarity remain available. Disable resampling or choose a finer interpolation grid."))
      else if (identical(rows$smoothing_reason[i], "irregular_wavelength_grid_sg_refused")) notes <- c(notes, paste0(rows$sample[i],
        ": Savitzky-Golay smoothing was not applied because the wavelength grid is irregular. The unsmoothed curve is used; resample to a uniform grid to apply this filter."))
      else if (isTRUE(rows$smoothing_reason[i] %in% c("signal_too_short_to_smooth", "partially_applied_short_runs"))) notes <- c(notes, paste0(rows$sample[i],
        ": some supported runs are too short for the requested smoothing window and remain unsmoothed. See the effective run settings in the metrics export."))
    }
    if (!length(notes)) { removeNotification("spectral_processing_refused"); return() }
    showNotification(tagList(tags$b("Effective spectral processing"), tags$ul(lapply(notes, tags$li))),
                     type = "warning", duration = NULL, id = "spectral_processing_refused")
  }, ignoreInit = FALSE, ignoreNULL = FALSE)

  observeEvent(tryCatch(results(), error = function(e) NULL), {
    res <- tryCatch(results(), error = function(e) NULL)
    if (is.null(res) || !nrow(res) || !"norm_applied" %in% names(res)) {
      removeNotification("norm_skipped_warn"); return()
    }
    skipped <- res %>%
      dplyr::filter(norm_applied %in% FALSE, norm_reason != "processed_curve_unavailable_resampling_refused") %>%
      dplyr::distinct(sample, norm_reason)
    if (!nrow(skipped)) { removeNotification("norm_skipped_warn"); return() }
    reason_label <- c(
      target_nonpositive  = "target ≤ 0",
      divisor_nonpositive = "normalization reference / peak / area ≤ 0",
      ref_out_of_range    = "reference wavelength outside the measured range",
      band_no_coverage    = "normalization band not covered by this spectrum",
      no_norm_band        = "no normalization band selected")
    line_items <- lapply(seq_len(nrow(skipped)), function(i){
      rl <- unname(reason_label[skipped$norm_reason[i]])
      if (!length(rl) || is.na(rl)) rl <- skipped$norm_reason[i]
      tags$li(paste0(skipped$sample[i], " — ", rl))
    })
    showNotification(
      tagList(
        tags$b("Normalization skipped for some samples."),
        tags$div("Their spectra are shown with pre-normalization values (grayed in the Metrics table); see norm_applied / norm_reason in the metrics export.",
                 style = "margin:4px 0;"),
        tags$ul(style = "margin:0;padding-left:18px;", line_items)
      ),
      type = "warning", duration = 12, id = "norm_skipped_warn")
  }, ignoreInit = FALSE, ignoreNULL = FALSE)

  curves <- reactive({
    # PERF: derive the plot curves from the ALREADY-processed results() instead of
    # re-running the identical per-spectrum pipeline in a separate plot-curve pass
    # (since removed). Both ran with the same inputs and clamp_zero=FALSE, so
    # results()'s stored display curve (.val_smooth_post_display) is byte-identical
    # to the val_smooth that pass produced (verified max|diff| = 0 on the 96-sample
    # dataset). This removes a full duplicate pass (~15 s on the large dataset). The
    # Spectra plot consumes
    # only sample / nm / val_smooth; blank (all-NA) samples that produced no rows are
    # omitted (they render nothing anyway and colors are keyed by sample name).
    res <- req(results())
    first <- res[!duplicated(res$sample), , drop = FALSE]
    parts <- lapply(seq_len(nrow(first)), function(i) {
      nmv <- first$.raw_nm_list[[i]]
      if (is.null(nmv) || !length(nmv)) return(NULL)
      data.frame(sample = as.character(first$sample[i]), nm = as.numeric(nmv),
                  val_smooth = as.numeric(first$.val_smooth_post_display[[i]]),
                  .plot_run = .spectra_plot_run_ids(nmv, first$.val_smooth_post_display[[i]], first$.measured_nm[[i]]),
                 stringsAsFactors = FALSE)
    })
    out <- do.call(rbind, parts)
    validate(need(!is.null(out) && nrow(out) > 0, "No plottable curves for the current selection."))
    tibble::as_tibble(out)
  })
  
  # Peaks reactive
  peak_points <- reactive({
    req(results())
    if(!isTRUE(input$show_peaks)) return(NULL)
    sel <- input$peak_bands
    if(is.null(sel) || !length(sel)) return(NULL)
    df <- results() %>%
      filter(band %in% sel) %>%
      select(sample, band, peak_nm, peak_val_post, peak_val_pre) %>%
      filter(is.finite(peak_nm), is.finite(peak_val_post))
    if(nrow(df)==0) return(NULL)
    df
  })
  
  # Exact QC residual specification. A configured baseline window is diagnosed
  # over that window itself (not its upper endpoint). A single-reference request
  # starts with +/-5 nm and compute_qc re-centers it per sample on the effective
  # native subtraction node when available.
  qc_residual_spec <- reactive({
    if (isTruthy(input$baseline_method) && input$baseline_method == "window_min") {
      bw <- suppressWarnings(as.numeric(input$baseline_win))
      if (length(bw) != 2L || any(!is.finite(bw))) bw <- c(745, 750)
      bw <- sort(bw)
      list(ref_nm = mean(bw), bounds = bw, statistic = "mean",
           kind = "configured baseline window", min_points = 3L)
    } else {
      raw <- input$baseline_nm
      v   <- suppressWarnings(as.numeric(if (is.null(raw) || length(raw) == 0) NA else raw))
      if (!(length(v) == 1L && is.finite(v))) v <- 750
      list(ref_nm = v, bounds = c(v - 5, v + 5), statistic = "mean",
           kind = "single-reference local window", min_points = 2L)
    }
  })
  ref_baseline_nm <- reactive(qc_residual_spec()$ref_nm)

  # Raw duplicate relationships depend on loaded data, never QC thresholds.
  qc_duplicate_summary <- reactive({ req(dat()); .qc_duplicate_summary(dat()) })
  # QC reactive
  qc <- reactive({
    req(dat())
    .rs <- qc_residual_spec()
    compute_qc(
      df_wide = dat(), results = results_core(), ref_nm = .rs$ref_nm,
      residual_bounds = .rs$bounds, residual_statistic = .rs$statistic,
      residual_kind = .rs$kind, residual_min_points = .rs$min_points,
      selected_samples = as.character(input$samples %||% character(0)),
      baseline_tol = { v <- suppressWarnings(as.numeric(input$qc_baseline_tol)); if (is.finite(v)) v else 0.005 },
      sat_thresh   = { v <- suppressWarnings(as.numeric(input$qc_sat_thresh));   if (is.finite(v)) v else 2.5 },
      dup_cor      = { v <- suppressWarnings(as.numeric(input$qc_dup_cor));      if (is.finite(v)) v else 0.9999 },
      norm_active = isTRUE(norm_active()),
      duplicate_summary = qc_duplicate_summary(),
      apply_baseline = isTRUE(input$apply_baseline)
    )
  })

  noise_qc_params <- debounce(reactive({
    state <- .noise_threshold_state(input)
    validate(need(!length(state$issues), paste(state$issues, collapse = " ")))
    state$params
  }), 600)
  noise_qc <- reactive({
    req(results()); res <- results()
    lg <- dplyr::bind_rows(lapply(split(res, res$sample), function(df){
      nm <- base <- NULL
      if (all(c(".decon_native_nm",".decon_native_base") %in% names(df))) {
        nm   <- as.numeric(df$.decon_native_nm[[1]])
        base <- as.numeric(df$.decon_native_base[[1]])
      }
      if (is.null(nm) || !length(nm) || is.null(base) || length(base) != length(nm)) {
        # Fallback for rows from an older pipeline: native measured nodes on the grid.
        nm0 <- df$.raw_nm_list[[1]]; b0 <- as.numeric(df$.val_base_quant[[1]])
        if (is.null(nm0) || is.null(b0)) return(NULL)
        mnm <- if (".measured_nm" %in% names(df)) df$.measured_nm[[1]] else NULL
        if (!is.null(mnm) && length(mnm) >= 1) {
          keep <- vapply(nm0, function(g) any(abs(g - mnm) < 1e-6), logical(1))
          b0[!keep] <- NA_real_
        }
        nm <- nm0; base <- b0
      }
      tibble::tibble(sample = df$sample[1], nm = nm, value_base = base)
    }))
    req(nrow(lg) > 0)
    compute_noise_qc(lg, value_col = "value_base", P = noise_qc_params())
  })

  # One canonical table for both the detailed on-screen table and the downloaded
  # QC report. It carries the exact denominator and axis-eligibility provenance.
  noise_export_df <- reactive({
    nq <- noise_qc(); req(nq)
    ps <- nq$per_sample
    data.frame(
      Sample = ps$sample,
      `Noise evaluable` = ps$evaluable,
      `Noise QC method` = ps$method_id,
      `Global usable residuals` = ps$global_residual_count,
      `Global minimum residuals` = ps$global_min_residuals,
      `Global estimate status` = ps$global_status,
      `Global estimate reason` = ps$global_reason,
      `Tail usable residuals` = ps$tail_residual_count,
      `Tail minimum residuals` = ps$tail_min_residuals,
      `Tail estimate status` = ps$tail_status,
      `Tail estimate reason` = ps$tail_reason,
      `Supported local intervals` = ps$local_supported_intervals,
      `Total local intervals` = ps$local_total_intervals,
      `Local minimum residuals` = ps$local_min_residuals,
      `Local estimate status` = ps$local_status,
      `Local estimate reason` = ps$local_reason,
      `Adjacent usable residuals` = ps$adjacent_residual_count,
      `Adjacent minimum residuals` = ps$adjacent_min_residuals,
      `Adjacent roughness % of denominator` = ps$adjacent_pct,
      `Adjacent roughness class` = ps$adjacent_class,
      `Adjacent estimate status` = ps$adjacent_status,
      `Adjacent estimate reason` = ps$adjacent_reason,
      `Denominator value` = ps$denominator_value,
      `Denominator definition` = ps$denominator_definition,
      `Axis status` = ps$axis_status,
      `Axis representative step (nm)` = ps$axis_step_nm,
      `Axis max relative step deviation` = ps$axis_max_rel_deviation,
      `Axis relative step tolerance` = ps$axis_rel_tolerance,
      `Gap count` = ps$gap_count,
      `Gap split threshold (nm)` = ps$gap_threshold_nm,
      `Unevaluable reason` = ps$unevaluable_reason,
      `Global % of denominator` = ps$global_pct,
      `Global class` = ps$global_class,
      `Tail % of denominator` = ps$tail_pct,
      `Tail class` = ps$tail_class,
      `Fraction sensitive` = ps$frac_sensitive,
      `Fraction class` = ps$frac_class,
      `Maximum local % of denominator` = ps$max_local_pct,
      `Maximum-local class` = ps$max_local_class,
      Composite = ps$composite,
      `Composite support` = ifelse(is.finite(ps$composite), "complete", "unavailable: one or more components lack support; absolute rules only"),
      `Final noise class` = ps$final_class,
      Interpretation = ifelse(
        ps$evaluable %in% TRUE & !is.na(ps$final_class),
        unname(.NOISE_QC_WORDING[ps$final_class]),
        ifelse(is.na(ps$unevaluable_reason), "not evaluated", ps$unevaluable_reason)),
      check.names = FALSE, stringsAsFactors = FALSE)
  })

  noise_intervals_export_df <- reactive({
    nq <- noise_qc(); req(nq)
    iv <- as.data.frame(nq$intervals)
    if (!nrow(iv)) data.frame(Note = "No interval data available.", stringsAsFactors = FALSE) else iv
  })
  noise_components_export_df <- reactive({
    nq <- noise_qc(); req(nq)
    ps <- nq$per_sample
    data.frame(
      Sample = ps$sample, Evaluable = ps$evaluable,
      G = ps$G, T = ps$T, F = ps$F, M = ps$M,
      Composite = ps$composite, `Severe FAIL` = ps$severe_fail,
      `Final noise class` = ps$final_class,
      `Unevaluable reason` = ps$unevaluable_reason,
      check.names = FALSE, stringsAsFactors = FALSE)
  })
  noise_thresholds_export_df <- reactive({
    P <- noise_qc_params()
    data.frame(
      parameter = c("global_caution_pct", "global_fail_pct", "tail_caution_pct", "tail_fail_pct",
                    "local_caution_pct", "local_fail_pct", "flagged_fraction_caution",
                    "flagged_fraction_fail", "uniform_step_rel_tolerance", "gap_step_factor",
                    "min_region_residuals", "minimum_scored_intervals", "denominator_definition",
                    "method_id", "min_global_residuals", "min_tail_residuals",
                    "min_adjacent_residuals", "adjacent_caution_pct", "adjacent_fail_pct",
                    "adaptive_ties", "adjacent_definition"),
      value = c(P$global_caution, P$global_fail, P$tail_caution, P$tail_fail,
                P$local_caution, P$local_fail, P$frac_caution, P$frac_fail,
                P$uniform_step_rel_tolerance, P$gap_step_factor,
                P$min_region_resid, P$frac_min_intervals, .NOISE_DENOMINATOR_DEFINITION,
                .NOISE_QC_METHOD, P$min_global_resid, P$min_tail_resid,
                P$min_adjacent_resid, P$adjacent_caution, P$adjacent_fail,
                "exact average rank; no rounding",
                "100 * 1.4826 * median(abs((2*y[i]-y[i-1]-y[i+1])/sqrt(6))) / denominator"),
      stringsAsFactors = FALSE)
  })
  noise_plot_export <- reactive({
    nq <- noise_qc(); req(nq)
    p <- build_noise_qc_chart(nq, dark = FALSE)
    req(!is.null(p)); p + theme_bg(FALSE)
  })

  output$noise_qc_chart <- renderPlot({
    nq <- noise_qc(); req(nq)
    p <- build_noise_qc_chart(nq, dark = is_dark())
    req(!is.null(p)); p + theme_bg(is_dark())
  }, bg = "transparent")

  # Per-sample per-region strips (global / tail / worst 10-nm), under the chart.
  output$noise_qc_strips <- renderUI({
    nq <- noise_qc(); req(nq)
    ps <- nq$per_sample
    ps <- ps[ps$evaluable %in% TRUE, , drop = FALSE]
    if (!nrow(ps)) return(div(class = "text-muted", em("No evaluable samples for noise QC.")))
    fg <- if (is_dark()) "#f0f0f0" else "#1a1a1a"
    cell <- function(cls, label) {
      col <- if (is.na(cls)) "#9e9e9e" else .NOISE_QC_COLORS[[cls]]
      div(style = sprintf("flex:1;text-align:center;padding:2px 4px;background:%s;color:#fff;font-size:0.72em;border-radius:3px;", col),
          paste0(label, ": ", if (is.na(cls)) "n/a" else cls))
    }
    rows <- lapply(seq_len(nrow(ps)), function(i) {
      div(style = "display:flex;align-items:center;gap:8px;margin:3px 0;",
          div(style = sprintf("flex:0 0 180px;font-size:0.85em;color:%s;", fg),
              ps$sample[i]),
          div(style = "flex:1;display:flex;gap:4px;",
              cell(ps$global_class[i], "Global"),
              cell(ps$adjacent_class[i], "Adjacent roughness"),
              cell(ps$tail_class[i],   "Tail"),
              cell(ps$max_local_class[i], "Worst 10-nm (advisory)"),
 # 4th bar — fraction of 10-nm windows flagged (frac_class).
              cell(ps$frac_class[i],   "Windows")))
    })
    div(style = "margin-top:6px;",
        div(style = sprintf("font-size:0.82em;font-weight:600;margin-bottom:4px;color:%s;", fg),
            "Global, adjacent roughness, tail and supported-window classes contribute to the verdict. The worst 10-nm strip is advisory. An unsupported region is not evaluated."),
        rows)
  })

  # One verdict sentence per class present in the dataset (with counts).
  output$noise_qc_verdicts <- renderUI({
    nq <- noise_qc(); req(nq)
    ps <- nq$per_sample
    ps <- ps[ps$evaluable %in% TRUE & !is.na(ps$final_class), , drop = FALSE]
    fg <- if (is_dark()) "#f0f0f0" else "#1a1a1a"
    sentences <- list(
      PASS    = "the configured residual-noise and adjacent-roughness thresholds did not fire.",
      CAUTION = "residual noise or adjacent roughness exceeded a caution rule; retained and flagged for review.",
      FAIL    = "residual noise or adjacent roughness exceeded a fail rule; retained and flagged for review (not excluded automatically)."
    )
    items <- lapply(c("PASS", "CAUTION", "FAIL"), function(cls) {
      k <- sum(ps$final_class == cls)
      if (k < 1) return(NULL)
      div(style = sprintf("display:flex;align-items:center;gap:8px;margin:3px 0;color:%s;", fg),
          div(style = sprintf("flex:0 0 14px;height:14px;border-radius:3px;background:%s;", .NOISE_QC_COLORS[[cls]])),
          span(sprintf("%s (%d): %s", cls, k, sentences[[cls]])))
    })
    .ne <- nq$per_sample[nq$per_sample$evaluable %in% FALSE, , drop = FALSE]
    non_eval <- nrow(.ne)
    if (non_eval > 0) {
      .reasons <- unique(.ne$unevaluable_reason[!is.na(.ne$unevaluable_reason) & nzchar(.ne$unevaluable_reason)])
      items[[length(items) + 1]] <- div(class = "text-muted", style = "font-size:0.85em;margin-top:4px;",
        sprintf("%d sample(s) were not evaluated%s.", non_eval,
                if (length(.reasons)) paste0(": ", paste(.reasons, collapse = "; ")) else ""))
    }
    div(style = "margin-top:8px;", items)
  })

  # ---- Detailed tables (behind the toggle) ----
  output$noise_qc_metrics_table <- renderTable({
    noise_export_df()
  }, na = "—")

  output$noise_qc_interval_table <- renderTable({
    nq <- noise_qc(); req(nq)
    iv <- nq$intervals
    if (!nrow(iv)) return(data.frame(Note = "No interval data available."))
    w <- tidyr::pivot_wider(
      dplyr::mutate(iv, cell = ifelse(evaluable,
        sprintf("%.2f (%s; n=%d)", local_pct, local_class, residual_count),
        sprintf("Not evaluated (n=%d; need %d)", residual_count, minimum_residuals))),
      id_cols = sample, names_from = interval_nm, values_from = cell)
    names(w)[1] <- "Sample"
    as.data.frame(w)
  }, na = "—")

  output$noise_qc_components_table <- renderTable({
    nq <- noise_qc(); req(nq)
    ps <- nq$per_sample[nq$per_sample$evaluable %in% TRUE, , drop = FALSE]
    data.frame(
      Sample = ps$sample,
      G = round(ps$G, 3), T = round(ps$T, 3), F = round(ps$F, 3), M = round(ps$M, 3),
      Composite = round(ps$composite, 3),
      `Severe FAIL` = ifelse(is.na(ps$severe_fail), "—", ifelse(ps$severe_fail, "yes", "no")),
      check.names = FALSE, stringsAsFactors = FALSE)
  }, na = "—")

  output$noise_qc_thresholds <- renderUI({
    P <- noise_qc_params()
    fg <- if (is_dark()) "#f0f0f0" else "#1a1a1a"
    tags$ul(style = sprintf("font-size:0.85em;color:%s;", fg),
      tags$li(tags$em("These PASS/CAUTION/FAIL cutoffs are operational defaults, not literature acceptance limits. The global, tail and local controls are editable above; adjacent roughness uses the fixed cutoffs shown below.")),
      tags$li(paste("Noise QC method:", .NOISE_QC_METHOD)),
      tags$li(sprintf("Adjacent-point roughness: 100 × 1.4826 × median absolute neighboring-point second difference / denominator (difference divided by sqrt(6)); PASS ≤ %.1f%%, CAUTION ≤ %.1f%%, FAIL > %.1f%%. This separate absolute floor can detect alternating structure; it is not a composite term or a detector-fault diagnosis.", P$adjacent_caution, P$adjacent_fail, P$adjacent_fail)),
      tags$li(sprintf("Minimum usable residuals: global %d, tail %d, adjacent %d, each 10-nm interval %d. An unsupported estimate is not evaluated; counts and reasons are exported. The window fraction needs %d supported intervals.", P$min_global_resid, P$min_tail_resid, P$min_adjacent_resid, P$min_region_resid, P$frac_min_intervals)),
      tags$li(sprintf("Global noise %%: PASS ≤ %.1f, CAUTION ≤ %.1f, FAIL > %.1f", P$global_caution, P$global_fail, P$global_fail)),
      tags$li(sprintf("Tail (720–750 nm) noise %%: PASS ≤ %.1f, CAUTION ≤ %.1f, FAIL > %.1f. Not evaluated (shown blank / “—” and never CAUTION/FAIL) when the 720–750 nm band is not measured or contains too few supported residuals — a spectrum ending before 720 nm carries no tail data to judge, so its tail metric is skipped rather than scored on out-of-band curvature.", P$tail_caution, P$tail_fail, P$tail_fail)),
      tags$li(sprintf("Local 10-nm noise %%: PASS ≤ %.2f, CAUTION ≤ %.2f, FAIL > %.2f", P$local_caution, P$local_fail, P$local_fail)),
      tags$li(sprintf("Fraction-sensitive: PASS ≤ %.0f%%, CAUTION ≤ %.0f%%, FAIL > %.0f%%", 100*P$frac_caution, 100*P$frac_fail, 100*P$frac_fail)),
      tags$li(sprintf("Composite = 0.40·G + 0.25·T + 0.20·F + 0.15·M, each capped at %d. A composite requires all four components; partial-support samples retain absolute classes and do not enter relative ranking.", P$component_cap)),
      tags$li(sprintf("Native spacing must be at most %.3g nm for this residual-noise screen. Coarser axes are not classified because sampling curvature can dominate the fixed noise thresholds.", P$max_axis_step_nm)),
      tags$li(sprintf("Adaptive: pass_fraction = %.2f, fail_fraction = %.2f, fail_score_ratio = %.2f× median, fail_min_composite = %.2f",
                      P$pass_fraction, P$fail_fraction, P$fail_score_ratio, P$fail_min_composite)),
      tags$li(sprintf("Severe absolute FAIL: (global FAIL & tail FAIL) OR (global FAIL & frac>%.3g) OR (tail FAIL & frac>%.3g) OR (frac_extreme>0.60).", P$frac_fail, P$frac_fail)),
      tags$li(paste0("Denominator for every noise percentage: ", .NOISE_DENOMINATOR_DEFINITION,
                     ". The value and definition are archived per sample.")),
      tags$li(sprintf("Axis eligibility: steps > %.2f× the preliminary median are segmented as gaps; among non-gap steps, the maximum relative deviation from the representative median step must be ≤ %.2f%% (uniform_step_rel_tolerance = %.4g). Five-point stencils never cross a segmented gap. Materially non-uniform axes are not evaluated.",
                      P$gap_step_factor, 100 * P$uniform_step_rel_tolerance, P$uniform_step_rel_tolerance)),
      tags$li("Exact tied composite scores share an average rank, regardless of sample order or names. Relative ranking never lowers an absolute class. Local curvature can contribute to roughness; all noise classes are advisory."))
  })

  output$qc_banner <- renderUI({
    req(qc()); q <- qc()
    n <- nrow(q)
    n_eval <- sum(q$Evaluation == "Evaluated")
    n_ok <- sum(q$Status == "No configured flags")
    n_warn <- sum(q$Status == "Review flags")
    n_not_eval <- n - n_eval
    n_ne_notes <- sum(q$Evaluation != "Evaluated" & nzchar(q$Issues))
    axis <- attr(q, "axis_issues")
    flagged <- q %>% filter(Status == "Review flags")
    col <- if (n_warn == 0 && length(axis) == 0) "#1a7f37" else "#b35900"
    bg  <- if (n_warn == 0 && length(axis) == 0) "#e6f4ea" else "#fff4e5"
    detail <- if (n_warn > 0) paste0(" — flagged: ", paste(flagged$Sample, collapse = ", ")) else ""
    ne_txt <- if (n_not_eval > 0) sprintf(" · %d not evaluated%s", n_not_eval,
      if (n_ne_notes > 0) sprintf(" (%d with raw-file review note%s)", n_ne_notes, if (n_ne_notes == 1) "" else "s") else "") else ""
    axis_txt <- if (length(axis) > 0) paste0(" | Axis issues: ", paste(axis, collapse = "; ")) else ""
    div(style = sprintf("padding:10px 14px;border-radius:6px;background:%s;color:%s;font-weight:600;", bg, col),
        sprintf("%d sample(s) loaded · %d evaluated · %d with no configured flags · %d flagged%s%s%s",
                n, n_eval, n_ok, n_warn, ne_txt, detail, axis_txt))
  })

  # Dynamic QC heading with ref_nm.
  # Guard against ref_baseline_nm() returning NULL, NA, or length zero before
  # inputs are fully initialized.
  output$qc_heading <- renderUI({
    .rs <- qc_residual_spec()
    h4(sprintf("Baseline residual mean — %s [%g, %g] nm", .rs$kind, .rs$bounds[1], .rs$bounds[2]))
  })

  # Specific (not generic) interpretation text under the baseline-residual chart.
  # Pulls the live reference \u03bb and user-configurable tolerance so the numbers
  # printed here always match what produced the chart.
  output$qc_chart_interpretation <- renderUI({
    .rs <- qc_residual_spec()
    tol <- suppressWarnings(as.numeric(input$qc_baseline_tol))
    if (!length(tol) || !is.finite(tol)) tol <- 0.005
    tol_txt <- format(tol, scientific = FALSE, trim = TRUE)
    div(style = paste0("margin-top:10px;padding:10px 12px;border-radius:6px;",
                       "background:var(--bs-tertiary-bg);border-left:3px solid var(--bs-primary);",
                       "font-size:0.9em;line-height:1.45;"),
      tags$b("How to read this chart"),
      tags$p(style = "margin:6px 0 4px;",
        "Each lollipop is the mean of native-coordinate baseline-corrected values within the exact per-row diagnostic bounds archived in the table and export. For a single-reference request, the ±5 nm window is centered on that sample's effective native subtraction node; for window-median baseline correction, the configured baseline window itself is used. Point count, statistic, anchor, bounds, and source scope are archived. A value near zero does not prove that the baseline choice is scientifically appropriate. ",
        "The gray band marks the user-set operational review window ", tags$b(sprintf("\u00b1%s OD", tol_txt)),
        " from the ", tags$em("Baseline residual tolerance"), " control."),
      tags$ul(style = "margin:4px 0 4px 18px;padding:0;",
        tags$li(tags$b("Inside the gray band (green \u2713 within tolerance):"),
          " the local/window mean is within the selected numerical tolerance; this is not proof that the baseline is appropriate."),
        tags$li(tags$b("Outside the gray band (red \u26a0):"),
          " the signed local/window mean exceeds ±", tol_txt, " OD. Its sign and magnitude do not identify a cause. Possible contributors include real residual absorption, wavelength-dependent scattering, blank/reference mismatch, drift, contamination, path or handling differences, and measurement noise; distinguish them with provenance, blanks, controls, and the full spectrum.")
      ),
      tags$p(style = "margin:6px 0 0;",
        "The chart never establishes causation, proves correction quality, or excludes samples. It only identifies a numerical mean inside or outside the chosen review tolerance.")
    )
  })

  output$qc_table <- renderTable({ req(qc()); as.data.frame(qc()) }, na = "\u2014")

  sim_trace_cap <- reactive(.sim_budget_cap(input$sim_pair_budget %||% .sim_budget_default_index()))
  # An explicit per-dataset override: clicking "Compute anyway" records the CURRENT data fingerprint, so
  # the consent is spent the moment the data or normalization changes (a new large upload must re-consent).
  sim_override_key <- reactiveVal(NULL)
  .sim_data_key <- reactive({
    r <- results(); if (is.null(r) || !nrow(r)) return(NA_character_)
    proc <- split(r, r$sample)
    proc <- proc[vapply(proc, function(d) nrow(d) > 0L && length(d$.raw_nm_list) > 0L, logical(1))]
    if (!length(proc)) return(NA_character_)
    .sim_key_serialize(proc, isTRUE(norm_active()))
  })
  observeEvent(input$sim_compute_anyway, { sim_override_key(.sim_data_key()) })
  # Consent is bound to the material fingerprint; irrelevant display/normalization changes retain it.

  sim_engine_cache <- new.env(parent = emptyenv())
  sim_engine_cache$has_value <- FALSE
  sim_engine_cache$key <- NULL
  sim_engine_cache$value_box <- NULL
  sim_engine <- reactive({
    req(results())
    res <- results()
    data_key <- .sim_data_key()
    block <- .sim_budget_check(res, cap = sim_trace_cap(), override = identical(sim_override_key(), data_key))
    if (!is.null(block)) return(block)
    if (isTRUE(sim_engine_cache$has_value) && identical(sim_engine_cache$key, data_key))
      return(sim_engine_cache$value_box[[1L]])
    value <- compute_similarity(res)
    sim_engine_cache$key <- data_key
    sim_engine_cache$value_box <- list(value)
    sim_engine_cache$has_value <- TRUE
    value
  })

  sim_view_authorized <- reactive(.sim_view_authorized(input$main_nav, input$qc_view))
  # ORDERING IS THE PROPERTY: authorization is checked BEFORE sim_engine() is ever read, so an
  # unauthorized invalidation stops here and the O(N^2) engine is never entered. Because sim_engine is
  # a single shared reactive, N hidden material changes coalesce to the LATEST state and cost nothing;
  # returning to the view computes that latest state exactly once for all consumers together, and
  # returning WITHOUT a material change finds the cache valid and computes nothing at all.
  #
  # There is no queued or asynchronous similarity work to cancel: compute_similarity() runs
  # synchronously inside this reactive, so a computation already in flight when the user navigates away
  # cannot be interrupted and this code does not claim to interrupt it. The enforceable boundary is the
  # one implemented here -- once the server has processed the inactive view state, no SUBSEQUENT
  # material change can start a new computation. `sim_auth_ack` below is that server acknowledgment.
  sim_cached <- reactive({
    req(isTRUE(sim_view_authorized()))
    sim_engine()
  })

  # The server's own answer to "is the similarity view active?", published so a browser test can wait
  # for the server to have PROCESSED a navigation before applying a material change -- distinguishing a
  # real authorization defect from ordinary event-delivery timing. Rendered into a hidden span with
  # suspendWhenHidden = FALSE (below) so it stays current on every leg, visible or not.
  output$sim_auth_ack <- renderText({
    sprintf("tab=%s|view=%s|authorized=%s",
            input$main_nav %||% "", input$qc_view %||% "",
            if (isTRUE(sim_view_authorized())) "yes" else "no")
  })

  output$sim_budget_status <- renderUI({
    req(results())
    cap <- sim_trace_cap(); slider_cap <- if (is.finite(cap)) cap else .SIM_TRACE_HARD_MAX
    auto_cap <- min(slider_cap, .SIM_AUTO_CAP)
    n <- .sim_trace_count(results()); pairs <- .sim_pair_count(n)
    cap_txt <- if (slider_cap <= auto_cap) sprintf("%d traces", auto_cap)
               else sprintf("%d traces (automatic cap; consent permits the selected limit within the wavelength-work safety limit)", auto_cap)
    sim <- sim_cached()
    if (inherits(sim, "sim_budget_block"))
      div(style = "margin:6px 0;padding:8px 10px;border-radius:6px;background:var(--bs-warning-bg-subtle,#fff3cd);border-left:3px solid var(--bs-warning,#ffc107);font-size:0.9em;",
          tags$b("Similarity budget reached. "), .sim_budget_text(sim), br(),
          if (identical(sim$reason, "consent_required")) actionButton("sim_compute_anyway", "Compute similarity anyway", class = "btn-warning btn-sm", style = "margin-top:6px;"))
    else
      div(style = "margin:6px 0;font-size:0.85em;color:var(--bs-secondary-color);",
          sprintf("Budget: %s. This dataset has %d comparable trace%s (%s pair%s) — within budget.",
                  cap_txt, n, if (n == 1L) "" else "s",
                  format(pairs, big.mark = ",", scientific = FALSE, trim = TRUE), if (pairs == 1) "" else "s"))
  })

  # The scientific pair table remains complete. Only the browser payload is bounded,
  # and this adjacent disclosure prevents a 780-row/edge projection from looking like
  # the complete population when a 160-trace run contains 12,720 computed pairs.
  output$sim_projection_status <- renderUI({
    req(results())
    sim <- sim_cached()
    if (inherits(sim, "sim_budget_block") || is.null(sim) || !is.data.frame(sim) || nrow(sim) == 0L)
      return(NULL)
    div(style = "margin:4px 0 8px;padding:7px 10px;border-radius:6px;background:var(--bs-info-bg-subtle,#cff4fc);border-left:3px solid var(--bs-info,#0dcaf0);font-size:0.85em;",
        .sim_ui_projection_text(nrow(sim), .SIM_UI_PAIR_LIMIT))
  })

  output$similarity_table <- renderTable({
    req(results())
    sim <- sim_cached()
    if (inherits(sim, "sim_budget_block")) return(.sim_budget_note_df(sim))   # #9: over budget -> note
    if (is.null(sim) || nrow(sim) == 0)
      return(data.frame(Note = "Need at least 2 samples with processed data."))
    .similarity_presentation_df(.sim_ui_table_projection(sim, .SIM_UI_PAIR_LIMIT))
  }, na = "\u2014")

  build_qc_chart_react <- reactive({
    req(qc()); build_qc_chart(qc(), dark = is_dark()) + theme_bg(is_dark())
  })
  output$qc_chart <- renderPlot({ build_qc_chart_react() }, bg = "transparent",
    alt = "Data-quality overview chart summarizing per-sample QC flags (saturation, baseline, noise, coverage).")

  similarity_edges_react <- reactive({
    req(results())
    sim <- sim_cached()
    .sim_edge_payload(sim, input$sim_metric %||% "sam")
  })

  output$similarity_network_ui <- renderUI({
    if (identical(similarity_network_backend, "visNetwork")) visNetwork::visNetworkOutput("similarity_visnet", height = "460px")
    else if (identical(similarity_network_backend, "ggraph")) plotOutput("similarity_ggraph", height = "460px")
    else tagList(
      div(class="alert alert-info", style="font-size:0.9em;",
          "Network view needs the 'visNetwork' (or 'igraph' + 'ggraph') package. Showing the similarity table instead."),
      tableOutput("similarity_table_fallback")
    )
  })

  # Dynamic two-handle range slider for edge thickness and strength.
  # The slider's min/max come from the current network's actual edge weights so
  # the user always sees real numbers (not qualitative tiers). Step is chosen so
  # the slider has ~100 discrete positions across the value range.
  output$sim_edge_range_ui <- renderUI({
    d <- tryCatch(similarity_edges_react(), error = function(e) NULL)
    if (is.null(d) || is.null(d$edges) || nrow(d$edges) == 0) {
      return(div(style="min-width:240px;color:var(--bs-secondary-color);font-size:0.85em;",
                 tags$label("Edge strength range"),
                 br(),
                 em("(needs \u22652 samples with processed data)")))
    }
    w <- suppressWarnings(as.numeric(d$edges$strength))
    w <- w[is.finite(w)]
    if (length(w) < 1) {
      return(div(style="min-width:240px;",
                 tags$label("Edge strength range"),
                 br(),
                 em("(no finite edge weights)")))
    }
    lo <- floor(min(w) * 1000) / 1000
    hi <- ceiling(max(w) * 1000) / 1000
    if (!isTRUE(hi > lo)) hi <- lo + 0.001
    step <- signif((hi - lo) / 100, 2)
    if (!isTRUE(step > 0)) step <- 0.001
    # Preserve the user's previous handle positions across re-renders, clamping
    # them to the new [lo, hi] window when the underlying data has changed.
    prev <- isolate(input$sim_edge_range)
    val <- if (is.null(prev) || length(prev) != 2 ||
               !all(is.finite(suppressWarnings(as.numeric(prev)))))
      c(lo, hi) else c(max(lo, prev[1]), min(hi, prev[2]))
    if (val[2] < val[1]) val <- c(lo, hi)
 # build the info icon HERE, on the slider's real "Edge strength range"
    # label (which exists at render time), so it sits inline next to the label
    # instead of detaching to a block position — the failure caused by wrapping
    # the label-less uiOutput placeholder with with_tip() at UI-build time.
    with_tip(
      sliderInput("sim_edge_range",
                  label = "Edge strength range",
                  min = lo, max = hi, value = val, step = step,
                  width = "100%", ticks = FALSE),
      "Edge-strength filter. Only sample pairs whose similarity strength falls INSIDE this range are eligible to be drawn; pairs outside it are hidden (the nodes stay, but the connecting line disappears). Move the LEFT handle to the RIGHT to hide weak/low-similarity links and keep only the strongest connections — a cleaner, less cluttered network. Move the RIGHT handle to the LEFT to also drop the very strongest links, e.g. to inspect only moderate similarities. Both handles to the LEFT shows weak edges and hides strong ones; both to the RIGHT shows strong edges and hides weak ones. Widen the range fully (left handle hard-left, right handle hard-right) to include the complete edge population before the browser's disclosed 780-edge display limit is applied.")
  })

  if (identical(similarity_network_backend, "visNetwork")) {
    output$similarity_visnet <- visNetwork::renderVisNetwork({
        d <- similarity_edges_react()
        validate(need(!is.null(d) && !is.null(d$edges) && nrow(d$edges) > 0,
                      "Need at least 2 samples with processed data to draw the network."))
        pal <- curve_palette(input$palette %||% "okabe", length(d$nodes), dark = is_dark())
        build_similarity_visnetwork(d$edges, d$nodes, d$metric,
                                    layout = input$sim_layout %||% "bubble",
                                    node_palette = pal,
                                    node_color_map = sample_color_map(),
                                    show_node_names = isTRUE(input$sim_show_node_names),
                                    show_edge_values = isTRUE(input$sim_show_edge_values),
                                    edge_range = input$sim_edge_range,
                                    edge_limit = .SIM_UI_PAIR_LIMIT,
                                    dark = is_dark())
      })
  } else if (identical(similarity_network_backend, "ggraph")) {
    output$similarity_ggraph <- renderPlot({
      d <- similarity_edges_react()
      validate(need(!is.null(d) && !is.null(d$edges) && nrow(d$edges) > 0,
                    "Need at least 2 samples with processed data to draw the network."))
      build_similarity_ggraph(d$edges, d$nodes, d$metric,
                              layout = input$sim_layout %||% "bubble", dark = is_dark(),
                              node_color_map = sample_color_map(),
                              show_node_names = isTRUE(input$sim_show_node_names),
                              show_edge_values = isTRUE(input$sim_show_edge_values),
                              edge_range = input$sim_edge_range,
                              edge_limit = .SIM_UI_PAIR_LIMIT)
    }, bg = "transparent")
  } else {
    output$similarity_table_fallback <- renderTable({
      req(results())
      sim <- sim_cached()
      if (inherits(sim, "sim_budget_block")) return(.sim_budget_note_df(sim))   # #9: over budget -> note
      if (is.null(sim) || nrow(sim) == 0)
        return(data.frame(Note = "Need at least 2 samples with processed data."))
      .similarity_presentation_df(.sim_ui_table_projection(sim, .SIM_UI_PAIR_LIMIT))
    }, na = "—")
  }

  # Preview
  output$preview <- renderTable({ req(dat()); utils::head(dat(), 10) })

  # Data format tab: show head of demo data as example
  output$demo_format_preview <- renderTable({
    fmt_nm <- function(x) ifelse(x == round(x), formatC(x, format="d"), formatC(x, format="g"))
    df <- utils::head(builtin_demo_data(), 6)
    samp_cols <- setdiff(names(df), "nm")
    display_df <- data.frame(
      nm = fmt_nm(df$nm),
      stringsAsFactors = FALSE
    )
    for (col in samp_cols) display_df[[col]] <- round(df[[col]], 4)
    display_df
  }, digits = 4)

  output$dl_template <- downloadHandler(
    filename = function() "PASA_template.csv",
    content  = function(file) {
      df <- utils::head(builtin_demo_data(), 10)
      utils::write.csv(.sanitize_df_for_csv(as.data.frame(df)), file, row.names = FALSE, na = "")
    }
  )
  
  .spectra_display <- reactive(.pasa_display_curves(curves()))
  .spectra_appearance <- debounce(reactive({
    ids <- c("lbl_curve","lbl_band","lbl_nm","lbl_val","analysis_nm","norm_method","norm_band",
      "band_fill_intensity","line_pattern","line_width","palette","overlay","share_y","show_probe_line",
      "probe_nm","probe_color","show_peak_points_on_plot","gridline_intensity","apply_baseline",
      "customize_titles","title_x_axis","title_y_axis","title_chart","title_legend","x_axis_intensity","y_axis_intensity")
    setNames(lapply(ids,function(id)input[[id]]),ids)
  }),400)
  .spectra_plot_impl <- function(.dark = FALSE, .display = FALSE) {
    .plot_input <- if(.display).spectra_appearance() else input
    req(curves()); crv <- if(.display).spectra_display() else curves(); bands_df <- bands_react()
    peaks_points <- peak_points()
    
    if(!is.null(peaks_points)){
      peaks_points <- peaks_points %>%
        mutate(
          .lab_curve = if (isTRUE(.plot_input$lbl_curve)) sample else NA_character_,
          .lab_band  = if (isTRUE(.plot_input$lbl_band))  band   else NA_character_,
          .lab_nm    = if (isTRUE(.plot_input$lbl_nm))    paste0(round(peak_nm,1)," nm") else NA_character_,
          .lab_val   = if (isTRUE(.plot_input$lbl_val))   format(round(peak_val_post,4), trim=TRUE) else NA_character_,
          label = trimws(paste0(
            ifelse(is.na(.lab_curve),"", paste0(.lab_curve," • ")),
            ifelse(is.na(.lab_band),"",  paste0(.lab_band," • ")),
            ifelse(is.na(.lab_nm),"",    paste0(.lab_nm,  ifelse(is.na(.lab_val),""," • "))),
            ifelse(is.na(.lab_val),"",   .lab_val)
          ))
        )
    }
    
    # ---- Band-range highlights (global display control) ----
    # The "active" band is the one currently driving band normalization (if any),
    # otherwise the first band. It is drawn darker so it stands out from the
    # other (context) bands, which are shown faintly.
    p <- ggplot(crv, aes(x=nm))
    rng <- range(.plot_input$analysis_nm)
    active_band <- if (.plot_input$norm_method %in% c("band_peak_to","band_auc_to") &&
                       isTruthy(.plot_input$norm_band)) .plot_input$norm_band else bands_df$band[1]
    bfi <- suppressWarnings(as.numeric(.plot_input$band_fill_intensity)); if (!is.finite(bfi)) bfi <- 0.16
    vis_bands <- bands_df[bands_df$to > rng[1] & bands_df$from < rng[2], , drop=FALSE]
    if (bfi > 0.01 && nrow(vis_bands) > 0) {
      other_df  <- vis_bands[vis_bands$band != active_band, , drop=FALSE]
      active_df <- vis_bands[vis_bands$band == active_band, , drop=FALSE]
      if (nrow(other_df) > 0)
        p <- p + geom_rect(data=other_df, inherit.aes=FALSE,
                  aes(xmin=pmax(from, rng[1]), xmax=pmin(to, rng[2]),
                      ymin=-Inf, ymax=Inf),
                  fill="gray60", alpha=bfi * 0.45)
      if (nrow(active_df) > 0)
        p <- p + geom_rect(data=active_df, inherit.aes=FALSE,
                  aes(xmin=pmax(from, rng[1]), xmax=pmin(to, rng[2]),
                      ymin=-Inf, ymax=Inf),
                  fill="#0072B2", alpha=bfi)
    }
    # ---- Curves: global palette, line-type pattern, and thickness ----
    samp_lv  <- sort(unique(as.character(crv$sample)))
    n_curves <- length(samp_lv)
    lt_vals  <- curve_linetypes(.plot_input$line_pattern %||% "solid", n_curves)
    lw       <- suppressWarnings(as.numeric(.plot_input$line_width)); if(!is.finite(lw) || lw<=0) lw <- 0.75
    # Color each curve from the shared sample color map so a given sample is the
    # same color here and on the Band AUC radar.
    scm      <- sample_color_map()
    pal_vals <- scm[samp_lv]
    miss <- is.na(pal_vals)
    if (any(miss)) pal_vals[miss] <- curve_palette(.plot_input$palette %||% "okabe", sum(miss), dark = .dark)
    names(pal_vals) <- samp_lv
    names(lt_vals)  <- samp_lv

    p <- p + geom_line(aes(y=val_smooth, color=sample, linetype=sample, group=interaction(sample, .plot_run)),
                       linewidth=lw, na.rm=TRUE) +
      scale_color_manual(values=pal_vals) +
      scale_linetype_manual(values=lt_vals)
    if (!isTRUE(.plot_input$overlay)) {
      p <- p + facet_wrap(~ sample, scales = if (isTRUE(.plot_input$share_y)) "fixed" else "free_y") +
        theme(legend.position="none")
    }
    
    if (isTRUE(.plot_input$show_probe_line) && isTruthy(.plot_input$probe_nm)) {
      # Probe line color: Auto -> white on dark theme, dark gray on light theme
      # (visible on either); Blue / Red are fixed accents that read on both.
      probe_col <- .resolve_probe_color(.plot_input$probe_color, .dark)
      p <- p + geom_vline(xintercept=.plot_input$probe_nm, linetype="dotted", color=probe_col, linewidth=0.8)
    }
    
    if (!is.null(peaks_points) && nrow(peaks_points)>0 && isTRUE(.plot_input$show_peak_points_on_plot)) {
      p <- p + geom_point(data=peaks_points, inherit.aes=FALSE,
                          aes(x=peak_nm, y=peak_val_post, color=sample), size=1.9, na.rm=TRUE)
      if (any(c(.plot_input$lbl_curve, .plot_input$lbl_band, .plot_input$lbl_nm, .plot_input$lbl_val))) {
        p <- p + ggrepel::geom_text_repel(
          data=peaks_points, inherit.aes=FALSE,
          aes(x=peak_nm, y=peak_val_post, label=label, color=sample),
          size=3, box.padding=0.25, max.overlaps=30, min.segment.length=0, na.rm=TRUE
        )
      }
    }
    
    gint <- suppressWarnings(as.numeric(.plot_input$gridline_intensity)); if (!is.finite(gint)) gint <- 0.18
    grid_col <- if (isTRUE(.dark))
                  grDevices::adjustcolor("#ffffff", alpha.f = pmin(pmax(gint, 0), 1))
                else
                  grDevices::adjustcolor("#000000", alpha.f = pmin(pmax(gint * 0.55, 0), 1))
    grid_theme <- if (gint > 0.01)
        theme(panel.grid.major = element_line(color = grid_col, linewidth = 0.35),
              panel.grid.minor = element_blank())
      else
        theme(panel.grid.major = element_blank(), panel.grid.minor = element_blank())

    # Do not clamp the y-axis to [0, ∞) when baseline correction is off;
    # raw OD can legitimately be negative and the user must see it.
    # The axis label names the effective baseline state.
    apply_baseline_on <- isTRUE(.plot_input$apply_baseline)
    y_label <- if (apply_baseline_on) {
      if (norm_active()) "Baseline-corrected OD (normalized)" else "Baseline-corrected OD (absorbance)"
    } else {
      if (norm_active()) "Raw OD (normalized)" else "Raw OD (absorbance)"
    }
    xt <- if (isTRUE(.plot_input$customize_titles) && nzchar(.plot_input$title_x_axis %||% "")) .plot_input$title_x_axis else "Wavelength (nm)"
    yt <- if (isTRUE(.plot_input$customize_titles) && nzchar(.plot_input$title_y_axis %||% "")) .plot_input$title_y_axis else y_label
    ct <- if (isTRUE(.plot_input$customize_titles) && nzchar(.plot_input$title_chart %||% "")) .plot_input$title_chart else (if(isTRUE(.plot_input$overlay)) "Spectral curves \u2014 overlay" else "Spectral curves \u2014 facets")
    legend_lt <- if (isTRUE(.plot_input$customize_titles) && nzchar(.plot_input$title_legend %||% "")) .plot_input$title_legend else "sample"

    # X/Y-axis intensity sliders control the AXIS LINES themselves
    # (axis.line.x / axis.line.y) \u2014 not tick labels and not axis titles.
    # Tick labels and axis titles inherit their color from the active theme.
    xi <- suppressWarnings(as.numeric(.plot_input$x_axis_intensity)); if (!is.finite(xi)) xi <- 0.85
    yi <- suppressWarnings(as.numeric(.plot_input$y_axis_intensity)); if (!is.finite(yi)) yi <- 0.85
    base_axis_col <- if (isTRUE(.dark)) "#ffffff" else "#000000"
    xa_col <- grDevices::adjustcolor(base_axis_col, alpha.f = pmin(pmax(xi, 0), 1))
    ya_col <- grDevices::adjustcolor(base_axis_col, alpha.f = pmin(pmax(yi, 0), 1))
    x_axis_line <- if (xi > 0.01) element_line(color = xa_col, linewidth = 0.5) else element_blank()
    y_axis_line <- if (yi > 0.01) element_line(color = ya_col, linewidth = 0.5) else element_blank()

    p + scale_y_continuous() +
      labs(x=xt, y=yt, title=ct, color=legend_lt, linetype=legend_lt,
           caption=if(isTRUE(attr(crv,"pasa_display_reduced")))"Display simplified with local extrema preserved; tables and exported plots retain all points." else NULL) +
      scale_x_continuous(breaks=seq(floor(min(.plot_input$analysis_nm)), ceiling(max(.plot_input$analysis_nm)), by=50)) +
      theme_minimal(base_size=12) +
      grid_theme +
      theme(strip.text=element_text(face="bold"), plot.title=element_text(face="bold"),
            axis.line.x = x_axis_line,
            axis.line.y = y_axis_line) +
      theme_bg(.dark)
  }
  build_spectra_plot <- reactive({ .spectra_plot_impl(is_dark(), .display = TRUE) })
  output$plot_spectra <- renderPlot({ build_spectra_plot() },
    alt = "Absorbance spectra: absorbance (y) versus wavelength in nm (x) for the selected samples. See the Metrics and Band-AUC tables for the numeric values.")
  # Interactive 3D waterfall (only registered when plotly is available). Uses the
  # same processed display curves and sample color map as the 2D plot.
  if (has_plotly) {
    # Shared builder for the 3D waterfall so the inline plot and the Enlarge modal
 # (1) render the identical figure from the same controls.
    spectra_3d_fig <- reactive({
      crv <- curves(); req(!is.null(crv), nrow(crv) > 0)
 # probe appears in 3D as a translucent plane (band peaks stay 2D-only).
      probe_on  <- isTRUE(input$show_probe_line) && isTruthy(input$probe_nm)
      probe_pos <- if (probe_on) suppressWarnings(as.numeric(input$probe_nm)) else NA_real_
      probe_hex <- if (probe_on) .resolve_probe_color(input$probe_color, is_dark()) else NULL
      build_spectra_plotly_3d(
        crv, color_map = sample_color_map(),
        opacity = { v <- suppressWarnings(as.numeric(input$spectra_3d_opacity)); if (is.finite(v)) v else 0.6 },
        res     = { v <- suppressWarnings(as.numeric(input$spectra_3d_res));     if (is.finite(v)) v else 150 },
        dark    = is_dark(),
        probe_nm = probe_pos, probe_color = probe_hex,
        probe_opacity = { v <- suppressWarnings(as.numeric(input$spectra_3d_probe_opacity)); if (is.finite(v)) v else 0.25 },
        label_dist    = { v <- suppressWarnings(as.numeric(input$spectra_3d_label_dist));    if (is.finite(v)) v else 40 })
    })
    .spectra_3d_export_es <- function() {
      v <- suppressWarnings(as.numeric(input$spectra_3d_export_scale))
      if (is.finite(v) && v >= 1) min(v, 8) else 3
    }
    output$plot_spectra_3d <- plotly::renderPlotly({
        plotly::config(spectra_3d_fig(), displaylogo = FALSE,
                       toImageButtonOptions = list(format = "png", scale = .spectra_3d_export_es(),
                                                   filename = "PASA_3D_overlay"))
      })
    output$plot_spectra_3d_big <- plotly::renderPlotly({
        plotly::config(spectra_3d_fig(), displaylogo = FALSE,
                       toImageButtonOptions = list(format = "png", scale = .spectra_3d_export_es(),
                                                   filename = "PASA_3D_overlay"))
      })
  }
  
  # Probe table — pre-norm always shown; post-norm only when normalization is active
  probe_export_df <- reactive({
    req(isTRUE(input$show_probe_line), results(), isTruthy(input$probe_nm))
    nm0 <- as.numeric(input$probe_nm); res <- results()
    na_act <- norm_active()
    # The 'Also show after-normalization values' toggle (Spectra tab) adds the
    # extra Post-norm column. Only relevant when normalization is active.
    show_post <- na_act && isTRUE(input$probe_after_norm)
    # Label the value column honestly: when baseline correction is off the shown
    # value is raw OD (no subtraction has occurred), not an "after baseline" value.
    base_lbl <- if (isTRUE(input$apply_baseline)) "baseline-corrected, dilution-scaled" else "dilution-scaled OD"
    if (any(res$smoothing_applied %in% TRUE)) base_lbl <- paste0(base_lbl,", smoothed where available")
    tbl <- lapply(split(res, res$sample), function(df){
      nm     <- df$.raw_nm_list[[1]]
      y_pre  <- if (!is.null(df$.val_smooth_pre[[1]]))  df$.val_smooth_pre[[1]]  else df$.raw_val_list[[1]]
      y_post <- if (!is.null(df$.val_smooth_post[[1]])) df$.val_smooth_post[[1]] else df$.norm_val_list[[1]]
      if(!length(nm)) return(NULL)
      mnm <- if (".measured_nm" %in% names(df)) df$.measured_nm[[1]] else nm
      .probe_at <- function(y) {
        if(length(y)!=length(nm)||!isTRUE(.coverage_mask(nm0,mnm)[1])) return(NA_real_)
        ok <- is.finite(nm)&is.finite(y)
        if(sum(ok)<2L||length(unique(nm[ok]))<2L)return(NA_real_)
        stats::approx(nm[ok],y[ok],xout=nm0,rule=1,ties=mean)$y
      }
      if (show_post) {
        t <- tibble(Sample = df$sample[1], pre = .probe_at(y_pre), post = .probe_at(y_post))
        names(t)[2:3] <- c(sprintf("Pre-norm (%s)", base_lbl), "Post-norm")
        t
      } else {
        t <- tibble(Sample = df$sample[1], val = .probe_at(y_pre))
        names(t)[2] <- sprintf("Value (%s)", base_lbl)
        t
      }
    }) %>% bind_rows()
    if(nrow(tbl)==0) return(NULL)
    if (show_post) {
      names(tbl)[2:3] <- paste0(names(tbl)[2:3], " @ λ=", input$probe_nm, " nm")
    } else {
      names(tbl)[2] <- paste0(names(tbl)[2], " @ λ=", input$probe_nm, " nm")
    }
    arrange(tbl, Sample)
  })
  output$probe_table <- renderTable({ probe_export_df() })
  
  # Peaks table — post-norm column only shown when normalization is active
  peaks_export_df <- reactive({
    pp <- peak_points(); if(is.null(pp) || nrow(pp)==0) return(NULL)
    if (norm_active()) {
      pp %>%
        transmute(
          Sample = sample,
          Band   = band,
          `Peak λ (nm)` = round(peak_nm, 1),
          `Peak value (pre-norm)`  = round(peak_val_pre,  4),
          `Peak value (post-norm)` = round(peak_val_post, 4)
        ) %>% arrange(Sample, Band)
    } else {
      pp %>%
        transmute(
          Sample = sample,
          Band   = band,
          `Peak λ (nm)` = round(peak_nm, 1),
          `Peak value`   = round(peak_val_pre,  4)
        ) %>% arrange(Sample, Band)
    }
  })
  output$peaks_table <- renderTable({ peaks_export_df() })
  
  # peaks_block: switchable between stacked and by-band layout
  output$peaks_block <- renderUI({
    pp <- peak_points()
    if (is.null(pp) || nrow(pp) == 0) return(NULL)
    na_act <- norm_active()
    layout <- if (isTruthy(input$peaks_layout)) input$peaks_layout else "stacked"
    lam_col <- paste0("Peak ", "\u03bb", " (nm)")
    make_html_table <- function(df) {
      header <- paste0("<th>", htmltools::htmlEscape(names(df)), "</th>", collapse="")
      rows <- apply(df, 1, function(r) paste0("<td>", htmltools::htmlEscape(as.character(r)), "</td>", collapse=""))
      rows_html <- paste0("<tr>", rows, "</tr>", collapse="")
      HTML(paste0("<table class='table table-sm table-striped'><thead><tr>",
                  header, "</tr></thead><tbody>", rows_html, "</tbody></table>"))
    }
    if (layout == "stacked") {
      tbl <- if (na_act) {
        data.frame(
          Sample = pp$sample, Band = pp$band,
          nm_col = round(pp$peak_nm, 1),
          pre = round(pp$peak_val_pre, 4),
          post = round(pp$peak_val_post, 4),
          stringsAsFactors = FALSE
        )
      } else {
        data.frame(
          Sample = pp$sample, Band = pp$band,
          nm_col = round(pp$peak_nm, 1),
          pre = round(pp$peak_val_pre, 4),
          stringsAsFactors = FALSE
        )
      }
      if (na_act) {
        names(tbl) <- c("Sample", "Band", lam_col, "Peak value (pre-norm)", "Peak value (post-norm)")
      } else {
        names(tbl) <- c("Sample", "Band", lam_col, "Peak value")
      }
      tbl <- tbl[order(tbl$Sample, tbl$Band), , drop=FALSE]
      make_html_table(tbl)
    } else {
      # byband: one mini-table per band
      bands_sel <- unique(pp$band)
      tagList(lapply(bands_sel, function(bn) {
        sub <- pp[pp$band == bn, , drop = FALSE]
        tbl <- if (na_act) {
          data.frame(
            Sample = sub$sample,
            nm_col = round(sub$peak_nm, 1),
            pre = round(sub$peak_val_pre, 4),
            post = round(sub$peak_val_post, 4),
            stringsAsFactors = FALSE
          )
        } else {
          data.frame(
            Sample = sub$sample,
            nm_col = round(sub$peak_nm, 1),
            pre = round(sub$peak_val_pre, 4),
            stringsAsFactors = FALSE
          )
        }
        if (na_act) {
          names(tbl) <- c("Sample", lam_col, "Peak value (pre-norm)", "Peak value (post-norm)")
        } else {
          names(tbl) <- c("Sample", lam_col, "Peak value")
        }
        tbl <- tbl[order(tbl$Sample), , drop=FALSE]
        tagList(
          h5(bn),
          make_html_table(tbl)
        )
      }))
    }
  })

  make_auc_plot <- function(res, bands, chart_type = "bar",
                            palette = "okabe", auc_common_y = TRUE,
                            auc_ov = TRUE, dark = FALSE, color_map = NULL) {

    if (chart_type == "radar") {
      # --- Radar / spider chart ---
      # Wide format: samples as rows, bands as columns
      radar_df <- res %>%
        select(sample, band, auc) %>%
        mutate(band = factor(band, levels = bands$band)) %>%
        tidyr::pivot_wider(names_from = band, values_from = auc, values_fill = 0)
      .rd_lv <- as.character(bands$band)
      for (.bn in setdiff(.rd_lv, names(radar_df))) radar_df[[.bn]] <- 0
      radar_df <- radar_df[, c("sample", .rd_lv), drop = FALSE]
      n_bands <- length(bands$band)
      if (n_bands < 3) {
        # Can't draw a radar with < 3 axes; fall back to a text plot
        return(
          ggplot() +
            annotate("text", x=0, y=0, label="Radar chart requires at least 3 bands.",
                     size=5, color="#888888") +
            theme_void()
        )
      }
      # Build polygon coords: each band is one spoke evenly spaced around a circle.
      angles <- seq(0, 2*pi, length.out = n_bands + 1)[1:n_bands]
      samps  <- radar_df$sample
      # Prefer the shared sample color map so each sample matches its color on
      # the Spectra curves plot; fall back to the palette for any unmapped sample.
      cols   <- curve_palette(palette %||% "okabe", length(samps), dark = dark)
      if (!is.null(color_map) && length(color_map)) {
        mapped <- color_map[as.character(samps)]
        cols[!is.na(mapped)] <- mapped[!is.na(mapped)]
      }
      names(cols) <- as.character(samps)
      max_auc <- max(unlist(radar_df[,-1]), na.rm = TRUE)
      if (any(suppressWarnings(as.matrix(radar_df[,-1, drop = FALSE])) < 0, na.rm = TRUE)) {
        return(ggplot2::ggplot() +
          ggplot2::annotate("text", x = 0, y = 0, size = 4.2,
            color = if (isTRUE(dark)) "#f0f0f0" else "#1a1a1a",
            label = "Radar chart unavailable: one or more band AUCs are negative\n(a baseline-corrected band dips below zero). Signed values cannot be\nshown honestly on a radial axis — use the Bar chart, which renders signed AUC.") +
          ggplot2::theme_void())
      }
      # Theme-aware colors for radar decorations
      dark_mode_active <- dark
      grid_col   <- if (dark_mode_active) "#606060" else "#cccccc"
      spoke_col  <- if (dark_mode_active) "#909090" else "#bbbbbb"
      # Text (axis/spoke labels, % rings, legend) must be clearly legible in every
      # theme: use the active theme's foreground (near-white on dark, near-black on
      # light) at full strength rather than a faint gray.
      fg_col     <- if (dark_mode_active) "#f0f0f0" else "#1a1a1a"
      label_col  <- fg_col
      if (!is.finite(max_auc) || max_auc == 0) max_auc <- 1

      poly_df <- do.call(rbind, lapply(seq_along(samps), function(i) {
        vals <- as.numeric(radar_df[i, -1]) / max_auc
        vals[!is.finite(vals)] <- 0
        # Close the polygon
        vals_cl <- c(vals, vals[1]); ang_cl <- c(angles, angles[1])
        data.frame(
          x = vals_cl * cos(ang_cl),
          y = vals_cl * sin(ang_cl),
          sample = samps[i],
          stringsAsFactors = FALSE
        )
      }))
      lab_r <- 1.12
      label_df <- data.frame(
        x = lab_r * cos(angles),
        y = lab_r * sin(angles),
        label = bands$band,
        hjust = ifelse(cos(angles) >  0.2, 0, ifelse(cos(angles) < -0.2, 1, 0.5)),
        stringsAsFactors = FALSE
      )
      # Grid circles
      grid_r <- c(0.25, 0.5, 0.75, 1.0)
      circle_df <- do.call(rbind, lapply(grid_r, function(r) {
        th <- seq(0, 2*pi, length.out=120)
        data.frame(x=r*cos(th), y=r*sin(th), r=r)
      }))
      # Radial tick labels (fraction of the max band AUC) placed up the +y spoke,
      # at the same font size as the spoke labels / legend.
      tick_df <- data.frame(
        x = 0.02, y = grid_r,
        label = paste0(round(grid_r * 100), "%"),
        stringsAsFactors = FALSE
      )
      # Spoke/tick label text is sized to match the legend (base_size 12 -> ~12pt,
      # i.e. ~4.2 mm in geom_text units).
      lab_size  <- 4.2
      # Expand the drawing limits beyond the unit circle so the outer spoke
      # labels fit inside the canvas instead of bleeding out.
      lim <- 1.55

      .na_mat  <- !is.finite(as.matrix(radar_df[, -1, drop = FALSE]))
      any_na_band <- any(.na_mat)
      radar_sub <- if (isTRUE(any_na_band)) {
        .na_bands <- colnames(.na_mat)[apply(.na_mat, 2, any)]
        .rsn <- if ("band_na_reason" %in% names(res)) {
          .r <- res$band_na_reason[as.character(res$band) %in% .na_bands]
          unique(.r[!is.na(.r)])
        } else character(0)
        .txt <- c(
          if ("no_measured_coverage"  %in% .rsn) "outside this spectrum's measured coverage",
          if ("out_of_analysis_range" %in% .rsn) "outside the analysis range",
          if ("empty_band_window"     %in% .rsn) "given a zero-width band window (its two endpoints are equal), so it cannot be integrated at any analysis range",
          # A band that IS covered and IS in range but is still NA on the plotted basis (e.g.
          # normalization refused for that sample) -- report it honestly rather than mislabel it.
          if (!length(.rsn)) "not evaluable on the selected AUC basis")
        sprintf("%s: %s; drawn as 0 (see the AUC table).",
                paste(.na_bands, collapse = ", "), paste(.txt, collapse = " / "))
      } else NULL

      plt <- ggplot() +
        geom_path(data=circle_df, aes(x=x, y=y, group=r), color=grid_col, linewidth=0.3) +
        geom_segment(data=label_df, aes(x=0, y=0, xend=cos(atan2(y,x))*0.87, yend=sin(atan2(y,x))*0.87),
                     color=spoke_col, linewidth=0.4, arrow=NULL) +
        geom_text(data=tick_df, aes(x=x, y=y, label=label), size=lab_size*0.8,
                  color=label_col, hjust=0, vjust=-0.3) +
        geom_text(data=label_df, aes(x=x, y=y, label=label, hjust=hjust),
                  size=lab_size, color=label_col, lineheight=0.9) +
        { if (auc_ov) {
            geom_polygon(data=poly_df, aes(x=x, y=y, group=sample, color=sample, fill=sample),
                         alpha=0.22, linewidth=0.9)
          } else {
            list(
              geom_polygon(data=poly_df, aes(x=x, y=y, group=sample, fill=sample),
                           alpha=0.35, linewidth=0.8),
              facet_wrap(~sample)
            )
          }
        } +
        scale_color_manual(values=cols, aesthetics=c("color","fill")) +
        coord_equal(xlim=c(-lim, lim), ylim=c(-lim, lim), clip="off") +
        # Only declare the `color` label when the color aesthetic is actually
        # mapped (overlay mode). In facet mode only `fill` is used, so declaring
        # `color` here triggers the harmless "Ignoring unknown labels: color" note.
        { if (auc_ov) labs(title="Band AUC — radar chart", subtitle=radar_sub, color="Sample", fill="Sample")
          else        labs(title="Band AUC — radar chart", subtitle=radar_sub, fill="Sample") } +
        theme_void(base_size=12) +
        theme(
          legend.position  = if(auc_ov) "right" else "none",
          legend.text      = element_text(size=11, color=fg_col),
          legend.title     = element_text(size=12, face="bold", color=fg_col),
          plot.title       = element_text(face="bold", color=fg_col),
          plot.subtitle    = element_text(color=fg_col, size=10),
          strip.text       = element_text(face="bold", color=fg_col),
          text             = element_text(color=fg_col),
          # Explicitly blank every axis element here (not only via theme_void()).
          # theme_void()'s blanking lives in the *complete* theme, which the ZIP
          # exporter's .preserve_blank_axes() cannot see (it inspects the plot's
          # incremental $theme). Declaring the blanks here makes them visible to
          # that guard, so theme_light_override cannot introduce spurious
          # -1/0/1 tick labels and x/y axis titles in band_auc_radar.png.
          axis.title       = element_blank(),
          axis.title.x     = element_blank(),
          axis.title.y     = element_blank(),
          axis.text        = element_blank(),
          axis.text.x      = element_blank(),
          axis.text.y      = element_blank(),
          axis.ticks       = element_blank(),
          axis.ticks.x     = element_blank(),
          axis.ticks.y     = element_blank(),
          axis.line        = element_blank(),
          axis.line.x      = element_blank(),
          axis.line.y      = element_blank(),
          plot.margin      = margin(14, 14, 14, 14),
          # Theme-aware backgrounds for radar chart
          plot.background  = element_rect(fill=if(dark_mode_active) "#1d1f21" else "white", color=NA),
          panel.background = element_rect(fill=if(dark_mode_active) "#1d1f21" else "white", color=NA),
          legend.background= element_rect(fill=if(dark_mode_active) "#1d1f21" else "white", color=NA),
          strip.background = element_rect(fill=if(dark_mode_active) "#27292b" else "#f5f5f5", color=NA)
        )
      return(plt)
    }

    # --- Default: Bar chart ---
    # Use auc_common_y to decide scales.
    auc_scales <- if (isTRUE(auc_common_y)) "fixed" else "free_y"
    bar_cols <- curve_palette(palette %||% "okabe", length(bands$band), dark = dark)
    res %>% mutate(band=factor(band, levels=bands$band)) %>%
      ggplot(aes(x=band, y=auc, fill=band)) +
      geom_col(width=0.75) +
      scale_fill_manual(values=bar_cols) +
      facet_wrap(~ sample, scales = auc_scales) +
      labs(x=NULL, y="AUC (band)", title="Band-wise AUC per sample") +
      guides(fill = guide_legend(title = "Band")) +
      theme_minimal(base_size=12) +
      theme(panel.grid.minor=element_blank(), strip.text=element_text(face="bold"),
            legend.position = "right", plot.title=element_text(face="bold"),
            axis.text.x = element_blank(), axis.ticks.x = element_blank(),
            axis.title.x = element_blank()) +
      theme_bg(dark)
  }

  build_auc_plot <- reactive({
    req(results()); res <- results(); bands <- bands_react()
    make_auc_plot(res, bands,
                  chart_type   = input$auc_chart_type %||% "bar",
                  palette      = input$palette %||% "okabe",
                  auc_common_y = isTRUE(input$auc_common_y),
                  auc_ov       = isTRUE(input$auc_overlay),
                  dark         = is_dark(),
                  color_map    = sample_color_map())
  })
  output$plot_auc <- renderPlot({ req(isTRUE(input$apply_baseline)); build_auc_plot() }, bg="transparent", alt="Band area-under-curve chart (bar or radar) of pigment-band AUC for each selected sample.")

  # Responsive container for the AUC plot. Radar charts need more square space;
  # bar charts can be a bit shorter. Width is always 100% to fill the panel.
  output$auc_plot_ui <- renderUI({
    ct <- input$auc_chart_type %||% "bar"
    h  <- if (ct == "radar") "min(80vw, 600px)" else "520px"
    enlarge_bar <- div(style="display:flex;justify-content:flex-end;margin-bottom:2px;",
                       actionButton("enlarge_auc", HTML("&#10530; Enlarge"),
                                    class="btn-sm btn-outline-secondary"))
    # The CSS calc ensures radar never exceeds panel width while remaining square.
    if (ct == "radar") {
      tagList(
        enlarge_bar,
        tags$style(HTML(".radar-plot-wrap { width:100%; max-width:700px; margin:0 auto; }
                         .radar-plot-wrap .shiny-plot-output { width:100% !important; }"))  ,
        div(class="radar-plot-wrap",
          plotOutput("plot_auc",
            height = "550px",
            width  = "100%"
          )
        )
      )
    } else {
      tagList(
        enlarge_bar,
        plotOutput("plot_auc", height="520px", width="100%")
      )
    }
  })

  observeEvent(input$enlarge_spectra, {
 # 1: when the 3D overlay is active, enlarge the interactive 3D plotly
    # (a larger plotlyOutput) instead of the 2D plot.
    body <- if (isTRUE(input$spectra_3d) && has_plotly)
      plotly::plotlyOutput("plot_spectra_3d_big", height = "95vh", width = "100%")
    else
      plotOutput("plot_spectra_big", height = "95vh", width = "100%")
    showModal(modalDialog(
      tags$style(HTML(".modal-xl{max-width:95vw !important;} .modal-xl .modal-body{padding:6px;}")),
      title = "Spectra", size = "xl", easyClose = TRUE, footer = modalButton("Close"),
      body
    ))
  })
  output$plot_spectra_big <- renderPlot({ build_spectra_plot() }, bg = "transparent",
    alt = "Enlarged absorbance spectra: absorbance (y) versus wavelength in nm (x) for the selected samples.")

  observeEvent(input$enlarge_auc, {
    showModal(modalDialog(
      tags$style(HTML(".modal-xl{max-width:95vw !important;} .modal-xl .modal-body{padding:6px;}")),
      title = if (identical(input$auc_chart_type %||% "bar", "radar"))
                "Band AUC — radar chart" else "Band AUC — bar chart",
      size = "xl", easyClose = TRUE, footer = modalButton("Close"),
      plotOutput("plot_auc_big", height = "95vh", width = "100%")
    ))
  })
  output$plot_auc_big <- renderPlot({ req(isTRUE(input$apply_baseline)); build_auc_plot() }, bg = "transparent", alt="Enlarged band area-under-curve chart of pigment-band AUC for each selected sample.")

  # Build the complete clipboard table only after the user clicks Copy.
  observeEvent(input$copy_metrics_table, {
    tryCatch({
      md <- metrics_df()
      if (is.null(md) || !nrow(md)) stop("No metrics table is available. Load data and resolve any flagged settings first.",call.=FALSE)
      bad <- .c0_offending(c(names(md),unlist(lapply(md,as.character),use.names=FALSE)),"metrics table")
      if (!is.null(bad)) stop("The metrics table contains unsupported control characters.",call.=FALSE)
      flat <- .sanitize_df_for_csv(md)
      txt <- paste(paste(names(flat),collapse="\t"),paste(.pasa_tsv_rows(flat),collapse="\n"),sep="\n")
      session$sendCustomMessage("pasa-copy-metrics",list(value=txt))
    },error=function(e) {
      msg <- conditionMessage(e)
      if(!nzchar(msg)) msg <- "No metrics table is available. Load data and resolve any flagged settings first."
      session$sendCustomMessage("pasa-copy-metrics",list(value="",error=msg))
    })
  },ignoreInit=TRUE)
  output$copy_metrics_notify <- renderUI({
    status <- input$copy_metrics_status
    if (is.null(status)) return(NULL)
    text <- switch(status,
      ok="Table copied to clipboard as tab-separated text. Paste into Excel or similar.",
      preparing="Preparing the complete metrics table...",
      empty="No metrics table is available. Load data and resolve any flagged settings first.",
      "Automatic copy was unavailable. Use the text dialog to select and copy the complete table, or download XLSX.")
    div(class=if(identical(status,"ok"))"alert alert-success" else "alert alert-info",
        style="padding:4px 10px;font-size:0.85em;margin:4px 0;",text)
  })
  metrics_page <- reactiveVal(1L)
  .metrics_page_size <- 20L
  observeEvent(results(),metrics_page(1L),ignoreInit=TRUE)
  observeEvent(input$metrics_page_prev,metrics_page(max(1L,metrics_page()-1L)),ignoreInit=TRUE)
  observeEvent(input$metrics_page_next,{
    n <- length(unique(results()$sample)); pages <- max(1L,ceiling(n/.metrics_page_size))
    metrics_page(min(pages,metrics_page()+1L))
  },ignoreInit=TRUE)
  output$metrics_page_controls <- renderUI({
    n <- length(unique(results()$sample)); pages <- max(1L,ceiling(n/.metrics_page_size))
    page <- min(metrics_page(),pages)
    div(class="pasa-metrics-pagination",
      actionButton("metrics_page_prev","Previous",class="btn-sm",disabled=if(page<=1L)"disabled" else NULL),
      span(sprintf("Page %d of %d · samples %d–%d of %d",page,pages,if(n)(page-1L)*.metrics_page_size+1L else 0L,min(page*.metrics_page_size,n),n)),
      actionButton("metrics_page_next","Next",class="btn-sm",disabled=if(page>=pages)"disabled" else NULL),
      tags$small("Copy and data downloads include every sample."))
  })

  # Metrics — renderUI instead of render_gt: supports 5 layout variants
  # (stacked/v1/v2 return one HTML gt block; v3/v4 return a tagList of blocks)
  output$metrics_ui <- renderUI({
    req(results())
    res <- results()
    sample_names <- sort(unique(as.character(res$sample)))
    page <- min(metrics_page(),max(1L,ceiling(length(sample_names)/.metrics_page_size)))
    shown <- sample_names[seq.int((page-1L)*.metrics_page_size+1L,min(page*.metrics_page_size,length(sample_names)))]
    res <- res[as.character(res$sample) %in% shown,,drop=FALSE]

    # Is a normalization method active?
    norm_active <- isTRUE(input$apply_baseline) && isTruthy(input$norm_method) && input$norm_method != "none"

    # ---- Normalization-INDEPENDENT band ratios (per sample) ----
    # Built from raw band AUC + pre-norm band peak values, which do NOT
    # depend on the chosen normalization method.
    ratios   <- band_ratio_tbl(res)
    od_peaks <- band_odpeak_tbl(res)

    base_tbl <- res %>%
      select(sample, band, auc, auc_raw, peak_nm, peak_val_post, peak_val_pre,
             baseline_nm_used, smoothing_method,
             dilution_factor, norm_method, norm_band, norm_target, norm_ref_nm,
             norm_applied, norm_reason,
             analysis_from, analysis_to, total_auc, total_auc_raw) %>%
      mutate(auc=round(auc,3), auc_raw=round(auc_raw,3),
             peak_nm=round(peak_nm,1),
             peak_post = if (norm_active) round(peak_val_post,4) else NA_real_,
             peak_pre  = round(peak_val_pre,4),
             total_auc=round(total_auc,3),
             total_auc_raw=round(total_auc_raw,3)) %>%
      left_join(ratios, by = "sample") %>%
      left_join(od_peaks, by = "sample") %>%
      # auc = post-norm (for display/normalization-independent ratios under linear norm).
      # auc_raw = truly raw: trapz on original uploaded OD values after dilution only,
      #           before baseline correction, smoothing, and normalization.
      rename(Sample=sample, Band=band,
             `AUC (processed)` = auc,
             `AUC (pre-baseline, dil-scaled)` = auc_raw,
             `Peak λ (nm)`=peak_nm,
             `Total AUC (processed)` = total_auc,
             `Total AUC (raw)` = total_auc_raw,
             `Peak value (pre-norm)`=`peak_pre`,
             `Peak value (post-norm)`=`peak_post`) %>%
      arrange(Sample, Band)

    metrics_layout_sel <- (input$metrics_layout %||% "stacked")

    # CSS follows the app theme; changing appearance does not rebuild the table.
    apply_dark <- function(gg) gg %>% tab_options(
      table.background.color="transparent",column_labels.background.color="transparent",
      row.striping.background_color="transparent",table.font.color="#111111")

    apply_postnorm_style <- function(gg, na_rows, skip_rows = integer(0)) {
      gray_rows <- union(na_rows, skip_rows)
      if (length(gray_rows) > 0) {
        gg <- gg %>%
          tab_style(
            style = list(cell_text(color = "#999999", style = "italic")),
            locations = cells_body(columns = `Peak value (post-norm)`, rows = gray_rows)
          )
      }
      if (!norm_active) {
        gg <- gg %>%
          tab_footnote(
            footnote = "No normalization selected \u2014 post-norm values are not computed (shown as \u2014). Raw metrics and ratios above are unaffected.",
            locations = cells_column_labels(columns = `Peak value (post-norm)`)
          )
      } else if (length(skip_rows) > 0) {
        gg <- gg %>%
          tab_footnote(
            footnote = "Normalization was requested but skipped for these grayed rows (non-positive divisor or target, or reference wavelength outside the measured range) \u2014 the value shown is the pre-normalization value, unscaled. See the norm_applied / norm_reason columns in the metrics export.",
            locations = cells_body(columns = `Peak value (post-norm)`, rows = skip_rows)
          )
      }
      gg
    }

    # The 3 spanners used in stacked and v2. Built with any_of() against the
    # actual columns present (after rename_pbs_cols), so newly added bands
    # (PE, Chl b Qy) and renamed bands (PBS vs Chl a Qx, Qy vs Chl a Qy) never
    # break the spanner targeting.
    apply_spanners <- function(gg, present_cols) {
      od_cols    <- present_cols[grepl("^OD at .* peak \\(baseline-corr., pre-norm\\)$", present_cols)]
      ratio_cols <- present_cols[grepl("\\(AUC\\)$", present_cols) & grepl("/", present_cols)]
      # AUC (processed) and Total AUC (processed) are integrated on the POST-
      # normalization curve, so they are rescaled by the active normalization and
      # are NOT normalization-independent. Only the raw/pre-norm areas, the peak
      # wavelength (argmax, invariant under positive scaling), the pre-norm peak
      # value, and the AUC ratios are truly invariant.
      indep_cols <- c("AUC (pre-baseline, dil-scaled)",
                      "Peak \u03bb (nm)", "Peak value (pre-norm)",
                      ratio_cols, "Total AUC (raw)")
      auc_cols <- c("AUC (processed)","Total AUC (processed)")
      auc_dep <- identical(auc_basis(),"normalized") && norm_active
      indep_cols <- c(indep_cols,if(!auc_dep)auc_cols)
      dep_cols <- c(if(auc_dep)auc_cols,"Peak value (post-norm)")
      gg %>%
        tab_spanner(label = "OD values per band peak (post-dilution-correction, pre-norm)",
                    columns = any_of(od_cols)) %>%
        tab_spanner(label = "Normalization-independent (raw/pre-norm areas, peak \u03bb, AUC ratios \u2014 invariant under multiplicative normalization)",
                    columns = any_of(indep_cols)) %>%
        tab_spanner(label = "Normalization-dependent (scaled by the active normalization)",
                    columns = any_of(dep_cols))
    }

    tryCatch({

      if (metrics_layout_sel %in% c("stacked", "v1", "v2")) {
        # --- Single-table layouts ---
        tbl_sel <- if (metrics_layout_sel == "stacked") {
          base_tbl %>% arrange(Sample, Band)
        } else {
          base_tbl %>% arrange(Band, Sample)
        }
        na_post_rows <- which(is.na(tbl_sel$`Peak value (post-norm)`))
        skip_post_rows <- if (norm_active) which(tbl_sel$norm_applied %in% FALSE) else integer(0)
        # Any extra band OD/ratio columns (PE, Chl b Qy) added generically.
        extra_cols <- names(tbl_sel)[
          grepl("^OD at Phycoerythrin|^OD at Chl b Qy|^Qy/PE|^Chl a Qy/Chl b Qy", names(tbl_sel))]
        full_cols <- c("Sample", "Band", "AUC (processed)", "AUC (pre-baseline, dil-scaled)",
                       "Peak \u03bb (nm)",
                       "Peak value (pre-norm)", "Peak value (post-norm)",
                       "OD at Qy peak (baseline-corr., pre-norm)", "OD at Soret/Bx peak (baseline-corr., pre-norm)",
                       "OD at Carotenoid peak (baseline-corr., pre-norm)", "OD at PBS peak (baseline-corr., pre-norm)",
                       "Qy/Car (AUC)", "Qy/PBS (AUC)", "Qy/Bx (AUC)", "Qy/Car (peak, pre-norm)",
                       extra_cols,
                       "Total AUC (processed)", "Total AUC (raw)",
                       "baseline_nm_used", "smoothing_method",
                       "dilution_factor", "norm_method", "analysis_from", "analysis_to")
        # Rename PBS cols to active band label before display
        tbl_data <- rename_pbs_cols(tbl_sel[, intersect(full_cols, names(tbl_sel))])
        present_cols <- names(tbl_data)

        gg <- if (metrics_layout_sel == "stacked") {
          # stacked: grouped by Sample, WITH the 3 spanners
          tbl_data %>%
            gt() %>%
            sub_missing(missing_text = "\u2014") %>%
            apply_spanners(present_cols) %>%
            tab_header(
              title = md("**Spectral Band Metrics**"),
              subtitle = metrics_subtitle(input, nm_native = tryCatch(dat()[[1]], error = function(e) NULL), eff = tryCatch(.metrics_eff_summary(results()), error = function(e) NULL))
            ) %>%
            apply_dark() %>%
            apply_postnorm_style(na_post_rows, skip_post_rows)
        } else if (metrics_layout_sel == "v1") {
          # Layout variant 1: row-grouped by band, without spanners.
          tbl_data %>%
            gt(groupname_col = "Band") %>%
            sub_missing(missing_text = "\u2014") %>%
            tab_header(
              title = md("**Spectral Band Metrics (by band)**"),
              subtitle = metrics_subtitle(input, nm_native = tryCatch(dat()[[1]], error = function(e) NULL), eff = tryCatch(.metrics_eff_summary(results()), error = function(e) NULL))
            ) %>%
            apply_dark() %>%
            apply_postnorm_style(na_post_rows, skip_post_rows)
        } else {
          # Layout variant 2: row-grouped by band, with three spanners.
          tbl_data %>%
            gt(groupname_col = "Band") %>%
            sub_missing(missing_text = "\u2014") %>%
            apply_spanners(present_cols) %>%
            tab_header(
              title = md("**Spectral Band Metrics (by band)**"),
              subtitle = metrics_subtitle(input, nm_native = tryCatch(dat()[[1]], error = function(e) NULL), eff = tryCatch(.metrics_eff_summary(results()), error = function(e) NULL))
            ) %>%
            apply_dark() %>%
            apply_postnorm_style(na_post_rows, skip_post_rows)
        }
        HTML(gt::as_raw_html(gg, inline_css = FALSE))

      } else {
        # --- Multi-table layouts: v3 / v4 ---
        # Render one gt table per band (band-specific cols only),
        # plus one shared per-sample summary table.
        with_spanners <- (metrics_layout_sel == "v4")

        # Band-specific columns for per-band tables
        band_specific_cols <- c("Sample", "AUC (processed)", "AUC (pre-baseline, dil-scaled)",
                                 "Peak \u03bb (nm)",
                                 "Peak value (pre-norm)", "Peak value (post-norm)")
        # Preferred band display order from the active band set (left-to-right by nm)
        band_order <- band_set()$band
        bands_present <- base_tbl %>% pull(Band) %>% unique()
        bands_ordered <- c(
          intersect(band_order, bands_present),
          setdiff(bands_present, band_order)
        )

        # Per-sample summary table (whole-spectrum metrics, not repeated per band)
        # Select the fixed columns plus any extra band ratio/OD columns present.
        summ_extra <- names(base_tbl)[
          grepl("^OD at Phycoerythrin|^OD at Chl b Qy|^Qy/PE|^Chl a Qy/Chl b Qy", names(base_tbl))]
        summ_cols <- c("Sample", "Total AUC (processed)", "Total AUC (raw)",
                       "Qy/Car (AUC)", "Qy/PBS (AUC)", "Qy/Bx (AUC)", "Qy/Car (peak, pre-norm)",
                       "OD at Qy peak (baseline-corr., pre-norm)", "OD at Soret/Bx peak (baseline-corr., pre-norm)",
                       "OD at Carotenoid peak (baseline-corr., pre-norm)", "OD at PBS peak (baseline-corr., pre-norm)",
                       summ_extra)
        summary_tbl <- rename_pbs_cols(
          base_tbl %>%
            select(any_of(summ_cols)) %>%
            distinct()
        )

        # Build one gt per band
        band_blocks <- lapply(bands_ordered, function(b) {
          bt_full <- base_tbl %>%
            filter(Band == b) %>%
            arrange(Sample)
          bt <- bt_full %>% select(all_of(band_specific_cols))
          na_rows_b   <- which(is.na(bt$`Peak value (post-norm)`))
          skip_rows_b <- if (norm_active) which(bt_full$norm_applied %in% FALSE) else integer(0)
          gg_b <- bt %>%
            gt() %>%
            sub_missing(missing_text = "\u2014") %>%
            tab_header(
              title = md(paste0("**", b, "**")),
              subtitle = if (b == bands_ordered[1]) metrics_subtitle(input, nm_native = tryCatch(dat()[[1]], error = function(e) NULL), eff = tryCatch(.metrics_eff_summary(results()), error = function(e) NULL)) else NULL
            ) %>%
            apply_dark()
          if (with_spanners) {
            gg_b <- gg_b %>%
              tab_spanner(
                label = "Band metrics",
                columns = c(`AUC (processed)`, `AUC (pre-baseline, dil-scaled)`,
                            `Peak λ (nm)`,
                            `Peak value (pre-norm)`, `Peak value (post-norm)`)
              )
          }
          gg_b <- gg_b %>% apply_postnorm_style(na_rows_b, skip_rows_b)
          div(style = "margin-bottom:18px;", HTML(gt::as_raw_html(gg_b, inline_css = FALSE)))
        })

        # Build the shared per-sample summary table
        gg_sum <- summary_tbl %>%
          gt() %>%
          sub_missing(missing_text = "\u2014") %>%
          tab_header(title = md("**Per-sample summary (whole-spectrum metrics)**")) %>%
          apply_dark()
        if (with_spanners) {
          sum_cols  <- names(summary_tbl)
          ratio_cols <- sum_cols[grepl("\\(AUC\\)|\\(peak, pre-norm\\)", sum_cols)]
          od_cols    <- sum_cols[grepl("^OD at ", sum_cols)]
          gg_sum <- gg_sum %>%
            tab_spanner(
              label = "Total AUC",
              columns = any_of(c("Total AUC (processed)", "Total AUC (raw)"))
            )
          if (length(ratio_cols)) {
            gg_sum <- gg_sum %>%
              tab_spanner(label = "Ratios", columns = any_of(ratio_cols))
          }
          if (length(od_cols)) {
            gg_sum <- gg_sum %>%
              tab_spanner(label = "OD at band peaks (post-dilution, pre-norm)",
                          columns = any_of(od_cols))
          }
        }
        summary_block <- div(style = "margin-bottom:18px;",
                             HTML(gt::as_raw_html(gg_sum, inline_css = FALSE)))

        do.call(tagList, c(band_blocks, list(summary_block)))
      }

    }, error = function(e) {
      # Fallback: simplified single gt so the tab never blanks
      na_post_rows_fb <- which(is.na(base_tbl$`Peak value (post-norm)`))
      g_fb <- gt(base_tbl %>% select(Sample, Band, `AUC (processed)`, `AUC (pre-baseline, dil-scaled)`,
                                     `Peak λ (nm)`,
                                     `Peak value (pre-norm)`,
                                     `Total AUC (processed)`, `Total AUC (raw)`)) %>%
        sub_missing(missing_text = "\u2014") %>%
        tab_header(title = md("**Spectral Band Metrics**"),
                   subtitle = paste0("(simplified view \u2014 ", conditionMessage(e), ")"))
      HTML(gt::as_raw_html(g_fb, inline_css = FALSE))
    })
  })

  # ---------- Downloads ----------
  # Processed (tidy long) quantitative data: nm + pre/post per sample (used to
  # build wide forms and the ZIP bundle). These values are unshifted by the
  # display-only baseline-offset option.
  processed_long <- reactive({
    req(results()); res <- results()
    dplyr::bind_rows(lapply(split(res, res$sample), function(df){
      nm   <- df$.raw_nm_list[[1]]
      pre  <- df$.val_smooth_pre[[1]]
      post <- df$.val_smooth_post[[1]]
      if (is.null(nm) || !length(nm)) return(NULL)
      tibble::tibble(sample = df$sample[1], nm = nm,
                     value_pre_norm = pre, value_post_norm = post)
    })) %>% dplyr::arrange(sample, dplyr::desc(nm))
  })

  # Wide processed quantitative data: one row per wavelength, one column per
  # sample. Built separately for pre-normalization and post-normalization values
  # so each download mirrors the input file's layout (nm in column 1, samples across).
  processed_wide <- function(which = c("pre","post")){
    which <- match.arg(which)
    lg <- processed_long()
    valcol <- if (which == "pre") "value_pre_norm" else "value_post_norm"
    w <- lg %>%
      dplyr::select(nm, sample, dplyr::all_of(valcol)) %>%
      tidyr::pivot_wider(names_from = sample, values_from = dplyr::all_of(valcol)) %>%
      dplyr::arrange(nm)
    names(w)[1] <- "nm"
    w
  }

  # Metrics as a flat data frame (same content as the Metrics tab/export).
  # Include ratio columns and OD-at-band-peak summary columns in every
  # export/copy path. Exported data should not be a reduced subset of the table
  # a scientist uses for interpretation.
  metrics_df <- reactive({
    req(results()); res <- results()
    norm_active_local <- isTRUE(input$apply_baseline) && isTruthy(input$norm_method) && input$norm_method != "none"
    ratios   <- band_ratio_tbl(res)
    od_peaks <- band_odpeak_tbl(res)
    res %>%
      transmute(
        Sample = sample, Band = band,
        `AUC (processed)`         = round(auc, 3),
        `AUC (pre-baseline, dil-scaled)` = round(auc_raw, 3),
        `Peak λ (nm)`             = round(peak_nm, 1),
        `Peak value (pre-norm)`   = round(peak_val_pre, 4),
        `Peak value (post-norm)`  = if (norm_active_local) round(peak_val_post, 4) else NA_real_,
        `Total AUC (processed)`   = round(total_auc, 3),
        `Total AUC (raw)`         = round(total_auc_raw, 3),
        `Baseline display shift (internal)` = round(baseline_display_shift, 6),
        `Baseline method requested` = baseline_method,
        `Baseline reference requested (nm)` = baseline_nm_req,
        `Baseline window requested lo (nm)` = baseline_win_lo_req,
        `Baseline window requested hi (nm)` = baseline_win_hi_req,
        `Baseline effective node/center (nm)` = baseline_nm_used,
        `Baseline effective window lo (nm)` = baseline_effective_lo,
        `Baseline effective window hi (nm)` = baseline_effective_hi,
        `Baseline contributing point count` = baseline_point_count,
        `Baseline statistic` = baseline_statistic,
        `Baseline source scope` = baseline_source_scope,
        `Baseline used outside analysis range` = baseline_used_outside_analysis,
        baseline_val_used,
        `Baseline refused` = baseline_refused, `Baseline status` = baseline_reason,
        smoothing_method, smoothing_requested, smoothing_applied, smoothing_reason,
        smoothing_run_count, smoothing_applied_run_count, smoothing_run_details,
        resample_applied, resample_refused, resample_reason, numerical_methods_version, dilution_factor,
        norm_method, norm_band, norm_target, norm_ref_nm,
        norm_applied, norm_reason, norm_divisor = round(norm_divisor, 6),
        `Native-fit normalization applied` = .decon_native_norm_applied,
        `Native-fit normalization reason` = .decon_native_norm_reason,
        `Native-fit normalization divisor` = .decon_native_norm_divisor,
        `Effective range lo (nm)` = round(eff_range_lo, 1),
        `Effective range hi (nm)` = round(eff_range_hi, 1),
        `Max native gap (nm)`     = round(max_native_gap_nm, 2),
        `Unmeasured in range (nm)`= round(unmeasured_nm, 1),
        `Processed finite support (nm)` = processed_support_nm,
        `Band processed finite support (nm)` = band_processed_support_nm,
        analysis_from, analysis_to
      ) %>%
      left_join(ratios, by = c("Sample" = "sample")) %>%
      left_join(od_peaks, by = c("Sample" = "sample")) %>%
      rename_pbs_cols() %>%
      arrange(Sample, Band)
  })

  # metrics_export_df: returns a flat data frame for export, honoring all 5
  # layout values.  v3/v4 reuse the v1/v2 by-band flat table (lossless) rather
  # than the split multi-table display — this keeps exports simple and complete.
  metrics_export_df <- function(layout = "stacked") {
    df <- metrics_df()
    byband_export <- function(d) {
      bands_list <- unique(d$Band)
      dfs <- lapply(bands_list, function(b) {
        sub <- d[d$Band == b, , drop = FALSE]
        sub <- sub[, setdiff(names(sub), "Band"), drop = FALSE]
        cbind(Band = b, sub)
      })
      do.call(rbind, dfs)
    }
    if (layout %in% c("v1", "v2")) {
      byband_export(df)
    } else if (layout %in% c("v3", "v4")) {
      # v3/v4 on-screen splits into per-band + summary tables; export uses the
      # same by-band flat layout as v1/v2 (lossless — all columns preserved).
      byband_export(df)
    } else {
      # stacked (default) or any unrecognized value
      df
    }
  }

  ts <- function() format(Sys.time(), "%Y%m%d_%H%M%S")

  .effective_dl_fmt <- function(fmt){ if (identical(fmt, "xlsx") && !isTRUE(has_writexl)) "csv" else fmt }

