  # A short legend explaining the QC wording (so "reference", residual, etc. are
  # self-documenting in the exported file).
  pad_to_qc_cols <- function(short_df, full_names){
    for (cn in setdiff(full_names, names(short_df))) short_df[[cn]] <- NA
    short_df[full_names]
  }

  qc_legend_df <- function(){
    data.frame(
      Sample = c("# LEGEND",
                 "# scope",
                 "# baseline residual",
                 "# residual interpretation",
                 "# not evaluated",
                 "# saturation",
                 "# duplicate"),
      Status = rep("", 7),
      Issues = c(
        "Explanations of the terms used in the Issues column above.",
        "Per-sample QC inventories all loaded columns. Analysis-dependent diagnostics are evaluated only for selected samples; raw-file checks and high-correlation candidate screening use all loaded columns.",
        "Mean native-coordinate, baseline-corrected value within the exact per-row archived bounds. The export records anchor, bounds, point count, statistic, source scope, and residual-specific class.",
        "A signed residual mean outside tolerance is a numerical review flag only. Its direction and magnitude do not identify a cause; review the full spectrum, provenance, blanks, and controls.",
        "Not evaluated (not selected or processing unavailable) is distinct from No configured flags and is never counted as a pass.",
        "A raw reading at/above the configured high-signal/saturation-risk threshold. This is a review prompt; detector nonlinearity requires instrument- and method-specific calibration.",
        "A high ordinary-Pearson-correlation candidate requiring provenance review. Correlation and fitted slope do not establish duplicate identity."
      ),
      stringsAsFactors = FALSE
    )
  }
  output$dl_qc_csv <- downloadHandler(
    filename = function() paste0("PASA_qc_", ts(), ".", fmt_ext(.effective_dl_fmt(input$dl_data_fmt %||% "csv"))),
    content  = function(file){
      fmt <- .effective_dl_fmt(input$dl_data_fmt %||% "csv")
      tryCatch({
        req(qc())
        q <- qc()
        axis <- attr(q, "axis_issues")
        df <- as.data.frame(q)
 # join exact per-sample noise denominator/axis metadata into the
        # same durable QC report users already download.
        nd <- tryCatch(noise_export_df(), error = function(e) NULL)
        if (is.data.frame(nd) && nrow(nd)) df <- dplyr::left_join(df, nd, by = "Sample")
        # Append axis-level notes and the term legend as extra rows.
        if (length(axis) > 0)
          df <- rbind(df, pad_to_qc_cols(data.frame(Sample = "# Axis-level issues", Status = "",
                                     Issues = paste(axis, collapse = "; "),
                                     stringsAsFactors = FALSE), names(df)))
        leg <- pad_to_qc_cols(qc_legend_df(), names(df))
        df  <- rbind(df, leg)
        write_table_fmt(df, file, fmt)
      }, error = function(e) write_export_error(file, fmt, e))
    }
  )

  save_plot <- function(file, plot_obj, fmt, strict = FALSE, width = 11, height = 6.5) {
    tryCatch({
      force(plot_obj)
      if (is.null(plot_obj)) stop("No plot is available for the current settings.",call.=FALSE)
      is_cuvette_scene <- inherits(plot_obj,"ggplot") && any(vapply(plot_obj$layers,
        function(layer)inherits(layer$geom,"GeomPasaCuvetteRaster"),logical(1)))
      plot_obj_light <- if(is_cuvette_scene)plot_obj else plot_obj+theme_light_override+.preserve_blank_axes(plot_obj)
      if(identical(fmt,"pdf")&&!isTRUE(capabilities("cairo")))
        stop("PDF export requires Cairo graphics support; use PNG instead.",call.=FALSE)
      ggplot2::ggsave(filename=file,plot=plot_obj_light,
        device=if(identical(fmt,"pdf"))grDevices::cairo_pdf else fmt,
        width=width,height=height,dpi=300,units="in",bg=if(is_cuvette_scene)NULL else "white")
      invisible(TRUE)
    },error=function(e) {
      if(isTRUE(strict))stop(e)
      msg <- conditionMessage(e)
      if(!nzchar(msg))msg <- "No valid plot is available. Review the current settings and result status."
      showNotification(paste("Plot export failed:",msg),type="error",duration=10,session=session)
      tryCatch({
        if(identical(fmt,"pdf")) .pasa_open_pdf(file,width=width,height=height)
        else grDevices::png(file,width=1100,height=650,res=100)
        on.exit(grDevices::dev.off(),add=TRUE)
        grid::grid.newpage()
        grid::grid.text("PASA — EXPORT FAILED",y=.7,gp=grid::gpar(fontsize=18,fontface="bold"))
        grid::grid.text(paste(strwrap(msg,90),collapse="\n"),y=.45,gp=grid::gpar(fontsize=12))
      },error=function(second)stop(msg,call.=FALSE))
      invisible(FALSE)
    })
  }
