  # Download everything as a single ZIP. zip::zipr is cross-platform and avoids
  # relying on an external zip/Rtools executable.
  output$dl_all_zip <- downloadHandler(
    filename = function() paste0("PASA_bundle_", ts(), if (isTRUE(has_zip)) ".zip" else ".txt"),
    content  = function(file){
      if (!isTRUE(has_zip)) {
        writeLines(c(
          "PASA bundle export unavailable.",
          "",
          "The optional R package 'zip' is not installed, so a ZIP archive cannot be",
          "created. Install it with:",
          "    install.packages('zip')",
          "",
          "In the meantime, use the individual download buttons (processed data, QC,",
          "metrics, plots, session state) -- none of those require the 'zip' package."), file)
        return(invisible())
      }
      tryCatch({
        .zip_stage <- "initialization"
        # Read download-context inputs by exact name and reject reactive/function
        # objects.  This prevents a missing optional control from being partially
        # matched to a closure in a download request while preserving the documented
        # default for that control.
        .zip_input <- function(id, default = NULL) {
          value <- tryCatch(shiny::isolate(input[[id]]), error = function(e) NULL)
          if (is.null(value) || is.function(value) || is.environment(value) ||
              is.symbol(value) || is.language(value)) default else value
        }
 fmt <- "png" # the sidebar plot-format selector was removed; the ZIP bundles PNGs
        dfmt  <- .effective_dl_fmt(.zip_input("dl_data_fmt", "csv"))
        dext  <- fmt_ext(dfmt)
        stamp <- ts()
        tmp   <- tempfile(pattern = paste0("bundle_", stamp, "_"))
        dir.create(tmp, showWarnings = FALSE, recursive = TRUE)
        on.exit(unlink(tmp, recursive = TRUE, force = TRUE), add = TRUE)

        paths <- c()
        manifest <- list()
        .mrec <- function(name, status, reason = "", bytes = NA_real_, sha256 = NA_character_) {
          manifest[[length(manifest) + 1L]] <<-
            data.frame(member = name, status = status, reason = reason,
                       bytes = bytes, sha256 = sha256, stringsAsFactors = FALSE)
        }
        # Record an INCLUDED physical member with its on-disk byte count AND SHA-256, computed the moment
        # it is added (the content identity the post-archive re-extraction verifies against).
        .mrec_incl <- function(name, path) {
          sz  <- tryCatch(as.numeric(file.info(path)$size), error = function(e) NA_real_)
          sha <- tryCatch(.pasa_sha256_file(path),          error = function(e) NA_character_)
          .mrec(name, "included", "", sz, sha)
        }
        add_tbl <- function(name, df) {
          member <- paste0(name, ".", dext)
          .ri <- match(member, required_registry$member)
          if (!is.na(.ri) && !isTRUE(required_registry$applicable[.ri])) {
            .mrec(member, "not_applicable", required_registry$description[.ri]); return(invisible())
          }
          if (is.null(df) || !is.data.frame(df)) { .mrec(member, "skipped", "no data"); return(invisible()) }
          p <- file.path(tmp, member)
          tryCatch({ write_table_fmt(df, p, dfmt); paths <<- c(paths, p); .mrec_incl(member, p) },
                   error = function(e) .mrec(member, "FAILED", conditionMessage(e)))
        }
        add_plot <- function(name, obj) {
          member <- paste0(name, ".", fmt)
          .ri <- match(member, required_registry$member)
          if (!is.na(.ri) && !isTRUE(required_registry$applicable[.ri])) {
            .mrec(member, "not_applicable", required_registry$description[.ri]); return(invisible())
          }
          if (is.null(obj)) { .mrec(member, "skipped", "not generated"); return(invisible()) }
          p <- file.path(tmp, member)
          tryCatch({ save_plot(p, obj, fmt, strict = TRUE); paths <<- c(paths, p); .mrec_incl(member, p) },
                   error = function(e) .mrec(member, "FAILED", conditionMessage(e)))
        }
        add_text <- function(name, txt) {
          member <- paste0(name, ".txt")
          .ri <- match(member, required_registry$member)
          if (!is.na(.ri) && !isTRUE(required_registry$applicable[.ri])) {
            .mrec(member, "not_applicable", required_registry$description[.ri]); return(invisible())
          }
          if (is.null(txt) || !length(txt)) { .mrec(member, "skipped", "empty"); return(invisible()) }
          p <- file.path(tmp, member)
          tryCatch({ writeLines(txt, p); paths <<- c(paths, p); .mrec_incl(member, p) },
                   error = function(e) .mrec(member, "FAILED", conditionMessage(e)))
        }
        add_member_file <- function(path) {
          if (file.exists(path) && !(path %in% paths)) { paths <<- c(paths, path); .mrec_incl(basename(path), path); TRUE }
          else FALSE
        }
        add_member_skip <- function(name, reason) .mrec(name, "skipped", reason)
        add_member_fail <- function(name, reason) .mrec(name, "FAILED", reason)

        # Freeze the analysis-state predicates once for this request.  The same
        # objects drive both applicability and member generation, preventing a
        # toggle/reactive race from changing the contract halfway through an
        # archive build.
        .zip_stage <- "freeze application state"
        .zip_res   <- results()  # validation refuses export of stale/invalid settings
        .zip_qc <- qc()
        .zip_qc_chart <- build_qc_chart(.zip_qc, dark = FALSE)
        .zip_noise_chart <- tryCatch(noise_plot_export(),error=function(e)NULL)
        .zip_color_grid <- if(isTRUE(rv_cuv_show_all()))tryCatch(all_cuv_grid_obj(),error=function(e)NULL) else NULL
        .zip_failures <- .pasa_processing_failures(.zip_res)
        .zip_gr    <- tryCatch(growth_result(), error = function(e) NULL)
        .zip_decon <- tryCatch(decon_fit(), error = function(e) NULL)
        .zip_blank <- tryCatch(decon_blank_df(), error = function(e) NULL)
        .zip_color <- tryCatch(cuv_color_info(), error = function(e) NULL)
        .zip_peak  <- tryCatch(peak_points(), error = function(e) NULL)
        .zip_norm  <- tryCatch(isTRUE(norm_active()), error = function(e) FALSE)
        # The same safety/consent policy applies to interactive and ZIP work.
        .zip_sim_eval <- tryCatch({
          key <- .sim_key_serialize(split(.zip_res,.zip_res$sample),FALSE)
          block <- .sim_budget_check(.zip_res,cap=.sim_budget_cap(.zip_input("sim_pair_budget",2)),
            override=identical(sim_override_key(),key))
          if(!is.null(block)) list(value=NULL,error=NULL,skipped=.sim_budget_text(block)) else {
            cached <- isTRUE(sim_engine_cache$has_value)&&identical(sim_engine_cache$key,key)
            list(value=if(cached)sim_engine_cache$value_box[[1L]] else compute_similarity(.zip_res,norm_active=.zip_norm),error=NULL,skipped=NULL)
          }
        },error=function(e)list(value=NULL,error=conditionMessage(e),skipped=NULL))
        .zip_sim <- .zip_sim_eval$value
        .zip_sim_settings <- list(
          metric = as.character(.zip_input("sim_metric", "sam"))[1],
          layout = as.character(.zip_input("sim_layout", "bubble"))[1],
          show_node_names = isTRUE(.zip_input("sim_show_node_names", FALSE)),
          show_edge_values = isTRUE(.zip_input("sim_show_edge_values", FALSE)),
          edge_range = suppressWarnings(as.numeric(.zip_input("sim_edge_range", numeric(0)))))
        .zip_sim_payload_eval <- tryCatch(
          list(value = .sim_edge_payload(.zip_sim, .zip_sim_settings$metric), error = NULL),
          error = function(e) list(value = NULL, error = conditionMessage(e)))
        .zip_sim_payload <- .zip_sim_payload_eval$value
        .zip_sim_raw_edges <- !is.null(.zip_sim_payload) &&
          !is.null(.zip_sim_payload$edges) && NROW(.zip_sim_payload$edges) > 0L
        # Applicability follows the frozen, post-filter view. If that view itself
        # errors despite available packages and raw edges, fail closed by treating
        # the network member as applicable.
        .zip_sim_view_eval <- if (!.zip_sim_raw_edges) {
          list(value = NULL, error = NULL)
        } else tryCatch(
          list(value = .sim_network_edge_view(
            .zip_sim_payload$edges,
            edge_range = .zip_sim_settings$edge_range,
            tier_filter = "all", edge_limit = NULL), error = NULL),
          error = function(e) list(value = NULL, error = conditionMessage(e)))
        .zip_sim_view_edges <- !is.null(.zip_sim_view_eval$value) &&
          !is.null(.zip_sim_view_eval$value$edges) &&
          NROW(.zip_sim_view_eval$value$edges) > 0L
        .zip_sim_network_applicable <- isTRUE(has_igraph && has_ggraph) &&
          .zip_sim_raw_edges &&
          (.zip_sim_view_edges || !is.null(.zip_sim_view_eval$error))
        .zip_growth_candidates <- tryCatch({
          if (is.null(.zip_gr) || !isTRUE(.zip_gr$ok) || is.null(.zip_gr$per_rep)) NULL else
            do.call(rbind, lapply(names(.zip_gr$per_rep), function(nm) {
              cc <- .zip_gr$per_rep[[nm]]$candidates
              if (is.null(cc) || !NROW(cc)) return(NULL)
              cbind(Replicate = nm, cc)
            }))
        }, error = function(e) NULL)
        .zip_state <- list(
          norm = .zip_norm,
          qc_chart = !is.null(.zip_qc_chart),
          noise_chart = !is.null(.zip_noise_chart),
          processing_failures = NROW(.zip_failures) > 0L,
          spectra_3d = isTRUE(.zip_input("spectra_3d", FALSE)),
          probe = isTRUE(.zip_input("show_probe_line", FALSE)) && isTruthy(.zip_input("probe_nm")),
          peaks = !is.null(.zip_peak) && NROW(.zip_peak) > 0L,
          auc = isTRUE(input$apply_baseline) && !is.null(.zip_res) && NROW(.zip_res) > 0L,
          similarity = is.null(.zip_sim_eval$skipped) && !is.null(.zip_res) && length(unique(as.character(.zip_res$sample))) >= 2L,
          similarity_network = .zip_sim_network_applicable,
          color = is.list(.zip_color) && identical(.zip_color$status, "available"),
          color_grid = is.list(.zip_color_grid) && !is.null(.zip_color_grid$plot),
          growth = !is.null(.zip_gr),
          growth_bestfit = !is.null(.zip_gr) && isTRUE(.zip_gr$ok) &&
            !is.null(.zip_gr$best_each) && NROW(.zip_gr$best_each) > 0L,
          growth_candidates = !is.null(.zip_growth_candidates) && NROW(.zip_growth_candidates) > 0L,
          growth_phases = !is.null(.zip_gr) && !is.null(.zip_gr$phases) && NROW(.zip_gr$phases) > 0L,
          decon = !is.null(.zip_decon) && !inherits(.zip_decon, "decon_error"),
          decon_bootstrap_summary = !is.null(.zip_decon) && !is.null(.decon_bootstrap_summary_df(.zip_decon)),
          decon_bootstrap_draws = !is.null(.zip_decon) && !is.null(.decon_bootstrap_draws_df(.zip_decon)),
          decon_blank = !is.null(.zip_blank) && is.data.frame(.zip_blank) && NROW(.zip_blank) > 0L
        )
        required_registry <- .pasa_complete_zip_registry(.zip_state, data_ext = dext, plot_ext = fmt)

        # The format contract is explicit: one lossless tabular representation
        # per table, PNG per raster plot, plain text for narrative/provenance,
        # plus the full state file. PDF/XLSX presentation duplicates are offered
        # separately but carry no distinct analysis fields and are not duplicated
        # here.  Every distinct field is represented by a required member below.
        .zip_stage <- "write export contract"
        add_text("README_COMPLETE_EXPORT", c(
          "PASA complete export contract (schema PASA-COMPLETE-ZIP-1)",
          "",
          "This archive is complete for the application state recorded in complete_export_contract.csv.",
          paste0("Tables use .", dext, "; plots use .", fmt, "; narrative/provenance uses .txt."),
          "PDF/XLSX presentation variants available from individual buttons are not duplicated when they contain no distinct analysis fields.",
          "The interactive 3D view is preserved as long-form coordinates plus its exact view settings.",
          "manifest.csv records the byte count and SHA-256 of every included member.",
          "A missing or failed required member prevents this normal archive from being delivered."
        ))
        .contract_path <- file.path(tmp, "complete_export_contract.csv")
        .contract_ok <- tryCatch({
          utils::write.csv(required_registry, .contract_path, row.names = FALSE, na = "")
          file.exists(.contract_path) && is.finite(file.info(.contract_path)$size) && file.info(.contract_path)$size > 0
        }, error = function(e) FALSE)
        if (isTRUE(.contract_ok)) add_member_file(.contract_path)
        else add_member_fail("complete_export_contract.csv", "required-member registry could not be written")

        .zip_stage <- "write data tables"
        # Data tables (wide pre/post + metrics), in the chosen data format.
        add_tbl("processed_pre-norm", processed_wide("pre"))
        if (norm_active()) add_tbl("processed_post-norm", processed_wide("post"))
        add_tbl("metrics", rename_pbs_cols(metrics_df()))

        .zip_stage <- "write spectra outputs"
        # ---- Spectra plot (always generated) ----
        add_plot("PASA_spectra_plot", .spectra_plot_impl(FALSE))

        # Durable equivalent of the interactive WebGL 3D view. Browser camera
        # pixels are not a stable scientific artifact; the exact decimated
        # coordinates and view/probe settings are portable and reconstructable.
        if (isTRUE(.zip_state$spectra_3d)) {
          .crv3 <- tryCatch(as.data.frame(curves()), error = function(e) NULL)
          .res3 <- suppressWarnings(as.integer(input$spectra_3d_res %||% 150L))
          if (!is.finite(.res3)) .res3 <- 150L
          .res3 <- max(20L, .res3)
          .s3 <- if (is.null(.crv3) || !nrow(.crv3)) NULL else {
            .ss <- sort(unique(as.character(.crv3$sample)))
            do.call(rbind, lapply(seq_along(.ss), function(.i) {
              .d <- .crv3[as.character(.crv3$sample) == .ss[.i], , drop = FALSE]
              .d <- .d[order(.d$nm), , drop = FALSE]
              .ok <- is.finite(.d$nm) & is.finite(.d$val_smooth)
              .d <- .d[.ok, , drop = FALSE]
              if (!nrow(.d)) return(NULL)
              if (nrow(.d) > .res3) .d <- .d[unique(round(seq(1, nrow(.d), length.out = .res3))), , drop = FALSE]
              data.frame(Sample = .ss[.i], DepthIndex = .i,
                         WavelengthNm = as.numeric(.d$nm),
                         Absorbance = as.numeric(.d$val_smooth),
                         stringsAsFactors = FALSE)
            }))
          }
          if(is.null(.s3)) .s3 <- data.frame(Sample=character(),DepthIndex=integer(),WavelengthNm=numeric(),Absorbance=numeric())
          add_tbl("spectra_3d_coordinates", .s3)
          add_text("spectra_3d_settings", c(
            "representation=durable_coordinates_equivalent_to_interactive_view",
            paste0("points_per_curve_cap=", .res3),
            paste0("ridge_opacity=", sprintf("%.17g", as.numeric(input$spectra_3d_opacity %||% 0.6))),
            paste0("probe_enabled=", isTRUE(input$show_probe_line) && isTruthy(input$probe_nm)),
            paste0("probe_nm=", if (isTruthy(input$probe_nm)) sprintf("%.17g", as.numeric(input$probe_nm)) else "NA"),
            paste0("probe_color=", as.character(input$probe_color %||% "auto")),
            paste0("probe_opacity=", sprintf("%.17g", as.numeric(input$spectra_3d_probe_opacity %||% 0.25))),
            paste0("label_distance_pixels=", sprintf("%.17g", as.numeric(input$spectra_3d_label_dist %||% 40))),
            "camera_eye_x=1.9", "camera_eye_y=-1.7", "camera_eye_z=0.9",
            "aspect_ratio_x=1.7", "aspect_ratio_y=1.1", "aspect_ratio_z=0.7"
          ))
        }

        if (isTRUE(.zip_state$probe))
          add_tbl("probe_values", tryCatch(as.data.frame(probe_export_df()), error = function(e) NULL))
        if (isTRUE(.zip_state$peaks))
          add_tbl("peak_values", tryCatch(as.data.frame(peaks_export_df()), error = function(e) NULL))

        # ---- Band AUC: bundle both bar and radar charts ----
        auc_ready <- isTRUE(input$apply_baseline) && isTruthy(tryCatch(results(), error = function(e) NULL))
        if (auc_ready) {
          res_auc <- results(); bands_auc <- bands_react()
          add_plot("band_auc_bar",
                   make_auc_plot(res_auc, bands_auc, chart_type = "bar",
                                 palette = input$palette %||% "okabe",
                                 auc_common_y = isTRUE(input$auc_common_y),
                                 auc_ov = isTRUE(input$auc_overlay), dark = FALSE))
          add_plot("band_auc_radar",
                   make_auc_plot(res_auc, bands_auc, chart_type = "radar",
                                 palette = input$palette %||% "okabe",
                                 auc_common_y = isTRUE(input$auc_common_y),
                                 auc_ov = isTRUE(input$auc_overlay), dark = FALSE,
                                 color_map = sample_color_map()))
        }

        .zip_stage <- "write quality and similarity outputs"
        # ---- Data Quality: complete tables are export-authorized independently
        # of which Data Quality subview/toggle is currently visible. ----
        if (isTRUE(.zip_state$qc_chart)) add_plot("data_quality_qc_chart", .zip_qc_chart + theme_bg(FALSE))
        if (isTRUE(.zip_state$processing_failures)) add_tbl("processing_failures", .zip_failures)
        add_plot("spectral_noise_chart", .zip_noise_chart)
        if(is.null(.zip_noise_chart)) add_text("spectral_noise_chart__skipped","No selected sample has an evaluable noise composite. See spectral_noise_metrics for per-sample reasons.")
        add_tbl("spectral_noise_metrics", tryCatch(noise_export_df(), error = function(e) NULL))
        add_tbl("spectral_noise_intervals", tryCatch(noise_intervals_export_df(), error = function(e) NULL))
        add_tbl("spectral_noise_components", tryCatch(noise_components_export_df(), error = function(e) NULL))
        add_tbl("spectral_noise_thresholds", tryCatch(noise_thresholds_export_df(), error = function(e) NULL))
        add_tbl("sample_similarity", .zip_sim)
        if(!is.null(.zip_sim_eval$skipped)) add_text("sample_similarity__skipped",.zip_sim_eval$skipped)
        # Sample-similarity static network (igraph+ggraph) when available.
        # Writes either the PNG (with an opaque white background per spec — the
        # transparent variant is reserved for the on-screen view inside the app)
        # or a small __skipped.txt explaining why no PNG was produced.
        sim_skip_reason <- NULL
        if (!isTRUE(.zip_state$similarity_network)) {
          sim_skip_reason <- if (!(has_igraph && has_ggraph)) paste0(
              "Sample similarity network is not available in this export because the\n",
              "required R packages are not installed:\n",
              if (!has_igraph) "  - igraph (missing)\n" else "  - igraph (ok)\n",
              if (!has_ggraph) "  - ggraph (missing)\n" else "  - ggraph (ok)\n")
            else if (!is.null(.zip_sim_eval$skipped)) .zip_sim_eval$skipped
            else if (!is.null(.zip_sim_eval$error))
              paste0("Sample similarity computation failed: ", .zip_sim_eval$error, "\n")
            else if (!is.null(.zip_sim_payload_eval$error))
              paste0("Sample similarity edge construction failed: ", .zip_sim_payload_eval$error, "\n")
            else if (!.zip_sim_raw_edges)
              "Sample similarity network was skipped because no pairwise edges were available.\n"
            else
              "Sample similarity network was skipped because the frozen display filter hides every edge.\n"
        } else {
          # The download click is its own explicit authorization reason. Source the
          # COMPLETE result from sim_engine() directly; similarity_edges_react()
          # intentionally inherits the active-view gate and must never feed an export.
          d_sim <- .zip_sim_payload
          if (is.null(d_sim) || is.null(d_sim$edges) || nrow(d_sim$edges) == 0) {
            sim_skip_reason <- paste0(
              "Sample similarity network was skipped because no edges were available\n",
              "at export time. Common reasons:\n",
              "  - Fewer than two samples are selected.\n",
              "  - The similarity-strength threshold filters out every pair.\n",
              "  - The similarity edge-thickness range slider hides every edge.\n")
          } else {
            edge_rng <- .zip_sim_settings$edge_range
            # ZIP exports have a white background, so force dark=FALSE to keep
            # labels legible on the white PNG.
            sim_build_error <- NULL
            p_sim <- tryCatch(
              build_similarity_ggraph(d_sim$edges, d_sim$nodes, d_sim$metric,
                layout = .zip_sim_settings$layout, dark = FALSE,
                node_color_map = tryCatch(sample_color_map(), error = function(e) NULL),
                show_node_names = .zip_sim_settings$show_node_names,
                show_edge_values = .zip_sim_settings$show_edge_values,
                edge_range = edge_rng, edge_limit = NULL),
              error = function(e) { sim_build_error <<- conditionMessage(e); NULL })
            if (is.null(p_sim)) {
              add_member_fail(paste0("data_quality_similarity_network.", fmt),
                              paste0("network build failed: ",
                                     sim_build_error %||% "builder returned no plot object"))
            } else {
              p_path <- file.path(tmp, paste0("data_quality_similarity_network.", fmt))
              sim_write_error <- NULL
              ok <- tryCatch({
                # White (not transparent) background per spec — every plot in the ZIP
                # must be opaque so text/labels stay legible on a white viewer.
                ggplot2::ggsave(filename = p_path, plot = p_sim, device = fmt,
                                width = 11, height = 6.5, dpi = 300, units = "in",
                                bg = "white")
                TRUE
              }, error = function(e) { sim_write_error <<- conditionMessage(e); FALSE })
              if (isTRUE(ok) && add_member_file(p_path)) invisible(TRUE)
              else add_member_fail(paste0("data_quality_similarity_network.", fmt),
                                   paste0("network image export failed: ",
                                          sim_write_error %||% "written file could not enter the archive ledger"))
            }
          }
        }
        if (!is.null(sim_skip_reason)) {
          sp_path <- file.path(tmp, "data_quality_similarity_network__skipped.txt")
          .note_written <- isTRUE(tryCatch({ writeLines(sim_skip_reason, sp_path); TRUE },
                                           error = function(e) FALSE))
          if (!.note_written || !add_member_file(sp_path))
            add_member_fail("data_quality_similarity_network__skipped.txt",
                            "similarity availability note could not be written")
        }
        {
          qd <- as.data.frame(qc())
          axis <- attr(qc(), "axis_issues")
          if (length(axis) > 0)
            qd <- rbind(qd, pad_to_qc_cols(data.frame(Sample = "# Axis-level issues", Status = "",
                                       Issues = paste(axis, collapse = "; "),
                                       stringsAsFactors = FALSE), names(qd)))
          qd <- rbind(qd, pad_to_qc_cols(qc_legend_df(), names(qd)))
          add_tbl("qc_report", qd)
        }

        .zip_stage <- "write sample-color outputs"
        # ---- Sample Color cuvette image (only if generated) ----
        # Cuvette plot exported with axes/ticks stripped (the spurious -10..10 / 0..40
        # numerals belong to the drawing-space coordinates, not real measurements).
        add_plot("sample_color_cuvette",
                 tryCatch({
                   pcu <- cuvette_plot_obj()
                   if (!is.null(pcu))
                     pcu + ggplot2::theme(axis.text  = ggplot2::element_blank(),
                                          axis.title = ggplot2::element_blank(),
                                          axis.ticks = ggplot2::element_blank())
                   else NULL
                 }, error = function(e) NULL))

        tryCatch({
          .cinfo <- cuv_color_info()
          if (!is.null(.cinfo) && identical(.cinfo$status, "available")) {
            .fmt_meta <- function(x) if (length(x) == 1L && is.finite(x))
              formatC(x, digits = 12, format = "fg") else "NA"
            add_text("sample_color_identity",
                     sprintf(paste0("sample=%s\neffective_analysis_od_object_hash=%s\nhash_algo=%s\n",
                                    "identity_source=pipeline (.effective_od_hash)\nrequested_target=%s\n",
                                    "effective_target=%s\ncolor_conf=%s\nlow_signal=%s\ncoverage_min_nm=%s\n",
                                    "coverage_max_nm=%s\nextrapolated_low_nm=%s\nextrapolated_high_nm=%s\n",
                                    "endpoint_policy=flat_hold_nearest_finite_endpoint_within_380_780_nm"),
                             as.character(.cinfo$sample %||% ""),
                             as.character(.cinfo$object_hash %||% "NA"),
                             as.character(.cinfo$object_hash_algo %||% "SHA-256"),
                             .fmt_meta(.cinfo$requested_target), .fmt_meta(.cinfo$effective_target),
                             .fmt_meta(.cinfo$color_conf), isTRUE(.cinfo$low_signal),
                             .fmt_meta(.cinfo$coverage_min_nm), .fmt_meta(.cinfo$coverage_max_nm),
                             .fmt_meta(.cinfo$extrapolated_low_nm), .fmt_meta(.cinfo$extrapolated_high_nm)))
          }
        }, error = function(e) NULL)

        # Durable per-sample color contract. Export all currently selected,
        # renderable items (or the single selected item as a fallback), including
        # requested/effective target, confidence and endpoint-extrapolation spans.
        add_tbl("sample_color_rendering_metadata", tryCatch({
          .acm <- all_cuv_colors()
          .items <- if (!is.null(.acm) && length(.acm$items)) .acm$items else {
            .ci <- cuv_color_info()
            if (!is.null(.ci) && identical(.ci$status, "available")) list(.ci) else list()
          }
          .color_rendering_metadata_df(.items)
        }, error = function(e) NULL))

        # ---- Sample Color: all-samples grid (only when the toggle is on) ----
        # A patchwork object, so it is written with a direct ggsave (sized by the
        # grid's rows/cols) rather than through save_plot(), whose theme/axis
        # helpers assume a single ggplot.
        # Gate on the mirrored reactiveVal (rv_cuv_show_all), not the raw input:
        # in the download-request context the bare-checkbox input$cuv_show_all can
        # read stale/FALSE, whereas the observer-fed reactiveVal reflects the value
        # the user last set on the main reactive flow.
        if (isTRUE(.zip_state$color_grid)) {
          grid_info <- .zip_color_grid
          if (!is.null(grid_info) && is.list(grid_info) && !is.null(grid_info$plot)) {
            gp <- file.path(tmp, paste0("sample_colors_all_grid.", fmt))
            ncol_g <- max(1L, grid_info$ncol); nrow_g <- ceiling(max(1L, grid_info$n) / ncol_g)
            okg <- tryCatch({
              ggplot2::ggsave(gp, plot = grid_info$plot, device = fmt,
                              width  = min(22, 2.3 * ncol_g + 1),
                              height = min(26, min(22, 2.3 * ncol_g + 1) *
                                (nrow_g * 927 - 40) / (if (grid_info$n == 1L) 1774 else (400 + ncol_g * 430)) + 0.2),
                              dpi = 200, units = "in", bg = NULL, limitsize = FALSE)
              TRUE
            }, error = function(e) FALSE)
            if (isTRUE(okg)) add_member_file(gp)
            else add_member_fail(basename(gp), "color grid image export failed")
          }
        }

        .zip_stage <- "write deconvolution outputs"
        # ---- Deconvolution (Advanced Mode): fit overlay + full self-documenting
        # summary (context + input provenance + settings + results), but only when
        # a valid fit is currently shown. ----
        decon_fit_zip <- .zip_decon
        if (!is.null(decon_fit_zip) && !inherits(decon_fit_zip, "decon_error")) {
          add_plot("deconvolution_fit",
                   tryCatch(.decon_overlay_ggplot(decon_fit_zip,
                              show_scatter = !is.null(decon_fit_zip$scatter)),
                            error = function(e) NULL))
          add_plot("deconvolution_residuals",
                   tryCatch(.decon_resid_ggplot(decon_fit_zip), error = function(e) NULL))
          add_text("deconvolution_summary",
                   tryCatch({ t <- decon_export_text(); if (nzchar(t)) t else NULL },
                            error = function(e) NULL))
        }
        if (isTRUE(.zip_state$decon_bootstrap_summary))
          add_tbl("deconvolution_bootstrap_summary", .decon_bootstrap_summary_df(decon_fit_zip))
        if (isTRUE(.zip_state$decon_bootstrap_draws))
          add_tbl("deconvolution_bootstrap_draws", .decon_bootstrap_draws_df(decon_fit_zip))
        if (isTRUE(.zip_state$decon_blank)) {
          .bdx <- data.frame(WavelengthNm = as.numeric(.zip_blank$nm),
                             BlankOD = as.numeric(.zip_blank$val),
                             stringsAsFactors = FALSE)
          attr(.bdx, "source_name") <- attr(.zip_blank, "source_name", exact = TRUE)
          add_tbl("deconvolution_measured_blank", .bdx)
        }

        .zip_stage <- "write cell-growth outputs"
        # ---- Cell Growth: every distinct result, independent of display toggle ----
        gr <- .zip_gr
        if (!is.null(gr)) {
          add_plot("cell_growth_curve", tryCatch(growth_plot(gr, phase_alpha = if (isTruthy(input$growth_phase_alpha)) input$growth_phase_alpha else 1), error = function(e) NULL))
          add_text("cell_growth_interpretation",
                   tryCatch({ .gt <- growth_interpretation(gr)
                              if (is.null(.gt)) NULL else gsub(.GROWTH_DETAIL_SEP, "", .gt, fixed = TRUE) },
                            error = function(e) NULL))
          # Extraction provenance and the exact window-selection configuration
          # are durable for every growth result, including a no-fit result.
          add_tbl("cell_growth_observations",
                  tryCatch(.growth_observations_df(growth_long()), error = function(e) NULL))
          add_tbl("cell_growth_window_selection_contract",
                  tryCatch(.growth_window_contract_df(), error = function(e) NULL))
          add_tbl("cell_growth_summary", tryCatch(.growth_summary_df(gr), error = function(e) NULL))
          if (isTRUE(.zip_state$growth_bestfit))
            add_tbl("cell_growth_best_fit", tryCatch(as.data.frame(gr$best_each), error = function(e) NULL))
          if (isTRUE(.zip_state$growth_candidates))
            add_tbl("cell_growth_window_candidates", as.data.frame(.zip_growth_candidates))
          if (isTRUE(.zip_state$growth_phases))
            add_tbl("cell_growth_phases", tryCatch(as.data.frame(gr$phases), error = function(e) NULL))
        }

        .zip_stage <- "write reproducible snapshot"
        # COMPLETE ZIP always embeds a full reproducible snapshot.  The two
        # standalone snapshot checkboxes continue to control the standalone TXT
        # download only; allowing them to remove Settings/Data from a file called
        # "complete" made the archive state-dependent in an undocumented way.
        inc_set <- TRUE
        inc_data <- TRUE
        state_fname <- "PASA_state.txt"
        p_state <- file.path(tmp, state_fname)
        .state_build_ok <- TRUE
        state_txt <- tryCatch(
          build_state_text(include_settings = inc_set, include_data = inc_data),
          error = function(e) { .state_build_ok <<- FALSE; paste0(
            "# PASA state file \u2014 EXPORT FAILED\n",
            "# Reason: ", conditionMessage(e), "\n",
            "# Generated: ", format(Sys.time(), "%Y-%m-%d %H:%M:%S"), "\n",
            "# The settings/data could not be serialized. Please report this with the steps that triggered it.\n") })
        # Guarantee non-empty content even if build_state_text returned ""/NULL.
        if (is.null(state_txt) || !length(state_txt) ||
            (length(state_txt) == 1 && !nzchar(state_txt))) {
          state_txt <- paste0(
            "# PASA state file\n",
            "# Generated: ", format(Sys.time(), "%Y-%m-%d %H:%M:%S"), "\n",
            "# (No settings or data sections were available to serialize.)\n")
        }
        # This tryCatch block is evaluated directly in the content environment,
        # so ordinary local assignment must be used for `paths`; super-assignment
        # would skip the local value and create or update a stray copy in the
        # parent/global scope. Plain `<-` updates the content-local `paths`.
        .state_write_ok <- tryCatch({
          writeLines(state_txt, p_state)
          # Verify the file landed on disk before trusting it.
          if (!file.exists(p_state) || file.info(p_state)$size <= 0)
            stop("state file was not written to disk")
          TRUE
        }, error = function(e) {
          # Last-resort placeholder so the entry is ALWAYS in the ZIP.
          msg <- paste0(
            "# PASA state file \u2014 EXPORT FAILED\n",
            "# Reason: ", conditionMessage(e), "\n",
            "# Generated: ", format(Sys.time(), "%Y-%m-%d %H:%M:%S"), "\n")
          tryCatch(writeLines(msg, p_state), error = function(e2) NULL)
          FALSE
        })
        # The session state is physical and `included` only when the real state
        # both BUILT and WROTE. A serialization/write failure is a non-physical
        # FAILED row. Because PASA_state.txt is required, finalization then refuses
        # the normal archive and emits the truthful verified EXPORT_ERROR archive.
        .state_ok <- isTRUE(.state_build_ok) && isTRUE(.state_write_ok)
        if (.state_ok) {
          if (!add_member_file(p_state))
            add_member_fail(basename(p_state), "state file could not be added to the archive")
        } else {
          try(unlink(p_state, force = TRUE), silent = TRUE)   # never include the failure placeholder in the archive
          add_member_fail(basename(p_state),
                          paste0("session state export failed: ",
                                 if (!isTRUE(.state_build_ok)) "serialization error" else "file write error"))
        }
        # Run summary text
        add_text("summary", summary_text())

        # Non-applicable members are explicit, nonphysical manifest rows. A
        # failed applicable writer keeps its FAILED/skipped status and is refused.
        for (.ii in which(!required_registry$applicable)) {
          .member <- required_registry$member[.ii]
          manifest <- Filter(function(z) !identical(z$member, .member), manifest)
          .mrec(.member, "not_applicable", required_registry$description[.ii])
        }
        .zip_stage <- "finalize and reopen archive"
        mdf <- if (length(manifest)) do.call(rbind, manifest) else
               data.frame(member = character(0), status = character(0), reason = character(0),
                          bytes = numeric(0), sha256 = character(0), stringsAsFactors = FALSE)
        .pasa_zip_finalize(paths, mdf, file, tmp, required_registry = required_registry)
      }, error = function(e) {
        .pasa_zip_error_archive(paste0(.zip_stage %||% "unidentified stage", ": ", conditionMessage(e)), file,
                                .pasa_zip_default_zipr(), .pasa_zip_default_ziplist(), .pasa_zip_default_unzip())
      })
    },
    # The content type must match the body. downloadHandler() requires a scalar
    # character value here (unlike its reactive filename callback); passing a
    # function makes Shiny try to coerce a closure before content() can run.
    # With zip present the body is a verified ZIP, otherwise it is a plain-text
    # availability note under a .txt filename.
    contentType = if (isTRUE(has_zip)) "application/zip" else "text/plain"
  )

  # Reset bands
  observeEvent(input$reset_bands, {
    # Reset every band slider to its default window. The 3rd band (id pbs) is
    # always 600-650 regardless of its active label (PBS vs Chl a Qx); the
    # extra bands (chlb_qy, pe) reset too when present.
    updateSliderInput(session,"qy",  value=default_bands$qy)
    updateSliderInput(session,"pbs", value=c(600,650))
    updateSliderInput(session,"car", value=default_bands$car)
    updateSliderInput(session,"bx",  value=default_bands$bx)
    updateSliderInput(session,"chlb_qy", value=c(640,657))
    updateSliderInput(session,"pe",  value=c(490,570))
  })

  # Reset share_y when overlay is toggled (keep share_y unchecked when overlay changes)
  observeEvent(input$overlay, { updateCheckboxInput(session, "share_y", value = FALSE) })

  # When switching to radar chart type, default auc_overlay to TRUE.
  # User can still uncheck it manually after switching.
  observeEvent(input$auc_chart_type, {
    if (isTRUE(input$auc_chart_type == "radar"))
      updateCheckboxInput(session, "auc_overlay", value = TRUE)
  }, ignoreInit = TRUE)

  # Show orange notification when normalization is activated; remove when set back to none.
  observeEvent(input$norm_method, {
    if (isTruthy(input$norm_method) && input$norm_method != "none") {
      showNotification(
        HTML('<span style="color:var(--bs-warning-text-emphasis, #b45309);">Note: when normalization is active, it rescales each curve, so the dilution-correction effect is no longer visible in the Spectra graph. Dilution correction is still applied to the absorbance values reported in the Metrics tab (OD-at-peak, AUC).</span>'),
        type = "warning", duration = 8, id = "norm_dilute_note")
    } else {
      removeNotification("norm_dilute_note")
    }
  }, ignoreInit = TRUE)

  observeEvent(input$reset_all, {
    showModal(modalDialog(
      title = "Reset all fields?",
      "This clears the loaded data and every setting and selection, and cannot be undone.",
      footer = tagList(modalButton("Cancel"),
                       actionButton("reset_all_confirm", "Reset everything", class = "btn-danger")),
      easyClose = TRUE))
  })
  observeEvent(input$reset_all_confirm, { removeModal(); session$reload() })

  # ==========================================================================
  # Summary tab
  # ==========================================================================
  summary_text <- reactive({
    req(dat())
    df <- dat()
    nm_col <- names(df)[1]
    samp_cols <- setdiff(names(df), nm_col)
    nm_vec <- as.numeric(df[[nm_col]])
    nm_range <- range(nm_vec, na.rm = TRUE)
    meta <- detected_meta()
    n_pts <- length(nm_vec)
    n_samps <- length(samp_cols)
    sel_samps <- intersect(samp_cols, input$samples %||% character(0))

    fmt_setting <- function(id, label, val) {
      paste0("  - ", label, ": ", paste(val, collapse = ", "), .prov_tag(id))
    }

    .ns_rs <- if (!is.null(meta) && isTRUE(meta$ok)) suppressWarnings(as.numeric(meta$step)) else NA_real_
    .rs_st <- .eff_resample_state(input$resample_on, input$grid_step, input$analysis_nm, .ns_rs)
    .sm_st <- .eff_smooth_state(input, nm_vec)
    .bl_on <- isTRUE(input$apply_baseline)
    .bl_na <- if (.bl_on) "" else " — not applied (baseline correction is OFF)"

    lines <- c(
      "=== Run Summary ===",
      "",
      "--- Input received ---",
      paste0("  - Source: ", { ls_src <- tryCatch(loaded_source(), error=function(e) NULL)
        if (isTruthy(ls_src)) ls_src
        else if (isTRUE(demo_flag())) "Built-in synthetic demo dataset (no external file)"
        else if (isTruthy(input$file$name)) input$file$name else if (isTruthy(input$path)) .sanitize_url_provenance(input$path) else "(none)" }),
      paste0("  - Samples in file: ", n_samps),
      paste0("  - Selected samples: ", length(sel_samps)),
      paste0("  - Wavelength range in file: ", round(nm_range[1], 2), " - ", round(nm_range[2], 2), " nm"),
      paste0("  - Number of wavelength points: ", n_pts),
      {
        d <- diff(sort(nm_vec[is.finite(nm_vec)]))
        if (length(d) >= 1) {
          step_med <- stats::median(d, na.rm = TRUE)
          irregular <- (!is.null(meta) && isTRUE(meta$irregular)) ||
                       (stats::sd(d, na.rm = TRUE) > 0.01 * abs(step_med))
          # Exactly-regular grids print without the leading "~"; the tilde is kept
          # only when the spacing is approximate/irregular.
          regular_exact <- all(abs(d - d[1]) <= 1e-9)
          tilde <- if (regular_exact && !isTRUE(irregular)) "" else "~"
          paste0("  - Step (sampling interval): ", tilde, format(round(step_med, 3), trim = TRUE),
                 " nm", if (isTRUE(irregular)) " (irregular)" else "")
        } else NULL
      },
      if (!is.null(meta) && isTRUE(meta$irregular)) "  - WARNING: irregular wavelength spacing detected" else NULL,
      "",
      "--- Settings applied ---",
      paste0("  - Organism / pigment system: ", {
        org <- if (isTruthy(input$organism)) input$organism else "cyano"
        lbl <- switch(org, cyano="Cyanobacteria", red="Red algae",
                      green="Green algae", plants="Plants", org)
        paste0(lbl, .prov_tag("organism"))
      }),
      if (!identical(input$organism, "plants"))
        paste0("  - Sample type: ", switch(eff_sample_type(),
                                           cells   = "Cells / Lysate",
                                           iso_pbp = "Isolated phycobiliprotein",
                                           "Protein sample")) else NULL,
      fmt_setting("analysis_nm", "Analysis range (nm)", input$analysis_nm),
      paste0("  - Baseline correction: ", if (.bl_on) "ON" else "OFF (raw curve — no offset subtracted)"),
      paste0(fmt_setting("baseline_method", "Baseline method", input$baseline_method), .bl_na),
      if (identical(input$baseline_method, "single_nm"))
        paste0(fmt_setting("baseline_nm", "Baseline reference request (nm)", input$baseline_nm), .bl_na)
      else paste0(fmt_setting("baseline_win", "Baseline window request (nm)", input$baseline_win), .bl_na),
      if (.bl_on)
        "  - Effective baseline lookup: full loaded source (may use points outside the analysis range); single-nm uses the nearest eligible native measured node; window median requires at least 3 eligible native measured points. Per-sample effective node/window, point count, statistic, and outside-range use are in Metrics exports."
      else NULL,
      {
        # leaves the curve UNSMOOTHED (ma_smooth_reflect / sgolay_smooth_reflect pass through), and a window wider than the
        # grid is silently clipped, so echoing the method alone documented a smoothing step the pipeline did not perform.
        # Single source: the same .eff_smooth_state the Metrics subtitle and the AUC-basis disclosure banner consume.
        .sm_par <- if (identical(.sm_st$method, "sgolay")) paste0("n=", .sm_st$effective_n, ", p=", input$sg_p %||% NA)
                   else paste0("n=", .sm_st$effective_n)
        .sm_val <- if (!isTRUE(.sm_st$requested)) .sm_st$method
                   else if (!isTRUE(.sm_st$applied))
                     paste0(.sm_st$method, " — requested ",
                            if (is.finite(.sm_st$requested_n)) paste0("window n=", .sm_st$requested_n) else "window is blank/invalid",
                            ", too short for this range/grid (", .sm_st$L,
                            " analysis nodes); NOT applied — the analysis used the unsmoothed curve")
                   else if (isTRUE(.sm_st$clipped))
                     paste0(.sm_st$method, " (effective ", .sm_par, "; requested n=", .sm_st$requested_n,
                            ", clipped to the ", .sm_st$L, "-node analysis grid)")
                   else paste0(.sm_st$method, " (effective ", .sm_par, ")")
        fmt_setting("smooth", "Smoothing", .sm_val) },
      if (!isTRUE(input$resample_on) || isTRUE(.rs_st$applied))
        fmt_setting("resample_on", "Resample to fixed grid", input$resample_on)
      else paste0(fmt_setting("resample_on", "Resample to fixed grid", input$resample_on),
                  " — requested, but the grid step is blank/invalid, so NO resampling was performed (the analysis used the measured wavelengths)"),
      if (isTRUE(.rs_st$applied)) {
        if (isTRUE(.rs_st$clamped) || isTRUE(.rs_st$regridded))
          fmt_setting("grid_step", "Grid step (nm)",
                      paste0(format(.rs_st$effective_step, digits = 12), " realized (requested ",
                             format(.rs_st$requested_step, digits = 12),
                             if (isTRUE(.rs_st$clamped)) "; below the 1e-06 nm floor, clamped up"
                             else "; the analysis range is not an exact multiple of it", ")"))
        else fmt_setting("grid_step", "Grid step (nm)", input$grid_step)
      } else NULL,
      if (isTRUE(.rs_st$applied)) {
        mth_txt <- if (identical(.rs_st$method, "bin"))
          "integral-based bin averaging (down-sampling; conditional full-range area target; arbitrary band AUC may change at bin boundaries)" else
          "linear interpolation (up-sampling)"
        paste0("  - Resample method (auto): ", mth_txt)
      } else NULL,
      {
        # pipeline actually used (safe_dilution()) and that the Metrics subtitle shows -- NOT the raw input.
        # An invalid entry (0, negative, blank/NA) is coerced to 1 for the analysis, so this run-documenting
        # artifact must not print a correction factor that was never applied; an invalid raw entry is annotated
        # honestly. (build_state_text/snapshot keep the raw field, so a restore round-trips the literal entry.)
        .dil_applied <- safe_dilution()
        .dil_raw_num <- suppressWarnings(tryCatch(
          as.numeric(input$dilution %||% NA_real_),
          error = function(e) NA_real_))
        .dil_raw_valid <- length(.dil_raw_num) == 1L &&
          is.finite(.dil_raw_num) && .dil_raw_num > 0
        .dil_val <- if (!.dil_raw_valid) {
          .raw_show <- if (length(.dil_raw_num) == 1L && is.finite(.dil_raw_num))
            format(.dil_raw_num) else "blank/NA"
          paste0(.dil_applied, " (entered ", .raw_show, "; invalid, using ", .dil_applied, ")")
        } else format(.dil_applied)
        fmt_setting("dilution", "Global dilution correction factor", .dil_val)
      },
      {
        psd <- tryCatch(per_sample_dilution(), error = function(e) NULL)
        if (!is.null(psd) && length(psd))
          paste0("  - Individual dilution factors: ",
                 paste(sprintf("%s=%g", names(psd), unname(psd)), collapse = "; "))
        else NULL
      },
      {
        # sample is normalized in that state. Echoing the requested method here documented a normalization that never ran.
        # (norm_active() already carries the same apply_baseline guard, so the "Norm target" line below already disappears.)
        .nm_req <- input$norm_method %||% "none"
        .nm_val <- if (!.bl_on && !identical(.nm_req, "none"))
                     paste0("none — requested ", .nm_req,
                            if (isTruthy(input$norm_target)) paste0(" (target ", paste(input$norm_target, collapse = ", "), ")") else "",
                            ", NOT applied (normalization requires baseline correction)")
                   else .nm_req
        fmt_setting("norm_method", "Normalization method", .nm_val) },
      if (norm_active()) fmt_setting("norm_target", "Norm target", input$norm_target) else NULL,
      "",
      "--- Output generated ---",
      paste0("  - Tabs populated: Spectra, Band AUC, Metrics, Data Quality"),
      paste0("  - Post-norm columns shown: ", if (norm_active()) "yes" else "no"),
      paste0("  - Bands: ", paste(bands_react()$band, collapse = ", ")),
      paste0("  - Note: normalization rescales Spectra display; dilution correction is still applied to Metrics OD values."),
      "",
      .release_identity_lines()
    )
    paste(Filter(Negate(is.null), lines), collapse = "\n")
  })

  output$run_summary_ui <- renderUI({
    if (!isTruthy(tryCatch(dat(), error = function(e) NULL)))
      return(div(style = "margin-top:20px;font-style:italic;opacity:0.7;",
                 "Load data to see the run summary."))
    txt <- summary_text()
    pre(style = "white-space:pre-wrap;word-break:break-word;font-size:0.85em;", txt)
  })

  output$dl_summary_txt <- downloadHandler(
    filename = function() paste0("run_summary_", ts(), ".txt"),
    content  = function(file) {
      tryCatch({
        req(dat())
        writeLines(summary_text(), con = file, useBytes = FALSE)
      }, error = function(e) writeLines(paste("Export error:", conditionMessage(e)), file))
    }
  )

  # Session-snapshot download handlers \u2014 header Save session + Summary-tab mirror.
  # Both honor the synced (snapshot_include_settings, snapshot_include_data)
  # checkbox pair on the Analysis settings page; the *_summary handler reads the
  # mirror inputs which the bidirectional observer keeps in lock-step with that pair.
  .state_snapshot_filename <- function() paste0("PASA_state_", ts(), ".txt")
  .state_snapshot_content <- function(inc_set, inc_data, file) {
    tryCatch({
      writeLines(build_state_text(include_settings = isTRUE(inc_set),
                                   include_data     = isTRUE(inc_data)), file)
    }, error = function(e) {
      if(file.exists(file))unlink(file)
      showNotification(paste("Session snapshot failed:",conditionMessage(e)),type="error",duration=NULL,session=session)
      stop(e)
    })
  }
  output$dl_state_file <- downloadHandler(
    filename = .state_snapshot_filename,
    content  = function(file) {
      .state_snapshot_content(input$snapshot_include_settings,
                              input$snapshot_include_data, file)
    },
    contentType = "text/plain"
  )
  output$dl_state_file_summary <- downloadHandler(
    filename = .state_snapshot_filename,
    content  = function(file) {
      .state_snapshot_content(input$snapshot_include_settings_summary,
                              input$snapshot_include_data_summary, file)
    },
    contentType = "text/plain"
  )

  .sync_checkbox_pair(input, session,
                      "snapshot_include_settings", "snapshot_include_settings_summary")
  .sync_checkbox_pair(input, session,
                      "snapshot_include_data", "snapshot_include_data_summary")

  output$dl_summary_pdf <- downloadHandler(
    filename = function() paste0("run_summary_", ts(), ".pdf"),
    content  = function(file) {
      tryCatch({
        req(dat())
        txt <- summary_text()
        lines <- strsplit(txt, "\n", fixed = TRUE)[[1]]
        df_txt <- data.frame(Summary = lines, stringsAsFactors = FALSE)
        grid_table_pdf(df_txt, file = file, title = "PASA Run Summary",
                       subtitle = format(Sys.time(), "%Y-%m-%d %H:%M:%S"),
                       max_rows = 50, width = 11, height = 8.5)
      }, error = function(e) {
        grDevices::pdf(file)
        grid::grid.newpage()
        grid::grid.text(paste("PDF error:", conditionMessage(e)), x = 0.5, y = 0.5)
        grDevices::dev.off()
      })
    }
  )

  # ==========================================================================
  # Sample Color tab
  # ==========================================================================

  # Update cuv_sample choices when data loads OR the sample selection on the
  # Analysis settings page changes. Only samples ticked there are offered here (the
  # Sample Color tab should not render samples the user has excluded from the analysis).
  observeEvent(list(dat(), input$samples), {
    nm_col <- names(dat())[1]
    all_samps <- setdiff(names(dat()), nm_col)
    sel_side  <- if (is.null(input$samples)) all_samps else intersect(all_samps, input$samples)
    # Preserve the current choice if it is still selected on the Analysis settings page.
    cur  <- isolate(input$cuv_sample)
    keep <- if (length(sel_side)) { if (!is.null(cur) && cur %in% sel_side) cur else sel_side[1] } else character(0)
    updateSelectInput(session, "cuv_sample", choices = sel_side, selected = keep)
  })

  .cuv_effective_curve <- function(res, sname) {
    sid <- as.character(sname)
    # A LOOKUP failure is not a scientific state: it carries no provenance, so it asserts none.
    .typed <- function(reason, stage = "input") list(
      schema = .PASA_EFF_OD_SCHEMA, sample_key = sid, sample_id = sid,
      status = "unavailable", failed_stage = stage, stage = stage,
      reason_code = reason, reason = reason,
      requested = NULL, effective = NULL,
      wavelength_nm = NULL, effective_od = NULL, nm = NULL, A = NULL, od = NULL,
      dilution = list(value = NA_real_, origin = NA_character_),
      baseline = list(method = NA_character_, value = NA_real_, requested_nm = NA_real_,
                      requested_window = c(NA_real_, NA_real_), nm_used = NA_real_,
                      effective_window = c(NA_real_, NA_real_), point_count = NA_integer_,
                      statistic = NA_character_, used_outside_analysis = NA,
                      source_scope = NA_character_, refused = NA,
                      reason = NA_character_, eligible = NA),
      preprocessing = NULL,
      vector_hash = NA_character_, hash_algorithm = NA_character_,
      object_hash = NA_character_, object_hash_algo = NA_character_)
    if (is.null(res) || !nrow(res) || !"sample" %in% names(res)) return(.typed("no_result"))
    rr <- res[as.character(res$sample) == sid, , drop = FALSE]
    if (!nrow(rr)) return(.typed("sample_absent"))
    if (!".effective_analysis_od" %in% names(rr) || !length(rr$.effective_analysis_od))
      return(.typed("no_effective_object", "pipeline"))
    obj <- rr$.effective_analysis_od[[1]]
    if (!is.list(obj)) return(.typed("no_effective_object", "pipeline"))
    if (!identical(as.character(obj$schema %||% ""), .PASA_EFF_OD_SCHEMA))
      return(.typed("schema_mismatch", "pipeline"))
    # Recompute the canonical hash and compare. TRUE = verified; NA = a refused/unavailable object that legitimately
    # carries no identity; FALSE = tampered content, a hash that no longer matches, or a hash where none belongs.
    .ok <- .pasa_effective_od_verify(obj)
    if (!is.na(.ok) && !isTRUE(.ok)) return(.typed("integrity_failed", "pipeline"))
    # Tamper detection: a self-consistent object can still be stale with respect to the row it belongs to
    # (a field edited after the pipeline ran). The rebuild below is used ONLY as a comparator -- the accessor returns
    # the STORED object or a typed integrity state, NEVER the rebuilt one -- so no scientific state is authored here.
    .rebuilt <- tryCatch(.pasa_effective_od_build(rr, sid), error = function(e) NULL)
    if (is.null(.rebuilt)) return(.typed("integrity_failed", "pipeline"))
    if (!identical(as.character(.rebuilt$status), as.character(obj$status)) ||
        !identical(as.character(.rebuilt$object_hash %||% NA_character_),
                   as.character(obj$object_hash %||% NA_character_))) {
      # FAIL-SAFE on divergence. When the ROW now carries a typed refusal (or no usable curve) while the stored object
      # still says "available", the color REFUSES and names the stage the row refused at -- reading a typed FLAG, not
      # recomputing any transformation, and emitting NO vector and NO identity. Any other divergence (e.g. an edited
      # vector with both sides "available") is reported as a plain identity mismatch.
      if (!identical(as.character(.rebuilt$status), "available")) {
        .r <- .typed(as.character(.rebuilt$reason_code), as.character(.rebuilt$failed_stage %||% "pipeline"))
        .r$status    <- as.character(.rebuilt$status)
        .r$reason    <- as.character(.rebuilt$reason_code)
        .r$dilution  <- .rebuilt$dilution
        .r$baseline  <- .rebuilt$baseline
        .r$integrity <- "row_object_divergence"
        return(.r)
      }
      return(.typed("identity_mismatch", "pipeline"))
    }
    # The row-level scalar view must agree with the object it is a view OF.
    if (".effective_od_hash" %in% names(rr) && length(rr$.effective_od_hash)) {
      .colh <- as.character(rr$.effective_od_hash[[1]])
      .objh <- as.character(obj$object_hash %||% NA_character_)
      if (!identical(is.na(.colh), is.na(.objh)) || (!is.na(.colh) && !identical(.colh, .objh)))
        return(.typed("identity_mismatch", "pipeline"))
    }
    obj
  }
  # Verification depends on the numerical result, not the illustrative color controls.
  verified_cuvette_objects <- reactive({
    res <- tryCatch(results(), error = function(e) NULL)
    selected <- as.character(input$samples %||% character())
    if (!length(selected) && !is.null(res)) selected <- unique(as.character(res$sample))
    stats::setNames(lapply(selected, function(sample) .cuv_effective_curve(res, sample)), selected)
  })
  cuv_render_controls <- debounce(reactive(list(
    actual = isTRUE(input$cuv_actual_od), target = input$cuv_od,
    qy = input$qy, car = input$car)), 600)
  .cuv_target <- function(controls) {
    if (isTRUE(controls$actual)) return(NA_real_)
    target <- suppressWarnings(as.numeric(controls$target))
    validate(need(length(target) == 1L && is.finite(target) && target > 0,
      "Enter a finite positive color-rendering target, or choose unrescaled values."))
    target
  }
  cuv_color_info <- reactive({
    if (!isTRUE(input$is_pigmented == "yes")) return(NULL)
    if (!isTruthy(input$cuv_sample)) return(NULL)
    res <- tryCatch(results(), error = function(e) NULL)
    s   <- input$cuv_sample
    obj <- verified_cuvette_objects()[[s]]
    if (is.null(obj)) return(NULL)
    # REFUSAL PARITY: a refused/unavailable object renders NO color; carry the typed status + reason so
    # the warning panel explains WHY instead of silently blanking, and the plot/ZIP withhold the swatch.
    if (!identical(obj$status, "available")) {
      return(list(status = obj$status, reason = obj$reason, stage = obj$failed_stage %||% obj$stage, sample = s,
                  dilution = obj$dilution, baseline = obj$baseline,
                  object_hash = obj$object_hash, object_hash_algo = obj$object_hash_algo,
                  hex = NA_character_, fallback = FALSE, car_fallback = FALSE,
                  near_blank = FALSE, low_signal = FALSE, normalized = FALSE,
                  normalization_method = "none", snr = NA_real_, peak = NA_real_,
                  diag = NULL, od = NA_real_, requested_target = NA_real_,
                  effective_target = NA_real_, color_conf = NA_real_,
                  coverage_min_nm = NA_real_, coverage_max_nm = NA_real_,
                  extrapolated_low_nm = NA_real_, extrapolated_high_nm = NA_real_))
    }
    nm_v <- obj$nm; A_bl <- obj$A     # final analysis curve; may be normalized arbitrary units
    .controls <- cuv_render_controls()
    od <- .cuv_target(.controls)
    # No illuminant chooser: render under neutral daylight (D65) internally.
    hex  <- spectrum_to_hex(nm_v, A_bl, target_OD_Qy=od,
                            qy_range=.controls$qy,
                            car_range=.controls$car, illum="D65", absorbance_units=!isTRUE(obj$effective$norm_applied))
    list(
      status       = "available",
      hex          = as.character(hex),                # plain string for plotting
      fallback     = isTRUE(attr(hex, "qy_fallback")), # TRUE == scaled on GLOBAL peak
      car_fallback = isTRUE(attr(hex, "car_fallback")),# TRUE == scaled on carotenoid peak
      near_blank   = isTRUE(attr(hex, "near_blank")),
      low_signal   = isTRUE(attr(hex, "low_signal")),
      normalized   = isTRUE(obj$effective$norm_applied),
      normalization_method = as.character(obj$requested$norm_method %||% "none"),
      snr          = attr(hex, "snr"),
      peak         = attr(hex, "peak_abs"),
      requested_target = attr(hex, "requested_target"),
      effective_target = attr(hex, "effective_target"),
      color_conf   = attr(hex, "color_conf"),
      coverage_min_nm = attr(hex, "coverage_min_nm"),
      coverage_max_nm = attr(hex, "coverage_max_nm"),
      extrapolated_low_nm = attr(hex, "extrapolated_low_nm"),
      extrapolated_high_nm = attr(hex, "extrapolated_high_nm"),
      diag         = attr(hex, "qy_diag"),
      sample       = s,
      od           = od,
      dilution     = obj$dilution,
      baseline     = obj$baseline,
      object_hash  = obj$object_hash,
      object_hash_algo = obj$object_hash_algo
    )
  })

  # Scene presentation is independent of the global app theme and numerical color mapping.
  cuv_scene_background <- reactive({
    if (identical(input$cuv_scene_background, "light")) "light" else "dark"
  })

  cuvette_plot_obj <- reactive({
    info <- cuv_color_info(); if (is.null(info)) return(NULL)
    if (!identical(info$status, "available")) return(NULL)
    dil <- info$dilution
    dil_txt <- if (!is.null(dil) && length(dil$value) == 1L && is.finite(dil$value))
      sprintf("dil x%.4g [%s]", dil$value, if (is.na(dil$origin)) "?" else dil$origin) else ""
    hid <- if (!is.null(info$object_hash) && length(info$object_hash) == 1L && !is.na(info$object_hash))
      paste0("id:", substr(info$object_hash, 1, 12)) else ""
    ref_txt <- if (isTRUE(info$fallback)) "global reference"
               else if (isTRUE(info$car_fallback)) "blue-window reference"
               else "Qy-window reference"
    basis_txt <- if (isTRUE(info$normalized))
      paste0("normalized analysis units [", info$normalization_method, "]")
    else "analysis absorbance"
    target_txt <- if (!is.finite(info$requested_target)) paste0("unrescaled ", basis_txt) else {
      .ef <- if (is.finite(info$effective_target)) formatC(info$effective_target, digits = 4, format = "fg") else "unavailable"
      .cf <- if (is.finite(info$color_conf)) formatC(info$color_conf, digits = 3, format = "fg") else "unavailable"
      paste0(ref_txt, " requested=", formatC(info$requested_target, digits = 4, format = "fg"),
             ", effective=", .ef, ", confidence=", .cf,
             if (isTRUE(info$normalized)) " [normalized units treated illustratively]" else "")
    }
    coverage_txt <- .color_coverage_summary(info$coverage_min_nm, info$coverage_max_nm,
                                            info$extrapolated_low_nm, info$extrapolated_high_nm)
    cap_txt <- paste0(info$sample,
                      "  |  ", target_txt,
                      "  |  ", coverage_txt,
                      if (nzchar(dil_txt)) paste0("  |  ", dil_txt) else "",
                      if (nzchar(hid)) paste0("  |  ", hid) else "")
    scene_width <- session$clientData[["output_cuvette_plot_width"]] %||% 740
    if (!is.finite(scene_width) || scene_width <= 0) scene_width <- 740
    draw_cuvette(fill=info$hex, fill_frac=0.62, bg_tex=TRUE, caption=cap_txt, sample=info$sample,
                 caption_width = max(38L, min(110L, as.integer(scene_width / 5.2))),
                 scene_background = cuv_scene_background())
  })

 # Illustrative D65/CIE sRGB mapping for every selected sample (not just the dropdown
  # one), so the "Show all sample colors" grid can render one small cuvette each.
  # spectrum_to_hex is inexpensive per sample, so all selected samples are shown.
  # The whole grid is drawn as one fast
  # ggplot (draw_cuvette_grid), so the cap only guards against a pathological
  # column count (e.g. a spreadsheet with thousands of columns); it warns rather
  # than silently dropping. Each item also carries its OD-scaling basis so the grid
  # can tag samples that fell back to carotenoid / global / near-blank.
  CUV_GRID_SAFE_MAX <- 400L
  all_cuv_colors <- reactive({
    if (!isTRUE(input$is_pigmented == "yes")) return(NULL)
    df <- tryCatch(dat(), error = function(e) NULL)
    if (!isTruthy(df)) return(NULL)
    res <- tryCatch(results(), error = function(e) NULL)
    nm_c <- names(df)[1]
    all_samps <- setdiff(names(df), nm_c)
    sel <- if (is.null(input$samples)) all_samps else intersect(all_samps, input$samples)
    if (!length(sel)) return(NULL)
    n_total   <- length(sel)
    truncated <- n_total > CUV_GRID_SAFE_MAX
    if (truncated) sel <- sel[seq_len(CUV_GRID_SAFE_MAX)]
    .controls <- cuv_render_controls()
    od <- .cuv_target(.controls)
    n_refused <- 0L
    items <- lapply(sel, function(s) {
      obj <- verified_cuvette_objects()[[s]]
      # REFUSAL PARITY: a refused/unavailable sample contributes NO color tile (never a curve rendered
      # from a rejected baseline). Refusals are counted so the grid can disclose how many were withheld.
      if (is.null(obj) || !identical(obj$status, "available")) {
        if (!is.null(obj) && identical(obj$status, "refused")) n_refused <<- n_refused + 1L
        return(NULL)
      }
      hex <- spectrum_to_hex(obj$nm, obj$A, target_OD_Qy = od,
                             qy_range = .controls$qy,
                             car_range = .controls$car, illum = "D65", absorbance_units = !isTRUE(obj$effective$norm_applied))
      list(sample = s, hex = as.character(hex),
           status       = "available",
           near_blank   = isTRUE(attr(hex, "near_blank")),
           low_signal   = isTRUE(attr(hex, "low_signal")),
           requested_target = attr(hex, "requested_target"),
           effective_target = attr(hex, "effective_target"),
           color_conf   = attr(hex, "color_conf"),
           coverage_min_nm = attr(hex, "coverage_min_nm"),
           coverage_max_nm = attr(hex, "coverage_max_nm"),
           extrapolated_low_nm = attr(hex, "extrapolated_low_nm"),
           extrapolated_high_nm = attr(hex, "extrapolated_high_nm"),
           car_fallback = isTRUE(attr(hex, "car_fallback")),
           qy_fallback  = isTRUE(attr(hex, "qy_fallback")),
           normalized   = isTRUE(obj$effective$norm_applied),
           normalization_method = as.character(obj$requested$norm_method %||% "none"),
           object_hash  = obj$object_hash)
    })
    items <- Filter(Negate(is.null), items)
    if (!length(items) && !n_refused) return(NULL)
    list(items = items, truncated = truncated, n_total = n_total, cap = CUV_GRID_SAFE_MAX,
         n_refused = n_refused)
  })

  # Mirror the "Show all sample colors" toggle into a server-side reactiveVal.
  # The Download-everything ZIP runs in a separate download-request context where a
  # direct read of the bare-checkbox input$cuv_show_all can come back stale; an
  # observer on the main reactive flow keeps this value current for the handler.
  rv_cuv_show_all <- reactiveVal(FALSE)
  observeEvent(input$cuv_show_all, rv_cuv_show_all(isTRUE(input$cuv_show_all)),
               ignoreNULL = FALSE, ignoreInit = FALSE)

  # Assemble the all-samples grid as one lightweight ggplot (draw_cuvette_grid).
  # so the ZIP can bundle it. The export keeps the responsive column count and
  # the scene background selected on screen. Returns NULL when unavailable.
  all_cuv_grid_obj <- reactive({
    ac <- all_cuv_colors(); if (is.null(ac) || !length(ac$items)) return(NULL)
    n    <- length(ac$items)
    ncol <- .cuv_grid_ncol(n)
    list(plot = draw_cuvette_grid(ac$items, ncol, scene_background = cuv_scene_background()), ncol = ncol, n = n)
  })

  # Column count follows the actual rendered width so cuvettes fill a row
  # (as many as fit) and wrap to the next row when space runs out, instead of a
  # fixed ~5-column grid. Width comes from Shiny's clientData for this output; it
  # is parent-driven (independent of the plot's own height), so reading it here
  # and in the height computation does not create a feedback loop. Falls back to a
  # sensible default before the width is first reported.
  CUV_TILE_PX <- 180
  .cuv_grid_ncol <- function(n) {
    w <- session$clientData[["output_cuvette_grid_width"]]
    if (is.null(w) || !is.finite(w) || w <= 0) return(max(1L, min(5L, n)))
    max(1L, min(n, as.integer(floor((w - 168) / CUV_TILE_PX))))
  }

  cuv_page <- reactive({
    ac <- all_cuv_colors(); n <- if (is.null(ac)) 0L else length(ac$items)
    total <- max(1L, ceiling(n / 30L))
    page <- suppressWarnings(as.integer(input$cuv_grid_page %||% 1L))
    if (length(page) != 1L || !is.finite(page)) page <- 1L
    page <- min(total, max(1L, page))
    indices <- if (n) seq.int((page - 1L) * 30L + 1L, min(page * 30L, n)) else integer()
    list(items = ac$items[indices], page = page, total = total, count = n)
  })
  observeEvent(length(all_cuv_colors()$items), {
    updateNumericInput(session, "cuv_grid_page", max = max(1L, ceiling(length(all_cuv_colors()$items) / 30L)))
  }, ignoreInit = FALSE)

  # Responsive container: legend for the OD-basis tags + a width-driven plot whose
  # height grows with the row count. Degrades gracefully when patchwork is absent.
  output$cuvette_grid_ui <- renderUI({
    ac <- all_cuv_colors()
    if (is.null(ac) || !length(ac$items)) {
      if (!is.null(ac) && isTRUE(ac$n_refused > 0))
        return(div(class = "cuvette-grid-note",
                   em(sprintf("No colors to show: a preprocessing step (baseline or normalization) was refused for all %d selected sample%s, so no effective-OD curve is available to color.",
                              ac$n_refused, if (ac$n_refused == 1L) "" else "s"))))
      return(div(class = "cuvette-grid-note", em("Select samples in Analysis settings to show their colors.")))
    }
    page <- cuv_page()
    n <- length(page$items)
    ncol  <- .cuv_grid_ncol(n)
    nrow  <- ceiling(n / ncol)
    # Every row is one bench with a lamp on the left. Match its drawing aspect
    # ratio to the available width, including the reserved lamp space.
    w_px <- session$clientData[["output_cuvette_grid_width"]] %||% (CUV_TILE_PX * ncol + 168)
    if (!is.finite(w_px) || w_px <= 0) w_px <- CUV_TILE_PX * ncol + 168
    scene_width <- if (n == 1L) 1774 else 400 + ncol * 430
    h_px <- min(4000L, max(230L, as.integer(w_px * (nrow * 927 - 40) / scene_width)))
    # Legend only for the tags that actually occur in the current selection.
    any_car   <- any(vapply(ac$items, function(it) isTRUE(it$car_fallback), logical(1)))
    any_glob  <- any(vapply(ac$items, function(it) isTRUE(it$qy_fallback),  logical(1)))
    any_blank <- any(vapply(ac$items, function(it) isTRUE(it$near_blank),   logical(1)))
    any_norm  <- any(vapply(ac$items, function(it) isTRUE(it$normalized),   logical(1)))
    any_low   <- any(vapply(ac$items, function(it) isTRUE(it$low_signal),   logical(1)))
    any_extrap <- any(vapply(ac$items, function(it)
      isTRUE((it$extrapolated_low_nm %||% 0) > 0 || (it$extrapolated_high_nm %||% 0) > 0), logical(1)))
    bits <- c(
      "T = 10^-value has physical-transmittance meaning only for verified decadic absorbance on the applicable optical basis; normalized or other non-OD/arbitrary inputs are illustrative",
      if (any_car)   "(blue OD) = scaled on a qualifying numerical feature in the blue reference window" else NULL,
      if (any_glob)  "(global OD) = scaled on the global maximum after the reference-window gates did not qualify" else NULL,
      if (any_blank) "(floor) = final curve did not exceed the operational numerical rendering floor; neutral gray shown" else NULL,
      if (any_norm)  "Normalization is active: the renderer is using arbitrary normalized units" else NULL,
      if (any_low)   "Low-signal rows use the displayed effective target (requested target multiplied by rendering confidence), not the unattenuated request" else NULL,
      if (any_extrap) "The metadata table quantifies visible-range spans filled by flat endpoint holding" else NULL)
    legend <- if (length(bits))
      div(class = "cuvette-grid-note", style = "opacity:0.85;margin-bottom:2px;",
          paste(bits, collapse = "   ·   ")) else NULL
    trunc_note <- if (isTRUE(ac$truncated))
      div(class = "cuvette-grid-note",
          sprintf("Showing the first %d of %d selected samples (safety cap).",
                  ac$cap, ac$n_total)) else NULL
    refused_note <- if (!is.null(ac$n_refused) && isTRUE(ac$n_refused > 0))
      div(class = "cuvette-grid-note",
          sprintf("%d selected sample%s withheld: a preprocessing step (baseline or normalization) was refused, so no effective-OD curve is available to color.",
                  ac$n_refused, if (ac$n_refused == 1L) "" else "s")) else NULL
    tagList(trunc_note, refused_note, legend,
            p(class="cuvette-grid-note", sprintf("Page %d of %d · %d samples. The Color details table and exports retain all selected samples within the safety cap.", page$page, page$total, page$count)),
            p(class = "cuvette-grid-note", "Bench lighting and glass are illustrative. Expand Color details below for the calculated hexadecimal colors and rendering metadata."),
            plotOutput("cuvette_grid", width = "100%", height = paste0(h_px, "px")))
  })

  output$cuvette_grid_metadata <- renderTable({
    items <- if (isTRUE(input$cuv_show_all)) {
      ac <- all_cuv_colors(); req(!is.null(ac), length(ac$items) > 0)
      ac$items
    } else {
      info <- cuv_color_info(); req(!is.null(info), identical(info$status, "available"))
      list(info)
    }
    d <- .color_rendering_metadata_df(items)
    d <- d[, intersect(c("sample", "hex", "requested_target", "effective_target", "color_conf",
                    "low_signal", "coverage_min_nm", "coverage_max_nm",
                    "extrapolated_low_nm", "extrapolated_high_nm"), names(d)), drop = FALSE]
    names(d)[match(c("sample", "hex"), names(d))] <- c("Sample", "Hex color")
    d
  }, digits = 4, striped = TRUE, bordered = TRUE, spacing = "xs")

  output$cuvette_grid <- renderPlot({
    req(isTRUE(input$cuv_show_all))
    ac <- all_cuv_colors(); req(!is.null(ac), length(ac$items) > 0)
    items <- cuv_page()$items
    draw_cuvette_grid(items, .cuv_grid_ncol(length(items)), scene_background = cuv_scene_background())
  }, bg = "transparent")

  # Stable warning shown only when the selected sample did not meet the configured
  # Qy reference-window gate and a fallback numerical reference was used.
  output$cuv_fallback_warn <- renderUI({
    info <- cuv_color_info()
    if (is.null(info)) return(NULL)
    if (identical(info$status, "refused") || identical(info$status, "unavailable")) {
      rsn <- if (length(info$reason) == 1L && !is.na(info$reason)) info$reason else info$status
      .stg <- tryCatch(as.character(info$stage %||% ""), error = function(e) "")
      msg <- if (identical(info$status, "refused")) {
        lead <- if (identical(.stg, "normalization")) "Normalization was refused"
                else if (identical(.stg, "baseline")) "Baseline correction was refused"
                else "A preprocessing step was refused"
        sprintf("%s for this sample (reason: %s), so no effective analysis curve was accepted under the configured pipeline. The swatch is withheld, matching the quantitative pipeline for this sample.", lead, rsn)
      } else
        sprintf("No effective-OD curve is available for this sample (reason: %s), so no color is rendered.", rsn)
      return(div(style="margin-top:10px;padding:12px 14px;border-radius:8px;
                 background:var(--bs-tertiary-bg);border-left:4px solid #6b7280;
                 border:1px solid var(--bs-border-color);font-size:0.85em;",
        tags$span(style="color:var(--pasa-muted-fg);font-weight:600;", tags$b("Color withheld. ")),
        tags$span(msg)))
    }
    .cov_lo <- suppressWarnings(as.numeric(info$extrapolated_low_nm %||% 0))
    .cov_hi <- suppressWarnings(as.numeric(info$extrapolated_high_nm %||% 0))
    .coverage_warn <- if (is.finite(.cov_lo) && is.finite(.cov_hi) && (.cov_lo > 0 || .cov_hi > 0))
      div(style="margin-top:10px;padding:12px 14px;border-radius:8px;
                 background:var(--bs-tertiary-bg);border-left:4px solid #e0a800;
                 border:1px solid var(--bs-border-color);font-size:0.85em;",
          tags$span(style="color:var(--pasa-warn-fg);font-weight:600;", tags$b("Visible-range endpoint extrapolation. ")),
          tags$span(sprintf(paste0("The finite analysis curve covers %.4g--%.4g nm. For this illustrative D65/CIE sRGB mapping, ",
                                   "the nearest endpoint absorbance is held flat across %.4g nm below coverage and %.4g nm above coverage ",
                                   "within the 380--780 nm integration range; those wavelengths were not measured for this sample."),
                            info$coverage_min_nm, info$coverage_max_nm, .cov_lo, .cov_hi)))
    else NULL
    # Near-blank samples (whole spectrum below the photometric floor) render
    # as neutral gray; explain why rather than showing a saturated noise color.
    if (isTRUE(info$near_blank)) {
      return(div(style="margin-top:10px;padding:12px 14px;border-radius:8px;
                 background:var(--bs-tertiary-bg);border-left:4px solid #6b7280;
                 border:1px solid var(--bs-border-color);font-size:0.85em;",
        tags$span(style="color:var(--pasa-muted-fg);font-weight:600;", tags$b("Numerical rendering floor applied. ")),
        tags$span("The final analysis curve did not exceed the operational 5×10⁻⁴-unit backstop, so PASA shows neutral gray rather than amplifying a near-zero curve. This is a rendering safeguard, not a blank classification, detection limit, or pigment-presence conclusion.")))
    }
    # Weak-feature advisory: rendered, with an explicit warning that the selected
    # reference rescale can amplify a faint or noise-sensitive numerical feature.
    if (isTRUE(info$low_signal)) {
      .lsm <- .color_low_signal_msg(info$peak, info$snr, info$requested_target,
                                    info$effective_target, info$color_conf, absorbance_units = !isTRUE(info$normalized))
      return(tagList(div(style="margin-top:10px;padding:12px 14px;border-radius:8px;
                 background:var(--bs-tertiary-bg);border-left:4px solid #e0a800;
                 border:1px solid var(--bs-border-color);font-size:0.85em;",
        tags$span(style="color:var(--pasa-warn-fg);font-weight:600;", tags$b(.lsm$header)),
        tags$span(.lsm$body)), .coverage_warn))
    }
    # Blue-window tier: the Qy reference gate was not met but the configured
    # blue window met its operational gate, so the color uses that numerical
    # reference rather than the global maximum.
    if (isTRUE(info$car_fallback)) {
      d <- info$diag
      car_win <- input$car
      car_txt <- if (!is.null(car_win) && length(car_win) == 2 &&
                     all(is.finite(suppressWarnings(as.numeric(car_win)))))
                   sprintf("%g–%g nm", car_win[1], car_win[2]) else "the carotenoid window"
      car_detail <- if (is.list(d) && is.finite(d$car_nm) && is.finite(d$car_frac))
        sprintf(" The carotenoid-window (%s) peak near %g nm is %.0f%% of this sample's overall maximum absorbance.",
                car_txt, d$car_nm, 100 * d$car_frac) else ""
      return(tagList(div(style="margin-top:10px;padding:12px 14px;border-radius:8px;
                 background:var(--bs-tertiary-bg);border-left:4px solid #e08600;
                 border:1px solid var(--bs-border-color);font-size:0.85em;",
        tags$span(style="color:var(--pasa-warn-fg);font-weight:600;", tags$b("Qy-window reference gate not met — scaled on a qualifying blue-window feature. ")),
        tags$span(
          "The Qy-window feature did not meet the operational fractional-peak gate, so the illustrative color was scaled by the strongest peak inside the blue reference window.",
          car_detail,
          " This numerical choice does not identify the contributing pigment or transition because the window can contain overlapping features.",
          paste0(" The target control refers to that blue-window feature for this rendering; it is not a pigment assignment or the absorbance at ", car_txt, ".")
        )), .coverage_warn))
    }
    if (!isTRUE(info$fallback)) return(.coverage_warn)
    d <- info$diag
    frac_txt <- if (is.list(d) && is.finite(d$frac))
      sprintf("%.2f%%", 100 * d$frac) else "<2%"
    # Use the LIVE Qy slider window, not a hardcoded 660-690 nm, so the stated
    # range matches the window actually used to compute the fallback fraction.
    qy_win <- input$qy
    qy_txt <- if (!is.null(qy_win) && length(qy_win) == 2 &&
                  all(is.finite(suppressWarnings(as.numeric(qy_win)))))
                sprintf("%g\u2013%g nm", qy_win[1], qy_win[2]) else "the Qy window"
    detail <- if (is.list(d) && is.finite(d$qy_peak) && is.finite(d$global_peak) &&
                  is.finite(d$global_nm)) {
      sprintf(" The peak inside the Qy window (%s) is %s of this sample's overall maximum value (near %g nm), so it did not meet the operational Qy-window reference gate.",
              qy_txt, frac_txt, d$global_nm)
    } else ""
    tagList(div(style="margin-top:10px;padding:12px 14px;border-radius:8px;
               background:var(--bs-tertiary-bg);border-left:4px solid #dc2626;
               border:1px solid var(--bs-border-color);font-size:0.85em;",
      tags$span(style="color:var(--pasa-err-fg);font-weight:600;", tags$b("Reference-window gates not met — scaled on the global maximum. ")),
      tags$span(
        "Neither reference window met its operational fractional-peak gate, so the illustrative color was scaled by the global numerical maximum.",
        detail,
        paste0(" The target control refers to that global maximum for this rendering; this is not a pigment-presence conclusion or the absorbance at ", qy_txt, ".")
      )
    ), .coverage_warn)
  })
  output$cuvette_plot <- renderPlot({
    p <- cuvette_plot_obj(); req(!is.null(p))
    p + ggplot2::theme(axis.text=ggplot2::element_blank(),
                      axis.title=ggplot2::element_blank(),
                      axis.ticks=ggplot2::element_blank())
  }, height = function() {
    width <- session$clientData[["output_cuvette_plot_width"]] %||% 740
    if (!is.finite(width) || width <= 0) width <- 740
    as.integer(max(340, width * 887 / 1774 + 112))
  }, bg = "transparent")

  # ==========================================================================
  # References tab
  # ==========================================================================
  output$references_content <- renderUI({
    HTML(paste0('
<h3>References</h3>
<p>The citations below support the definitions, algorithms, and band assignments used in this application.</p>

<h4>Beer\u2013Lambert law</h4>
<ul>
  <li>IUPAC. \u201cBeer\u2013Lambert law (or Beer\u2013Lambert\u2013Bouguer law).\u201d <em>IUPAC Compendium of Chemical Terminology</em> (the Gold Book), entry B00626, 2014. <a href="https://goldbook.iupac.org/terms/view/B00626" target="_blank" rel="noopener">https://goldbook.iupac.org/terms/view/B00626</a></li>
  <li>Edinburgh Instruments. \u201cThe Beer\u2013Lambert Law: Transmittance &amp; Absorbance.\u201d Technical note, 2021. <a href="https://www.edinst.com/resource/the-beer-lambert-law/" target="_blank" rel="noopener">https://www.edinst.com/resource/the-beer-lambert-law/</a></li>
</ul>

<h4>Savitzky\u2013Golay smoothing and differentiation</h4>
<ul>
  <li>Savitzky, A.; Golay, M. J. E. \u201cSmoothing and Differentiation of Data by Simplified Least Squares Procedures.\u201d <em>Analytical Chemistry</em>, 36(8), 1627\u20131639, 1964. <a href="https://doi.org/10.1021/ac60214a047" target="_blank" rel="noopener">https://doi.org/10.1021/ac60214a047</a></li>
</ul>

<h4>Derivative (2nd-derivative) spectroscopy \u2014 examining overlapping spectral features</h4>
<ul>
  <li>O\u2019Haver, T. C.; Green, G. L. \u201cNumerical error analysis of derivative spectrometry for the quantitative analysis of mixtures.\u201d <em>Analytical Chemistry</em>, 48(2), 312\u2013318, 1976. <a href="https://doi.org/10.1021/ac60366a016" target="_blank" rel="noopener">https://doi.org/10.1021/ac60366a016</a></li>
  <li>Antonov, L.; Nedeltcheva, D. \u201cResolution of overlapping UV\u2013Vis absorption bands and quantitative analysis.\u201d <em>Chemical Society Reviews</em>, 29(3), 217\u2013227, 2000. <a href="https://doi.org/10.1039/a900007k" target="_blank" rel="noopener">https://doi.org/10.1039/a900007k</a></li>
</ul>

<h4>CIE 1931 color-matching functions and the D65 illuminant</h4>
<ul>
  <li>CIE (International Commission on Illumination). CIE 1931 color-matching functions, 2-degree observer. Official 1-nm dataset, DOI 10.25039/CIE.DS.xvudnb9b. <a href="https://doi.org/10.25039/CIE.DS.xvudnb9b" target="_blank" rel="noopener">CIE dataset DOI</a>. PASA uses an attributed 10-nm, rounded adaptation under CC BY-SA 4.0; the shipped data notice records the official title and changes.</li>
  <li>CIE (International Commission on Illumination). \u201cCIE standard illuminant D65.\u201d Official 1-nm dataset, DOI 10.25039/CIE.DS.hjfjmt59. <a href="https://cie.co.at/datatable/cie-standard-illuminant-d65" target="_blank" rel="noopener">CIE dataset page</a>. PASA uses an attributed 10-nm, rounded adaptation under CC BY-SA 4.0; the shipped data notice records the changes.</li>
  <li>W3C. <em>CSS Color Module Level 4</em>, sample color-conversion implementation. <a href="https://www.w3.org/TR/css-color-4/#color-conversion-code" target="_blank" rel="noopener">W3C public implementation reference</a>. PASA uses the documented D65 XYZ-to-linear-sRGB rational matrix and sRGB transfer constants as an implementation reference; W3C does not endorse PASA.</li>
</ul>

<h4>Okabe\u2013Ito colorblind-safe palette</h4>
<ul>
  <li>Okabe, M.; Ito, K. \u201cColor Universal Design (CUD): How to make figures and presentations that are friendly to colorblind people.\u201d J*FLY, University of Cologne, 2008. <a href="https://jfly.uni-koeln.de/color/" target="_blank" rel="noopener">https://jfly.uni-koeln.de/color/</a></li>
</ul>

<h4>Spectral band assignments (Qy, Phycobilin/PBS or Chl b, Carotenoid, Soret/Bx)</h4>
<ul>
  <li>Chlorophyll <em>a</em> reference solution spectrum: Oregon Medical Laser Center / PhotochemCAD, \u201cChlorophyll <em>a</em>.\u201d <a href="https://omlc.org/spectra/PhotochemCAD/html/122.html" target="_blank" rel="noopener">https://omlc.org/spectra/PhotochemCAD/html/122.html</a>. This reference spectrum does not prescribe PASA\u2019s window for other sample conditions.</li>
  <li>Dagnino-Leone, J.; Pinto Figueroa, C.; Latorre Casta\u00f1eda, M.; et al. \u201cPhycobiliproteins: Structural aspects, functional characteristics, and biotechnological perspectives.\u201d <em>Computational and Structural Biotechnology Journal</em> 20, 1506\u20131527, 2022. <a href="https://doi.org/10.1016/j.csbj.2022.02.016" target="_blank" rel="noopener">https://doi.org/10.1016/j.csbj.2022.02.016</a> \u2014 review context for phycobiliprotein structure and absorption; PASA\u2019s windows remain configurable starting values.</li>
  <li>Carotenoid and chlorophyll absorption ranges in photosynthesis (400\u2013700 nm): \u201cLimits on Natural Photosynthesis.\u201d <em>J. Phys. Chem. B</em>, 2017 (PMC). <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC5647561/" target="_blank" rel="noopener">https://pmc.ncbi.nlm.nih.gov/articles/PMC5647561/</a></li>
  <li>Phycoerythrin (PE) absorption (~490\u2013570 nm, peak ~565 nm) in red algae and cyanobacteria: Glazer, A. N. \u201cPhycobilisomes: structure and dynamics.\u201d <em>Annu. Rev. Microbiol.</em> 36, 173\u2013198, 1982. <a href="https://doi.org/10.1146/annurev.mi.36.100182.001133" target="_blank" rel="noopener">https://doi.org/10.1146/annurev.mi.36.100182.001133</a></li>
  <li>Chlorophyll <em>b</em> reference solution spectrum, blue-shifted relative to the cited Chl <em>a</em> reference: Oregon Medical Laser Center / PhotochemCAD, \u201cChlorophyll <em>b</em>.\u201d <a href="https://omlc.org/spectra/PhotochemCAD/html/125.html" target="_blank" rel="noopener">https://omlc.org/spectra/PhotochemCAD/html/125.html</a>. This reference spectrum does not validate the 640\u2013657 nm preset for other sample conditions.</li>
  <li><em>Note:</em> The default windows (Qy / Chl <em>a</em> Qy 660\u2013690, variable 600\u2013650 band [Chl <em>a</em> Qx/Vibronic, or PBS for whole cells/lysate of cyanobacteria/red algae], Phycoerythrin 490\u2013570 [red algae cells], Chl <em>b</em> Qy 640\u2013657 [green algae &amp; plants], Carotenoid 430\u2013520, Soret/Bx 420\u2013460 nm) are practical starting points and are user-adjustable. The active band set is driven by the Organism preset and the Sample type toggle. Exact positions shift with the pigment\u2013protein environment and organism.</li>
</ul>

<h4>Growth kinetics \u2014 apparent OD-derived log-linear rate and OD doubling time</h4>
<ul>
  <li>During balanced exponential growth, specific growth rate is the slope of log biomass versus time and doubling time is ln(2)/&mu; (Monod 1949). PASA instead fits log OD; its output is therefore an apparent OD-derived log-linear rate unless an applicable OD\u2013biomass relationship has been independently justified. Monod, J. \u201cThe growth of bacterial cultures.\u201d <em>Annu. Rev. Microbiol.</em> 3, 371\u2013394, 1949. <a href="https://doi.org/10.1146/annurev.mi.03.100149.002103" target="_blank" rel="noopener">https://doi.org/10.1146/annurev.mi.03.100149.002103</a></li>
  <li>Far-red / near-IR optical density (including operational choices near 730\u2013750 nm) is often used for microalgal or cyanobacterial growth tracking to reduce pigment-absorption interference, but the relationship remains matrix-, wavelength-, instrument-, and calibration-dependent. Griffiths, M. J.; Garcin, C.; van Hille, R. P.; Harrison, S. T. L. \u201cInterference by pigment in the estimation of microalgal biomass concentration by optical density.\u201d <em>J. Microbiol. Methods</em> 85(2), 119\u2013123, 2011. <a href="https://doi.org/10.1016/j.mimet.2011.02.005" target="_blank" rel="noopener">https://doi.org/10.1016/j.mimet.2011.02.005</a>.</li>
  <li>Andersen, R. A. (ed.). <em>Algal Culturing Techniques.</em> Phycological Society of America / Academic Press, 2005. ISBN 978-0120884261. Standard methods reference for batch-culture growth-rate determination across eukaryotic microalgae (green and red algae).</li>
</ul>

', '
<h4>Baseline / blank correction rationale</h4>
<ul>
  <li>IUPAC Gold Book \u2014 Absorbance (A00028) defines absorbance. <a href="https://goldbook.iupac.org/terms/view/A00028" target="_blank" rel="noopener">https://goldbook.iupac.org/terms/view/A00028</a>. PASA\u2019s additive-offset rationale and its limits are stated separately below rather than attributed to this definition.</li>
  <li>App rationale (also explained in Help): a user-selected far-red reference such as ~750 nm can estimate a single additive offset only when the sample, blank, and instrument support a low-absorption reference region. A non-zero value can also reflect residual absorption, blank mismatch, scattering, or other artifacts; subtraction does not by itself make instruments comparable.</li>
</ul>

<h4>Trapezoidal rule for AUC integration</h4>
<ul>
  <li>Press, W. H.; Teukolsky, S. A.; Vetterling, W. T.; Flannery, B. P. <em>Numerical Recipes: The Art of Scientific Computing</em>, 3rd ed., Cambridge University Press, 2007, \u00a74.1. ISBN 978-0521880688.</li>
  <li>The app uses the composite trapezoidal rule over the band\u2019s wavelength grid.</li>
</ul>

<h4>Spectral Angle Mapper (SAM) and 2nd-derivative correlation as shape-comparison metrics</h4>
<ul>
  <li>Kruse, F. A.; Lefkoff, A. B.; Boardman, J. W.; Heidebrecht, K. B.; Shapiro, A. T.; Barloon, P. J.; Goetz, A. F. H. \u201cThe Spectral Image Processing System (SIPS) \u2014 Interactive Visualization and Analysis of Imaging Spectrometer Data.\u201d <em>Remote Sensing of Environment</em>, 44(2\u20133), 145\u2013163, 1993. <a href="https://doi.org/10.1016/0034-4257(93)90013-N" target="_blank" rel="noopener">https://doi.org/10.1016/0034-4257(93)90013-N</a></li>
  <li>App rationale: SAM compares vector direction and is invariant to a common positive scale factor. A second derivative mathematically removes an affine offset/slope, but derivative noise, smoothing choices, curvature, and other baseline structure remain; PASA therefore treats the derivative correlation as advisory. The Data Quality <b>sample-similarity network</b> can use weighted r on pair-local union-grid interpolated pre-normalization analysis curves, weighted r on the 2nd derivative, or weighted spectral angle as descriptive edge weights. Interpolation is linear only within each trace&rsquo;s measured span; joint coverage and gap masks exclude unsupported nodes. None establishes sample identity.</li>
  <li>Force-directed network layout (used by the similarity network’s “Force-directed” option): Fruchterman, T. M. J.; Reingold, E. M. “Graph Drawing by Force-Directed Placement.” <em>Software: Practice and Experience</em>, 21(11), 1129–1164, 1991. <a href="https://doi.org/10.1002/spe.4380211102" target="_blank" rel="noopener">https://doi.org/10.1002/spe.4380211102</a></li>
</ul>

', '
<h4>Spectral noise qualification (DER-SNR)</h4>
<ul>
  <li>Stoehr, F.; et al. “DER_SNR: A Simple &amp; General Spectroscopic Signal-to-Noise Measurement Algorithm.” In <em>Astronomical Data Analysis Software and Systems (ADASS) XVII</em>, ASP Conf. Ser. 394, p. 505, 2008. <a href="https://ui.adsabs.harvard.edu/abs/2008ASPC..394..505S" target="_blank" rel="noopener">https://ui.adsabs.harvard.edu/abs/2008ASPC..394..505S</a> — the second-difference estimator used by the per-sample noise screen. The spacing-2 difference cancels local constant and linear trend exactly only on a uniform wavelength axis and does not remove curvature. PASA treats steps &gt;1.5&times; the preliminary median as gaps, never spans them, and evaluates only axes whose remaining increments have maximum relative deviation &le;1% from their representative median step; cancellation is approximate within that admitted tolerance. Materially non-uniform axes are not evaluated. The denominator is the maximum absolute native-coordinate, baseline-corrected, pre-smoothing analysis value and is archived with the axis diagnostics.</li>
  <li>Rousseeuw, P. J.; Croux, C. “Alternatives to the Median Absolute Deviation.” <em>Journal of the American Statistical Association</em>, 88(424), 1273–1283, 1993. <a href="https://doi.org/10.1080/01621459.1993.10476408" target="_blank" rel="noopener">https://doi.org/10.1080/01621459.1993.10476408</a> — the 1.4826 scale factor that makes the MAD a consistent estimator of the Gaussian standard deviation.</li>
  <li><b>Whole-sample verdict:</b> driven by the global metric, the 720–750 nm tail, and the reliability-gated <b>fraction of 10-nm windows flagged</b> (only counted when at least 5 windows are scored, so a coarse-grid spectrum with a couple of windows cannot post a spurious “50% flagged” FAIL). A single flagged 10-nm window does <em>not</em> by itself raise a whole-sample CAUTION; each region needs at least 4 residuals before its MAD is scored. These per-region cutoffs (0.5 / 1.5 % global, etc.) are operational defaults, not literature values (the threshold logic is shown in the detailed-QC panel).</li>
</ul>

', '
<h4>Deconvolution thresholds and band-width justification</h4>
<ul>
  <li>Meloun, M.; \u010capek, J.; Mik\u0161\u00edk, P.; Brereton, R. G. \u201cCritical comparison of methods predicting the number of components in spectroscopic data.\u201d <em>Analytica Chimica Acta</em>, 423(1), 51\u201368, 2000. <a href="https://doi.org/10.1016/S0003-2670(00)01100-4" target="_blank" rel="noopener">https://doi.org/10.1016/S0003-2670(00)01100-4</a> \u2014 component-count selection and the risk of over-resolving noise into extra bands (advisory box and interpretation notes).</li>
  <li>Akaike, H. \u201cA new look at the statistical model identification.\u201d <em>IEEE Transactions on Automatic Control</em>, 19(6), 716\u2013723, 1974. <a href="https://doi.org/10.1109/TAC.1974.1100705" target="_blank" rel="noopener">https://doi.org/10.1109/TAC.1974.1100705</a> \u2014 conceptual origin of AIC. The app label denotes a plug-in residual-AR(1) penalized parsimony variant, not classical AIC from a jointly maximized likelihood.</li>
  <li>Schwarz, G. \u201cEstimating the dimension of a model.\u201d <em>The Annals of Statistics</em>, 6(2), 461\u2013464, 1978. <a href="https://doi.org/10.1214/aos/1176344136" target="_blank" rel="noopener">https://doi.org/10.1214/aos/1176344136</a> \u2014 conceptual origin of BIC. The app default is an analogous plug-in parsimony variant and is not standard likelihood-based BIC.</li>
  <li>R\u00e4tsep, M.; Linnanto, J.; Freiberg, A. \u201cMirror symmetry and vibrational structure in optical spectra of chlorophyll a.\u201d <em>The Journal of Chemical Physics</em> 130, 194501, 2009. <a href="https://doi.org/10.1063/1.3125183" target="_blank" rel="noopener">https://doi.org/10.1063/1.3125183</a> \u2014 reports Chl-a Q<sub>y</sub> vibronic structure under specific low-temperature experimental conditions. It provides scale context only and does not validate PASA\u2019s configurable FWHM bounds for other samples.</li>
  <li>Peterman, E. J. G.; Wenk, S.-O.; Pullerits, T.; P\u00e5lsson, L.-O.; van Grondelle, R.; Dekker, J. P.; R\u00f6gner, M.; van Amerongen, H. \u201cFluorescence and absorption spectroscopy of the weakly fluorescent chlorophyll a in cytochrome b<sub>6</sub>f of <em>Synechocystis</em> PCC6803.\u201d <em>Biophysical Journal</em> 75(1), 389\u2013398, 1998. <a href="https://doi.org/10.1016/S0006-3495(98)77523-X" target="_blank" rel="noopener">https://doi.org/10.1016/S0006-3495(98)77523-X</a> \u2014 reports a Chl-a feature and model widths in one protein-complex context. It is illustrative context, not evidence that PASA\u2019s chosen floor lies below every genuine pigment band.</li>
  <li>Macernis, M.; Streckait\u0117, S.; Litv\u00edn, R.; et al. \u201cElectronic and Vibrational Properties of Allene Carotenoids.\u201d <em>The Journal of Physical Chemistry A</em>, 126(6), 813\u2013824, 2022. <a href="https://doi.org/10.1021/acs.jpca.1c09393" target="_blank" rel="noopener">https://doi.org/10.1021/acs.jpca.1c09393</a> \u2014 carotenoid vibronic structure. Note: the ~20\u201324 nm figure describes vibronic-mode <em>spacings</em>, not band FWHM, so the app\u2019s carotenoid-band width bounds are operational defaults rather than values read from this paper.</li>
  <li>Taniguchi, M.; Lindsey, J. S. \u201cAbsorption and Fluorescence Spectral Database of Chlorophylls and Analogues.\u201d <em>Photochemistry and Photobiology</em>, 2021. <a href="https://doi.org/10.1111/php.13319" target="_blank" rel="noopener">https://doi.org/10.1111/php.13319</a> \u2014 a chlorophyll absorption/fluorescence database that documents spectra across compounds and measurement conditions. It does not prescribe PASA\u2019s configurable center-tolerance setting, which is an operational search constraint.</li>
</ul>

<h4>Empirical inverse-power baseline correction</h4>
<p>The optional Deconvolution pre-processing step fits a red-edge tail that the user assumes has sufficiently low analyte absorption to S(&lambda;) = a&middot;&lambda;<sup>&minus;b</sup> + c, then subtracts the extrapolated empirical wavelength-dependent baseline. Its physical origin is unidentified: the procedure does not establish a scattering contribution, prove that the fitted tail is non-absorbing, or show that physical scattering has been removed.</p>
<ul>
  <li>Leach, S. J.; Scheraga, H. A. \u201cEffect of Light Scattering on Ultraviolet Difference Spectra.\u201d <em>Journal of the American Chemical Society</em>, 82(18), 4790\u20134792, 1960. <a href="https://doi.org/10.1021/ja01503a008" target="_blank" rel="noopener">https://doi.org/10.1021/ja01503a008</a> \u2014 an early report of wavelength-dependent apparent absorbance and power-law correction in ultraviolet difference spectra. PASA uses a related empirical form but does not assume every selected tail is absorption-free.</li>
  <li>Basalla, A. J.; Kendrick, B. S. \u201cCorrecting Ultraviolet-Visible Spectra for Baseline Artifacts.\u201d <em>Journal of Pharmaceutical Sciences</em>, 112(12), 3240\u20133247, 2023. <a href="https://doi.org/10.1016/j.xphs.2023.08.015" target="_blank" rel="noopener">https://doi.org/10.1016/j.xphs.2023.08.015</a> \u2014 presents a Rayleigh\u2013Mie\u2013offset curve-fitting approach and evaluates it on specified test materials. PASA adopts the a&middot;&lambda;<sup>&minus;b</sup> + c form as an optional empirical baseline; that study does not validate PASA on a user\u2019s sample.</li>
  <li>Phillips, S. M.; Smith, G. D. \u201cSpectroscopic comparison of water- and methanol-soluble brown carbon particulate matter.\u201d <em>Aerosol Science and Technology</em>, 51(9), 1113\u20131121, 2017. <a href="https://doi.org/10.1080/02786826.2017.1334109" target="_blank" rel="noopener">https://doi.org/10.1080/02786826.2017.1334109</a> \u2014 uses power-law functions in a specific particulate-matter analysis. The exponent terminology in that context does not make PASA\u2019s fitted b a universal physical classifier.</li>
  <li>Bohren, C. F.; Huffman, D. R. <em>Absorption and Scattering of Light by Small Particles.</em> Wiley, 1983 (print ISBN 978-0471057727; the DOI below is the 1998 Wiley-VCH online edition, same text). <a href="https://doi.org/10.1002/9783527618156" target="_blank" rel="noopener">https://doi.org/10.1002/9783527618156</a> \u2014 Mie scattering depends on particle size distribution, refractive index, geometry, and wavelength and need not follow one power law. Over a limited range an empirical \u03bb<sup>\u2212b</sup> baseline may be useful, but fitted b is sample/model dependent and is not a direct Mie/Rayleigh classification.</li>
  <li>Duysens, L. N. M. \u201cThe flattening of the absorption spectrum of suspensions, as compared to that of solutions.\u201d <em>Biochimica et Biophysica Acta</em>, 19(1), 1\u201312, 1956. <a href="https://doi.org/10.1016/0006-3002(56)90380-8" target="_blank" rel="noopener">https://doi.org/10.1016/0006-3002(56)90380-8</a> \u2014 supports caution about package/flattening effects in suspensions. PASA therefore treats OD at Q<sub>y</sub> as descriptive unless the study independently establishes an applicable calibration.</li>
</ul>
<p class="text-muted" style="font-size:0.85em;">Provenance note: the a\u00b7\u03bb<sup>\u2212b</sup>&nbsp;+&nbsp;c form is the \u201cRayleigh-Mie-Offset (RMO) model\u201d named by Basalla &amp; Kendrick (2023); this app adopts their functional form but does not otherwise use the RMO label in its interface.</p>
    '))
  })

  # ==========================================================================
  # Help tab
  # ==========================================================================
  output$help_content <- renderUI({
    HTML(.pasa_help_fill('
<h3>Help Manual</h3>

<h4>Workspace and guided tours</h4>
<p><b>Open PASA</b> opens <b>Input data</b>. Load and inspect the input there, then open the separate <b>Analysis settings</b> tab for range, sample selection, band windows, baseline, conditioning, scaling and export options. <b>Summary</b> follows immediately, then Spectra, Metrics, Band AUC, Data Quality, optional Deconvolution, Sample color and Cell growth. The top-right Analysis settings shortcut is available on analysis pages and hidden on Welcome, About, Help, FAQ, References and Feedback.</p>
<p><b>Guided tour</b> in the header and on Welcome offers <b>Quick</b> and <b>Detailed</b> choices. Quick introduces the workflow, every tab and Advanced Mode. Detailed explains individual fields and outputs with examples; the <b>Detailed guided tour</b> button in Analysis settings opens its especially detailed settings chapter. Use <b>Jump to chapter</b>, <b>Back</b>, <b>Next</b> and, for related controls, <b>Next field</b>. <b>Pause tour</b> or Escape closes the tour and retains that tour position; the chooser offers independent Resume buttons for Quick and Detailed.</p>
<p>The tour highlights applicable controls and opens explanatory disclosures. If a field needs another option or a result is unavailable, it highlights the relevant controller and explains how to reveal it. You may continue and return with <b>Revisit</b>. The tour does not change analysis settings, load or replace data, apply a saved session, run fits or bootstrap jobs, download results or send feedback. Opened disclosures return to their prior state when the tour leaves them.</p>
<p><b>Expand all</b> and <b>Collapse all</b> open or close the sections in About, Help and FAQ. Individual headings remain independently expandable.</p>

<h4>1. Input / Data Loading</h4>
<ul>
  <li><b>Data source</b> (toggle on the Input data tab): pick one of four sources; the matching field then appears below.
    <ul>
      <li><b>Local</b>: Upload a local Excel (.xlsx/.xls), CSV, TSV, or tab-/whitespace-delimited .txt file. First column = wavelength (nm), remaining columns = samples. Then click <b>Load data</b>.</li>
      <li><b>URL</b>: Enter a supported public URL (Google Sheets, OneDrive), or an absolute path in an explicitly permitted desktop launch, then click <b>Load data</b>. Hosted sessions cannot use arbitrary local server paths. Use Inspect sheets when offered to review the workbook before loading.</li>
      <li><b>Import session</b>: Upload a previously exported session-snapshot file (<code>PASA_state.txt</code>). A dialog appears showing only the sections present in the snapshot (Settings, Input data, Cell Growth data, and measured deconvolution blank); tick the ones you want to apply and click <b>Apply selected</b>. See section 8 below for what the snapshot contains.</li>
      <li><b>Demo data</b>: Click <b>Load demo data</b> to load a built-in worked example without uploading anything.</li>
    </ul>
  </li>
  <li><b>Sheet</b>: For Excel / Google-Sheets sources, select which worksheet to read (populated after specifying a file/URL).</li>
  <li><b>Analysis Range</b> (Analysis settings): <b>Use only this &lambda;-range</b> restricts reported analysis curves, metrics, normalization, peaks, plots, and processed exports to the chosen interval. <b>Baseline lookup is the documented exception:</b> it uses the full loaded source and can use eligible native measured points outside this interval. The loaded source remains intact.</li>
  <li><b>Samples</b> (Analysis settings): Tick/untick samples for analysis-dependent plots and calculations. <b>Per-sample QC is the explicit exception:</b> it inventories all loaded columns; raw-file checks and high-correlation candidate screening use all loaded columns, while analysis-dependent diagnostics are evaluated only for selected samples. Deselected rows are marked Not evaluated and never counted as passed. <b>Select all</b> / <b>Clear</b> act on the whole list.</li>
</ul>

<h4>2. Baseline Correction</h4>
<ul>
  <li><b>Apply baseline correction (checkbox)</b>: When unchecked, spectra and raw-basis AUC use the uploaded values before PASA baseline subtraction, preserving the input units and prior processing. Values can be negative and are shown without forcing them to zero. Normalization is disabled and baseline-residual QC is not evaluated. The illustrative D65/CIE sRGB mapping remains available from the final unbaselined analysis curve.</li>
  <li><b>Single nm</b>: The entered wavelength is the <em>requested</em> reference. PASA uses the nearest eligible native measured node in the full loaded source; that effective node can differ from the request and can lie outside the selected analysis range. Requested/effective wavelengths, one-point statistic, and outside-range use are archived per sample. The result remains sensitive to noise, blank mismatch, residual analyte absorption, and wavelength-dependent background.</li>
  <li><b>Window median baseline</b>: PASA subtracts the median only when at least three eligible native measured points occur within the requested window of the full loaded source. Those points can lie outside the selected analysis range. A window with fewer than three eligible points is refused and not relocated. Requested/effective bounds, point count, statistic, and outside-range use are archived per sample.</li>
</ul>

<h4>3. Signal Conditioning / Smoothing</h4>
<ul>
  <li><b>Resample to fixed grid</b>: Optionally puts samples onto a common evenly-spaced wavelength axis. A finer/equal target uses <b>linear interpolation</b>; interpolated values are estimates, not new measured observations. A coarser target uses <b>integral-based bin averaging</b>. That method targets preservation of full-range trapezoidal area when measured coverage, output range, and edge-bin conditions permit, but arbitrary band AUC can change when bins straddle band boundaries. The notification reports the method and steps.</li>
  <li><b>Savitzky&ndash;Golay (SG)</b>: local polynomial smoothing. Under suitable window/order settings it can retain local feature shape better than a same-width boxcar, but it can still shift, broaden, or distort features; inspect sensitivity to window, order, and grid. Smoothing is not resampling, and similarity, noise QC, and deconvolution use their separately documented paths.</li>
  <li><b>Moving average (MA)</b>: Simple boxcar average over <i>n</i> points. Faster but broadens peaks slightly. Useful when peak sharpness is less critical.</li>
</ul>
<p><b>Why 1.25&times; and centered bins?</b> A <b>1.25&times; margin</b> prevents a trivially-coarser grid from needlessly switching methods. Above it, centered bins (node &plusmn; step/2) average each bin&rsquo;s trapezoidal integral onto the requested grid. This is a conditional full-range area target, not a guarantee for every range or band: incomplete coverage and edge bins can affect the full-range result, and an arbitrary band AUC can change when a bin crosses its boundary.</p>

<h4>4. Scaling / Normalization</h4>
<ul>
  <li><b>Dilution correction factor</b>: Multiplies measured absorbance values by a nominal scale before processing. Using the recorded dilution gives an undiluted-equivalent absorbance scale only when Beer&ndash;Lambert linearity, blank treatment, path length, matrix, and instrument response are appropriate and matched; it does not recover concentration or correct scattering, stray light, or other non-linearity. Values &le;0 are treated as 1. <b>Blank basis (known limitation):</b> if you also upload a measured blank for deconvolution, it is subtracted <i>after</i> dilution scaling (<code>dilution &times; measured &minus; blank</code>). That form applies only when the blank is already in <b>undiluted-equivalent</b> units; a blank measured on the same acquisition scale as the diluted sample would instead need <code>dilution &times; (measured &minus; blank)</code>. The file carries no blank-basis metadata, so the app cannot infer which form applies. Record the basis alongside the result.</li>
  <li><b>Normalization methods</b> (Analysis settings): None (no normalization), Max&rarr;target (scale so spectral peak = target), Value@&lambda;&rarr;target, Total area&rarr;target, Band peak&rarr;target, Band AUC&rarr;target. The target must be finite and strictly greater than 0; zero or negative targets are refused. The Spectra current-view panel uses a readable description such as <b>Band peak: Qy, target value: 1</b>; check any accompanying processing warnings to see whether the requested method was applied.</li>
  <li><b>Normalization requires baseline correction.</b> If you try to normalize while baseline correction is off, the app will warn you and reset normalization to None. Normalizing unbaselined OD is invalid because the instrument offset enters the scaling factor.</li>
  <li><b>Normalization is applied after smoothing</b>, so the reported band peak value (post-norm) in the Metrics tab exactly equals the target. For example, Band peak &rarr; target = 1 on the Qy band will show Qy Peak value (post-norm) = 1.0000 in the Metrics table.</li>
  <li><b>AUC columns</b>: <em>AUC (processed)</em> uses the basis selected on the Band AUC tab. Raw and baseline-corrected band/total AUC use <b>native measured wavelength coordinates</b>; display resampling is not an input. Smoothed and normalized AUC use the <b>processed-grid</b> curve and are resolution-dependent; resampling is optional. <em>AUC (pre-baseline, dil-scaled)</em> applies dilution only. <b>Coverage:</b> uncovered intervals are excluded using the adaptive effective-gap rule <code>min(max(3, 1.25 * native_step), 25) nm</code> when a native step is estimable (3&nbsp;nm floor, 25&nbsp;nm ceiling), rather than an always-3-nm cutoff. A fully unmeasured band reads as &mdash;. The Metrics export reports effective range, largest native gap, and unmeasured span.</li>
</ul>

<h4>5. Bands / Metrics (adaptive)</h4>
<p>Define wavelength ranges for each spectral band. Ratios and AUC metrics are computed within these windows. The active band set adapts to two controls in <b>Analysis settings</b>: the <b>Organism / pigment system</b> preset and the <b>Sample type</b> control (<em>Protein sample</em> = purified proteins or thylakoid membranes; <em>Isolated phycobiliprotein</em> = a purified phycobiliprotein, offered only for cyanobacteria and red algae; <em>Cells / Lysate</em> = whole cells or lysate retaining assembled phycobilisomes). The control is shown for cyanobacteria, red, and green algae and hidden for plants.</p>
<ul>
  <li><b>600&ndash;650 nm band:</b> labeled <b>Chl <i>a</i> Q<sub>x</sub> / Vibronic Band</b> by default; becomes <b>PBS</b> for cyanobacteria + Cells/Lysate and red algae + Cells/Lysate; becomes <b>Phycobiliprotein</b> for cyanobacteria + Isolated phycobiliprotein and red algae + Isolated phycobiliprotein.</li>
  <li><b>Isolated phycobiliprotein vs Cells/Lysate:</b> both presets label the 600&ndash;650 nm analysis window for possible phycobiliprotein-associated structure, while only the Cells/Lysate preset uses the <b>PBS</b> label for an assembled-phycobilisome context. These labels configure windows; they do not establish which pigment or complex is present and do not quantify one.</li>
  <li><b>Phycoerythrin (PE), 490&ndash;570 nm:</b> shown only for red algae + Cells/Lysate (between Carotenoid and PBS).</li>
  <li><b>Chl <i>b</i> Q<sub>y</sub>, 640&ndash;657 nm:</b> shown for green algae and plants; the 660&ndash;690 band is then renamed <b>Chl <i>a</i> Q<sub>y</sub></b>.</li>
  <li><b>Carotenoid</b> (430&ndash;520) and <b>Soret / Bx</b> (420&ndash;460) are always present.</li>
</ul>
<p><b>Why chlorophyll bands and phycobiliprotein bands are named differently.</b> Chlorophyll bands carry <em>electronic-transition</em> names (Q<sub>y</sub>, Q<sub>x</sub>, Soret/B) because chlorins follow the four-orbital Gouterman scheme. Phycobiliprotein / PBS bands instead carry <em>pigment or complex</em> names, because open-chain bilins are not cyclic tetrapyrroles and have no Gouterman Q/B transition scheme. This naming asymmetry is physically correct, not an inconsistency.</p>
<p><b>Organism scope.</b> The presets cover chlorophyll <i>a</i>/<i>b</i> systems with phycobiliproteins (cyanobacteria, red and green algae, plants). Chlorophyll <i>c</i>/<i>d</i>/<i>f</i> systems (diatoms, dinoflagellates, brown algae, <i>Acaryochloris</i>, and Chl <i>f</i>-containing cyanobacteria) are out of scope: their band positions and identities are not modeled here.</p>
<p>Sliders for PE and Chl <i>b</i> Q<sub>y</sub> appear only when their band is active; <b>Reset Bands to Defaults</b> resets every active band. All ratios, OD-at-peak values, AUC charts, QC, plots, and exports follow the active band set automatically.</p>
<p>The <b>Metrics</b> tab reports AUC (processed and raw), peak positions and values (pre- and post-norm), OD values per band, and band ratios for every sample. Use the layout selector to arrange the table by sample (Stacked), by band (By band), or as separate tables per band. The <b>Copy the entire table</b> button copies the full data as tab-separated text for pasting into Excel.</p>
<p><b>Wide Metrics tables:</b> horizontal scrollbars at the top and bottom stay synchronized. Translucent arrows at the sides also move the view left or right, so distant sample columns are reachable without scrolling to the bottom first. Each table has its own controls when separate tables per band are selected. Scrolling changes the visible columns, not the full table or its exported content.</p>
<p>The <b>Band AUC</b> tab visualizes the band-wise AUC as bar charts (one panel per sample, with optional shared y-axis for visual comparability) or as a radar/spider chart. In bar chart mode, check <em>Use common Y-axis across samples</em> to make bar heights directly comparable across panels. In radar chart mode, toggle <em>Overlay all samples in one panel</em> to see all samples on one chart.</p>

<h4>6. Plots / Tabs / QC / Exports</h4>
<ul>
  <li><b>Spectra tab</b>: Open <b>Customize spectra plot</b> above the graph. <b>Curve style</b> contains overlay (all samples on one axis), facets (one panel per sample, optionally sharing a Y axis), palette, line style and width. <b>Titles and axes</b> contains the four title fields (X axis, Y axis, chart and legend), axis/gridline intensity and band shading. The X- and Y-axis intensity sliders affect axis lines; tick labels follow the active theme. Open <b>Wavelength probe</b> or <b>Band peaks and labels</b>, then use its On/Off switch to enable the feature. Opening or closing a section keeps the feature setting unchanged. Enabled probe and peak result tables appear below the graph.</li>
  <li><b>3D overlay (Spectra tab)</b>: The <b>3D overlay</b> switch in the control strip turns the flat overlay into an interactive 3D <em>waterfall</em> &mdash; each selected sample becomes a filled ridge at its own depth, colored the same as its 2D curve (wavelength runs left&ndash;right, samples run front&ndash;back, absorbance is the height). It is rendered in your browser with WebGL, so you move the view directly with the mouse and the app does <em>not</em> re-draw while you do:
    <ul>
      <li><b>Rotate / tilt</b>: click and hold the <b>left</b> mouse button inside the plot and drag &mdash; left/right spins the point of view (the 0&ndash;360&deg; rotation), up/down tilts the scene.</li>
      <li><b>Zoom (depth of view)</b>: scroll the mouse wheel (or pinch on a trackpad/touch screen) to move closer or further away.</li>
      <li><b>Pan</b>: hold the <b>right</b> mouse button (or Ctrl/Cmd + left-drag) and drag to slide the scene.</li>
      <li><b>Reset the view</b>: double-click empty space, or use the little tool-bar (a &ldquo;home&rdquo; / camera icon) that appears at the top-right when you hover over the plot.</li>
      <li><b>Show / hide a sample</b>: click its name in the legend (double-click to isolate just that one).</li>
      <li><b>Read a value</b>: hover a ridge to see its wavelength and absorbance.</li>
    </ul>
    When 3D is enabled, open <b>3D rendering</b> within <b>Customize spectra plot</b> for fill opacity, resolution (points per curve), sample-label distance, probe-plane opacity when the probe is on, and export resolution. Lower fill opacity to see ridges behind; lower points per curve when a large plot feels sluggish. Export resolution changes image pixel dimensions. The 2D-only appearance controls are hidden in 3D. The overlay needs the optional <code>plotly</code> package; if it is absent, an explanatory hint appears.</li>
  <li><b>Data Quality tab</b>: Per-sample QC inventories all loaded columns, with analysis-dependent residual/noise fields evaluated only for selected samples and deselected rows explicitly Not evaluated. Baseline residual is a native-coordinate local/window mean with exact per-row bounds, point count, statistic, and residual-specific class. Raw-file thresholds and high ordinary-Pearson-correlation candidates are review prompts, not diagnoses or identity findings. Sample similarity uses the separately documented selected-sample analysis curves.</li>
  <li><b>Sample Color tab</b>: Shows an illustrative D65/CIE sRGB mapping; PASA has no path-length input and does not predict a physical cuvette appearance or calibrated color. The <b>Target value at selected reference feature</b> control rescales a Qy-window, blue-window, or global numerical feature before rendering. For a low-signal curve, the displayed/exported effective target equals the request multiplied by the operational rendering-confidence factor. The integral spans 380&ndash;780 nm; when finite curve coverage is shorter, the nearest endpoint absorbance is held flat and the exact unmeasured spans are displayed/exported. The transform T = 10<sup>&minus;value</sup> has physical-transmittance meaning only when the final values are verified decadic absorbance on the applicable optical basis. Normalized or other non-OD/arbitrary inputs are illustrative. Negative final values are clamped to zero for rendering only; quantitative curves and metrics are not clamped by this color step.</li>
  <li><b>Reading the Sample color scene</b>: Select Yes for a visibly colored sample to show the cuvettes on a static photographic lab bench. The light source and textured background help illustrate transparent liquid; no animated light beam, filter, detector or spectrum screen is added. Select one sample or turn on <b>Show all sample colors</b> to wrap selected samples into responsive rows. For example, a wide view around 1100 pixels can show fifteen samples as three rows of five. Choose <b>Scene background: Dark or Light</b> for the original blue-gray laboratory or a white-painted textured bench and walls. This choice is independent of the app theme, is saved with session settings, and applies to image exports without changing calculated sample colors. The image retains sample names. Open the <b>Color details</b> arrow below it for the table of exact hexadecimal sRGB codes, full sample names and rendering information. This table is folded by default; the shaded glass scene is illustrative.</li>
  <li><b>Exports</b>: Use <b>Save session</b> and <b>Export</b> in the header for a session snapshot and a state-aware complete ZIP; processed-data downloads are in <b>Analysis settings</b>. The ZIP contains every applicable distinct table, plot, report, measured blank, and a full snapshot; its manifest and required-member registry are verified before delivery. It preserves PASA&rsquo;s parsed active wide table and state, not necessarily the exact original uploaded byte stream or byte-for-byte source-file formatting.</li>
</ul>
<ul>
  <li><b>Display controls (Spectra &rarr; Customize spectra plot)</b>: Overlay/facets, palette (Okabe&ndash;Ito, Viridis, Set1, Dark2 or ggplot default), line-pattern cycling, line width, titles, axis/gridline intensity and band highlighting are presentation options. Configure numerical band limits and normalization in the separate Analysis settings tab.</li>
  <li><b>QC Thresholds</b> (Data Quality tab &rarr; <b>Per-sample QC</b> view):
    <ul>
      <li><b>Baseline residual tolerance</b>: Flag selected samples whose mean native-coordinate, baseline-corrected value in the exact archived diagnostic bounds exceeds this threshold. A single-reference local window is centered on the per-sample effective native subtraction node; a window-median baseline uses the configured window itself. Sign and magnitude do not identify a cause.</li>
      <li><b>High-signal/saturation-risk threshold</b>: Flag samples with any raw OD above this value for review. This is an instrument-agnostic heuristic, not a diagnosis of detector saturation.</li>
      <li><b>Duplicate-detection r cutoff</b>: Flag pairs with ordinary Pearson r above this value for provenance review. Correlation and the fitted amplitude slope do not establish duplicate identity.</li>
    </ul>
  </li>
  <li><b>Dyslexia-friendly toggle</b> (in the <b>Theme</b> menu, top navigation bar): switches the whole app to a dyslexia-friendly typeface (OpenDyslexic / Atkinson Hyperlegible where available, otherwise a well-spaced sans-serif) with increased letter- and word-spacing and taller lines, so longer passages of text are easier to read. It layers on top of whichever color theme (Light / Dark / Midnight Teal / High-Contrast / Sepia) is active and changes only how text is displayed, not the analysis or any result. Toggle it off to return to the standard typeface.</li>
</ul>

<h4>6a. Data Quality: “Per-sample QC” vs “Sample similarity (shape-based)”</h4>
<p>The Data Quality tab has two views. Per-sample QC inventories all loaded columns; analysis-dependent diagnostics are evaluated only for selected samples, so deselected rows are Not evaluated rather than passed. Sample similarity uses selected evaluable samples.</p>
<p>Use <b>Compare</b> to select the view. Per-sample controls are under <b>QC thresholds</b>. In Sample similarity, open <b>Network appearance</b> for layout and relationship metric, <b>Labels and visible connections</b> for names, values and edge filtering, <b>Calculation limit</b> for the trace budget, or <b>How similarity is calculated</b> for the method and tier definitions. The current budget and display-coverage messages remain visible. Opening a group does not change its settings.</p>
<ul>
  <li><b>Per-sample QC</b> is a single-sample operational threshold screen. It reports:
    <ul>
      <li><b>Baseline residual tolerance</b> &mdash; whether the native-coordinate local/window mean within the archived per-row bounds exceeds the selected tolerance. Chart color represents this residual-specific class, not overall QC status.</li>
      <li><b>Raw-OD review threshold</b> &mdash; whether any raw value reaches the editable threshold; instrument linearity must be established from manufacturer or study validation.</li>
      <li><b>Possible-duplicate r cutoff</b> &mdash; whether a pair has very high Pearson correlation and therefore merits provenance review; correlation does not prove duplicate identity.</li>
    </ul>
    Output: informational flags and a baseline-residual chart. PASA does not decide whether a spectrum is trustworthy, should be remeasured, or should be discarded.</li>
  <li><b>Sample similarity (shape-based)</b> compares every pair. Its metrics are invariant or insensitive to a common positive multiplicative scale as specified:
    <ul>
      <li><b>Wavelength/trapezoid-weighted spectral angle (SAM variant)</b> &mdash; angular distance computed with PASA&rsquo;s trapezoidal wavelength weights on the pair-local sorted union of both wavelength axes after within-span linear interpolation and joint coverage/gap masking; lower = more similar shape. The spectral-angle concept follows Kruse et al. (1993), while the wavelength weighting and projection are documented PASA implementation choices. The mathematical angle is invariant to a common positive multiplicative factor and, <b>together with weighted r on the same pair-local grid</b>, drives the four-tier operational label.</li>
      <li><b>Weighted r (pre-normalization analysis curve)</b> &mdash; PASA&rsquo;s wavelength/trapezoid-weighted Pearson correlation on the pair-local sorted union of the pre-normalization analysis-curve wavelength axes under the selected baseline setting. Each curve is linearly interpolated only within its own span, then joint coverage and gap masks exclude unsupported nodes. Endpoint half-weights mean it can differ from ordinary Pearson r even on a uniform finite grid. It saturates near 1 for pairs that share a broad envelope and is one of the two label drivers. The Per-sample QC high-correlation flag is a separate ordinary-Pearson calculation on uploaded values.</li>
      <li><b>r (2nd derivative)</b> &mdash; PASA&rsquo;s wavelength/trapezoid-weighted Pearson correlation of the curves&rsquo; second derivatives; endpoint half-weights mean it can differ from ordinary Pearson r even on a uniform finite grid. This derivative metric is retained as an <b>advisory diagnostic only</b> and does <i>not</i> drive the verdict. It is computed on an <i>internally</i> Savitzky&ndash;Golay-smoothed copy of each curve.</li>
    </ul>
    Output: the similarity network (and table) assigning each pair one of four descriptive operational tiers (Very high &rarr; Lower shape similarity). It groups samples by spectral shape so you can spot outliers, mislabeled samples, or unexpected variation <i>between</i> samples.</li>
</ul>
<p><b>In short:</b> Per-sample QC reports operational threshold exceedances; Sample similarity reports pairwise numerical shape relationships. Neither certifies data quality, identity, or biological interpretation. Use provenance, instrument validation, controls, and independent assays for study decisions.</p>
<p><b>Where the QC thresholds come from:</b> the Per-sample QC cutoffs (baseline-residual tolerance, saturation ceiling, duplicate-detection r) and noise PASS/CAUTION/FAIL boundaries are <b>operational development defaults</b>, not literature, standards, or independently validated decision limits. They were exercised on a limited local development collection and produce informational flags without excluding or hiding samples. Their transferability to another instrument, matrix, or study endpoint has not been established. The duplicate, baseline and saturation settings are editable in the Per-sample QC view under &ldquo;QC thresholds&rdquo;. Noise cutoffs are in the noise section under &ldquo;Show detailed QC tables&rdquo;; justify and, where necessary, recalibrate them for the intended use.</p>

<h4>7. Cell Growth</h4>
<p>Estimates an apparent OD-derived log-linear rate (&mu;) and OD doubling time for a <b>single strain</b> from an optical-density time series. Interpreting &mu; as a biological specific growth rate requires an independently justified OD&ndash;biomass relationship. Two input modes:</p>
<ul>
  <li><b>From loaded spectra:</b> becomes active when you select <b>Cells / Lysate</b> for a unicellular organism (cyanobacteria, red, or green algae). The activated samples are interpreted as a time series. Pick a <b>tracking wavelength for OD</b> (720&ndash;750 nm; 730/750 nm are often used to reduce pigment-absorption interference, but the wavelength and OD&ndash;biomass relationship must be justified for the matrix, instrument, and study). For each replicate, use the multi-select dropdown to assign which samples (in time order) belong to it.</li>
  <li><b>Manual entry:</b> tick <em>Enter OD values manually instead of using the loaded spectra</em> to type OD values into a grid. Manual entry is always available, independent of Sample type in Analysis settings. Column headers (e.g. &ldquo;0 h, 12 h, 24 h&hellip;&rdquo; or &ldquo;0 d, 1 d, 2 d&hellip;&rdquo;) update from the time unit and interval; the first column is the t = 0 measurement. The <b>Load built-in demo data</b> button populates a 3-replicate &times; 8-timepoint OD matrix so you can explore the tab without your own data.</li>
</ul>
<p>Set the <b>time unit</b> (Days/Hours), any positive <b>interval size</b> (fractional values are retained), and the <b>number of replicates</b> (1&ndash;10). Intervals are assumed <b>equidistant</b>. A live summary sentence restates your inputs.</p>
<p><b>Provide uploaded as-measured, instrument-blanked OD.</b> When using loaded spectra an exact native node is used when present; otherwise a gap-guarded linear interpolation may be used only when the tracking wavelength lies inside the native range and its bracketing gap is no wider than the effective coverage guard. Endpoint holding and interpolation across an over-wide internal gap are refused. The observations export records source sample, tracking wavelength, exact/interpolated/unavailable method, reason, bracketing wavelengths, bracketing gap, effective guard, and source-point counts for every mapped sample/timepoint. Manual-entry values are used verbatim and typed as manual entries. The app does not add a second blank, so zero/blank your instrument on medium first. What is intentionally bypassed is the <em>spectral-tail baseline</em> in <b>Analysis settings</b> (subtracting A at the reference &lambda; from every wavelength): at a 720&ndash;750 nm tracking wavelength that would subtract the turbidity signal itself and flatten the fit. A constant medium/instrument blank <em>is</em> a genuine offset that biases &mu; at low OD, so blank on the spectrophotometer before entering data.</p>
<p><b>Complete automatic window-selection contract.</b> Each replicate is sorted by time and every contiguous window is considered. A qualifying window requires: at least the tier-specific point count; finite positive OD; strictly increasing time; every interval log-slope &gt; 0; total log-OD rise &ge; 10<sup>&minus;9</sup>; interval-&mu; CV &le; 0.35 when there are at least three intervals; finite OLS &mu; &gt; 0; R<sup>2</sup> &ge; 0.98; and, when the model-conditional slope p-value is finite, p &lt; 0.005. The <b>high-consistency</b> tier requires at least four points and additionally rejects a finite quadratic-curvature p &lt; 0.05; a non-finite curvature p does not reject. If that tier fails, the same window may enter the <b>preliminary</b> tier with at least three points and without the curvature rejection. Eligible candidates rank by tier (high-consistency first), point count descending, time span descending, R<sup>2</sup> descending, then interval-&mu; CV ascending with missing CV last. A non-finite slope p-value does not reject. These are operational selection gates, not a calibrated biological growth test. The downloadable <code>growth_window_selection_contract.csv</code> is generated directly from the engine constants and records this contract machine-readably.</p>
<p><b>Outputs.</b> By default you see the apparent OD-derived log-linear rate &mu;, OD doubling time (t<sub>d</sub> = ln(2)/&mu;), a presentation-quality growth curve (linear, plus a log10 panel when the optional <code>patchwork</code> package is installed), and a plain-language interpretation. A conditional post-selection sensitivity interval for &mu; is reported only with &ge;3 fitted replicates; because the window is auto-selected it is not a calibrated confidence interval. Tick <em>Show advanced / supplementary outputs</em> for per-replicate fits, all qualifying window candidates, detected phase boundaries, the source/extraction observations CSV, the machine-readable window contract, and CSV/PNG/PDF downloads.</p>

<p><b>Pasting manual growth data:</b> enter a rectangular table in the paste area, then click <b>Apply pasted data</b>. Opening this area does not overwrite edited cells. Tab- or semicolon-delimited tables may use decimal commas. Invalid values or excess rows/columns are refused before the grid changes.</p>
<h4>8. Save / reload session</h4>
<p>The <b>Session snapshot</b> block (in <b>Analysis settings</b>, mirrored under <b>Data preview</b> on the Summary tab) writes a single text file &mdash; <code>PASA_state.txt</code> &mdash; that captures the current analysis so you can reload it later. Two synced checkboxes pick what to include:</p>
<ul>
  <li><b>Settings</b>: every analysis / display / QC control. Stored as machine-parseable <code>key=value</code> lines so they round-trip back to the UI exactly. Cell Growth scalars (unit, interval, replicate count, tracking wavelength) are also stored under <b>Settings</b>.</li>
  <li><b>Input data</b>: the currently active parsed wide table (the loaded samples) plus &mdash; if you used the Cell Growth manual grid &mdash; the replicate &times; timepoint OD matrix. For Cell Growth using loaded spectra the replicate-to-sample mapping is stored instead. This supports analytical state replay; it is not a byte-identical preservation of the original uploaded file.</li>
</ul>
<p>Click <b>Save session</b> in the header, or <b>Export session snapshot (TXT)</b> on the Summary tab. <b>Download everything (ZIP)</b> always includes the full version of this state (Settings, Input data, Cell Growth, and the measured-blank section) regardless of the standalone-export checkboxes. Reload by setting <b>Data source</b> on the <b>Input data</b> tab to <b>Import session</b> and uploading the file; a dialog lists only the sections actually present in the file, so you can selectively apply Settings, Input data, Cell Growth data, the measured deconvolution blank, or any combination. When you tick <b>Input data</b> and confirm, the saved samples become the active dataset and the wavelength range and band sliders are re-detected. Leave it unticked to preserve current data. The Advanced-Mode toggle, dynamic sample and normalization-band selections, per-sample dilution values, and deconvolution controls are stored under <b>Settings</b>; the numeric measured-blank curve is stored separately under <code>[DECON_BLANK_DATA]</code>.</p>

<h4>9. Advanced Mode &amp; Spectral Deconvolution</h4>
<p>Deconvolution and its optional bootstrap use a background worker when available; <b>Cancel deconvolution</b> stops the requested work. The interface remains available while the worker runs. Bootstrap requires the worker and is refused with an explanation if it is unavailable; ordinary fitting can use the documented fallback. A previous fit remains visible while replacement work is pending.</p>
<p><b>Advanced Mode</b> is an optional switch in the top navigation bar. Turning it <b>ON</b> inserts <b>Deconvolution</b> between Data Quality and Sample color. Turning it <b>OFF</b> removes that tab; if Deconvolution was active, the app selects an available tab. Enabling the mode does not run a fit. It starts OFF for a fresh analysis, while an imported session can restore its saved choice.</p>
<ul>
  <li><b>What it does</b>: The Deconvolution tab represents the processed absorbance curve as a sum of <b>pseudo-Voigt components</b> sharing one Gaussian&ndash;Lorentzian shape parameter and reports each fitted component&rsquo;s center, FWHM, height, and area. This is a phenomenological curve description, not recovery of pigments, transitions, or molecular contributions.</li>
  <li><b>vs. Band-AUC</b>: <b>Band AUC</b> integrates the measured curve directly between fixed wavelength limits with no peak-shape assumption. <b>Deconvolution</b> partitions a fitted pseudo-Voigt model among its components. They answer different descriptive questions and are not interchangeable.</li>
  <li><b>Which curve is fitted</b>: Deconvolution preferentially fits processed analysis-curve values at native measured wavelength coordinates after the selected analysis range, dilution scaling, baseline subtraction, and optional normalization. Display resampling and smoothing are not fit inputs. Requested normalization must be effectively applied on that fit curve; otherwise the fit is refused and its reason/divisor are reported. Run metadata and exports use this effective status rather than inferring units from the requested method.</li>
  <li><b>Controls</b>: <b>Sample</b> (which processed curve), <b>Sample class</b> (loads configurable starting values), <b>Min/Max components</b>, <b>Search-depth limit</b> (Tested range K &le; 4 by default; explicit Advanced opt-in up to K = 20), <b>Selection criterion</b> (AIC-like, BIC-like, or AICc-like plug-in score), and <b>Advanced settings</b>. Every K &gt; 4 lies outside the separately distributed recovery study and must be reported as an uncharacterized sensitivity analysis.</li>
  <li><b>Reading the K-selection table</b>: The app fits every component count from Min to Max and lists R&sup2;, RMSE, and the AIC-like/BIC-like/AICc-like plug-in parsimony scores. Selected K is the lowest selected-criterion score among candidates with a finite score, accepted optimizer, and no operational-resolution flag. The raw all-candidate minimum is marked separately. Neither minimum proves a true component count.</li>
  <li><b>AIC-like, BIC-like, and AICc-like plug-in scores</b>: PASA applies the familiar penalty forms to a <b>plug-in AR(1)-penalized</b> residual log-likelihood. The residual correlation &rho; is estimated after each curve fit and plugged in rather than jointly maximized, so these are reproducible parsimony heuristics, not classical likelihood-based information criteria and not calibrated counts of molecular species. The lowercase <code>aic</code>/<code>bic</code>/<code>aicc</code> fields remain in machine exports only as backward-compatible aliases.</li>
  <li><b>Derivative-seeded vs. residual-seeded model components</b>: the second derivative supplies a set of candidate initial features. If a larger K is requested, additional phenomenological components are initialized by <b>residual deflation</b>, up to k_max and the numerical feasibility guard. Neither seed route establishes a real pigment band; residual-seeded components are flagged as especially tentative. Why the distinction matters:
    <ul>
      <li><b>Identifiability.</b> A residual-seeded component can be weakly constrained; its center, width, and height may depend strongly on bounds and initialization. Derivative minima are only candidate seeds and may merge overlapping structure or respond to noise. Treat every fitted component as model-conditional and inspect parameter, residual, and sensitivity diagnostics.</li>
      <li><b>Fitting noise.</b> Extra components can absorb noise and nudge R&sup2; upward. The plug-in parsimony scores penalize parameters but do not prove physical reality or prevent every noise-driven fit.</li>
      <li><b>Seeding sensitivity.</b> Changing the <b>Seeding window</b> changes the candidate-feature count, while k_max changes search depth. Compare results across justified settings; no seed route is evidence of a molecular band.</li>
      <li><b>Honest reporting.</b> Report the searched K range, seeding method, bounds, preprocessing, selected plug-in score, and sensitivity results. Do not report K as a recovered molecular-species or pigment-band count.</li>
    </ul>
  </li>
  <li><b>Reading the method badge</b>: A badge above the plot reports which fitter actually ran. <b>nlsLM</b> (the bounded Levenberg&ndash;Marquardt fit from <code>minpack.lm</code>) is the preferred path and can report local-curvature, model-conditional standard-error approximations when the covariance calculation is estimable; otherwise the corresponding cells are blank. PASA multiplies available approximations by a heuristic scalar derived from plug-in lag-1 residual correlation; this is not a calibrated AR(1) covariance model and has no coverage guarantee. If <code>minpack.lm</code> is unavailable or the fit fails to converge, the app falls back to <b>L-BFGS-B</b> and reports no standard errors.</li>
  <li><b>Reading the interpretation notes</b>: The panel applies deterministic diagnostics to the current fit, including near-noise components, constraint proximity, search-bound sensitivity, score agreement, edge proximity, and overlap. If no condition is flagged, that means only that none of these programmed rules fired; it is not scientific validation. Read the notes with the residuals, sensitivity analyses, and honesty caveat.</li>
  <li><b>Requirements</b>: Baseline subtraction must be ON. The optional <code>minpack.lm</code> package is recommended; it enables the nlsLM path and model-conditional standard-error calculation when estimable. Without it the fit still runs via the L-BFGS-B fallback, but standard-error cells show &ldquo;&mdash;&rdquo;. The tab tells you exactly what to enable or install.</li>
</ul>
<p><b>Stated limit &mdash; deconvolution requires a complete uniform wavelength grid:</b> derivative seeding and the residual-order model assume evenly spaced consecutive coordinates. PASA therefore checks the native wavelength axis before fitting. Axes whose small departures are compatible with stored-coordinate rounding may be reconstructed to a uniform lattice; when reconstruction moves coordinates, PASA also attempts an observed-coordinate sensitivity re-fit and reports changes in selected K, score preference, fitted centers, or the inability to complete that comparison. Materially irregular, drifting, mixed-resolution, periodic, or gapped axes are refused rather than silently resampled. Axes that cannot be distinguished from a missing-node pattern at the available coordinate precision are also refused as ambiguous. This is a conservative engineering policy for the packaged algorithm, not a scientifically validated rule for every instrument or sampling design. If an axis is refused, provide wavelengths at finer precision, restrict the analysis to a complete uniformly sampled region, or supply a spectrum on a complete uniform grid.</p>
<p><b>Honesty caveat:</b> Pseudo-Voigt deconvolution is a <em>phenomenological</em> curve-modeling technique, not a measurement of chemical species. A good fit means the curve <em>can be described</em> by that set of bands &mdash; it is <b>not</b> proof that those pigments or transitions are present, nor of their concentrations, and several different band sets can fit the same curve almost equally well. Treat fitted centers and areas as a quantitative description of curve shape to corroborate against your own knowledge of the sample, not as standalone identification or quantification.</p>
<hr/>

<h4>10. Feedback and contact</h4>
<p>The <b>Feedback</b> tab follows References and is also available in <b>Contacts</b> immediately below LinkedIn. Choose a reaction and add an optional comment. For a problem report, describe the tab, the steps you took, what you expected and what happened.</p>
<ul>
  <li><b>Send feedback</b> uses the existing PASA Google Form without requesting a name, email address, or sign-in. Choose a reaction and acknowledge the notice before sending. Only your reaction, comment, submission time (UTC), and app version are sent; Google also receives ordinary connection metadata.</li>
  <li><b>Save feedback (.txt)</b> downloads a local draft. On an offline computer, save it and transfer it to a connected device to send later.</li>
  <li><b>Compose email</b> optionally prepares a draft in your email application. Review and send it there; sending reveals the email identity you use. If direct sending fails or receipt is unconfirmed, your draft remains available to save. An operator can disable the direct service or supply a configured alternative.</li>
</ul>
<p>Spectra, sample names and analysis results are not attached automatically. Contacts also provides Email, X (Twitter) and LinkedIn. The guided tours introduce these routes without opening external destinations or submitting a message.</p>

<h3>Science Reference</h3>
<h4>Band Assignments</h4>
<ul>
  <li><b>Qy (660&ndash;690 nm)</b>: A configurable starting window for the red chlorophyll absorption region; the label does not establish pigment identity. Qy absorbance can be a study-specific relative descriptor only when path length, dilution, baseline, sample matrix, and instrument are controlled; it is not chlorophyll concentration without an applicable coefficient or calibration. <b>Whole cells / thylakoids:</b> package/flattening effects and scattering can distort apparent spectra, so chlorophyll-content comparisons require an independently justified method.</li>
  <li><b>Soret / Bx (420&ndash;460 nm)</b>: The strong blue chlorophyll absorption region. Relative Soret and Qy amplitudes depend on pigment composition, solvent or protein environment, path length, concentration, blanking, and instrument response; PASA assumes no universal Soret/Qy ratio.</li>
  <li><b>Carotenoid (430&ndash;520 nm default; overlaps Soret tail at 430&ndash;460 nm)</b>: Carotenoids (&beta;-carotene, lutein, zeaxanthin, etc.) have major transitions at ~425, 450, and 480 nm. The default lower bound was moved from 460 to 430 nm to capture the dominant &beta;-carotene shoulder at ~450 nm; note that this range overlaps the Soret/Bx band (420&ndash;460 nm) between ~430&ndash;460 nm. Adjust both windows for your specific pigment system.</li>
  <li><b>Phycobilin / PBS (600&ndash;650 nm) &mdash; cyanobacteria and red algae</b>: Phycobiliproteins absorb here (phycocyanin ~620 nm, allophycocyanin ~650 nm). Note: Chl-a Qx (~636 nm) overlaps but is not the same as phycobilin absorption. For green algae and plants, the Organism preset ADDS a <b>Chl b (~640&ndash;657 nm)</b> band (chlorophyll b absorbs here, its Qy band being blue-shifted relative to Chl a); this 640&ndash;657 nm window overlaps the 600&ndash;650 nm band over 640&ndash;650 nm, so those two band AUCs both include that region and should not be summed there.</li>
</ul>
<h4>Why Baseline Correction Matters</h4>
<p>A far-red/NIR wavelength near 750 nm is often used as a reference when the particular sample, blank, and instrument support the assumption of low analyte absorption there. A non-zero value can reflect residual absorption, blank mismatch, instrument offset, scattering, or other artifacts. Subtracting the reference value removes only that single additive offset. It does <b>not</b> make spectra from different instruments directly comparable and does not correct wavelength calibration, spectral bandwidth/response, path length, detector non-linearity, stray light, or wavelength-dependent scattering &mdash; those require study- and instrument-specific controls.</p>
<p><b>Uploaded values when baseline correction is off:</b> When you uncheck &ldquo;Apply baseline correction,&rdquo; the app shows the uploaded values before PASA baseline subtraction, retaining their original units and any processing performed before import. Values can be negative for several source- or processing-specific reasons. PASA does not force them to zero; interpret them using the provenance of the input data.</p>
<p><b>Single nm vs Window median:</b> A single-nm <em>request</em> uses the nearest eligible native measured node in the full loaded source and is noise-sensitive at that effective one-point statistic. Window median uses the median only when at least three eligible native measured points occur in the requested full-source window; it is more robust to single-point noise but can overcorrect if the window contains real pigment absorption. Either method can use eligible source points outside the selected analysis range. Both warn if the request is below 730 nm, where some pigments may still absorb, and both refuse insufficient measured support rather than relocating the request/window.</p>
<p><b>Limitation of single-wavelength baseline correction:</b> A reference near 750 nm can be useful for some dilute, optically clear samples when its assumptions are justified. It does <em>not</em> correct wavelength-dependent scattering in turbid or concentrated samples. Mie scattering depends on particle size distribution, refractive index, geometry, and wavelength and need not follow a single power law (Bohren &amp; Huffman 1983). Over a limited range, PASA can fit an empirical <code>a&middot;&lambda;<sup>&minus;b</sup>&nbsp;+&nbsp;c</code> baseline, but fitted b is sample/model dependent and the subtraction is not a direct Mie/Rayleigh classification or universal physical correction. Residual analyte absorption, including absorption extending toward 750 nm in some preparations, can also bias either baseline approach.</p>
<h4>Beer&ndash;Lambert Law</h4>
<p>In the ideal linear Beer&ndash;Lambert regime, OD = &epsilon; &times; c &times; l, where &epsilon; is the molar absorption coefficient (L mol&#8315;&sup1; cm&#8315;&sup1;), c is concentration (mol/L), and l is path length (cm). Component absorbances are additive only for noninteracting components measured under compatible solvent/matrix, blank, path length, units, concentration, and instrument conditions. Arbitrary sums need not represent real mixtures when scattering, chemical interactions, inner-filter effects, nonlinearity, or mismatched conditions are present.</p>
<h4>OD at Qy Peak Convention</h4>
<p>OD at the Qy-region peak (after the selected baseline and dilution scaling) is a descriptive absorbance proxy, not a chlorophyll-content measurement. Converting absorbance to concentration requires a study-appropriate absorption coefficient or independent calibration together with controlled path length, dilution, blank, matrix, and instrument response. Changes in OD<sub>Qy</sub> can also reflect pigment environment, scattering, package effects, baseline choice, and preprocessing. For whole cells and thylakoids, these effects are especially important; use an independently justified extraction or calibration method for chlorophyll-content conclusions.</p>
<h4>Illustrative D65/CIE sRGB Mapping</h4>
<p>The &ldquo;Sample Color&rdquo; tab maps the final analysis curve through: (1) the selected baseline setting, dilution scale, smoothing, resampling, and any normalization; (2) optional numerical reference rescaling; (3) T = 10<sup>&minus;value</sup>; (4) the CIE 1931 2-degree observer under D65; and (5) XYZ-to-sRGB conversion. A low-signal safeguard can attenuate the request: <b>effective target = requested target &times; color_conf</b>; both targets, <code>color_conf</code>, and the low-signal state are displayed and exported. The numerical integral uses 380&ndash;780 nm. <code>approx(..., rule=2)</code> holds the nearest finite absorbance endpoint flat when coverage starts above 380 nm or ends below 780 nm; the finite coverage bounds and exact low/high extrapolated spans are displayed and exported per sample. Negative final values are clamped to zero for this rendering only. T has physical-transmittance meaning only when the final values are verified decadic absorbance on the applicable optical basis. Normalized values, concentration-specific coefficients, or other non-OD/arbitrary inputs produce an illustrative numerical mapping only. PASA has no path-length input and does not predict a physical cuvette appearance or calibrated color.</p>
<h4>Sample Similarity</h4>
<p>The <b>Sample similarity</b> table in the Data Quality tab computes three shape-based metrics for every pair using pre-normalization analysis curves under the selected baseline setting. The metrics describe shape and are invariant or insensitive to a common positive multiplicative scale as stated below:</p>
<ul>
  <li><b>Weighted r (pre-normalization analysis curve)</b>: PASA&rsquo;s wavelength/trapezoid-weighted Pearson correlation on the pair-local sorted union of both pre-normalization analysis-curve wavelength axes under the selected baseline setting. Each trace is linearly interpolated only within its own span; joint coverage and gap masks exclude unsupported nodes. Endpoint half-weights mean it can differ from ordinary Pearson r even on a uniform finite grid. Together with weighted SAM it is one of the two label drivers. A high value describes linear shape agreement, not sample identity. The editable Per-sample QC correlation flag is a separate ordinary-Pearson calculation on uploaded values.</li>
  <li><b>r (2nd deriv)</b>: PASA&rsquo;s wavelength/trapezoid-weighted Pearson correlation on the second derivative of each curve; endpoint half-weights mean it can differ from ordinary Pearson r even on a uniform finite grid. It is retained as an <b>advisory diagnostic only</b> and does not drive the verdict. It is computed on an <i>internally</i> Savitzky&ndash;Golay-smoothed copy of each curve (a fixed ~15 nm span converted to an odd point count, order 3; Savitzky &amp; Golay 1964).</li>
  <li><b>Wavelength/trapezoid-weighted spectral angle (SAM variant, deg)</b>: PASA computes the angle between two spectra with trapezoidal wavelength weights on their pair-local sorted union grid after within-span linear interpolation and joint coverage/gap masking. The spectral-angle concept follows Kruse et al. (1993); the wavelength weighting and projection are documented PASA implementation choices. The mathematical angle is invariant to a common positive multiplicative factor; lower values mean more similar shapes. Together with weighted r on the same pair-local grid it drives the four-tier operational label.</li>
</ul>
<p><b>Operational tiers (descriptive development labels):</b> the label is driven by PASA&rsquo;s wavelength/trapezoid-weighted Pearson <b>r</b> and weighted spectral angle (SAM variant) on the pair-local sorted union grid after within-span linear interpolation and joint coverage/gap masking, with weighted r(2nd derivative) advisory only. Endpoint half-weights mean weighted and ordinary metrics can differ even on a uniform finite grid. The packaged cut-points are: r &ge; 0.995 and weighted SAM &le; 2&deg; (&ldquo;Very high shape similarity&rdquo;); r &ge; 0.99 and weighted SAM &le; 4&deg; (&ldquo;High shape similarity&rdquo;); r &ge; 0.95 and weighted SAM &le; 10&deg; (&ldquo;Moderate shape similarity&rdquo;); otherwise &ldquo;Lower shape similarity&rdquo;. These cut-points were selected during development, were not independently validated, and must not be treated as biological identity or acceptance thresholds. Metrics are withheld when support is inadequate or configured processing is not comparable. Recalibrate the labels for a defined study endpoint and confirm interpretations with independent standards, controls, or assays.</p>
<p><b>Limitation:</b> These are purely spectral shape metrics. They are estimation aids for spotting gross differences, not a substitute for authenticated pigment standards, chromatography/HPLC, mass spectrometry where applicable, or another study-specific independent assay. Pearson r and SAM are also described in the <b>FAQ</b> tab under Sample similarity (shape-based).</p>
<hr/>
<h3>Operational defaults (not literature values)</h3>
<p>The constants below are <b>operational defaults</b> — reasoned engineering choices, <em>not</em> values prescribed by any peer-reviewed paper or standards body. Each is disclosed here for transparency; most are user-adjustable. None should be read as a physical constant or a validated limit. Where a genuine literature basis exists it is cited in the References tab and the Science Reference above.</p>
<ul>
  <li><b>Growth R<sup>2</sup> ≥ 0.98</b> (min_r2): configured linearity screen for a log-linear window; complements the model-conditional OLS slope and curvature screens. Not a literature-fixed value.</li>
  <li><b>Growth slope screen α = 0.005</b> (slope_alpha): a window is rejected when its model-conditional OLS log-linear slope p-value is finite and ≥ 0.005; a non-finite p-value does not reject. The high-consistency curvature gate similarly rejects only when its quadratic-term p-value is finite and &lt; 0.05. Because the window is selected automatically, these are operational filters rather than unqualified significance tests.</li>
  <li><b>Interval-μ CV ≤ 35%</b> (max_interval_mu_cv, applied with ≥ 3 intervals): windows whose point-to-point rates vary more are rejected as non-homogeneous — an in-house tolerance motivated by the constant-rate definition of balanced growth (Monod 1949), not a literature value.</li>
  <li><b>Similarity operational tiers</b> (Very high shape similarity: weighted analysis-curve r ≥ 0.995 &amp; weighted SAM ≤ 2°; High shape similarity: r ≥ 0.99 &amp; weighted SAM ≤ 4°; Moderate shape similarity: r ≥ 0.95 &amp; weighted SAM ≤ 10°; else Lower shape similarity): the label is driven by weighted Pearson correlation and PASA&rsquo;s wavelength/trapezoid-weighted spectral-angle variant on a pair-local sorted union grid after within-span linear interpolation and joint coverage/gap masking; the 2nd-derivative correlation is advisory only. Boundaries are development defaults selected on a limited local relationship collection, not literature-fixed or independently validated values, and describe spectral shape rather than identity.</li>
  <li><b>Internal Savitzky–Golay span = 15 nm, p = 3</b>: an advisory-derivative smoothing default exercised on development probes. The 15-nm physical span is converted to an odd point count on each pair-local wavelength grid, so the point count varies with sampling interval.</li>
  <li><b>Empirical exponent bound b_max = 4.5</b>: a numerical constraint on the optional inverse-power baseline fit. Values near the bound are flagged because they may be weakly identified or boundary-driven. The bound is an operational fitting choice, not a physical ceiling or a particle-size/scattering-regime classifier.</li>
  <li><b>Inverse-power baseline fit floor min_tail_pts = {{DECON_SCATTER_MIN_TAIL_PTS}}</b>: minimum finite tail points before the 3-parameter empirical model is fitted; below it the app uses a flat-median offset. <b>Acceptance RMSE ratio 0.9</b> and <b>blow-up guard 3×</b> are operational numerical safeguards, not physical scattering or detection thresholds.</li>
  <li><b>Seed spacing min_sep_nm = 6</b>, <b>center tolerance mu_tol = 8 nm</b>, <b>seed prominence 2%</b>: deconvolution seeding/fitting heuristics (de-duplication, reproducibility anchor, and a relative noise-rejection floor); not cited resolution limits.</li>
  <li><b>Band-width bounds</b>: per-class FWHM ceilings (40 / 50 / 60 nm) limit very broad, baseline-like components; these are not boundaries of physical possibility. The upper-bound control accepts 5–200 nm. Per-class floors (5 / 8 / 10 nm) are configurable development defaults, not values prescribed by the cited spectra or universal physical limits. Report the bounds and inspect sensitivity.</li>
  <li><b>Color-rendering weak-feature screen SPECTRUM_BLANK_SNR = 8</b> and <b>numerical backstop 5×10<sup>−4</sup> units</b>: a warning appears when the numerical feature-to-noise ratio is low, and a curve below the backstop is rendered neutral gray. These are operational rendering safeguards, not blank, pigment-presence, or detection-limit classifications.</li>
  <li><b>Resample binning trigger RESAMPLE_BIN_TOL = 1.25</b>: integral-based bin averaging is used only when the requested grid step exceeds 1.25× the native spacing, so a trivially coarser grid does not needlessly over-smooth. It conditionally targets full-range trapezoidal-area preservation; it does not guarantee arbitrary band-AUC invariance.</li>
  <li><b>Duplicate-review ordinary Pearson r ≥ 0.9999</b> (qc_dup_cor, editable): this flags very-high-correlation uploaded traces for provenance review. The fitted amplitude slope distinguishes near-unity from proportional scaling descriptively; neither quantity proves duplicate identity.</li>
  <li><b>Baseline residual tolerance 0.005 AU</b> (qc_baseline_tol, editable): an operational flag for reviewing residual offsets, not a universal noise specification. Set it from blanks, controls, and instrument performance in the intended study.</li>
  <li><b>Saturation flag 2.5 AU</b> (qc_sat_thresh, editable): an operational prompt to review possible saturation or photometric non-linearity, not a universal instrument limit. Set it from the validated linear range of the instrument and method.</li>
  <li><b>Noise-QC cutoffs</b> (global 0.5 / 1.5%, tail 1.0 / 3.0%, local 0.75 / 2.5%, fraction 0.20 / 0.50): every noise percentage uses the <b>maximum absolute native-coordinate, baseline-corrected, pre-smoothing analysis value</b> as denominator. Axis eligibility uses <code>uniform_step_rel_tolerance = 0.01</code> after splitting steps &gt;1.5&times; the preliminary median as gaps. These are operational, informational defaults, not literature or certification limits.</li>
</ul>
    '))
  })

  # ---------------------------------------------------------------------------
  # Feedback drafts and downloads work without an external form service.
  # Direct submission uses the bundled Google Form or an operator replacement.
  # ---------------------------------------------------------------------------
  fb_config <- PASA_FEEDBACK_CONFIG
  app_version <- RELEASE_ID$version

  fb_options <- list(
    list(id="love",       emoji="\U0001F60D", label="Love it"),
    list(id="good",       emoji="\U0001F60A", label="Good"),
    list(id="okay",       emoji="\U0001F610", label="Okay"),
    list(id="confused",   emoji="\U0001F615", label="Confused"),
    list(id="frustrated", emoji="\U0001F61E", label="Frustrated")
  )
  fb_rating <- reactiveVal(NULL)   # holds the human-readable label once chosen
  fb_sending <- reactiveVal(FALSE)

  fb_draft <- reactive(.pasa_feedback_text(fb_rating(), input$fb_comment, app_version))
  output$fb_email_link <- renderUI({
    tags$a(id="fb_compose_email", href=.pasa_feedback_mailto(fb_draft()),
           class="btn btn-outline-secondary", "Compose email")
  })
  output$fb_download <- downloadHandler(
    filename=function() paste0("PASA-feedback-", format(Sys.Date(), "%Y-%m-%d"), ".txt"),
    content=function(file) writeLines(enc2utf8(fb_draft()), file, useBytes=TRUE),
    contentType="text/plain; charset=utf-8"
  )

  output$emoji_buttons <- renderUI({
    sel <- fb_rating()
    div(style="display:flex;justify-content:center;flex-wrap:wrap;gap:6px;",
      lapply(fb_options, function(o){
        cls <- paste("emoji-btn", if(!is.null(sel) && identical(sel, o$label)) "selected" else "")
        actionButton(paste0("fb_", o$id), label=tagList(span(o$emoji), tags$small(o$label)),
                     class=cls, `aria-pressed`=if (!is.null(sel) && identical(sel, o$label)) "true" else "false")
      })
    )
  })

  # Each emoji button records its label as the current rating.
  lapply(fb_options, function(o){
    observeEvent(input[[paste0("fb_", o$id)]], {
      fb_rating(o$label)
      output$fb_status <- renderUI(NULL)   # clear any prior thank-you / error
    }, ignoreInit=TRUE)
  })

  observeEvent(input$fb_submit, {
    if (isTRUE(fb_sending())) return(invisible())
    if (!.pasa_feedback_submission_allowed(fb_config, input$fb_consent)) {
      if (isTRUE(fb_config$enabled))
        output$fb_status <- renderUI(
          div(style="color:var(--bs-warning);font-weight:500;",
              "Please read and acknowledge what will be sent before submitting."))
      return(invisible(NULL))
    }
    rating <- fb_rating()
    if(is.null(rating)){
      output$fb_status <- renderUI(
        div(style="color:var(--bs-warning);", "Please tap a reaction above first."))
      return()
    }
    comment <- if (isTruthy(input$fb_comment)) input$fb_comment else ""
    fb_sending(TRUE)
    session$sendCustomMessage("pasa_feedback_busy", list(busy = TRUE))
    finish_feedback <- function(result, deadline = NULL) {
      fb_sending(FALSE)
      session$sendCustomMessage("pasa_feedback_busy", list(busy = FALSE))
      if (isTRUE(result$ok)) {
        same_draft <- identical(input$fb_comment %||% "", comment) && identical(fb_rating(), rating)
        if (same_draft) {
          fb_rating(NULL)
          updateTextAreaInput(session, "fb_comment", value = "")
          updateCheckboxInput(session, "fb_consent", value = FALSE)
        }
        output$fb_status <- renderUI(div(style = "color:var(--bs-success);font-weight:500;",
          if (same_draft) "Thank you! Your feedback was sent." else "Your submitted feedback was sent. Your newer draft is still here."))
      } else output$fb_status <- renderUI(div(style = "color:var(--bs-danger);",
        if (identical(result$reason, "not_confirmed"))
          "The service did not confirm receipt. Your draft is still here. Check before retrying to avoid a duplicate."
        else "The feedback could not be sent. Your draft is still here; retry later or save it as text."))
    }
    .run_io("feedback", list(config = fb_config, rating = rating, comment = comment, version = app_version),
      budget = 60, on_result = finish_feedback,
      on_error = function(message) finish_feedback(list(ok = FALSE, reason = "connection")))
  }, ignoreInit=TRUE)

  # ==========================================================================
  # Cell Growth tab
  # ==========================================================================
  GROWTH_UNICELL <- c("cyano", "red", "green")

  growth_sidebar_active <- reactive({
    identical(eff_sample_type(), "cells") &&
      isTruthy(input$organism) && input$organism %in% GROWTH_UNICELL
  })
  growth_manual_active <- reactive(isTRUE(input$growth_manual))
  growth_active <- reactive(growth_manual_active() || growth_sidebar_active())
  growth_mode <- reactive(if (growth_manual_active()) "manual"
                          else if (growth_sidebar_active()) "sidebar" else "none")

  growth_unit_word <- reactive(if (identical(input$growth_unit, "Days")) "days" else "hours")
  growth_n_rep <- reactive({
    n <- suppressWarnings(as.integer(input$growth_nrep)); if (!isTruthy(n) || is.na(n)) n <- 1L
    max(1L, min(10L, n))
  })
  growth_n_tp <- reactive({
    n <- suppressWarnings(as.integer(input$growth_ntp)); if (!isTruthy(n) || is.na(n)) n <- 7L
    max(2L, min(30L, n))
  })
  growth_n_tech <- reactive({
    n <- suppressWarnings(as.integer(input$growth_ntech)); if (!isTruthy(n) || is.na(n)) n <- 1L
    max(1L, min(6L, n))
  })
  # Nested manual mode is active only when technical reps >= 2 in manual entry.
  growth_nested_manual <- reactive(growth_mode() == "manual" && growth_n_tech() >= 2L)
  growth_interval <- reactive({
    v <- suppressWarnings(as.numeric(input$growth_interval))
    if (!isTruthy(v) || !is.finite(v) || v <= 0) v <- 1
    v
  })
  observeEvent(list(input$growth_nrep, input$growth_ntp, input$growth_ntech, input$growth_interval), {
    effective <- list(growth_nrep = growth_n_rep(), growth_ntp = growth_n_tp(),
                      growth_ntech = growth_n_tech(), growth_interval = growth_interval())
    changed <- character(0)
    for (id in names(effective)) {
      raw <- input[[id]]; if (is.null(raw)) next
      value <- suppressWarnings(as.numeric(raw))
      if (length(value) != 1L || !is.finite(value) || value != effective[[id]]) {
        updateNumericInput(session, id, value = effective[[id]])
        changed <- c(changed, paste0(sub("growth_", "", id), " = ", effective[[id]]))
      }
    }
    if (length(changed)) showNotification(paste("Growth inputs adjusted to their supported values:",
      paste(changed, collapse = "; ")), type = "message", duration = 5, session = session)
  }, ignoreInit = FALSE)

  # Values deliberately written by paste/demo/clear outrank stale browser inputs
  # until the rebuilt grid echoes them. This is separate from snapshot replay.
  growth_pending_cells <- reactiveVal(list())
  .growth_stage_cells <- function(values) {
    growth_pending_cells(values); .growth_cell_state_set(values)
    for (id in names(values)) updateNumericInput(session, id, value = values[[id]])
  }
  growth_mapping_state <- new.env(parent = emptyenv())

  # Cumulative time-point labels: interval * (index - 1), so the first column is
  # t = 0 (the first measurement) and matches the 0-based time axis the fit, plot,
  # and summary use (growth_long uses Time = iv * (k - 1)).
  growth_tp_labels <- reactive({
    iv <- growth_interval(); n <- growth_n_tp()
    suff <- if (identical(input$growth_unit, "Days")) " d" else " h"
    vapply(seq_len(n), function(k) paste0(iv * (k - 1L), suff), character(1))
  })
  growth_tp_times <- reactive(growth_interval() * (seq_len(growth_n_tp()) - 1L))

  # ---- Gating banner ----
  output$growth_gate_banner <- renderUI({
    if (growth_active()) {
      mode <- growth_mode()
      msg <- if (mode == "manual")
        "Manual-entry mode is active. Enter your OD values in the grid below."
      else
        "Growth from loaded spectra is active: your activated samples are interpreted as a single strain's OD time series."
      # The Cell Growth tab bypasses the Analysis-settings SPECTRAL-TAIL baseline
      # (per-spectrum A at ~750 nm) regardless of the toggle, because at a
      # 720-750 nm tracking wavelength that subtraction removes the turbidity
      # signal being tracked. It is NOT a claim the input is blank-free: the app
      # adds no blank here, so the input must already be instrument-zeroed /
      # medium-blanked upstream.
      bl_msg <- if (mode == "sidebar")
        " Uploaded as-measured basis: an exact native node is used when present; otherwise a gap-guarded linear interpolation may be used and is labeled with its bracket/reason. The spectral-tail baseline in Analysis settings is bypassed; the app adds no blank, so input must already be instrument-zeroed / medium-blanked."
      else
        " Manual OD entries are used verbatim and labeled as manual entries. The app adds no blank, so values must already be instrument-zeroed / medium-blanked."
      div(style="margin:8px 0;padding:10px 12px;border-radius:6px;background:var(--bs-success-bg-subtle,#d1e7dd);border-left:3px solid var(--bs-success,#198754);",
          tags$b("Active. "), msg, br(),
          tags$small(style="color:var(--bs-secondary-color);", bl_msg))
    } else {
      div(style="margin:8px 0;padding:10px 12px;border-radius:6px;background:var(--bs-tertiary-bg);border-left:3px solid var(--bs-secondary);",
          "This tab becomes available when you select ", tags$b("Cells / Lysate"),
          " as the sample type (for cyanobacteria, red, or green algae) in Analysis settings, ",
          "or when you choose to enter OD values manually below.")
    }
  })

  # ---- Body (dimmed when inactive) ----
  output$growth_body <- renderUI({
    active <- growth_active()
    dim_style <- if (!active) "opacity:0.45;pointer-events:none;" else ""
    mode <- growth_mode()
    .seed_value <- function(id) {
      grid <- isolate(pending_growth_restore())
      txn <- isolate(restore_txn())
      if (!is.null(grid) && identical(grid$restore_txn, txn) &&
          identical(grid$generation, isolate(growth_restore_generation())) &&
          id %in% names(grid$scalars)) return(grid$scalars[[id]])
      settings <- isolate(pending_growth_settings_restore())
      if (!is.null(settings) && identical(settings$restore_txn, txn) &&
          id %in% names(settings$values)) {
        i <- match(id, .SNAPSHOT_SETTINGS_REGISTRY$key)
        if (!is.na(i)) return(.SNAPSHOT_SETTINGS_REGISTRY$parse[[i]](settings$values[[id]]))
      }
      isolate(input[[id]])
    }
    .seed_num <- function(id, default, lo = -Inf, hi = Inf) {
      value <- suppressWarnings(as.numeric(.seed_value(id)))
      if (length(value) == 1L && is.finite(value) && value >= lo && value <= hi)
        value else default
    }
    .seed_text <- function(id, default = "") {
      value <- .seed_value(id)
      if (length(value) == 1L && !is.na(value)) as.character(value) else default
    }
    .seed_choice <- function(id, choices, default) {
      value <- .seed_text(id, default)
      if (value %in% choices) value else default
    }
    .seed_flag <- function(id, default = FALSE) {
      value <- .seed_value(id)
      if (length(value) == 1L && !is.na(value)) isTRUE(value) else isTRUE(default)
    }
    .growth_wl_seed <- .seed_num("growth_wl", 730, 720, 750)
    tagList(
      div(style=dim_style,
        layout_columns(col_widths = c(4,8),
          card(card_header("Measurement setup"),
            with_tip(div(class="growth-strain-input",
                       textInput("growth_strain", "Strain / sample name",
                                 value = .seed_text("growth_strain"),
                                 placeholder = "Optional: your strain", width = "360px")),
                     "Optional. Used only to label the growth curve and summary sentence."),
            # Tracking wavelength: shown in BOTH modes. Required in sidebar mode (drives OD);
            # optional metadata-only in manual mode (OD is typed directly).
            with_tip(
              sliderInput("growth_wl",
                          uiOutput("growth_wl_label_inline", inline = TRUE),
                          min = 720, max = 750, value = .growth_wl_seed, step = 1,
                          ticks = TRUE),
              "Wavelength at which values are read from each sample to build the OD time series. Far-red choices such as 730 or 750 nm are often used to reduce pigment-absorption interference, but the wavelength and OD\u2013biomass relationship must be justified for the study. In manual entry this is optional metadata only."),
            div(class="growth-narrow-input",
                numericInput("growth_wl_num", NULL, value = .growth_wl_seed,
                             min = 720, max = 750, step = 1)),
            uiOutput("growth_wl_warn"),
            with_tip(
              radioButtons("growth_unit", "Time unit", choices = c("Days", "Hours"),
                           selected = .seed_choice("growth_unit", c("Days", "Hours"), "Days"),
                           inline = TRUE),
              "Unit for the spacing between measurements and the x-axis of the growth curve."),
            with_tip(div(class="growth-narrow-input",
                       numericInput("growth_interval", "Interval size",
                                    value = .seed_num("growth_interval", 1, 0.001),
                                    min = 0.001, step = 0.1)),
              "Any positive spacing between consecutive measurements, including fractional values, in the chosen time unit (e.g. every 0.5 hours)."),
            with_tip(div(class="growth-narrow-input",
                       numericInput("growth_nrep", "Number of biological replicates",
                                    value = .seed_num("growth_nrep", 1, 1, 10),
                                    min = 1, max = 10, step = 1)),
              "Independent BIOLOGICAL replicates (1–10) — separate cultures / colonies. Each gets one row (or a nested block, if technical replicates are set below). A conditional sensitivity interval is shown with at least 3 fitted biological replicates; it is not a calibrated 95% confidence interval because auto-selected-window uncertainty is omitted. In the nested design, each contributing biological unit supplies one slope and receives equal weight. A replicate you configure but leave entirely blank is still recorded as part of the design — the nested summary reports both the configured count and how many supplied finite readings, so a blank unit is never silently dropped."),
            conditionalPanel("output.growth_is_manual",
              with_tip(div(class="growth-narrow-input",
                         numericInput("growth_ntech", "Number of technical replicates (per biological replicate)",
                                      value = .seed_num("growth_ntech", 1, 1, 6),
                                      min = 1, max = 6, step = 1)),
                "Repeated MEASUREMENTS of the SAME biological replicate (1–6). 1 (or blank) uses the ordinary replicate analysis. ≥2 expands each biological replicate into technical sub-rows. Technical OD values are averaged within each biological unit and time; one qualifying log-linear slope is then fitted per biological unit within the common selected interval. The reported rate is their equal-weight mean. With at least 3 contributing biological units, a t-based conditional sensitivity interval summarizes between-unit slope variation. It omits window-selection and within-trajectory uncertainty and is not a calibrated confidence interval."),
              with_tip(div(class="growth-narrow-input",
                         numericInput("growth_ntp", "Number of timepoints",
                                      value = .seed_num("growth_ntp", 7, 2, 30),
                                      min = 2, max = 30, step = 1)),
                "How many measurements per replicate (columns in the grid below).")
            )
          ),
          card(card_header(if (mode == "manual") "OD values (manual entry)" else "Replicate → sample mapping"),
            conditionalPanel("output.growth_is_sidebar",
              helpText(em("For each replicate, choose the activated samples in time order (1st = first measurement).")),
              uiOutput("growth_rep_mapping")
            ),
            conditionalPanel("output.growth_is_manual",
              div(style="margin-bottom:6px;",
                actionButton("growth_load_dummy", "Load built-in demo data", class="btn-sm btn-outline-secondary"),
                tags$small(style="margin-left:8px;color:var(--bs-secondary-color);",
                  "Populates 3 replicates \u00d7 8 timepoints with a typical growth curve.")),
              checkboxInput("growth_paste_mode",
                            "Paste delimited data instead of typing cell-by-cell",
                            value = .seed_flag("growth_paste_mode")),
              div(style="margin:-2px 0 8px;",
                actionButton("growth_clear_grid", "Clear inputs", class="btn-sm btn-outline-danger"),
                tags$small(style="margin-left:8px;color:var(--bs-secondary-color);",
                  "Empties every OD cell in the grid below.")),
              conditionalPanel("input.growth_paste_mode",
                div(style="width:100%;max-width:1100px;",
                  textAreaInput("growth_paste_data", NULL, value = .seed_text("growth_paste_data"), rows = 8, width="100%",
                    placeholder = "Paste one replicate per line. Tab or semicolon columns support decimal commas. Otherwise use spaces or comma-separated decimal-point values. Click Apply pasted data to replace the grid.")),
                div(class="text-muted", style="font-size:0.82em;margin:-4px 0 8px 2px;",
                    tags$em("Each line corresponds to one replicate in ascending order (line 3 = replicate 3).")),
                actionButton("growth_apply_paste", "Apply pasted data", class = "btn-sm btn-primary")
              ),
              helpText(em("Type OD values; column headers update from the time unit & interval.")),
              uiOutput("growth_manual_grid")
            )
          )
        ),
        div(style="margin-top:6px;padding:10px 12px;border-radius:6px;background:var(--bs-tertiary-bg);border-left:3px solid var(--bs-info);font-size:0.9em;",
          tags$b("Assumptions: "),
          "only a single species/strain per analysis; the first sample is the first measurement and the last is the last; ",
          "measurement intervals are assumed equal (equidistant) for the apparent OD-derived rate calculation to be valid."),
        uiOutput("growth_summary_sentence"),
        hr(),
        div(style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:4px;",
          h4("Results", style="margin:0;"),
          uiOutput("growth_top_downloads")),
        uiOutput("growth_result_msg"),
        div(style="display:flex;flex-wrap:wrap;gap:14px 18px;align-items:center;margin-bottom:6px;",
          div(style="min-width:200px;",
            sliderInput("growth_phase_alpha", "Phase color intensity",
                        min = 0, max = 1,
                        value = .seed_num("growth_phase_alpha", 1, 0, 1),
                        step = 0.05, width = "200px"))),
        plotOutput("growth_plot", height = 480),
        uiOutput("growth_metrics_cards"),
        # Wrapping prose box for long interpretation text.
        div(style="margin-top:8px;padding:12px 14px;border:1px solid var(--bs-border-color);border-radius:8px;background:var(--bs-tertiary-bg);line-height:1.55;white-space:normal;word-break:break-word;",
            uiOutput("growth_interpretation")),
        hr(),
        with_tip(
          checkboxInput("growth_advanced", "Show advanced / supplementary outputs",
                        value = .seed_flag("growth_advanced")),
          "Window candidates, per-replicate fit diagnostics, phase boundaries, and CSV/plot downloads."),
        with_tip(
          checkboxInput("growth_boot", "Reselection-bootstrap percentile sensitivity interval (slower)",
                        value = .seed_flag("growth_boot")),
          "Re-runs the full log-linear OD-window selection on residual-bootstrapped series to give a model-conditional percentile sensitivity interval and bias estimate under that resampling design. It is not a calibrated 95% confidence interval and the bias estimate can have either sign. Runs behind an explicit confirmation with a runtime estimate; off by default."),
        uiOutput("growth_boot_nested_note"),
        conditionalPanel("input.growth_boot",
          uiOutput("growth_boot_controls")),
        conditionalPanel("input.growth_advanced",
          uiOutput("growth_advanced_block"))
      )
    )
  })

  # Helper output flags for conditionalPanel
  output$growth_is_sidebar <- reactive(growth_mode() == "sidebar")
  output$growth_is_manual  <- reactive(growth_mode() == "manual")
  outputOptions(output, "growth_is_sidebar", suspendWhenHidden = FALSE)
  outputOptions(output, "growth_is_manual",  suspendWhenHidden = FALSE)

  # Settings inside growth_body are mounted dynamically. Retain and replay the
  # serialized growth family until the final widget instances have echoed every
  # typed value for four consecutive checks. This also covers Settings-only
  # restores where no [GROWTH_DATA] grid transaction is requested.
  observeEvent(pending_growth_settings_restore(), {
    .pending <- pending_growth_settings_restore()
    if (is.null(.pending)) return(invisible())
    .txn <- .pending$restore_txn
    .values <- .pending$values
    .attempt <- new.env(parent = emptyenv())
    .attempt$n <- 0L
    .attempt$stable <- 0L
    .expected_value <- function(key, raw) {
      .i <- match(key, .SNAPSHOT_SETTINGS_REGISTRY$key)
      if (is.na(.i)) return(NULL)
      .op <- .SNAPSHOT_SETTINGS_REGISTRY$parse[[.i]]
      tryCatch(if (is.function(.op)) .op(raw) else raw,
               error = function(e) NULL)
    }
    .same_value <- function(key, expected) {
      .actual <- isolate(input[[key]])
      if (is.null(expected) || is.null(.actual)) return(FALSE)
      if (is.numeric(expected))
        return(isTRUE(all.equal(as.numeric(.actual), as.numeric(expected),
                                tolerance = 0, check.attributes = FALSE)))
      if (is.logical(expected))
        return(length(.actual) == 1L && identical(isTRUE(.actual), isTRUE(expected)))
      identical(as.character(.actual), as.character(expected))
    }
    .expected <- lapply(names(.values), function(k) .expected_value(k, .values[[k]]))
    names(.expected) <- names(.values)
    .retry <- function() {
      if (!.restore_callbacks$alive()) return(invisible())
      .live <- isolate(pending_growth_settings_restore())
      if (is.null(.live) || !identical(.live$restore_txn, .txn) ||
          !identical(.txn, isolate(restore_txn()))) return(invisible())
      .matches <- if (!length(.expected)) logical(0) else
        vapply(names(.expected), function(k) .same_value(k, .expected[[k]]), logical(1))
      .sample_pending <- isolate(pending_samples_restore())
      .same_txn_sample_pending <- !is.null(.sample_pending) &&
        identical(attr(.sample_pending, "restore_txn", exact = TRUE), .txn)
      .all_match <- !length(.matches) || all(.matches)
      .attempt$stable <- if (.all_match && !.same_txn_sample_pending)
        .attempt$stable + 1L else 0L
      if (.attempt$stable >= 4L) {
        pending_growth_settings_restore(NULL)
        return(invisible())
      }
      if (!.all_match) {
        for (.k in names(.values)[!.matches]) {
          tryCatch(.apply_one_setting(session, .k, .values[[.k]]), error = function(e) FALSE)
          .ev <- .expected[[.k]]
          if (length(.ev) == 1L && !is.null(.ev) && !is.na(.ev))
            tryCatch(session$sendCustomMessage(
              "pasa_restore_input_echo", list(id = .k, value = unname(.ev))),
              error = function(e) NULL)
        }
      }
      .attempt$n <- .attempt$n + 1L
      if (.attempt$n < 120L && requireNamespace("later", quietly = TRUE)) {
        .restore_callbacks$schedule(.retry, delay = 0.25)
      } else {
        pending_growth_settings_restore(NULL)
        showNotification("Some Cell Growth settings were not confirmed by the browser; check the controls before continuing.", type = "warning", duration = 12)
      }
      invisible()
    }
    session$onFlushed(.restore_callbacks$guard(function() .retry()), once = TRUE)
  }, ignoreNULL = TRUE, priority = -50)

  # Bidirectional wavelength slider <-> numeric sync (sidebar mode).
  observeEvent(input$growth_wl, {
    if (isTruthy(input$growth_wl) && !isTRUE(all.equal(input$growth_wl, input$growth_wl_num)))
      updateNumericInput(session, "growth_wl_num", value = input$growth_wl)
  })
  observeEvent(input$growth_wl_num, {
    v <- suppressWarnings(as.numeric(input$growth_wl_num))
    if (isTruthy(v) && is.finite(v)) {
      v <- max(720, min(750, round(v)))
      if (!isTRUE(all.equal(v, input$growth_wl))) updateSliderInput(session, "growth_wl", value = v)
    }
  })
  output$growth_wl_warn <- renderUI({
    v <- input$growth_wl
    if (isTruthy(v) && v < 730)
      div(style="color:var(--bs-warning-text,#997404);font-size:0.85em;",
          "Operational note: values below 730 nm may intersect more pigment absorption. Choose and validate the tracking wavelength for the sample, matrix, instrument, and OD\u2013biomass relationship.")
  })
  output$growth_wl_label_inline <- renderUI({
    if (growth_mode() == "manual")
      HTML("Tracking wavelength for OD (nm) <span style='color:var(--bs-secondary-color);font-weight:400;'>(optional)</span>")
    else
      HTML("Tracking wavelength for OD (nm)")
  })
  outputOptions(output, "growth_wl_label_inline", suspendWhenHidden = FALSE)

  growth_wl_label <- reactive({
    v <- if (isTruthy(input$growth_wl)) input$growth_wl else 730
    as.character(round(v))
  })

  # ---- Replicate → sample mapping (sidebar mode) ----
  output$growth_rep_mapping <- renderUI({
    growth_mode(); growth_active()  # regenerate selected markup whenever the body remounts
    samples <- if (isTruthy(input$samples)) input$samples else character(0)
    nrep <- growth_n_rep()
    selections <- lapply(seq_len(nrep), function(i) {
      id <- paste0("growth_map_", i)
      cur <- isolate(input[[id]])
      if (is.null(cur) && exists(id, growth_mapping_state, inherits = FALSE)) cur <- growth_mapping_state[[id]]
      as.character(cur)[as.character(cur) %in% samples]
    })
    inputs <- lapply(seq_len(nrep), function(i) {
      sel <- selections[[i]]  # a never-assigned replicate stays empty
      choices <- samples[samples %in% union(sel, setdiff(samples, unlist(selections[-i], use.names = FALSE)))]
      selectizeInput(paste0("growth_map_", i), paste0("Rep ", i, " samples (time order)"),
                     choices = choices, selected = sel, multiple = TRUE,
                     options = list(plugins = list("remove_button"), items = sel))
    })
    tagList(inputs,
            tags$hr(style="margin:8px 0;"),
            div(style="font-size:0.86em;color:var(--bs-secondary-color);margin-bottom:4px;",
                "Assigned mapping (timepoint → sample):"),
            uiOutput("growth_map_preview"))
  })

  # Exclusive replicate→sample mapping: a sample assigned to any replicate is
  # excluded from the available choices of every other replicate, so each sample
  # maps to exactly one replicate. Recomputed for all N replicates whenever any
  # replicate's selection changes; each input keeps its own current selections.
  observe({
    samples <- if (isTruthy(input$samples)) input$samples else character(0)
    nrep <- growth_n_rep()
    sel <- lapply(seq_len(nrep), function(i) {
      id <- paste0("growth_map_", i)
      s <- input[[id]]
      if (!is.null(s)) growth_mapping_state[[id]] <- as.character(s)[as.character(s) %in% samples]
      if (is.null(s) && exists(id, growth_mapping_state, inherits = FALSE)) s <- growth_mapping_state[[id]]
      as.character(s)[as.character(s) %in% samples]
    })
    for (i in seq_len(nrep)) {
      taken_by_others <- unlist(sel[-i], use.names = FALSE)
      avail <- setdiff(samples, taken_by_others)
      # This input's own selection must stay available so it is preserved.
      avail <- union(sel[[i]], avail)
      avail <- samples[samples %in% avail]  # keep the original sample order
      updateSelectizeInput(session, paste0("growth_map_", i),
                           choices = avail, selected = sel[[i]], server = FALSE)
    }
  })

  output$growth_map_preview <- renderUI({
    iv <- growth_interval(); nrep <- growth_n_rep()
    suff <- if (identical(input$growth_unit, "Days")) " d" else " h"
    wl <- suppressWarnings(as.numeric(growth_wl_label()))
    # Show the SAME raw OD the growth fit actually uses. Cell Growth always fits
    # raw OD regardless of the Analysis-settings baseline toggle (growth_long reads dat()
    # directly). A baseline-corrected preview would collapse to approximately zero
    # when the tracking wavelength sits near the baseline
    # reference (e.g. 730 vs 750 nm), disagreeing with the fit and with the tab's
    # own "raw OD" promise. Interpolate raw absorbance from dat() instead.
    wide <- tryCatch(dat(), error = function(e) NULL)
    raw_nm <- if (!is.null(wide)) suppressWarnings(as.numeric(wide[[names(wide)[1]]])) else NULL
    .raw_od_preview <- function(samp, wl) {
      if (is.null(wide) || !(samp %in% names(wide)))
        return(list(value = NA_real_, method = "unavailable", reason = "sample_column_not_found",
                    bracket_lower_nm = NA_real_, bracket_upper_nm = NA_real_))
      v <- suppressWarnings(as.numeric(wide[[samp]]))
      .growth_od_info_at_wl(raw_nm, v, wl)
    }
    # Count assigned cells to decide whether to render the table or the empty msg
    any_assigned <- FALSE
    for (i in seq_len(nrep)) {
      samps_i <- input[[paste0("growth_map_", i)]]
      if (isTruthy(samps_i)) { any_assigned <- TRUE; break }
    }
    if (!any_assigned)
      return(div(class="text-muted", style="font-size:0.85em;font-style:italic;",
                 "No samples assigned yet."))

    # OD column header (small, right-aligned, sits above the OD cells of the first block)
    header <- div(style="display:flex;justify-content:flex-end;margin-bottom:2px;",
                  div(style="flex:0 0 150px;text-align:center;font-size:0.78em;color:var(--bs-secondary-color);font-weight:600;",
                      paste0("OD at ", if (is.finite(wl)) wl else "\u2014", " nm (uploaded basis)")))

    blocks <- list()
    for (i in seq_len(nrep)) {
      samps <- input[[paste0("growth_map_", i)]]
      if (!isTruthy(samps)) next
      # Build per-sample rows for this replicate
      rows <- lapply(seq_along(samps), function(k) {
        tlab <- paste0(iv * (k - 1), suff)
        od_info <- if (!is.null(wide) && is.finite(wl))
          suppressWarnings(.raw_od_preview(samps[k], wl)) else
            list(value = NA_real_, method = "unavailable", reason = "input_unavailable",
                 bracket_lower_nm = NA_real_, bracket_upper_nm = NA_real_)
        od_val <- od_info$value
        od_txt <- if (is.finite(od_val)) formatC(od_val, format = "f", digits = 3) else "\u2014"
        method_txt <- if (identical(od_info$method, "exact_native")) "exact native node"
          else if (identical(od_info$method, "gap_guarded_linear_interpolation"))
            sprintf("interpolated %.4g--%.4g nm", od_info$bracket_lower_nm, od_info$bracket_upper_nm)
          else paste0("unavailable: ", od_info$reason %||% "unknown_reason")
        div(style="display:flex;align-items:stretch;gap:0;margin:0;",
          # time label cell
          div(style="flex:0 0 60px;display:flex;align-items:center;justify-content:center;padding:4px 6px;background:var(--bs-tertiary-bg);border:1px solid var(--bs-border-color);border-right:0;font-weight:600;font-size:0.85em;",
              tlab),
          # sample name cell
          div(style="flex:1 1 auto;padding:4px 10px;border:1px solid var(--bs-border-color);border-right:0;font-size:0.88em;",
              samps[k]),
          # OD value cell
          div(style="flex:0 0 150px;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:4px 6px;border:1px solid var(--bs-border-color);font-size:0.88em;font-variant-numeric:tabular-nums;",
              tags$span(od_txt), tags$small(style="opacity:0.72;font-size:0.72em;", method_txt))
        )
      })
      # Left Rep-N indicator: a single cell that vertically spans the rows
      rep_cell <- div(
        style="flex:0 0 64px;display:flex;align-items:center;justify-content:center;background:var(--bs-tertiary-bg);border:1px solid var(--bs-border-color);font-weight:700;font-size:0.9em;",
        paste0("Rep ", i)
      )
      rows_stack <- div(style="display:flex;flex-direction:column;flex:1 1 auto;", rows)
      blocks[[length(blocks) + 1]] <- div(
        style="display:flex;align-items:stretch;margin:3px 0;",
        rep_cell, rows_stack
      )
    }
    wl_out_of_range <- !is.null(raw_nm) && any(is.finite(raw_nm)) && is.finite(wl) &&
      (wl < min(raw_nm, na.rm = TRUE) - 1e-9 || wl > max(raw_nm, na.rm = TRUE) + 1e-9)
    range_note <- if (isTRUE(wl_out_of_range))
      div(class = "alert alert-warning", style = "padding:4px 10px;font-size:0.82em;margin:4px 0;",
          sprintf("Tracking wavelength %g nm is outside the measured range of the loaded data (%.0f–%.0f nm), so OD cannot be read there — the cells below show “—” (unavailable) rather than a flat-held / extrapolated value. Choose a wavelength within the measured range, or load spectra that extend to %g nm.",
                  wl, min(raw_nm, na.rm = TRUE), max(raw_nm, na.rm = TRUE), wl)) else NULL
    tagList(range_note, header, blocks)
  })

  # ---- Manual OD grid ----
  output$growth_manual_grid <- renderUI({
    nrep <- growth_n_rep(); labs <- growth_tp_labels(); ntech <- growth_n_tech()
    # Preserve any value already entered (typed, pasted, demo-loaded, or applied
    # from a saved session) when this grid re-renders due to a change in the
    # replicate/timepoint count. Seed each rebuilt input from its current value so
    # a grid remount cannot discard manual or restored entries. We
    # read the current input value via isolate() and seed each numericInput with
    # it so existing measurements survive the rebuild.
    seed_cell <- function(id){
      .pending <- isolate(pending_growth_restore())
      .pending_here <- !is.null(.pending) &&
        identical(.pending$generation, isolate(growth_restore_generation())) &&
        id %in% names(.pending$values)
      if (.pending_here) {
        cur <- suppressWarnings(as.numeric(.pending$values[[id]]))
      } else if (id %in% names(isolate(growth_pending_cells()))) {
        cur <- suppressWarnings(as.numeric(isolate(growth_pending_cells())[[id]]))
      } else {
        cur <- suppressWarnings(as.numeric(isolate(input[[id]])))
        if (length(cur) != 1L || !is.finite(cur)) {
          .state <- isolate(growth_cell_state())
          cur <- if (id %in% names(.state))
            suppressWarnings(as.numeric(.state[[id]])) else NA_real_
        }
      }
      if (length(cur) != 1L || !is.finite(cur)) cur <- NA_real_
      tags$td(numericInput(id, NULL, value = cur, step = 0.01, width = "90px"))
    }
    if (ntech >= 2L) {
      hdr <- tags$tr(tags$th("Biological × technical"), lapply(labs, function(L) tags$th(L)))
      rows <- do.call(c, lapply(seq_len(nrep), function(i){
        lapply(seq_len(ntech), function(t){
          cells <- lapply(seq_along(labs), function(j) seed_cell(paste0("growth_od_", i, "_", t, "_", j)))
          bg <- if (i %% 2L == 0L) "background:rgba(13,110,253,0.04);" else ""
          tags$tr(style = bg, tags$td(tags$b(sprintf("Bio %d · Tech %d", i, t))), cells)
        })
      }))
      note <- tags$div(style="font-size:0.8em;opacity:0.85;margin-bottom:4px;",
        sprintf("Nested design: %d biological × %d technical = %d rows. Technical OD values are averaged within each biological unit and time. The reported rate is the equal-weight mean of qualifying biological-unit log-linear slopes in the common selected interval. A t-based conditional sensitivity interval is shown only with at least 3 contributing biological units. It omits window-selection and within-trajectory uncertainty; treat it as exploratory. Contributing and excluded biological counts are reported below.", nrep, ntech, nrep*ntech))
      div(note, div(style="overflow-x:auto;", tags$table(class="table table-sm", tags$thead(hdr), tags$tbody(rows))))
    } else {
      hdr <- tags$tr(tags$th("Replicate"), lapply(labs, function(L) tags$th(L)))
      rows <- lapply(seq_len(nrep), function(i) {
        cells <- lapply(seq_along(labs), function(j) seed_cell(paste0("growth_od_", i, "_", j)))
        tags$tr(tags$td(tags$b(paste0("Rep ", i))), cells)
      })
      div(style="overflow-x:auto;", tags$table(class="table table-sm", tags$thead(hdr), tags$tbody(rows)))
    }
  })

  # Keep a server-side copy of every mounted manual OD cell. The renderUI grid
  # can be replaced while other outputs are rendering; retaining these values
  # prevents a transient unmount from blanking analysis or snapshot exports.
  observe({
    if (!isTRUE(input$growth_manual)) return(invisible())
    nrep <- growth_n_rep(); ntech <- growth_n_tech(); ntp <- length(growth_tp_labels())
    ids <- character(0)
    if (ntech >= 2L) {
      for (i in seq_len(nrep)) for (t in seq_len(ntech)) for (j in seq_len(ntp))
        ids <- c(ids, paste0("growth_od_", i, "_", t, "_", j))
    } else {
      for (i in seq_len(nrep)) for (j in seq_len(ntp))
        ids <- c(ids, paste0("growth_od_", i, "_", j))
    }
    .pending <- isolate(pending_growth_restore())
    .pending_ids <- if (!is.null(.pending) &&
      identical(.pending$generation, isolate(growth_restore_generation())))
      names(.pending$values) else character(0)
    updates <- list(); staged <- isolate(growth_pending_cells())
    for (id in setdiff(ids, .pending_ids)) {
      raw <- input[[id]]
      if (is.null(raw)) next
      value <- suppressWarnings(as.numeric(raw))
      if (id %in% names(staged)) {
        target <- suppressWarnings(as.numeric(staged[[id]]))
        if (length(value) != 1L || !isTRUE(all.equal(value, target, check.attributes = FALSE))) next
        staged[[id]] <- NULL
      }
      updates[[id]] <- value
    }
    if (!identical(staged, isolate(growth_pending_cells()))) growth_pending_cells(staged)
    .growth_cell_state_set(updates)
    invisible()
  })

  # Apply is explicit: opening the paste box or restoring its visibility must
  # never replay an old draft over subsequently edited cells.
  observeEvent(input$growth_apply_paste, {
    if (!isTRUE(input$growth_paste_mode)) return(invisible())
    parsed <- .growth_parse_paste(input$growth_paste_data %||% "", growth_n_rep(), growth_n_tp())
    if (!isTRUE(parsed$ok)) {
      showNotification(parsed$error, type = "warning", duration = 8, session = session)
      return(invisible())
    }
    if (growth_n_tech() > 1L) updateNumericInput(session, "growth_ntech", value = 1)
    .growth_stage_cells(parsed$values)
    showNotification(sprintf("Applied %d row(s) and %d numeric OD value(s). Missing cells are blank.",
      parsed$rows, parsed$n_values), duration = 5, session = session)
  }, ignoreInit = TRUE)

  observeEvent(input$growth_clear_grid, {
    nrep  <- suppressWarnings(as.integer(growth_n_rep()))
    ntech <- suppressWarnings(as.integer(growth_n_tech()))
    ntp   <- length(growth_tp_labels())
    if (!is.finite(nrep)  || nrep  < 1L) nrep  <- 1L
    if (!is.finite(ntech) || ntech < 1L) ntech <- 1L
    if (!is.finite(ntp)   || ntp   < 1L) ntp   <- 0L
    .updates <- list()
    if (ntech >= 2L) {
      for (i in seq_len(nrep)) for (t in seq_len(ntech)) for (j in seq_len(ntp)) {
        .id <- sprintf("growth_od_%d_%d_%d", i, t, j)
        .updates[[.id]] <- NA_real_
        updateNumericInput(session, .id, value = NA)
      }
    } else {
      for (i in seq_len(nrep)) for (j in seq_len(ntp)) {
        .id <- sprintf("growth_od_%d_%d", i, j)
        .updates[[.id]] <- NA_real_
        updateNumericInput(session, .id, value = NA)
      }
    }
    .growth_stage_cells(.updates)
    if (isTRUE(input$growth_paste_mode))
      updateTextAreaInput(session, "growth_paste_data", value = "")
  }, ignoreInit = TRUE)

  observeEvent(input$growth_load_dummy, {
    dummy <- list(
      R1 = c(0.078, 0.085, 0.155, 0.283, 0.516, 0.620, 0.618, 0.470),
      R2 = c(0.080, 0.087, 0.159, 0.290, 0.529, 0.636, 0.634, 0.482),
      R3 = c(0.076, 0.083, 0.151, 0.276, 0.503, 0.604, 0.602, 0.458)
    )
    nrep <- 3L; ntp <- 8L
    # Push grid-shape scalars first so the renderUI starts rebuilding the grid.
    updateNumericInput(session, "growth_nrep", value = nrep)
    updateNumericInput(session, "growth_ntp",  value = ntp)
    updateNumericInput(session, "growth_ntech", value = 1)
    # Keep the paste box in sync (harmless, and used if paste-mode is on).
    paste_txt <- paste(vapply(dummy, function(v) paste(v, collapse = "\t"), character(1)),
                       collapse = "\n")
    updateTextAreaInput(session, "growth_paste_data", value = paste_txt)
    .dummy_state <- list()
    for (i in seq_len(nrep)) for (j in seq_len(ntp))
      .dummy_state[[paste0("growth_od_", i, "_", j)]] <- dummy[[i]][j]
    .growth_stage_cells(.dummy_state)
    # Poll-until-mounted writer (mirrors .apply_growth): write the cells only once
    # the new grid input slots exist on the client; retry up to ~5 s.
    write_cells <- function() {
      for (i in seq_len(nrep)) for (j in seq_len(ntp)) {
        tryCatch(updateNumericInput(session, paste0("growth_od_", i, "_", j),
                                    value = dummy[[i]][j]),
                 error = function(e) NULL)
      }
    }
    st <- new.env(); st$n <- 0L; st$done <- FALSE
    retry <- function() {
      if (!.restore_callbacks$alive()) return(invisible())
      if (st$done) return(invisible())
      st$n <- st$n + 1L
      cur_nrep <- suppressWarnings(as.integer(isolate(session$input[["growth_nrep"]])))
      cur_ntp  <- suppressWarnings(as.integer(isolate(session$input[["growth_ntp"]])))
      first_cell_exists <- !is.null(isolate(session$input[["growth_od_3_8"]]))
      ready <- isTRUE(is.finite(cur_nrep) && cur_nrep >= nrep &&
                      is.finite(cur_ntp)  && cur_ntp  >= ntp) && first_cell_exists
      if (ready || st$n >= 20L) { write_cells(); st$done <- TRUE; return(invisible()) }
      if (requireNamespace("later", quietly = TRUE)) .restore_callbacks$schedule(retry, delay = 0.25)
    }
    if (requireNamespace("later", quietly = TRUE)) .restore_callbacks$schedule(retry, delay = 0.25) else write_cells()
    showNotification("Built-in demo growth data loaded (3 replicates \u00d7 8 timepoints, raw OD).",
                     type = "message", duration = 6)
  }, ignoreInit = TRUE)

  # ---- Build tidy long data (Time, Replicate, OD) from active path ----
  growth_long <- reactive({
    mode <- growth_mode(); if (mode == "none") return(NULL)
    iv <- growth_interval(); nrep <- growth_n_rep()
    if (mode == "sidebar") {
      # Cell Growth uses the uploaded as-measured basis and bypasses the
      # Analysis-settings SPECTRAL-TAIL baseline (per-spectrum A at ~750 nm), regardless of
      # the toggle \u2014 subtracting the tracking-wavelength value would remove the
      # turbidity signal being tracked. We therefore read directly from dat() (the
      # as-measured wide input table) and interpolate absorbance at the tracking
      # wavelength \u2014 NOT from processed_long(), which applies that spectral-tail
      # baseline whenever that toggle is on. The app adds no blank here, so
      # the input is assumed already instrument-zeroed / medium-blanked upstream.
      req(dat())
      wide <- dat()
      nm_col <- names(wide)[1]
      raw_nm <- suppressWarnings(as.numeric(wide[[nm_col]]))
      wl <- as.numeric(growth_wl_label())
      .raw_od_info <- function(samp, wl) {
        if (!(samp %in% names(wide)))
          return(list(value = NA_real_, method = "unavailable", reason = "sample_column_not_found",
                      bracket_lower_nm = NA_real_, bracket_upper_nm = NA_real_,
                      bracketing_gap_nm = NA_real_, max_allowed_gap_nm = NA_real_,
                      source_finite_point_count = 0L, source_distinct_wavelength_count = 0L))
        v <- suppressWarnings(as.numeric(wide[[samp]]))
        .growth_od_info_at_wl(raw_nm, v, wl)
      }
      rows <- list()
      for (i in seq_len(nrep)) {
        samps <- input[[paste0("growth_map_", i)]]
        if (!isTruthy(samps)) next
        for (k in seq_along(samps)) {
          gi <- .raw_od_info(samps[k], wl)
          rows[[length(rows)+1]] <- data.frame(Time = iv * (k - 1), Replicate = paste0("R", i),
            OD = gi$value, SourceSample = as.character(samps[k]), TrackingWavelengthNm = wl,
            InputBasis = "uploaded_as_measured_spectrum",
            ExtractionMethod = gi$method, ExtractionReason = gi$reason,
            BracketLowerNm = gi$bracket_lower_nm, BracketUpperNm = gi$bracket_upper_nm,
            BracketingGapNm = gi$bracketing_gap_nm, MaxAllowedGapNm = gi$max_allowed_gap_nm,
            SourceFinitePointCount = gi$source_finite_point_count,
            SourceDistinctWavelengthCount = gi$source_distinct_wavelength_count,
            stringsAsFactors = FALSE)
        }
      }
      if (!length(rows)) return(NULL)
      do.call(rbind, rows)
    } else {
      ntp <- growth_n_tp(); ntech <- growth_n_tech(); rows <- list()
      wl <- suppressWarnings(as.numeric(growth_wl_label()))
      if (ntech >= 2L) {
        for (i in seq_len(nrep)) for (t in seq_len(ntech)) for (j in seq_len(ntp)) {
          v <- suppressWarnings(as.numeric(input[[paste0("growth_od_", i, "_", t, "_", j)]]))
          if (is.null(v) || !length(v) || is.na(v)) next
          rows[[length(rows)+1]] <- data.frame(Time = iv * (j - 1),
            biological_rep = paste0("B", i), technical_rep = paste0("T", t),
            Replicate = paste0("B", i), OD = v,
            SourceSample = sprintf("manual_B%d_T%d_timepoint_%d", i, t, j),
            TrackingWavelengthNm = wl, InputBasis = "manual_instrument_blanked_OD",
            ExtractionMethod = "manual_entry", ExtractionReason = "user_entered_value",
            BracketLowerNm = NA_real_, BracketUpperNm = NA_real_, BracketingGapNm = NA_real_,
            MaxAllowedGapNm = NA_real_, SourceFinitePointCount = NA_integer_,
            SourceDistinctWavelengthCount = NA_integer_, stringsAsFactors = FALSE)
        }
      } else {
        for (i in seq_len(nrep)) for (j in seq_len(ntp)) {
          v <- suppressWarnings(as.numeric(input[[paste0("growth_od_", i, "_", j)]]))
          if (is.null(v) || !length(v) || is.na(v)) next
          rows[[length(rows)+1]] <- data.frame(Time = iv * (j - 1), Replicate = paste0("R", i),
            OD = v, SourceSample = sprintf("manual_R%d_timepoint_%d", i, j),
            TrackingWavelengthNm = wl, InputBasis = "manual_instrument_blanked_OD",
            ExtractionMethod = "manual_entry", ExtractionReason = "user_entered_value",
            BracketLowerNm = NA_real_, BracketUpperNm = NA_real_, BracketingGapNm = NA_real_,
            MaxAllowedGapNm = NA_real_, SourceFinitePointCount = NA_integer_,
            SourceDistinctWavelengthCount = NA_integer_, stringsAsFactors = FALSE)
        }
      }
      if (!length(rows)) return(NULL)
      do.call(rbind, rows)
    }
  })

  GROWTH_BOOT_MAX <- 200L
  growth_boot_n <- reactive({
    n <- suppressWarnings(as.integer(input$growth_boot_n %||% GROWTH_BOOT_MAX))
    if (!is.finite(n) || n < 10L) n <- GROWTH_BOOT_MAX
    min(n, GROWTH_BOOT_MAX)
  })

  boot_env <- new.env(parent = emptyenv())          # heavy accumulating state (non-reactive)
  growth_boot_state_value <- reactiveVal(list(status = "idle"))
  growth_boot_result <- reactiveVal(NULL)
  growth_boot_state <- function(value) {
    if (missing(value)) return(growth_boot_state_value())
    growth_boot_state_value(value)
    growth_boot_result(if (identical(value$status, "done")) value else NULL)
    invisible(value)
  }
  growth_boot_cancel <- reactiveVal(FALSE)
  GROWTH_BOOT_TICK_BUDGET <- 0.25                     # seconds of CPU per event-loop tick
  boot_run_id <- reactiveVal(0L)                      # immutable per-run token (see run_chunk)

  # A fingerprint of the exact data the bootstrap would run on, so a completed bootstrap is only
  # merged into a MATCHING result and any data/settings change invalidates an in-flight run.
  growth_data_key <- reactive({
    lg <- growth_long(); if (is.null(lg) || !nrow(lg)) return(NA_character_)
    ord <- order(as.character(lg$Replicate), lg$Time)
    body <- paste(sprintf("%s#%.10g#%.12g", lg$Replicate[ord], lg$Time[ord], lg$OD[ord]), collapse = ";")
    paste(isTRUE(growth_nested_manual()), growth_boot_n(), nrow(lg), body, sep = "|")
  })

  # Point estimate: always fast (never runs the bootstrap inline).
  growth_point <- reactive({
    lg <- growth_long(); if (is.null(lg) || !nrow(lg)) return(NULL)
    strain <- if (isTruthy(input$growth_strain)) input$growth_strain else "your strain"
    wl <- growth_wl_label()
    if (isTRUE(growth_nested_manual()) && all(c("biological_rep","technical_rep") %in% names(lg)))
      # Carry the configured biological-replicate count so a wholly blank unit (which contributes no
      # rows to `lg`) is still recorded as part of the supplied design, not silently erased.
      analyze_growth_nested(lg, unit = input$growth_unit, wl = wl, strain = strain,
                            n_bio_configured = growth_n_rep())
    else
      analyze_growth(lg, unit = input$growth_unit, wl = wl, strain = strain, n_boot = 0L,
                     n_configured = growth_n_rep())
  })

  .boot_release_task <- function() if (isTRUE(boot_env$holds_task)) {
    boot_env$holds_task <- FALSE; if (is.function(.growth_bg_task_release)) .growth_bg_task_release() }
  .BOOT_REAP_MAX <- 20L; .BOOT_REAP_DELAY <- 0.25
  .boot_schedule_reconcile <- function() {
    if (isTRUE(boot_env$reaping)) return(invisible())
    boot_env$reaping <- TRUE; boot_env$reap_tries <- 0L
    reap <- function() {
      h <- boot_env$mirai
      if (is.null(h) || !isTRUE(boot_env$holds_task)) { boot_env$reaping <- FALSE; return(invisible()) }
      if (identical(.pasa_task_stop_once(h), "TERMINAL_CONFIRMED")) {
        boot_env$mirai <- NULL; boot_env$stop_state <- "STOP_CONFIRMED"; boot_env$reaping <- FALSE
        .boot_release_task(); return(invisible())
      }
      boot_env$reap_tries <- boot_env$reap_tries + 1L
      if (boot_env$reap_tries >= .BOOT_REAP_MAX) {
        boot_env$stop_state <- "STOP_FAILED_OWNERSHIP_RETAINED_HANDED_OFF"; boot_env$reaping <- FALSE
        .pasa_orphan_enroll(h, .boot_release_task, task_id = "growth_boot_bg",
                            attempts = boot_env$reap_tries)
        return(invisible())
      }
      later::later(reap, delay = .BOOT_REAP_DELAY)
    }
    later::later(reap, delay = .BOOT_REAP_DELAY)
    invisible()
  }
  .stop_boot_bg <- function() {
    h <- boot_env$mirai
    if (!is.null(h)) {
      obs <- .pasa_task_stop_once(h)
      if (!identical(obs, "TERMINAL_CONFIRMED")) {
        boot_env$stop_state <- if (identical(obs, "STOP_FAULT")) "STOP_FAILED_OWNERSHIP_RETAINED"
                               else                              "STOP_REQUESTED_OWNERSHIP_RETAINED"
        .boot_schedule_reconcile()
        return(invisible(FALSE))
      }
      boot_env$mirai <- NULL                    # PROVEN terminal
    }
    boot_env$stop_state <- "STOP_CONFIRMED"
    .boot_release_task()                        # release the live-task reference EXACTLY ONCE (holds_task guard)
    invisible(TRUE)
  }
  .boot_terminalizing <- FALSE
  .boot_terminalize <- function() {
    if (isTRUE(.boot_terminalizing)) return(invisible())
    .boot_terminalizing <<- TRUE
    on.exit(.boot_terminalizing <<- FALSE, add = TRUE)
    growth_boot_cancel(TRUE)                                    # 1. cancel the cooperative poll
    boot_env$active <- FALSE                                    # 2. mark inactive (poll run-id/active guards bail)
    .stop_boot_bg()                                            # 3. stop the mirai task + release the ref EXACTLY ONCE
    boot_env$st <- NULL; boot_env$run_id <- NULL; boot_env$pending <- NULL   # 4. clear run handles
    invisible()
  }
  observeEvent(growth_data_key(), {
    key <- growth_data_key()
    if (identical(key, boot_env$last_key %||% boot_env$key)) return(invisible())
    boot_env$last_key <- key
    .boot_terminalize()
    boot_env$key <- NULL   # site-specific: also drop the data key so a stale completed bootstrap cannot merge
    removeModal()
    if (!identical(isolate(growth_boot_state())$key, growth_data_key()))
      growth_boot_state(list(status = "idle"))
  }, ignoreInit = TRUE)

  session$onSessionEnded(function() {
    .boot_terminalize()
  })

  # The result every growth output consumes: point estimate + matching completed bootstrap.
  growth_result <- reactive({
    base <- growth_point(); if (is.null(base)) return(NULL)
    bs <- growth_boot_result()
    if (isTRUE(input$growth_boot) &&
        isTRUE(base$ok) && !isTRUE(base$nested) && identical(bs$status, "done") &&
        identical(bs$key, growth_data_key()) && !is.null(bs$result)) {
      lg <- growth_long()
      r2 <- tryCatch(analyze_growth(lg, unit = input$growth_unit, wl = growth_wl_label(),
              strain = if (isTruthy(input$growth_strain)) input$growth_strain else "your strain",
              boot_result = bs$result, n_configured = growth_n_rep()), error = function(e) NULL)
      if (!is.null(r2)) return(r2)
    }
    base
  })

  GROWTH_BOOT_COST_PER   <- 3.5e-4   # measured seconds per resample per (culture x timepoint^2)
  GROWTH_BOOT_SMOOTH_MAX <- 0.5      # per-resample seconds below which the run is genuinely smooth
  GROWTH_BOOT_BUDGET_SEC <- 180      # plate-size budget: above this estimated total, warn emphatically
  .growth_boot_preflight <- function(lg, n_total) {
    reps <- unique(lg$Replicate)
    n_cult <- length(reps)
    n_tp <- suppressWarnings(max(vapply(split(lg$Time, lg$Replicate),
                                        function(t) length(unique(t[is.finite(t)])), integer(1))))
    if (!is.finite(n_tp) || n_tp < 1L) n_tp <- 1L
    per <- GROWTH_BOOT_COST_PER * n_cult * n_tp^2
    list(n_cult = n_cult, n_tp = n_tp, per = per, est = per * n_total, n_total = n_total)
  }
  observeEvent(input$growth_boot_run, {
    lg <- growth_long()
    if (is.null(lg) || !nrow(lg) || isTRUE(growth_nested_manual())) return()
    pf <- .growth_boot_preflight(lg, growth_boot_n())
    # Record ONLY the cheap request fingerprint (+ the estimate, so Confirm can route a heavy plate to the
    # background worker). No prepare, no draw -- Cancel from this modal costs nothing.
    boot_env$pending <- list(key = growth_data_key(), n_total = pf$n_total, per = pf$per, est = pf$est)
    over_budget <- is.finite(pf$est) && pf$est > GROWTH_BOOT_BUDGET_SEC
    heavy <- is.finite(pf$per) && pf$per > GROWTH_BOOT_SMOOTH_MAX
    bg <- .growth_bg_available()
    tail_txt <- if (heavy && bg)
      sprintf(paste0("This is a large run. It attempts a cancellable BACKGROUND process so the interface stays ",
             "responsive; if the background worker is not ready it falls back to short interruptible slices ",
             "(the interface then pauses briefly between slices). Cancel takes effect promptly on the background ",
             "path, or within one resample (~%s) in the slice fallback. Fewer timepoints per culture still ",
             "shortens it: the work grows steeply with the timepoint count (about its square over typical sizes, ",
             "approaching its cube for very large plates)."),
             .fmt_secs(pf$per))
    else if (over_budget)
      sprintf(paste0("This is a LARGE run (over ~%s) and no background worker is available, so it runs in ",
                     "short interruptible slices; a single resample (~%s) cannot be split, so the interface ",
                     "pauses in steps of about that length and Cancel takes up to that long. Fewer timepoints ",
                     "per culture shortens it steeply (about the square of the timepoint count over typical ",
                     "sizes, approaching the cube for very large plates)."),
              .fmt_secs(GROWTH_BOOT_BUDGET_SEC), .fmt_secs(pf$per))
    else if (heavy)
      sprintf(paste0("No background worker is available, so a single resample (~%s) cannot be interrupted ",
                     "part-way: the interface pauses in steps of about that length and Cancel takes up to ~%s. ",
                     "Fewer timepoints per culture is the most effective way to speed this up."),
              .fmt_secs(pf$per), .fmt_secs(pf$per))
    else paste0("It runs in short time-budgeted slices and yields to the interface between them, so the app ",
                "stays usable while it runs. Cancel stops it after the resample in flight finishes.")
    showModal(modalDialog(title = "Run reselection bootstrap?",
      sprintf(paste0("This re-runs the full log-linear OD-window selection on %d residual-bootstrapped resamples ",
                     "of %d culture(s) x up to %d timepoints. Estimated total: ~%s on this machine (~%s per ",
                     "resample), from the plate size (a measured model; the actual time is typically within ",
                     "~1.5x). Nothing is prepared or computed until you press Run, so Cancel costs nothing. %s"),
              pf$n_total, pf$n_cult, pf$n_tp, .fmt_secs(pf$est), .fmt_secs(pf$per), tail_txt),
      footer = tagList(actionButton("growth_boot_preflight_cancel", "Cancel"),
                       actionButton("growth_boot_confirm", "Run", class = "btn-primary"))))
  })
  observeEvent(input$growth_boot_preflight_cancel, { boot_env$pending <- NULL; removeModal() })

  # Confirm -> PREPARE (now, after consent) and start the cooperative chunked worker.
  observeEvent(input$growth_boot_confirm, {
    removeModal()
    pend <- boot_env$pending
    lg <- growth_long()
    if (!isTRUE(input$growth_boot) || isTRUE(growth_nested_manual()) || is.null(lg) || !nrow(lg) ||
        is.null(pend) || !identical(pend$key, growth_data_key())) {
      .boot_terminalize()
      growth_boot_state(list(status = "idle"))
      showNotification("The bootstrap request is no longer valid (the option, mode or data changed). Press Run again to restart it.",
                       type = "warning", duration = 8)
      return()
    }
    reps <- unique(lg$Replicate)
    st <- .growth_boot_prepare(lg, reps)          # PREPARE now (post-consent), not before the modal
    if (!st$n_models) {
      boot_env$pending <- NULL
      growth_boot_state(list(status = "idle"))
      showModal(modalDialog(title = "Bootstrap not available", easyClose = TRUE, footer = modalButton("OK"),
        sprintf("The reselection bootstrap could not run: no culture can be residual-bootstrapped. Of %d supplied culture(s): %s.",
                length(reps),
                { .p <- .growth_reason_phrase(st$n_too_few %||% 0L, st$n_nonpos %||% 0L,
                                              st$n_loessfail %||% 0L)
                  if (nzchar(.p)) .p else "none qualified" })))
      return()
    }
    boot_env$st <- st; boot_env$n_total <- pend$n_total; boot_env$key <- pend$key; boot_env$pending <- NULL
    boot_env$last_key <- pend$key
    growth_boot_cancel(FALSE)
    boot_env$active <- TRUE
    this_run <- isolate(boot_run_id()) + 1L
    boot_run_id(this_run)
    boot_env$run_id <- this_run
    growth_boot_state(list(status = "running", progress = boot_env$st$next_b - 1L,
                           n_total = boot_env$n_total, key = boot_env$key))
    run_chunk <- function() tryCatch({
      # Stale-callback guard: a callback from a superseded run must do nothing at all.
      if (!identical(boot_env$run_id, this_run)) return(invisible())
      if (!isTRUE(boot_env$active) || isTRUE(isolate(growth_boot_cancel()))) {
        boot_env$active <- FALSE
        growth_boot_state(list(status = "canceled", key = boot_env$key)); return(invisible())
      }
      st <- boot_env$st
      t_tick <- Sys.time()
      repeat {
        done_iters <- st$next_b - 1L
        if (done_iters >= boot_env$n_total) break
        st <- tryCatch(.growth_boot_step(st, 1L), error = function(e) NULL)
        if (is.null(st)) break
        if (as.numeric(difftime(Sys.time(), t_tick, units = "secs")) >= GROWTH_BOOT_TICK_BUDGET) break
      }
      if (is.null(st)) {
        boot_env$active <- FALSE
        growth_boot_state(list(status = "error", key = boot_env$key)); return(invisible())
      }
      boot_env$st <- st
      if ((st$next_b - 1L) >= boot_env$n_total) {
        boot_env$active <- FALSE
        growth_boot_state(list(status = "done", progress = boot_env$n_total, n_total = boot_env$n_total,
                               result = .growth_boot_finalize(st), key = boot_env$key)); return(invisible())
      }
      growth_boot_state(list(status = "running", progress = st$next_b - 1L,
                             n_total = boot_env$n_total, key = boot_env$key))
      later::later(run_chunk, delay = 0.01)   # yield to the event loop, then continue
    }, error = function(e) {
      boot_env$active <- FALSE
      growth_boot_state(list(status = "error", key = boot_env$key, error = conditionMessage(e)))
    })
    start_cooperative <- function() later::later(run_chunk, delay = 0.01)
    fall_back_cooperative <- function() {
      .stop_boot_bg()                                                  # stop this session's task + release refcount
      .growth_bg_invalidate()                                         # re-check readiness on the next run (daemon may have died)
      .growth_bg_stop_daemon()
      start_cooperative()                                             # run the whole bootstrap cooperatively
    }
    .heavy <- is.finite(pend$per %||% NA_real_) && (pend$per %||% 0) > GROWTH_BOOT_SMOOTH_MAX
    still_ours <- function() identical(boot_env$run_id, this_run) &&
      isTRUE(boot_env$active) && !isTRUE(isolate(growth_boot_cancel()))
    launch_bg <- function() {
      {
      if (!still_ours()) return(invisible())
      if (!isTRUE(.stop_boot_bg())) return(fall_back_cooperative())
      m <- tryCatch(mirai::mirai({ RNGkind("Mersenne-Twister", "Inversion", "Rejection")
                                   .growth_boot_finalize(.growth_boot_step(ST, N)) },
                                 ST = boot_env$st, N = boot_env$n_total), error = function(e) NULL)
      if (is.null(m)) return(fall_back_cooperative())                           # mirai launch itself failed
      boot_env$mirai <- m
      boot_env$holds_task <- TRUE; if (is.function(.growth_bg_task_acquire)) .growth_bg_task_acquire()
      growth_boot_state(list(status = "running_bg", progress = boot_env$st$next_b - 1L,   # background does not stream counts
                             n_total = boot_env$n_total, key = boot_env$key))
      bg_deadline <- Sys.time() + as.difftime(max(180, 5 * (pend$est %||% 30)), units = "secs")
      poll_bg <- function() {
        tryCatch({
          if (!identical(boot_env$run_id, this_run)) return(invisible())          # superseded run
          if (!isTRUE(boot_env$active) || isTRUE(isolate(growth_boot_cancel()))) {          # canceled
            boot_env$active <- FALSE; .stop_boot_bg()
            growth_boot_state(list(status = "canceled", key = boot_env$key)); return(invisible())
          }
          if (mirai::unresolved(m)) {
            if (Sys.time() > bg_deadline) return(fall_back_cooperative())         # daemon stuck/dead mid-run
            later::later(poll_bg, delay = 0.15); return(invisible())
          }
          res <- tryCatch(m$data, error = function(e) NULL); boot_env$mirai <- NULL
          if (is.list(res) && !is.null(res$n_boot)) {
            boot_env$active <- FALSE; .boot_release_task()
            growth_boot_state(list(status = "done", progress = boot_env$n_total, n_total = boot_env$n_total,
                                   result = res, key = boot_env$key))
          } else return(fall_back_cooperative())                                 # task returned no valid result
        }, error = function(e) {
          tryCatch(fall_back_cooperative(), error = function(e2) {               # boundary: any fault -> terminal
            boot_env$active <- FALSE; boot_env$mirai <- NULL
            tryCatch(.boot_release_task(), error = function(e3) NULL)            # release exactly once (guarded)
            tryCatch(growth_boot_state(list(status = "error", key = boot_env$key)), error = function(e3) NULL)
          })
        })
      }
      later::later(poll_bg, delay = 0.15)
      }
    }
    if (isTRUE(.heavy) && .growth_bg_available()) {
      # Show a cancellable "starting worker" state IMMEDIATELY, then resolve readiness OFF the event loop.
      growth_boot_state(list(status = "starting", n_total = boot_env$n_total, key = boot_env$key))
      .growth_bg_ready_async(on_ready = launch_bg,
          on_fail = function() if (still_ours()) start_cooperative(),   # readiness failed -> cooperative worker
          should_continue = still_ours)
      return()   # readiness is async -- do NOT also start the cooperative worker synchronously here
    }
    start_cooperative()
  })

  observeEvent(input$growth_boot_cancel_run, {
    .boot_terminalize()
    growth_boot_state(list(status = "canceled", key = boot_env$key))
  })

  observeEvent(input$growth_boot, {
    if (!isTRUE(input$growth_boot)) {
      .boot_terminalize()
      growth_boot_state(list(status = "idle"))   # drop any completed/merged result
    }
  }, ignoreInit = TRUE)

  # Run / Cancel / progress controls (classic mode only).
  output$growth_boot_controls <- renderUI({
    if (!isTRUE(input$growth_boot) || isTRUE(growth_nested_manual())) return(NULL)
    bs <- growth_boot_state()
    if (identical(bs$status, "starting")) {
      div(style = "margin:4px 0 6px;",
        div(style = "font-size:0.85em;margin-bottom:3px;color:var(--pasa-muted-fg);",
            "Starting background worker… Cancel is available; if the worker is not ready it falls back to short interruptible slices."),
        div(style = "height:6px;background:var(--bs-tertiary-bg);border-radius:3px;overflow:hidden;",
            div(style = "height:100%;width:40%;background:#6c8ebf;")),
        actionButton("growth_boot_cancel_run", "Cancel", class = "btn-warning btn-sm", style = "margin-top:5px;"))
    } else if (identical(bs$status, "running_bg")) {
      div(style = "margin:4px 0 6px;",
        div(style = "font-size:0.85em;margin-bottom:3px;",
            sprintf("Bootstrap running in the background (%d resamples). Per-resample progress is not reported; Cancel remains available.", bs$n_total)),
        tags$progress(style = "width:100%;height:6px;", max = 1),
        actionButton("growth_boot_cancel_run", "Cancel", class = "btn-warning btn-sm", style = "margin-top:5px;"))
    } else if (identical(bs$status, "running")) {
      tot <- bs$n_total %||% 0L; prog <- bs$progress %||% 0L
      pct <- if (tot > 0) round(100 * prog / tot) else 0
      div(style = "margin:4px 0 6px;",
        div(style = "font-size:0.85em;margin-bottom:3px;",
            sprintf("Bootstrap running… %d%% (%d / %d resamples)", pct, prog, tot)),
        div(style = "height:6px;background:var(--bs-tertiary-bg);border-radius:3px;overflow:hidden;",
            div(style = sprintf("height:100%%;width:%d%%;background:#28a745;", pct))),
        actionButton("growth_boot_cancel_run", "Cancel", class = "btn-warning btn-sm", style = "margin-top:5px;"))
    } else {
      lbl <- switch(bs$status %||% "idle",
                    done = "Re-run bootstrap", canceled = "Run bootstrap", error = "Run bootstrap (retry)", "Run bootstrap")
      div(style = "margin:4px 0 6px;",
        actionButton("growth_boot_run", lbl, class = "btn-primary btn-sm"),
        if (identical(bs$status, "done")) span(style = "margin-left:8px;color:var(--pasa-ok-fg);font-size:0.85em;", "✓ bootstrap complete")
        else if (identical(bs$status, "canceled")) span(style = "margin-left:8px;color:var(--pasa-warn-fg);font-size:0.85em;", "canceled")
        else NULL)
    }
  })

  output$growth_boot_nested_note <- renderUI({
    if (isTRUE(growth_nested_manual()) && isTRUE(input$growth_boot))
      div(style = "margin:2px 0 6px;padding:6px 9px;border-left:3px solid #e69500;background:rgba(230,149,0,0.08);font-size:0.82em;",
          "Nested (biological × technical) mode is active. The reselection bootstrap applies to the classic single-level engine only; the nested engine reports its own conditional sensitivity interval, so this checkbox has no effect here.")
    else NULL
  })

  output$growth_top_downloads <- renderUI({
    r <- growth_result(); if (is.null(r) || !isTRUE(r$ok)) return(NULL)
    div(style = "display:flex;gap:6px;flex-wrap:wrap;",
      downloadButton("growth_top_dl_pdf", "Download as PDF", class = "btn-sm btn-outline-primary"),
      downloadButton("growth_top_dl_img", "Download as Image", class = "btn-sm btn-outline-primary"))
  })

  # ---- Live summary sentence ----
  output$growth_summary_sentence <- renderUI({
    if (!growth_active()) return(NULL)
    strain <- if (isTruthy(input$growth_strain)) input$growth_strain else "your strain"
    unit <- growth_unit_word(); iv <- growth_interval()
    ntp <- if (growth_mode() == "manual") growth_n_tp() else {
      lg <- growth_long(); if (is.null(lg)) growth_n_tp() else length(unique(lg$Time)) }
    total <- iv * (ntp - 1)
    wl <- growth_wl_label()
    wl_txt <- if (growth_mode() == "sidebar") sprintf(" on the uploaded basis at %s nm (exact native node or labeled gap-guarded interpolation)", wl) else ""
    div(style="margin-top:8px;padding:8px 12px;border-radius:6px;background:var(--bs-tertiary-bg);font-size:0.95em;",
      sprintf("You entered growth data for %s%s every %.4g %s over %.4g %s, with %d replicate(s). Total elapsed time spans interval × (timepoints − 1).",
              strain, wl_txt, iv, unit, total, unit, growth_n_rep()))
