  # ---- Result message / essential outputs ----
  output$growth_result_msg <- renderUI({
    if (!growth_active())
      return(div(em("Activate a data path above to see results.")))
    r <- growth_result()
    if (is.null(r)) return(div(em("Enter data (map samples or fill the grid) to compute the growth curve.")))
    if (!isTRUE(r$ok)) {
      has_curve <- !is.null(r$long) && nrow(r$long) > 0
      return(div(class="alert alert-info", style="font-size:0.92em;",
                 tags$b("Apparent OD-derived rate not estimated. "),
                 r$message,
                 if (has_curve) tags$div(style="margin-top:4px;",
                   em("Your available uploaded-basis or manual OD observations are plotted below so you can still inspect the trend."))))
    }
    NULL
  })

  output$growth_plot <- renderPlot({
    r <- growth_result(); req(r)
    p <- growth_plot(r, phase_alpha = if (isTruthy(input$growth_phase_alpha)) input$growth_phase_alpha else 1)
    req(!is.null(p))
    if (isTRUE(is_dark())) {
      if (inherits(p, "patchwork") && isTRUE(has_patchwork)) {
        p & theme_bg(TRUE)
      } else {
        p + theme_bg(TRUE)
      }
    } else p
  }, bg = "transparent",
  alt = "Growth curve: optical density (OD) versus time for each replicate, with the fitted log-linear OD window and operationally detected OD-trend phases highlighted.")

  output$growth_metrics_cards <- renderUI({
    r <- growth_result(); if (is.null(r) || !isTRUE(r$ok)) return(NULL)
    u <- r$unit_sing
    fmt <- function(x, d=3) formatC(x, digits=d, format="f")
    ci_txt <- if (!is.null(r$mu_ci)) sprintf(" (%s–%s, %s)%s", fmt(r$mu_ci[1]), fmt(r$mu_ci[2]), .MU_INTERVAL_LABEL, if (isTRUE(r$n_fit != r$n_rep)) " — over fitted replicates only" else "") else ""
    layout_columns(col_widths = c(6,6),
      value_box(title = "Apparent OD-derived log-linear rate (μ)",
                value = sprintf("%s %s⁻¹", fmt(r$mu_mean), u),
                showcase = NULL, p(ci_txt)),
      value_box(title = "OD doubling time",
                value = sprintf("%s %s", fmt(r$td_mean, 2), u),
                showcase = NULL, p(if (isTRUE(r$nested))
                  sprintf("n = %d of %d biological units contributed", r$n_bio_contributing %||% r$n_fit,
                          r$n_bio_supplied %||% r$n_rep)
                  else if (isTRUE((r$n_missing %||% 0L) > 0L))
                    sprintf("n = %d of %d configured replicates fitted (%d data-bearing, %d configured but blank)",
                            r$n_fit, r$n_configured, r$n_data_bearing, r$n_missing)
                  else sprintf("n = %d of %d replicates fitted", r$n_fit, r$n_rep))))
  })

  output$growth_interpretation <- renderUI({
    r <- growth_result(); if (is.null(r)) return(NULL)
    txt <- tryCatch(growth_interpretation(r), error = function(e) NULL)
    if (is.null(txt) || !nzchar(txt)) return(NULL)
    parts     <- strsplit(txt, .GROWTH_DETAIL_SEP, fixed = TRUE)[[1]]
    essential <- trimws(parts[1])
    detail    <- if (length(parts) > 1) trimws(paste(parts[-1], collapse = "")) else ""
    # od_note and any embedded "\n\n" become paragraph breaks inside the expander.
    detail_paras <- if (nzchar(detail)) strsplit(detail, "\n\n", fixed = TRUE)[[1]] else character(0)
    tagList(
      tags$p(style = "margin:0;", essential),
      if (length(detail_paras))
        tags$details(class = "growth-interp-detail", style = "margin-top:8px;",
          tags$summary(style = "cursor:pointer;font-weight:500;", "Show details & caveats"),
          lapply(detail_paras, function(p) tags$p(style = "margin:6px 0 0;", trimws(p))))
    )
  })

  # ---- Advanced / supplementary outputs ----
  output$growth_advanced_block <- renderUI({
    r <- growth_result(); if (is.null(r))
      return(div(em("Advanced outputs appear once a valid fit is available.")))
    if (!isTRUE(r$ok))
      return(tagList(
        div(em("Advanced outputs appear once a valid fit is available.")),
        div(style = "margin-top:8px;display:flex;gap:8px;flex-wrap:wrap;",
            downloadButton("growth_dl_summary", "Summary CSV", class = "btn-sm"),
            downloadButton("growth_dl_observations", "Observations CSV", class = "btn-sm"),
            downloadButton("growth_dl_contract", "Window contract CSV", class = "btn-sm")),
        div(style = "margin-top:4px;font-size:0.85em;color:var(--pasa-muted-fg);",
            if (isTRUE(r$nested))
              "The summary preserves the supplied, in-window, and contributing biological-unit counts. A qualifying-window k/n estimand is not defined for the nested common-window model, so it is recorded as not applicable."
            else
              "The summary records the observed qualifying-window result (k of n and its Wilson binomial reference interval) even though no rate could be fitted.")))
    has_perrep <- !is.null(r$per_rep) && !is.null(r$best_each)
    has_phases <- !is.null(r$phases) && NROW(r$phases) > 0
    tagList(
      if (has_perrep) tagList(
        h5("Per-replicate best-window fits"),
        tableOutput("growth_bestfit_tbl"),
        h5("Window candidates (all qualifying windows)"),
        div(style="max-height:280px;overflow:auto;", tableOutput("growth_candidates_tbl"))),
      if (isTRUE(r$nested) && !has_perrep)
        div(style="font-size:0.9em;color:var(--pasa-muted-fg);margin-bottom:6px;",
            em("Nested biological × technical analysis: a common log-linear OD window is fitted across biological units, so there are no per-replicate window tables. The summary and phase outputs below apply.")),
      if (has_phases) tagList(h5("Detected phase boundaries"), tableOutput("growth_phase_tbl")),
      div(style="margin-top:10px;display:flex;gap:8px;flex-wrap:wrap;",
        downloadButton("growth_dl_summary", "Summary CSV", class="btn-sm"),
        downloadButton("growth_dl_observations", "Observations CSV", class="btn-sm"),
        downloadButton("growth_dl_contract", "Window contract CSV", class="btn-sm"),
