  .growth_observations_df <- function(d) {
    if (is.null(d) || !is.data.frame(d) || !nrow(d)) return(data.frame())
    wanted <- c("Time", "Replicate", "biological_rep", "technical_rep", "OD",
                "SourceSample", "TrackingWavelengthNm", "InputBasis",
                "ExtractionMethod", "ExtractionReason", "BracketLowerNm",
                "BracketUpperNm", "BracketingGapNm", "MaxAllowedGapNm",
                "SourceFinitePointCount", "SourceDistinctWavelengthCount")
    for (nm in setdiff(wanted, names(d))) d[[nm]] <- NA
    d[, wanted, drop = FALSE]
  }

  .growth_dl_csv <- function(fn, getter, allow_no_fit = FALSE) downloadHandler(
    filename = function() fn,
    content = function(file) {
      r <- growth_result()
      .emit <- !is.null(r) && (isTRUE(r$ok) || isTRUE(allow_no_fit))
      d <- if (.emit) getter(r) else data.frame()
      utils::write.csv(.sanitize_df_for_csv(as.data.frame(d)), file, row.names = FALSE, na = "")
    })
  .growth_summary_df <- function(r) {
    nested <- isTRUE(r$nested)
    obs    <- !nested                      # observed k/n defined only on the classic path
    has_ci <- obs && length(r$p_observed_ci) == 2L
    n_sup  <- if (nested) r$n_bio_supplied %||% r$n_rep %||% NA_integer_ else r$n_rep %||% NA_integer_
    n_con  <- if (nested) r$n_bio_contributing %||% r$n_fit %||% NA_integer_ else r$n_fit %||% NA_integer_
    data.frame(strain = r$strain %||% NA_character_,
               tracking_wavelength_nm = r$wl %||% NA,
               unit = r$unit %||% NA_character_,
               n_replicates = n_sup, n_fitted = n_con,
               n_biological_supplied     = if (nested) r$n_bio_supplied %||% NA_integer_ else NA_integer_,
               n_biological_configured    = if (nested) r$n_bio_configured %||% r$n_bio_supplied %||% NA_integer_ else NA_integer_,
               n_biological_in_window     = if (nested) r$n_bio_in_window %||% NA_integer_ else NA_integer_,
               n_biological_contributing  = if (nested) r$n_bio_contributing %||% NA_integer_ else NA_integer_,
               n_biological_excluded      = if (nested) r$n_bio_excluded %||% NA_integer_ else NA_integer_,
               # observed two-part result (point quantities; independent of the bootstrap)
               qualifying_window_estimand = if (nested) "not_applicable_nested"
                                            else "observed_qualifying_window_k_of_n_data_bearing_cultures",
               qualifying_window_k = if (obs) r$k_observed %||% NA_integer_ else NA_integer_,
               qualifying_window_n = if (obs) r$n_rep %||% NA_integer_ else NA_integer_,
               qualifying_window_fraction = if (obs) r$p_observed %||% NA_real_ else NA_real_,
               qualifying_window_wilson_low  = if (has_ci) r$p_observed_ci[1] else NA_real_,
               qualifying_window_wilson_high = if (has_ci) r$p_observed_ci[2] else NA_real_,
               mu = r$mu_mean %||% NA_real_, mu_sd = r$mu_sd %||% NA_real_,
               mu_sem = r$mu_sem %||% NA_real_,
               doubling_time = r$td_mean %||% NA_real_,
               mu_conditional_ci_low  = if (!is.null(r$mu_ci)) r$mu_ci[1] else NA_real_,
               mu_conditional_ci_high = if (!is.null(r$mu_ci)) r$mu_ci[2] else NA_real_,
               # bootstrap fields, explicitly labeled CONDITIONAL so they cannot be read as population
               mu_bootstrap_conditional_ci_low  = if (!is.null(r$mu_ci_boot)) r$mu_ci_boot[1] else NA_real_,
               mu_bootstrap_conditional_ci_high = if (!is.null(r$mu_ci_boot)) r$mu_ci_boot[2] else NA_real_,
               bootstrap_n_eligible = r$boot_n_eligible %||% NA_integer_,
               bootstrap_n_indeterminate = r$boot_n_indeterminate %||% NA_integer_,
               growth_n_configured   = if (nested) r$n_bio_configured   %||% NA_integer_ else r$n_configured   %||% NA_integer_,
               growth_n_data_bearing = if (nested) r$n_bio_supplied     %||% NA_integer_ else r$n_data_bearing %||% NA_integer_,
               growth_n_fitted       = if (nested) r$n_bio_contributing %||% NA_integer_ else r$n_fit          %||% NA_integer_,
               growth_n_missing      = if (nested) {
                                         .gcfg <- suppressWarnings(as.integer(r$n_bio_configured %||% r$n_bio_supplied))
                                         .gsup <- suppressWarnings(as.integer(r$n_bio_supplied))
                                         if (is.na(.gcfg) || is.na(.gsup)) NA_integer_ else max(0L, .gcfg - .gsup)
                                       } else r$n_missing %||% NA_integer_,
               bootstrap_attempted = suppressWarnings(as.integer(r$boot_n_attempt %||% 0L)),
               bootstrap_successful_rate_resamples = suppressWarnings(as.integer(r$boot_n %||% 0L)),
               bootstrap_success_rate = { .a <- suppressWarnings(as.numeric(r$boot_n_attempt %||% 0L))
                                          .s <- suppressWarnings(as.numeric(r$boot_n %||% 0L))
                                          if (is.finite(.a) && .a > 0 && is.finite(.s)) .s / .a else NA_real_ },
               bootstrap_interval_status = {
                 .a <- suppressWarnings(as.integer(r$boot_n_attempt %||% 0L))
                 .s <- suppressWarnings(as.integer(r$boot_n %||% 0L))
                 .haveci <- !is.null(r$mu_ci_boot) && length(r$mu_ci_boot) == 2L && all(is.finite(r$mu_ci_boot))
                 .min <- suppressWarnings(as.integer(r$boot_min_success %||% 100L))
                 if (!is.finite(.a) || .a == 0L) "disabled"
                 else if (isTRUE(r$boot_insufficient)) "insufficient_success"
                 else if (isTRUE(.haveci) && is.finite(.s) && .s >= .min) "available"
                 else "failed" },
               bootstrap_min_success_required = suppressWarnings(as.integer(r$boot_min_success %||% 100L)),
               bootstrap_conditional_estimand = r$boot_estimand %||% NA_character_,
               internally_consistent = r$internally_consistent %||% NA,
               stringsAsFactors = FALSE)
  }
  output$growth_dl_summary <- .growth_dl_csv("growth_summary.csv", .growth_summary_df,
                                             allow_no_fit = TRUE)
