  # ==========================================================================
  # DECONVOLUTION (Advanced Mode) -- server logic
  # All on-demand: the fit runs ONLY on the decon_run actionButton. The curve
  # fitted input is the native-grid analysis curve retained in results(): after
  # dilution scaling, baseline correction, and optional normalization, but before
  # display resampling or smoothing. A documented legacy fallback is used only for
  # older result rows that do not carry those native-fit fields.
  # ==========================================================================

  # --- Advanced Mode: insert/remove the Deconvolution tab at runtime ---------
  # The Deconvolution nav_panel (decon_tab, defined at top level) is NOT baked
  # into page_navbar(); it is inserted AFTER "Data Quality" only while the toggle is
  # ON and removed when OFF. select = FALSE keeps the user's current tab focus,
  # and a presence flag prevents double-insert / double-remove, so toggling has
  # ZERO effect on the order, active tab, or state of any other tab.
  .decon_tab_present <- reactiveVal(FALSE)
  .decon_tab_generation <- reactiveVal(0L)
  .advance_decon_tab_generation <- function() {
    .decon_tab_generation(isolate(.decon_tab_generation()) + 1L)
    invisible()
  }
  observeEvent(input$advanced_mode, {
    want <- isTRUE(input$advanced_mode)
    have <- isTRUE(.decon_tab_present())
    if (want && !have) {
      bslib::nav_insert(
        "main_nav", target = "Data Quality", position = "after",
        select = FALSE, session = session,
        nav = decon_tab
      )
      .decon_tab_present(TRUE)
      .advance_decon_tab_generation()
    } else if (!want && have) {
      bslib::nav_remove("main_nav", target = "Deconvolution", session = session)
      .decon_tab_present(FALSE)
      .advance_decon_tab_generation()
    }
  }, ignoreInit = FALSE)

  # A snapshot can enable Advanced Mode and restore its controls in the same
  # transaction. Those controls do not exist until nav_insert reaches the
  # browser. A value left over from the preceding widget instance is not an
  # acknowledgment of the current restore. Retain the transaction until every
  # control has acknowledged a generation-bound forced echo and all typed values
  # agree for four consecutive post-flush checks.
  .DECON_RESTORE_STABLE_PASSES <- 4L
  .DECON_RESTORE_MAX_ATTEMPTS <- 120L
  .decon_restore_ack_id <- function(key)
    paste0("pasa_decon_restore_ack_", key)
  .decon_restore_ack_token <- function(generation, tab_generation)
    paste(as.integer(generation), as.integer(tab_generation), sep = ":")
  .decon_restore_pending_current <- function(live, expected_txn,
                                              expected_generation,
                                              current_txn,
                                              current_generation) {
    !is.null(live) &&
      identical(live$restore_txn, expected_txn) &&
      identical(live$generation, expected_generation) &&
      identical(current_txn, expected_txn) &&
      identical(current_generation, expected_generation)
  }
  .decon_restore_stable_step <- function(previous, values_match, echoes_match) {
    if (isTRUE(values_match) && isTRUE(echoes_match)) as.integer(previous) + 1L else 0L
  }
  .decon_restore_same_value <- function(actual, expected) {
    if (is.null(expected) || is.null(actual)) return(FALSE)
    if (is.numeric(expected))
      return(isTRUE(all.equal(as.numeric(actual), as.numeric(expected),
                              tolerance = 0, check.attributes = FALSE)))
    if (is.logical(expected))
      return(length(actual) == 1L && !is.na(actual) &&
               identical(as.logical(actual), expected))
    identical(as.character(actual), as.character(expected))
  }
  observeEvent(list(pending_decon_settings_restore(), input$advanced_mode,
                    .decon_tab_present(), .decon_tab_generation()), {
    decon_restore_apply_env$token <- decon_restore_apply_env$token + 1L
    .callback_token <- decon_restore_apply_env$token
    .pending <- pending_decon_settings_restore()
    if (is.null(.pending) || !isTRUE(input$advanced_mode) ||
        !isTRUE(.decon_tab_present())) return(invisible())
    .txn <- .pending$restore_txn
    .generation <- .pending$generation
    .tab_generation <- isolate(.decon_tab_generation())
    .values <- .pending$values
    if (length(.txn) != 1L || length(.generation) != 1L) return(invisible())
    .attempt <- new.env(parent = emptyenv())
    .attempt$n <- 0L
    .attempt$stable <- 0L
    .expected_value <- function(key, raw) {
      .i <- match(key, .SNAPSHOT_SETTINGS_REGISTRY$key)
      if (is.na(.i)) return(NULL)
      .op <- .SNAPSHOT_SETTINGS_REGISTRY$parse[[.i]]
      tryCatch(if (is.function(.op)) .op(raw) else raw,
               error = function(e) NULL)
    }
    .expected <- lapply(names(.values), function(.k)
      .expected_value(.k, .values[[.k]]))
    names(.expected) <- names(.values)
    .same_value <- function(key, expected) {
      .actual <- isolate(input[[key]])
      .decon_restore_same_value(.actual, expected)
    }
    .ack_token <- .decon_restore_ack_token(.generation, .tab_generation)
    .is_current <- function() {
      if (!.restore_callbacks$alive()) return(FALSE)
      isTRUE(tryCatch({
        .live <- isolate(pending_decon_settings_restore())
        identical(.callback_token, decon_restore_apply_env$token) &&
          .decon_restore_pending_current(
            .live, .txn, .generation,
            isolate(restore_txn()), isolate(decon_settings_restore_generation())) &&
          identical(isolate(.decon_tab_generation()), .tab_generation) &&
          isTRUE(isolate(input$advanced_mode)) &&
          isTRUE(isolate(.decon_tab_present()))
      }, error = function(e) FALSE))
    }
    .replay <- function() {
      for (.k in names(.values)) {
        tryCatch(.apply_one_setting(session, .k, .values[[.k]]),
                 error = function(e) FALSE)
        .ev <- .expected[[.k]]
        if (length(.ev) == 1L && !is.null(.ev) && !is.na(.ev)) {
          tryCatch(session$sendCustomMessage(
            "pasa_restore_input_echo",
            list(id = .k, value = unname(.ev),
                 ack_id = .decon_restore_ack_id(.k),
                 ack_value = .ack_token)),
            error = function(e) NULL)
        }
      }
      invisible()
    }
    .schedule_retry <- function() {
      if (!requireNamespace("later", quietly = TRUE)) return(invisible())
      session$onFlushed(function() {
        if (.is_current()) .restore_callbacks$schedule(.retry, delay = 0.25)
      }, once = TRUE)
      invisible()
    }
    .retry <- function() {
      if (!.is_current()) return(invisible())
      .attempt$n <- .attempt$n + 1L
      # Replay on every attempt. The first check cannot pass because its unique
      # acknowledgments do not exist until the browser consumes this message.
      .replay()
      .values_match <- !length(.values) ||
        all(vapply(names(.values), function(.k)
          .same_value(.k, .expected[[.k]]), logical(1)))
      .echoes_match <- !length(.values) ||
        all(vapply(names(.values), function(.k)
          identical(as.character(isolate(input[[.decon_restore_ack_id(.k)]])),
                    .ack_token), logical(1)))
      .attempt$stable <- .decon_restore_stable_step(
        .attempt$stable, .values_match, .echoes_match)
      if (.attempt$stable >= .DECON_RESTORE_STABLE_PASSES) {
        pending_decon_settings_restore(NULL)
        return(invisible())
      }
      if (.attempt$n < .DECON_RESTORE_MAX_ATTEMPTS) {
        .schedule_retry()
      } else {
        pending_decon_settings_restore(NULL)
        showNotification(
          "Some restored Deconvolution settings could not be confirmed by the browser; check the controls before continuing.",
          type = "warning", duration = 8, session = session)
      }
      invisible()
    }
    if (requireNamespace("later", quietly = TRUE)) {
      session$onFlushed(function() {
        if (.is_current()) .restore_callbacks$schedule(.retry, delay = 0.25)
      }, once = TRUE)
    } else {
      session$onFlushed(.restore_callbacks$guard(function() .retry()), once = TRUE)
    }
  }, ignoreNULL = FALSE, priority = -50)

  # --- Transparent input-provenance banner (above the controls) ------------
  output$decon_input_provenance <- renderUI({
    .bs <- decon_blank_state()
    if (isTRUE(input$decon_scatter_on) && identical(.bs$status, "invalid"))
      return(div(class = "decon-baseline-warn", role = "alert",
        "Deconvolution is unavailable until the measured blank is corrected or removed. ", .bs$reason))
    # Use the app's own settings-summary string so wording stays consistent.
    summ <- tryCatch(metrics_subtitle(input, nm_native = tryCatch(dat()[[1]], error = function(e) NULL), eff = tryCatch(.metrics_eff_summary(results()), error = function(e) NULL)), error = function(e) NULL)
    base_on <- isTRUE(input$apply_baseline)
    .drow <- tryCatch({
      rr <- results()
      rr[as.character(rr$sample) == as.character(input$decon_sample), , drop = FALSE][1, , drop = FALSE]
    }, error = function(e) NULL)
    .dnorm_req <- isTruthy(input$norm_method) && !identical(input$norm_method, "none")
    .dnorm_ap <- if (!is.null(.drow) && nrow(.drow) && ".decon_native_norm_applied" %in% names(.drow))
                   .drow$.decon_native_norm_applied[[1]] else NA
    .dnorm_reason <- if (!is.null(.drow) && nrow(.drow) && ".decon_native_norm_reason" %in% names(.drow))
                       as.character(.drow$.decon_native_norm_reason[[1]]) else "unrecorded"
    div(class = "detected-info",
      tags$b("Input fed to deconvolution: "),
      if (base_on)
        "the analysis-pipeline settings for the selected sample are \u2014 "
      else
        "baseline correction is OFF, so deconvolution is disabled (see the note below). The pipeline that WOULD be applied is \u2014 ",
      if (!is.null(summ)) summ else "settings unavailable.",
      tags$br(),
      tags$span(style = "opacity:0.8;",
        if (isTRUE(input$decon_scatter_on))
          paste0(
            if (isTRUE(tryCatch(.decon_scatter_axis(
                  results()[as.character(results()$sample) == as.character(input$decon_sample), , drop = FALSE]
                )$use_native, error = function(e) NA)))
              "With local baseline pre-processing ON, the fit still runs on analysis-range-clipped native-grid analysis-curve values (original wavelength coordinates; pre-resample and unsmoothed)"
            else
              paste0("With local baseline pre-processing ON, this is the analysis-range-clipped",
                     if (isTRUE(input$resample_on)) ", resampled" else "",
                     if (isTruthy(input$smooth) && input$smooth != "none") ", smoothed" else "",
                     " curve"),
            if (isTruthy(decon_blank_df()))
              ", with the uploaded measured blank subtracted."
            else ", with the fitted power-law baseline subtracted.")
        else
          "With scattering OFF (default), the fit and its information criteria run on native-grid analysis-curve values (original wavelength coordinates; pre-resample and unsmoothed), baseline-corrected",
        if (!isTRUE(input$decon_scatter_on) && isTRUE(.dnorm_req) && isTRUE(.dnorm_ap))
          " and effectively normalized (amplitudes/areas are in normalized units)."
        else if (!isTRUE(input$decon_scatter_on) && isTRUE(.dnorm_req))
          sprintf("; native-fit normalization was requested but not applied (%s), so Run will refuse this fit.", .dnorm_reason)
        else if (!isTRUE(input$decon_scatter_on))
          " (amplitudes/areas are in the curve's OD units)." else ""
      ),
      if (isTRUE(input$decon_scatter_on)) tagList(
        tags$br(),
        tags$span(style = "color:var(--pasa-warn-fg);font-weight:600;",
          if (isTruthy(decon_blank_df())) paste0(
            "Measured-blank subtraction is ON: the uploaded blank curve is ",
            "subtracted directly from this input — no power law is fitted, and no red-edge tail ",
            "window is used. The blank must cover the whole analysis range or the fit is refused. ",
            "The offset baseline in Analysis settings is bypassed for this input.")
          else paste0(
            "Empirical baseline correction is ON: an inverse-power curve is fitted on the ",
            "user-selected red-edge window and extrapolated before this fit. This does not establish ",
            "a scattering regime or prove the window absorption-free. The offset baseline in Analysis settings is ",
            "bypassed for this input (its constant is replaced by the fitted c — see the panel below).")))
    )
  })

  # --- Live tail-window validation vs the selected sample's data range -------
  # Surface the tail-window guard in the UI before the fit runs: this
  # dataset stops at 750 nm, so the 730-800 default is clamped and flagged.
  output$decon_scatter_window_note <- renderUI({
    if (!isTRUE(input$decon_scatter_on)) return(NULL)
    res  <- tryCatch(results(), error = function(e) NULL)
    samp <- input$decon_sample
    if (is.null(res) || !nrow(res) || !isTruthy(samp)) return(NULL)
    row <- res[as.character(res$sample) == as.character(samp), , drop = FALSE]
    if (!nrow(row)) return(NULL)
    fs <- suppressWarnings(as.numeric(input$decon_scatter_start)); if (!is.finite(fs)) fs <- 730
    fe <- suppressWarnings(as.numeric(input$decon_scatter_end));   if (!is.finite(fe)) fe <- 800
    .bst <- decon_blank_state()
    if (identical(.bst$status, "invalid"))
      return(div(class = "decon-baseline-warn", role = "alert", .bst$reason))
    .blank_now <- .decon_blank_state_data(.bst)
    if (isTruthy(.blank_now)) {
      .ax <- .decon_scatter_axis(row)
      .cvg <- if (!is.null(.ax) && is.data.frame(.blank_now) &&
                  all(c("nm","val") %in% names(.blank_now))) {
        .bo <- is.finite(.blank_now$nm) & is.finite(.blank_now$val)
        if (sum(.bo) >= 2) {
          .al <- suppressWarnings(as.numeric(stats::approx(.blank_now$nm[.bo], .blank_now$val[.bo],
                                                           xout = .ax$nm, rule = 1)$y))
          .al[!.coverage_mask(.ax$nm, .blank_now$nm[.bo], AUC_MAX_GAP_NM,
                              eff_gap = .blank_coverage_gap(.blank_now$nm[.bo]))] <- NA_real_
          c(sum(is.finite(.al)), length(.ax$nm))
        } else c(0L, length(.ax$nm))
      } else NULL
      if (is.null(.cvg))
        return(div(style = "font-size:0.8em;color:var(--pasa-ok-fg);margin-top:6px;",
                   "Measured blank supplied: it is subtracted directly, so no red-edge tail window and no power law are used."))
      if (.cvg[1] == 0L)
        return(div(class = "decon-baseline-warn", style = "margin-top:8px;",
                   tags$ul(style = "margin:0;padding-left:18px;", tags$li(
                     sprintf("The blank overlaps 0 of this sample's %d wavelengths. ", .cvg[2]),
                     .decon_blank_zero_overlap_msg(.blank_now$nm, .ax$nm, "prefit")))))
      if (.cvg[1] < .cvg[2])
        return(div(class = "decon-baseline-warn", style = "margin-top:8px;",
                   tags$ul(style = "margin:0;padding-left:18px;", tags$li(
                     sprintf("The measured blank covers %d of this sample's %d wavelengths; the fit is refused unless it covers the whole analysis range. No tail window or power law is used on this path.",
                             .cvg[1], .cvg[2])))))
      return(div(style = "font-size:0.8em;color:var(--pasa-ok-fg);margin-top:6px;",
                 sprintf("Measured blank covers all %d of this sample's wavelengths; it is subtracted directly, so no red-edge tail window and no power law are used.",
                         .cvg[2])))
    }
    .tp <- .decon_scatter_tail_preview(row, fit_start = fs, fit_end = fe)
    if (is.null(.tp) || !is.finite(.tp$data_min) || !is.finite(.tp$data_max)) return(NULL)
    dmin <- .tp$data_min; dmax <- .tp$data_max; npts <- .tp$n_tail
    msgs <- character(0)
    if (fe <= fs) msgs <- c(msgs, "Tail end must be greater than tail start.")
    if (isTRUE(.tp$clamped_hi))
      msgs <- c(msgs, sprintf("Tail end (%.0f nm) is beyond this sample's genuinely-measured range (max %.0f nm); the fit will use %.0f–%.0f nm. A short tail makes the exponent b poorly determined — if your raw spectrum extends further, widen the analysis range in Analysis settings to include a longer tail.",
                              fe, dmax, .tp$eff_start, .tp$eff_end))
    if (isTRUE(.tp$clamped_lo))
      msgs <- c(msgs, sprintf("Tail start (%.0f nm) is below this sample's genuinely-measured range (min %.0f nm).", fs, dmin))
    if (isTRUE(.tp$inverted) && fe > fs)
      msgs <- c(msgs, "The tail window is empty after clamping to this sample's measured range; the fit will fall back to a flat median offset.")
    if (fe > fs && !isTRUE(.tp$inverted) && npts < .tp$min_tail_pts)
      msgs <- c(msgs, sprintf("Only %d genuinely-measured point(s) fall in the tail window (need ≥ %d); the fit will fall back to a flat median offset.",
                              npts, .tp$min_tail_pts))
    if (!length(msgs))
      return(div(style = "font-size:0.8em;color:var(--pasa-ok-fg);margin-top:6px;",
                 sprintf("Tail window %.0f–%.0f nm lies within this sample's measured range (%.0f–%.0f nm, %d measured points).",
                         fs, fe, dmin, dmax, npts)))
    div(class = "decon-baseline-warn", style = "margin-top:8px;",
        tags$ul(style = "margin:0;padding-left:18px;",
                lapply(msgs, function(m) tags$li(m))))
  })

  observeEvent(input$decon_scatter_blank, {
    fi <- input$decon_scatter_blank
    if (!is.null(fi) && NROW(fi) > 0L)
      restored_decon_blank(list(active = FALSE, data = NULL))
  }, ignoreInit = TRUE)

  observeEvent(input$decon_blank_clear, {
    restored_decon_blank(list(active = TRUE, data = NULL,
      upload_token = .decon_blank_upload_token(isolate(input$decon_scatter_blank))))
  }, ignoreInit = TRUE)

  decon_blank_state <- reactive({
    st <- .decon_blank_read_state(input$decon_scatter_blank, restored_decon_blank())
    if (identical(st$status, "valid"))
      attr(st$data, "content_sha256") <- .decon_blank_content_sha256(st$data)
    st
  })
  decon_blank_df <- reactive({ .decon_blank_state_data(decon_blank_state()) })

  output$decon_blank_source_status <- renderUI({
    st <- decon_blank_state()
    if (identical(st$status, "invalid"))
      return(div(class = "decon-baseline-warn", role = "alert",
        tags$b("Measured blank was not accepted. "), st$reason,
        " Correct the file and upload it again, or use Remove measured blank to choose the empirical correction route."))
    if (identical(st$status, "absent"))
      return(div(class = "text-muted", "No measured blank is active. With local baseline correction enabled, the empirical correction route is selected."))
    div(class = "text-muted", style = "font-size:0.82em;margin-top:4px;",
      sprintf("Active measured blank: %s (%d points; %s).", st$source_name, nrow(st$data), st$origin))
  })
  output$decon_blank_basis_note <- renderUI({
    if (!isTRUE(input$decon_scatter_on) || !identical(decon_blank_state()$status, "valid")) return(NULL)
    div(class = "decon-baseline-warn", style = "margin-top:6px;",
      tags$b("Blank basis: "), "The correction uses dilution × measured − blank. The blank must therefore be in undiluted-equivalent units. ",
      "If it was measured on the diluted sample's acquisition scale, scale the blank by the dilution factor before upload. ",
      "At dilution 1 the two bases are identical. Record the blank's basis with your results.")
  })

  output$decon_scatter_readout <- renderUI({
    if (!isTRUE(input$decon_scatter_on)) return(NULL)
    fit <- tryCatch(decon_fit(), error = function(e) NULL)
    if (is.null(fit) || inherits(fit, "decon_error") || is.null(fit$scatter)) return(NULL)
    s <- fit$scatter
    is_blank <- identical(s$method, "measured_blank")
    if (is_blank) {
      bd <- "#28a745"; bg <- "rgba(40,167,69,0.10)"; col <- "var(--pasa-ok-fg)"
      n_fin <- sum(is.finite(s$scattering)); n_tot <- length(s$scattering)
      head <- sprintf("Measured-blank correction applied: the uploaded blank/turbidity curve was subtracted directly (no power-law extrapolation). %s",
                      s$interpretation)
      win <- if (is.finite(n_tot) && n_fin < n_tot)
        sprintf("Blank covers %d of %d wavelengths; the remainder is marked unavailable. No inverse-power tail fit is used; the measured blank is subtracted directly. Offset baseline bypassed (mutual exclusivity).", n_fin, n_tot)
      else "No inverse-power tail fit is used; the measured blank is subtracted directly. Offset baseline bypassed (mutual exclusivity)."
    } else if (isTRUE(s$fit_ok)) {
      bd <- "#28a745"; bg <- "rgba(40,167,69,0.10)"; col <- "var(--pasa-ok-fg)"
      head <- sprintf("Empirical inverse-power baseline correction applied: b = %.2f, a = %.4g, c = %.4g  —  %s",
                      s$b, s$a, s$c, s$interpretation)
      win <- sprintf("Tail window used: %.0f–%.0f nm (%d points). Offset baseline bypassed (mutual exclusivity).",
                     s$fit_start, s$fit_end, s$n_tail)
    } else {
      bd <- "#c62828"; bg <- "rgba(198,40,40,0.12)"; col <- "var(--pasa-err-fg)"
      head <- sprintf("Empirical inverse-power baseline fit FAILED — fell back to a flat median offset (c = %.4g); no slope was removed.",
                      s$c)
      win <- sprintf("Tail window used: %.0f–%.0f nm (%d points). Offset baseline bypassed (mutual exclusivity).",
                     s$fit_start, s$fit_end, s$n_tail)
    }
    warns <- if (length(s$warnings))
      tags$ul(style = "margin:4px 0 0;padding-left:18px;",
              lapply(s$warnings, function(w) tags$li(w))) else NULL
    bcav <- if (isTRUE(s$fit_ok) && !is_blank)
      tags$div(style = "margin-top:4px;opacity:0.85;",
               "b is an empirical wavelength exponent reported without a calibrated uncertainty interval. It is not a particle-size or scattering-regime measurement.")
    else NULL
    div(style = sprintf("margin:6px 0 10px;padding:9px 12px;border:1px solid %s;border-left:4px solid %s;border-radius:6px;background:%s;color:%s;font-size:0.85em;line-height:1.4;",
                        bd, bd, bg, col),
        tags$b(head), tags$br(), win, warns, bcav)
  })

  .decon_sample_restore_selection <- function(samps, pend, cur, pending_samples,
                                               current_txn) {
    .pend_txn <- if (is.null(pend)) NULL else attr(pend, "restore_txn")
    .samples_txn <- if (is.null(pending_samples)) NULL else
      attr(pending_samples, "restore_txn")
    .same_txn_samples_pending <- !is.null(pending_samples) &&
      !is.null(.pend_txn) && !is.null(.samples_txn) &&
      identical(.pend_txn, .samples_txn) &&
      identical(.pend_txn, current_txn)
    force_default <- !is.null(pend) && isTRUE(attr(pend, "reset_to_default"))
    .target <- if (is.null(pend) || !length(pend)) "" else as.character(pend)[1]
    .wait_for_samples <- !force_default && !is.null(pend) &&
      !(.target %in% samps) && .same_txn_samples_pending
    sel <-
      if (force_default) { if (length(samps)) samps[1] else NULL }
      else if (!is.null(pend)) {
        if (.target %in% samps) .target
        else if (.wait_for_samples) NULL       # the same restore transaction has not committed its sample selection/data yet
        else if (length(samps)) samps[1]       # final restored value unavailable -> DEFAULT
        else NULL                              # results() not ready yet -> keep pend, resolve on a later sync
      }
      else if (!is.null(cur) && cur %in% samps) cur
      else if (length(samps)) samps[1] else NULL
    list(selected = sel, wait_for_samples = .wait_for_samples)
  }

  sync_decon_sample <- function() {
    res <- tryCatch(results(), error = function(e) NULL)
    samps <- if (!is.null(res) && nrow(res)) unique(as.character(res$sample)) else character(0)
    pend <- isolate(pending_decon_sample_restore())
    cur  <- isolate(input$decon_sample)
    if (!is.null(pend) && !is.null(attr(pend, "restore_txn")) &&
        !identical(attr(pend, "restore_txn"), isolate(restore_txn()))) {
      pending_decon_sample_restore(NULL); pend <- NULL
    }
    .choice <- .decon_sample_restore_selection(
      samps = samps, pend = pend, cur = cur,
      pending_samples = isolate(pending_samples_restore()),
      current_txn = isolate(restore_txn()))
    sel <- .choice$selected
    if (isTRUE(.choice$wait_for_samples)) return(invisible())
    .pend_txn <- if (is.null(pend)) NULL else attr(pend, "restore_txn")
    session$onFlushed(.restore_callbacks$guard(function() {
      updateSelectInput(session, "decon_sample", choices = samps, selected = sel)
      if (!is.null(pend) && length(samps) && !is.null(sel) &&
          requireNamespace("later", quietly = TRUE)) {
        .attempt <- new.env(parent = emptyenv()); .attempt$n <- 0L
        .retry <- function() {
          if (!.restore_callbacks$alive()) return(invisible())
          .live <- isolate(pending_decon_sample_restore())
          if (is.null(.live) || (!is.null(.pend_txn) &&
              !identical(attr(.live, "restore_txn"), .pend_txn))) return(invisible())
          if (identical(as.character(isolate(input$decon_sample)), as.character(sel))) {
            pending_decon_sample_restore(NULL)
            return(invisible())
          }
          updateSelectInput(session, "decon_sample", choices = samps, selected = sel)
          .attempt$n <- .attempt$n + 1L
          if (.attempt$n < 120L) .restore_callbacks$schedule(.retry, delay = 0.25)
          else {
            pending_decon_sample_restore(NULL)
            showNotification("Deconvolution sample restore was not confirmed by the browser; check the selected sample.", type = "warning", duration = 12, session = session)
          }
          invisible()
        }
        .restore_callbacks$schedule(.retry, delay = 0.25)
      }
    }), once = TRUE)
  }
  observe({
    results(); adv <- isTRUE(input$advanced_mode)
    pending_decon_sample_restore(); pending_samples_restore()
    # Take dependencies on results, Advanced Mode, and both transaction-staged
    # selections. Consuming the sample selection must re-run this observer so a
    # genuinely unavailable deconvolution target can then use the normal fallback.
    if (adv) sync_decon_sample()                    # widget only exists (and is worth updating) when Advanced is ON
  })

  # --- Baseline gate --------------------------------------------------------
  # The entire controls block (incl. the Run button) lives inside
  # conditionalPanel("input.apply_baseline") in the UI, so when baseline is OFF
  # the Run button is not rendered at all and the orange baseline notice shows
  # in its place. decon_fit() ALSO validates apply_baseline as a server-side
  # backstop, so a fit can never run on an un-baselined curve.

  decon_run_go <- reactiveVal(0L)
  observeEvent(input$decon_run, {
    if (isTRUE(input$decon_bootstrap)) {
      .kk <- tryCatch(.decon_effective_k(input$decon_depth, input$decon_kmin, input$decon_kmax),
                      error = function(e) NULL)
      .single_k <- !is.null(.kk) && is.finite(.kk$kmin) && is.finite(.kk$kmax) && .kk$kmax <= .kk$kmin
      showModal(if (.single_k) modalDialog(
        title = "The K-stability bootstrap cannot run for this K range",
        tags$p("The ", tags$b("Estimate K-selection stability (bootstrap)"), " option is enabled, but k_min and ",
               "k_max are both ", tags$b(as.character(.kk$kmin)), ", so the search fits a single component count. ",
               "A K-selection stability measures how often the resampled data re-selects the SAME K, which is ",
               "undefined when there is nothing to select between — the fit will run at normal speed and report no ",
               "stability."),
        tags$p("Widen k_min / k_max if you want the stability percentages, or continue for a normal fast fit."),
        footer = tagList(
          modalButton("Cancel"),
          actionButton("decon_boot_confirm", "Continue — run the fit (no bootstrap)", class = "btn-primary",
                       onclick = "")
        ),
        easyClose = TRUE
      ) else modalDialog(
        title = "Run the K-selection stability bootstrap?",
        tags$p("The ", tags$b("Estimate K-selection stability (bootstrap)"),
               " option is enabled. It refits the entire component-count search on many ",
               "80 resampled copies of the residuals. This can take minutes to hours, depending on ",
               "the wavelength count and component range. It runs in a background worker so the app ",
               "remains usable; a Cancel deconvolution button stops it without applying a partial result."),
        tags$p("Continue only if you need the stability percentages. Otherwise press Cancel, ",
               "untick the bootstrap box, and run a fast fit."),
        footer = tagList(
          modalButton("Cancel"),
          actionButton("decon_boot_confirm", "Continue — run bootstrap", class = "btn-warning",
                       onclick = "")
        ),
        easyClose = TRUE
      ))
    } else {
      decon_run_go(isolate(decon_run_go()) + 1L)
    }
  }, ignoreInit = TRUE)
  observeEvent(input$decon_boot_confirm, {
    removeModal()
    decon_run_go(isolate(decon_run_go()) + 1L)
  }, ignoreInit = TRUE)

  decon_prepared <- reactive({
    validate(need(isTRUE(input$apply_baseline),
                  "Enable baseline correction to run deconvolution."))
    validate(need(.decon_available(),
                  "Deconvolution module is not available (deconvolution_module.R missing)."))
    res <- results()
    validate(need(!is.null(res) && nrow(res) > 0, "No processed samples available."))
    samp <- input$decon_sample
    validate(need(isTruthy(samp), "Choose a sample to fit."))
    row <- res[as.character(res$sample) == as.character(samp), , drop = FALSE]
    validate(need(nrow(row) > 0, "Selected sample not found in processed results."))

    if (!isTRUE(input$decon_scatter_on))
      validate(need(!isTRUE(row$baseline_refused[1]), sprintf(
        "This sample's baseline reference was refused (%s), so no baseline was actually subtracted and the curve is un-baselined. Deconvolution needs a baseline-processed input: choose an in-range / in-coverage baseline reference, enable the empirical inverse-power baseline option, or provide a measured blank.",
        row$baseline_reason[1] %||% "reference out of range or inside a data gap")))

    # Scattering ON -> build a Deconvolution-local, scattering-corrected curve
    # (offset baseline bypassed; see .decon_scatter_input). OFF -> the exact same
    # processed curve the other tabs use.
    scat_on <- isTRUE(input$decon_scatter_on)
    if (scat_on) {
      fs <- suppressWarnings(as.numeric(input$decon_scatter_start %||% 730)); if (!is.finite(fs)) fs <- 730
      fe <- suppressWarnings(as.numeric(input$decon_scatter_end   %||% 800)); if (!is.finite(fe)) fe <- 800
      blank_state <- decon_blank_state()
      validate(need(!identical(blank_state$status, "invalid"),
                    paste0("Measured blank is invalid: ", blank_state$reason %||% "check the blank file")))
      blank_df <- .decon_blank_state_data(blank_state)
      if (is.null(blank_df))
        validate(need(fe > fs, "Inverse-power baseline tail: fit end must be greater than fit start."))
      fb_val <- if (is.null(blank_df) && isTRUE(input$decon_scatter_fixb_on)) {
        v <- suppressWarnings(as.numeric(input$decon_scatter_fixb))
        validate(need(is.finite(v) && v >= 0, "Fixed exponent b must be a finite, non-negative number."))
        v
      } else NULL
      cur <- tryCatch(.decon_scatter_input(row, fit_start = fs, fit_end = fe, bands_df = bands_react(),
                                  fixed_b = fb_val, blank = blank_df),
        pasa_decon_blank_refusal = function(e) validate(need(FALSE, paste0(conditionMessage(e),
          " Fitting corrected and uncorrected regions together would model the blank's edge as spectral structure."))))
      validate(need(!is.null(cur) && !is.null(cur$scatter), "Could not build the requested local-baseline-processed curve for this sample."))
      if (identical(cur$scatter$method, "measured_blank")) {
        validate(need(isTRUE(cur$scatter$fit_ok) && any(is.finite(cur$scatter$scattering)),
          "Measured-blank correction: the uploaded blank has no finite values aligned to this sample. Check the blank file covers the sample's wavelength range."))
        .sc_fin <- is.finite(cur$scatter$scattering)
        validate(need(all(.sc_fin), sprintf(
          paste0("Measured-blank correction: the blank covers only %d of %d wavelengths in the ",
                 "deconvolution range (it spans %.4g-%.4g nm; the sample needs %.4g-%.4g nm). ",
                 "Fitting corrected and uncorrected regions together would let the components model ",
                 "the step at the blank's edge as if it were spectral structure. Either supply a ",
                 "blank covering the full range, or narrow the analysis range to the blank's ",
                 "coverage so the whole fitted curve is blank-corrected."),
          sum(.sc_fin), length(.sc_fin),
          if (any(.sc_fin)) min(cur$nm[.sc_fin]) else NA_real_,
          if (any(.sc_fin)) max(cur$nm[.sc_fin]) else NA_real_,
          min(cur$nm), max(cur$nm))))
      } else {
        .blank_up <- tryCatch(decon_blank_df(), error = function(e) NULL)
        if (isTruthy(.blank_up)) {
          .bnm <- suppressWarnings(as.numeric(.blank_up$nm)); .bnm <- .bnm[is.finite(.bnm)]
          validate(need(FALSE, .decon_blank_zero_overlap_msg(.bnm, cur$nm, "refusal")))
        }
        validate(need(is.finite(cur$scatter$n_tail) && cur$scatter$n_tail >= 1,
          "Empirical inverse-power baseline correction: no measured points fall in the tail window, so the baseline cannot be estimated. Widen the analysis range / tail window, provide a measured blank, or disable this option."))
      }
    } else {
      cur <- .decon_processed_curve(row)
      validate(need(!is.null(cur), "Could not extract a processed curve for this sample."))
    }

 # a requested normalization is a fit precondition, not a label inferred
    # from the control. Both native and local-background paths carry the effective
    # status from normalize_signal(); refuse rather than fit an unchanged curve and
    # archive it as normalized.
    if (isTRUE(cur$norm_requested))
      validate(need(isTRUE(cur$norm_applied), sprintf(
        "Deconvolution was not run because the requested normalization was not applied to its effective fit curve (%s; divisor=%s). Choose a valid positive target/reference/band or turn normalization off.",
        as.character(cur$norm_reason %||% "unrecorded"),
        if (is.finite(suppressWarnings(as.numeric(cur$norm_divisor))))
          format(signif(as.numeric(cur$norm_divisor), 8), trim = TRUE) else "unavailable")))

    .eff <- .decon_effective_k(input$decon_depth, input$decon_kmin, input$decon_kmax)
    kmin <- .eff$kmin
    .kmsg <- c(
      kmin_uncoercible = "Min components (k_min) is not a number. Enter a whole number ≥ 1.",
      kmin_noninteger  = "Min components (k_min) must be a whole number.",
      kmin_nonscalar   = "Min components (k_min) must be a single value.",
      kmax_uncoercible = "Max components (k_max) is not a number. Enter a whole number between k_min and the search-depth cap.",
      kmax_noninteger  = "Max components (k_max) must be a whole number.",
      kmax_nonscalar   = "Max components (k_max) must be a single value.",
      kmin_gt_cap      = sprintf("Min components (k_min = %s) exceeds the maximum for the current search depth (%d). Lower k_min, or raise the search depth so the cap allows it.",
                                 .eff$kmin, .eff$cap),
      kmax_gt_cap      = sprintf("Max components (k_max = %s) exceeds the current search-depth cap (%d). Lower k_max or choose an appropriate search depth.",
                                 .eff$kmax_raw, .eff$cap),
      kmax_lt_kmin     = sprintf("Component range is inverted: Max components (k_max = %s) must be at least Min components (k_min = %s). Adjust the Min/Max components.",
                                 .eff$kmax_raw, .eff$kmin))
    if (!isTRUE(.eff$ok)) {
      .m <- unname(.kmsg[.eff$status])
      validate(need(FALSE, if (length(.m) && !is.na(.m)) .m
                           else "The component range (k_min / k_max) is invalid. Enter whole numbers with k_min ≤ k_max."))
    }
    kmax <- .eff$kmax
    crit <- if (isTruthy(input$decon_criterion)) input$decon_criterion else "bic"
    mu_tol   <- as.numeric(input$decon_mu_tol %||% 8)
    fwhm_min <- as.numeric(input$decon_fwhm_min %||% 8)
    fwhm_max <- as.numeric(input$decon_fwhm_max %||% 50)
    validate(need(is.finite(fwhm_min) && is.finite(fwhm_max) && fwhm_min < fwhm_max,
                  "FWHM min must be finite and strictly less than FWHM max. Adjust the width bounds."))
    validate(need(is.finite(mu_tol) && mu_tol >= 0,
                  "μ tolerance must be a finite, non-negative value (nm)."))

    # Red-edge clip (per Sample class): apply the user-controlled upper wavelength
    # limit to both seeding and fitting. Exclusion can reduce tail-driven seeds but
    # does not assert that the omitted wavelengths are absorption-free.
    red_clip <- input$decon_red_clip
    clip <- .decon_prepare_red_clip(cur$nm, cur$val, red_clip, kmin, kmax)
    validate(need(isTRUE(clip$ok), clip$meta$reason))
    cur$nm <- clip$nm; cur$val <- clip$val
    red_clip <- clip$meta$requested_limit_nm

    .gaps <- .decon_internal_gaps(cur$nm)
    .why <- paste0("Deconvolution is refused: it is seeded from a second derivative that assumes a ",
                   "uniform wavelength grid, and the model score treats the point after a break as the ",
                   "immediate neighbor of the point before it, so a non-uniform axis can both invent a ",
                   "component and suppress a real one -- the selected component count would not be a ",
                   "property of the spectrum. Either narrow the analysis range to one continuously and ",
                   "uniformly sampled region, or supply a spectrum measured on a complete uniform grid.")
    validate(need(isTRUE(.gaps$ok),
      if (identical(.gaps$reason, "gap"))
        sprintf(paste0("This spectrum has %d internal measurement gap%s in the deconvolution range ",
                       "(largest: %.4g nm between %.4g and %.4g nm; the native sampling step is ",
                       "%.4g nm). %s"),
                .gaps$n_gaps, if (.gaps$n_gaps == 1L) "" else "s",
                .gaps$max_gap, .gaps$gap_from, .gaps$gap_to, .gaps$step, .why)
      else if (identical(.gaps$reason, "ambiguous_quantized"))
        sprintf(paste0("This spectrum's wavelength axis is a persistent alternating schedule (native step ",
                       "~%.4g nm) that is only a uniform grid if its coordinates were half-unit rounded at ",
                       "export. The stored values cannot distinguish that from a genuinely non-uniform ",
                       "acquisition, and reconstructing one reading could change the component count, so the ",
                       "fit is refused rather than run on an unprovable assumption. Provide the wavelengths ",
                       "at finer coordinate precision, or on a uniform grid. %s"),
                .gaps$step, .why)
      else
        sprintf(paste0("This spectrum's wavelength axis is not a uniform grid in the deconvolution ",
                       "range (native step ~%.4g nm, but the spacing changes near %.4g nm). %s"),
                .gaps$step, .gaps$gap_from, .why)))

    .recon_disp_nm <- 0
    .nm_before <- cur$nm
    if (is.finite(.gaps$anchor) && is.finite(.gaps$step) && .gaps$step > 0) {
      .nm_before <- cur$nm
      cur$nm <- .gaps$anchor + .gaps$step * round((cur$nm - .gaps$anchor) / .gaps$step)
      .recon_disp_nm <- max(abs(cur$nm - .nm_before))
      .recon_tol_nm <- 1024 * .Machine$double.eps * max(1, max(abs(.nm_before), na.rm = TRUE))
      if (is.finite(.recon_disp_nm) && .recon_disp_nm <= .recon_tol_nm) {
        cur$nm <- .nm_before          # within ULP of the stored grid -> it WAS uniform: keep the original labels
        .recon_disp_nm <- 0           # -> the `> 0` guard below is FALSE: no second fit, no reconstruction note
      }
    }

    # Seeding window is specified in nm; convert to an odd number of data points
    # using the (clipped) curve's median wavelength step.
    step_nm <- suppressWarnings(stats::median(diff(sort(cur$nm)), na.rm = TRUE))
    if (!is.finite(step_nm) || step_nm <= 0) step_nm <- 1
    seed_win_nm <- suppressWarnings(as.numeric(input$decon_seed_win %||% 15))
    if (!is.finite(seed_win_nm) || seed_win_nm <= 0) seed_win_nm <- 15
    sg_n <- as.integer(round(seed_win_nm / step_nm))
    if (sg_n %% 2L == 0L) sg_n <- sg_n + 1L
    sg_n <- max(5L, sg_n)

    clip$meta$retained_input_range_nm <- clip$meta$effective_range_nm
    clip$meta$effective_range_nm <- range(cur$nm)
    clip$meta$coordinate_adjustment_max_nm <- .recon_disp_nm
    list(cur = cur, row = row, samp = samp, scat_on = scat_on,
      fs = if (scat_on) fs else NA_real_, fe = if (scat_on) fe else NA_real_,
      kmin = kmin, kmax = kmax, crit = crit, mu_tol = mu_tol,
      fwhm_min = fwhm_min, fwhm_max = fwhm_max, red_clip = red_clip, clip = clip$meta,
      .gaps = .gaps, .recon_disp_nm = .recon_disp_nm, .nm_before = .nm_before,
      seed_win_nm = seed_win_nm, sg_n = sg_n)
  })

  decon_fit_run <- reactiveVal(NULL)
  decon_job_state <- reactiveVal(list(status = "idle"))
  decon_job <- new.env(parent = emptyenv())
  decon_job$generation <- 0L; decon_job$active <- FALSE
  .decon_stop_timer <- function() {
    secs <- if (is.null(decon_job$started)) 0 else
      as.numeric(difftime(Sys.time(), decon_job$started, units = "secs"))
    try(session$sendCustomMessage("decon_timer_stop", list(secs = secs)), silent = TRUE)
  }
  .decon_cancel_job <- function(show_status = TRUE) {
    was_active <- isTRUE(decon_job$active)
    decon_job$active <- FALSE
    decon_job$generation <- decon_job$generation + 1L
    h <- decon_job$handle; release <- decon_job$release
    decon_job$handle <- NULL; decon_job$release <- NULL
    if (!is.null(h)) {
      terminal <- identical(.pasa_task_stop_once(h), "TERMINAL_CONFIRMED")
      if (terminal) { if (is.function(release)) release() }
      else .pasa_orphan_enroll(h, release, task_id = "deconvolution")
    } else if (is.function(release)) release()
    if (show_status && was_active) decon_job_state(list(status = "canceled"))
    .decon_stop_timer()
    invisible()
  }
  session$onSessionEnded(function() .decon_cancel_job(FALSE))
  observeEvent(input$decon_cancel, .decon_cancel_job())
  output$decon_run_status <- renderUI({
    st <- decon_job_state()
    if (st$status %in% c("starting", "running"))
      div(role = "status", class = "alert alert-info", style = "margin-top:8px;",
        if (identical(st$status, "starting")) "Preparing the background worker. "
        else "Deconvolution is queued or running in the background. ",
        "You can keep using the app. Progress is not reported per resample; previous-fit outputs remain unchanged until completion. ",
        tags$progress(max = 1, style = "width:100%;height:6px;"),
        actionButton("decon_cancel", "Cancel deconvolution", class = "btn-sm btn-warning"))
    else if (identical(st$status, "canceled")) div(class = "alert alert-secondary", "Deconvolution canceled; no partial result was applied.")
    else if (identical(st$status, "error")) div(class = "alert alert-warning", st$error)
    else NULL
  })
  observeEvent(decon_run_go(), {
    .decon_cancel_job(FALSE)
    prep <- tryCatch(decon_prepared(), error = function(e) e)
    if (inherits(prep, "condition")) {
      msg <- conditionMessage(prep)
      if (!nzchar(msg)) msg <- "Load data and choose a sample before running deconvolution."
      decon_job_state(list(status = "error", error = msg))
      showNotification(msg, type = "warning", duration = 8, session = session)
      return(invisible())
    }
    ids <- c("decon_sample_class", "decon_scatter_fixb_on", "decon_scatter_fixb",
             "decon_bootstrap", "apply_baseline", "resample_on", "smooth", "norm_method")
    request <- setNames(lapply(ids, function(id) isolate(input[[id]])), ids)
    blank <- isolate(decon_blank_state())
    decon_job$generation <- decon_job$generation + 1L
    generation <- decon_job$generation
    decon_job$active <- TRUE; decon_job$started <- Sys.time()
    decon_job_state(list(status = "starting"))
    session$sendCustomMessage("decon_timer_start", list())
    current <- function() isTRUE(decon_job$active) && identical(generation, decon_job$generation) &&
      !isTRUE(tryCatch(session$isClosed(), error = function(e) FALSE))
    failed <- function(message) structure(list(error = message), class = "decon_error")
    finish <- function(out) {
      if (!current()) return(invisible())
      if (is.function(decon_job$release)) decon_job$release()
      decon_job$handle <- NULL; decon_job$release <- NULL; decon_job$active <- FALSE
      decon_fit_run(out)
      decon_job_state(if (inherits(out, "decon_error")) list(status = "error", error = out$error) else list(status = "done"))
      .decon_stop_timer()
      invisible()
    }
    unavailable <- function() {
      if (!current()) return(invisible())
      if (isTRUE(request$decon_bootstrap)) {
        finish(failed("The K-selection bootstrap requires the background worker, which is unavailable. Retry after other jobs finish, or disable the bootstrap for an ordinary fit."))
      } else finish(tryCatch(.pasa_decon_compute(prep, request, blank), error = function(e) failed(conditionMessage(e))))
    }
    launch <- function() {
      if (!current()) return(invisible())
      h <- tryCatch(mirai::mirai(.pasa_decon_compute(PREP, INPUT, BLANK),
        PREP = prep, INPUT = request, BLANK = blank), error = function(e) NULL)
      if (is.null(h)) { .growth_bg_invalidate(); return(unavailable()) }
      token <- new.env(parent = emptyenv()); token$held <- TRUE
      .growth_bg_task_acquire()
      release <- function() if (isTRUE(token$held)) {
        token$held <- FALSE; .growth_bg_task_release()
      }
      decon_job$handle <- h; decon_job$release <- release
      decon_job_state(list(status = "running"))
      poll <- function() tryCatch({
        if (!current()) return(invisible())
        if (mirai::unresolved(h)) return(invisible(later::later(poll, delay = 0.15)))
        out <- h$data
        if (!is.list(out) || (!inherits(out, "decon_error") && is.null(out$comparison))) {
          .growth_bg_invalidate()
          out <- failed(paste("The deconvolution worker did not return a valid fit.", paste(as.character(out), collapse = " ")))
        }
        finish(out)
      }, error = function(e) {
        if (!current()) return(invisible())
        message <- conditionMessage(e)
        .decon_cancel_job(FALSE); .growth_bg_invalidate()
        decon_fit_run(failed(message)); decon_job_state(list(status = "error", error = message))
      })
      later::later(poll, delay = 0.15)
      invisible()
    }
    if (.growth_bg_available() && requireNamespace("later", quietly = TRUE))
      .growth_bg_ready_async(launch, unavailable, should_continue = current)
    else unavailable()
  }, ignoreInit = TRUE)

  # Withhold a cached fit whenever the current requested preparation is invalid.
  # Valid changes retain the existing explicit previous-fit/stale presentation.
  decon_fit <- reactive({
    decon_prepared()
    fit <- decon_fit_run()
    validate(need(!is.null(fit), "Run deconvolution and wait for the fit to finish."))
    fit
  })

  .decon_live_run_key <- reactive({
    scat_on <- isTRUE(input$decon_scatter_on)
    fs <- suppressWarnings(as.numeric(input$decon_scatter_start %||% 730)); if (!is.finite(fs)) fs <- 730
    fe <- suppressWarnings(as.numeric(input$decon_scatter_end   %||% 800)); if (!is.finite(fe)) fe <- 800
    .live_eff <- .decon_effective_k(input$decon_depth, input$decon_kmin, input$decon_kmax)
    live_kmin <- .live_eff$kmin
    live_kmax <- .live_eff$kmax
    live_seed <- suppressWarnings(as.numeric(input$decon_seed_win %||% 15))
    if (!is.finite(live_seed) || live_seed <= 0) live_seed <- 15
    live_hash <- {
      res <- tryCatch(results(), error = function(e) NULL)
      samp <- as.character(input$decon_sample %||% "")
      if (!is.null(res) && nrow(res) && nzchar(samp)) {
        rr <- res[as.character(res$sample) == samp, , drop = FALSE]
        if (nrow(rr) && ".decon_native_nm" %in% names(rr))
          .curve_fingerprint(rr$.decon_native_nm[[1]], rr$.decon_native_val[[1]]) else ""
      } else ""
    }
    meta <- list(
      sample = as.character(input$decon_sample %||% ""),
      kmin = live_kmin,
      kmax = live_kmax,
      criterion = if (isTruthy(input$decon_criterion)) input$decon_criterion else "bic",
      mu_tol = as.numeric(input$decon_mu_tol %||% 8),
      fwhm_min = as.numeric(input$decon_fwhm_min %||% 8),
      fwhm_max = as.numeric(input$decon_fwhm_max %||% 50),
      red_clip = { .v <- suppressWarnings(as.numeric(input$decon_red_clip));
                   if (length(.v) == 1L) .v else NA_real_ },
      seed_win = live_seed,
      sample_class = input$decon_sample_class %||% "",
      scatter_on = scat_on,
      scatter_start = if (scat_on) fs else NA_real_,
      scatter_end   = if (scat_on) fe else NA_real_,
      fixed_b_on = scat_on && isTRUE(input$decon_scatter_fixb_on),
      fixed_b    = if (scat_on && isTRUE(input$decon_scatter_fixb_on)) suppressWarnings(as.numeric(input$decon_scatter_fixb)) else NA_real_,
      blank_hash = if (scat_on) .decon_blank_state_key(decon_blank_state()) else "none",
      bootstrap = isTRUE(input$decon_bootstrap),
      apply_baseline = isTRUE(input$apply_baseline),
      resample_on = isTRUE(input$resample_on),
      smooth = input$smooth %||% "none", norm_method = input$norm_method %||% "none",
      curve_hash = live_hash)
    .decon_run_key(meta)
  })

  decon_is_stale <- reactive({
    fit <- tryCatch(decon_fit(), error = function(e) NULL)
    if (is.null(fit) || inherits(fit, "decon_error") || is.null(fit$run_key)) return(FALSE)
    !identical(fit$run_key, .decon_live_run_key())
  })

  output$decon_stale_banner <- renderUI({
    .prep_error <- tryCatch({ decon_prepared(); NULL }, error = function(e) conditionMessage(e))
    if (!is.null(.prep_error) && !nzchar(trimws(.prep_error)))
      .prep_error <- "No processed data is loaded. Load data and choose a sample first."
    if (!is.null(.prep_error))
      return(div(class = "decon-baseline-warn", role = "alert",
        tags$b("The current deconvolution request cannot run. "), .prep_error,
        " Previous-fit outputs are withheld until these settings are valid."))
    if (!isTRUE(decon_is_stale())) return(NULL)
    div(class = "decon-baseline-warn", role = "status", `aria-live` = "polite",
        style = "margin-top:6px;padding:7px 10px;border-radius:6px;font-size:0.83em;",
        tags$b("⚠ Settings changed since the last run. "),
        "The plot, notes and exports below still describe the PREVIOUS fit. Press ",
        tags$b("Run deconvolution"), " again to update them to the current sample and settings.")
  })

  # Label components by the active bands (cosmetic) ---------------------------
  decon_labeled <- reactive({
    fit <- decon_fit()
    if (inherits(fit, "decon_error")) return(fit)
    # Label by spectral-REGION windows (pigment-agnostic), NOT the app's pigment
    # bands_react() \u2014 a region name never makes a molecular claim.
    comp <- tryCatch(label_components_by_band(fit$best$components, .decon_region_bands),
                     error = function(e) fit$best$components)
    list(fit = fit, components = comp)
  })

  # --- Status line ----------------------------------------------------------
  output$decon_status <- renderUI({
    fit <- decon_fit()
    if (inherits(fit, "decon_error"))
      return(div(class = "decon-baseline-warn",
                 "Deconvolution failed: ", fit$error))
    pres <- .decon_presentation(fit)
    if (is.null(fit$best))
      return(div(class = "decon-baseline-warn", style = "margin:8px 0;",
                 tags$b("⚠ "), pres$display_note, tags$br(), pres$export_status_line))
    g <- fit$best$gof
    # Always state BOTH criteria's choices, computed from the comparison table.
    cmp <- fit$comparison
    .crit_summary <- .decon_ic_selection_summary(cmp)
    dual <- if (nzchar(.crit_summary)) paste0(" | ", .crit_summary) else ""
    # Measured lag-1 residual autocorrelation is descriptive. It can arise from
    # model mismatch, correlated acquisition/preprocessing noise, sampling, or
    # several causes; it does not diagnose a mechanism. Selected K remains a
    # plug-in parsimony heuristic rather than a species count.
    rho <- suppressWarnings(as.numeric(g$rho_lag1 %||% NA_real_))
    rho_txt <- if (is.finite(rho)) sprintf(" | lag-1 residual \u03c1 = %.2f", rho) else ""
    .crit_lc  <- tolower(as.character(fit$criterion %||% "bic"))
    .crit_col <- suppressWarnings(as.numeric(cmp[[.crit_lc]]))
    .ic_unavailable <- is.null(cmp) || !length(.crit_col) || !any(is.finite(.crit_col))
    .kic_s <- suppressWarnings(as.numeric(fit$best_K_ic))
    .no_adm <- !identical(pres$display_role, "selected")
    .nad <- if (.no_adm) .decon_no_adm_cause(fit) else NULL
    guard_moved <- isTRUE(!.ic_unavailable && length(.kic_s) == 1L && is.finite(.kic_s) &&
                          !is.na(pres$selected_K) && .kic_s != pres$selected_K)
    div(style = "margin:8px 0;",
      tags$b(if (.no_adm)
               sprintf("No admissible component count \u2014 %s", .nad$raw_phrase)
             else sprintf("Selected K = %d", pres$selected_K)),
      if (.no_adm)
        sprintf(" \u2014 %s | R\u00b2 = %.4f | RMSE = %.4g | n = %d points",
                .nad$detail, g$r2, g$rmse, g$n_points)
      else if (guard_moved)
        sprintf(" %s | R\u00b2 = %.4f | RMSE = %.4g | n = %d points",
                .decon_selected_k_banner_phrase(fit, "guard_moved", .kic_s),
                g$r2, g$rmse, g$n_points)
      else if (.ic_unavailable)
        sprintf(" %s | R\u00b2 = %.4f | RMSE = %.4g | n = %d points",
                .decon_selected_k_banner_phrase(fit, "unavailable"),
                g$r2, g$rmse, g$n_points)
      else
        sprintf(" %s | R\u00b2 = %.4f | RMSE = %.4g | n = %d points",
                .decon_selected_k_banner_phrase(fit, "normal"),
                g$r2, g$rmse, g$n_points),
      rho_txt,
      dual,
      if (guard_moved && !is.null(fit$k_guard_note) && !is.na(fit$k_guard_note))
        div(class = "decon-baseline-warn", style = "margin-top:4px;", fit$k_guard_note)
      else NULL,
      if (is.finite(g$r2) && g$r2 <= 0)
        div(class = "decon-baseline-warn", style = "margin-top:4px;",
            "Non-informative fit (R\u00b2 \u2264 0): the model explains no more variance than a flat line at the mean, so the component table is not a meaningful decomposition for this sample.")
      else NULL,
      if (is.finite(rho) && abs(rho) >= 0.5)
        div(class = "decon-baseline-warn", style = "margin-top:4px;",
            sprintf("Residuals show strong lag-1 dependence (\u03c1 = %.2f, |\u03c1| \u2265 0.5). The ranking uses the documented plug-in AR(1) parsimony heuristic (the residual correlation is estimated from the residuals and plugged in, not jointly optimized), so it is only approximately accommodated, NOT fully accounted for by a joint likelihood. Structured residual dependence can arise from model mismatch, acquisition or preprocessing effects, sampling, or multiple causes; it does not identify a cause. Read \u201cSelected K\u201d as a reproducible parsimony heuristic, not a count of molecular species. %s",
                    rho,
                    if (rho >= 0)
                      "For positive \u03c1, neighboring residuals tend to share sign, forming runs in the residual plot."
                    else
                      "For negative \u03c1, neighboring residuals tend to alternate sign point-to-point, forming a zig-zag or oscillatory pattern in the residual plot."))
      else NULL)
  })

  # --- Note under the criterion radio: compares AIC-like and BIC-like scores --
  output$decon_criterion_note <- renderUI({
    fit <- tryCatch(decon_fit(), error = function(e) NULL)
    if (is.null(fit) || inherits(fit, "decon_error")) return(NULL)
    cmp <- fit$comparison
    if (is.null(cmp) || !all(c("K","aic","bic") %in% names(cmp)) || !nrow(cmp)) return(NULL)
    if (nrow(cmp) < 2) {
      return(div(style = "font-size:0.8em;color:var(--pasa-muted-fg);margin-top:3px;",
                 sprintf("Only one component count (K = %d) was fitted, so the AIC-like and BIC-like scores cannot be compared across K.",
                         cmp$K[1])))
    }
    raw_aic <- .decon_ic_argmin_K(cmp, "aic"); raw_bic <- .decon_ic_argmin_K(cmp, "bic")
    sel_aic <- .decon_ic_admissible_K(cmp, "aic"); sel_bic <- .decon_ic_admissible_K(cmp, "bic")
    .aicc_note <- if (identical(tolower(as.character(fit$criterion %||% "")), "aicc"))
      " The current selection criterion is the AICc-like plug-in score, so this AIC-like-versus-BIC-like comparison does not determine the displayed fit." else ""
    .raw_note <- sprintf(" Raw all-candidate minima: AIC-like -> K = %s; BIC-like -> K = %s.",
                         .decon_fmt_K(raw_aic), .decon_fmt_K(raw_bic))
    agree_div <- if (is.na(sel_aic) || is.na(sel_bic)) {
      div(style = "font-size:0.8em;color:var(--pasa-warn-fg);margin-top:3px;",
          sprintf("Guard-adjusted AIC-like and BIC-like selections could not both be made (AIC-like admissible -> K = %s; BIC-like admissible -> K = %s).%s%s",
                  .decon_fmt_K(sel_aic), .decon_fmt_K(sel_bic), .raw_note, .aicc_note))
    } else if (identical(sel_aic, sel_bic)) {
      div(style = "font-size:0.8em;color:var(--pasa-ok-fg);margin-top:3px;",
          sprintf("Guard-adjusted AIC-like and BIC-like selections agree on K = %d for this search and admissibility rule.%s This conditional agreement is not evidence of a true component count or robustness to other preprocessing, bounds, seeds, model families, or datasets.%s",
                  sel_aic, .raw_note, .aicc_note))
    } else {
      div(style = "font-size:0.8em;color:var(--pasa-warn-fg);margin-top:3px;",
          sprintf("Guard-adjusted AIC-like and BIC-like selections differ (AIC-like admissible -> K = %d; BIC-like admissible -> K = %d).%s Treat the difference as criterion sensitivity and report it.%s",
                  sel_aic, sel_bic, .raw_note, .aicc_note))
    }
    .boot_lines <- .decon_bootstrap_text(fit)
    boot_div <- if (length(.boot_lines))
      div(style = "font-size:0.8em;color:var(--pasa-muted-fg);margin-top:3px;",
        lapply(.boot_lines, function(line) tags$p(style = "margin:2px 0;", line))) else NULL
    adeq_div <- NULL; g <- fit$best$gof
    if (!is.null(g) && !isTRUE(g$adequate)) {
      poor_r2 <- isTRUE(is.finite(g$r2) && g$r2 < 0.5) && !isTRUE(g$r2_negative)
      reasons <- c(if (isTRUE(g$r2_negative)) "negative R\u00b2 (worse than a flat mean)",
                   if (poor_r2) sprintf("a low R\u00b2 (%.2f, below 0.5)", g$r2),
                   if (isTRUE(g$any_boundary_pinned)) "a component width is pinned at a bound",
                   if (isTRUE(g$any_resolution_limited)) "a component is narrower than ~3 native samples")
      adeq_div <- div(style = "font-size:0.8em;color:var(--pasa-warn-fg);margin-top:3px;font-weight:600;",
        "\u26a0 The selected model may be an artifact of the fit, not a real decomposition: ",
        paste(reasons, collapse = "; "), ". Treat the component areas and shares as unreliable.")
    }
    tagList(agree_div, boot_div, adeq_div)
  })

  # --- Permanent search-depth advisory box (keyed to LIVE k_max value) -------
  # Lightweight preview of how many bands the seeder can actually resolve for the
  # currently-selected sample at the current Seeding window. Seeding is cheap (a
  # 2nd-derivative peak scan, milliseconds) \u2014 unlike the fit it is safe to run
  # reactively \u2014 so the advisory can tell the user when k_max exceeds what the data
  # supports, and that lowering the Seeding window raises the cap.
  decon_seed_count <- reactive({
    prep <- tryCatch(decon_prepared(), error = function(e) NULL)
    if (is.null(prep)) return(NA_integer_)
    seeds <- tryCatch(seed_peaks(prep$cur$nm, prep$cur$val,
                                 max_peaks = 60, sg_n = prep$sg_n), error = function(e) NULL)
    if (is.null(seeds)) NA_integer_ else as.integer(nrow(seeds))
  })

  output$decon_depth_advisory <- renderUI({
    eff <- .decon_effective_k(input$decon_depth, input$decon_kmin, input$decon_kmax)
    if (!isTRUE(eff$ok)) return(div(class = "alert alert-warning",
      if (identical(eff$status, "kmax_gt_cap"))
        sprintf("k_max = %s exceeds the current search-depth cap of %d. This request will not run until the bounds are corrected.", eff$kmax_raw, eff$cap)
      else "The component bounds are invalid. Enter whole numbers with 1 ≤ k_min ≤ k_max within the search-depth limit."))
    km <- eff$kmax
    if (km <= 4) {
      bg <- "rgba(40,167,69,0.10)"; bd <- "#28a745"; col <- "var(--pasa-ok-fg)"
      msg <- sprintf("Component-count search up to K = %d is within the separately distributed recovery study's tested range (K = 1-4). This does not validate a particular fitted K or make K a count of pigments, transitions, or molecular species; a higher R\u00b2 does not prove that more molecular species are present (Meloun et al., 2000).", km)
    } else if (km <= 12) {
      bg <- "rgba(255,159,64,0.12)"; bd <- "#ff9f40"; col <- "var(--pasa-warn-fg)"
      msg <- sprintf("UNTESTED SEARCH RANGE: K = 5-%d was not exercised by the separately distributed recovery study. Searching up to K = %d is an advanced sensitivity analysis and can increase runtime, non-identifiability, and convergence failures. Inspect residuals and bootstrap stability, report the full search range, and do not interpret K as a molecular-species count (Meloun et al., 2000).", km, km)
    } else {
      bg <- "rgba(198,40,40,0.12)"; bd <- "#c62828"; col <- "var(--pasa-err-fg)"
      msg <- sprintf("UNTESTED SEARCH RANGE: K = 5-%d was not exercised by the separately distributed recovery study. This wide advanced search carries substantial computational, non-identifiability, and overfitting risk. Use it only to examine sensitivity to the bound; inspect convergence, residuals, and bootstrap stability, and interpret the result as phenomenological band modeling rather than a molecular-species count (Meloun et al., 2000).", km)
    }
    n_seed <- suppressWarnings(decon_seed_count())
    div(style = sprintf("margin:10px 0 2px;padding:9px 12px;border:1px solid %s;border-left:4px solid %s;border-radius:6px;background:%s;color:%s;font-size:0.85em;line-height:1.4;",
                        bd, bd, bg, col),
        msg,
        if (is.finite(n_seed) && n_seed < km)
          tags$div(style = "margin-top:6px;font-weight:600;",
                   sprintf("The 2nd derivative supplies %d candidate seed feature(s) at the current Seeding window; K up to %d is still searched, with extra phenomenological components seeded by residual deflation and flagged as tentative. Changing the Seeding window changes the initial-feature count and should be treated as a sensitivity analysis.", n_seed, km)))
  })

  # --- Search-depth toggle caps the editable k_max field ---------------------
  observeEvent(input$decon_depth, {
    cap <- .decon_depth_cap(input$decon_depth)
    cur <- suppressWarnings(as.integer(input$decon_kmax %||% cap))
    if (!is.finite(cur)) cur <- cap
    updateNumericInput(session, "decon_kmax", max = cap, value = min(cur, cap))
  })

  # --- Active fit-method badge ----------------------------------------------
  output$decon_method_badge <- renderUI({
    fit <- decon_fit()
    if (inherits(fit, "decon_error")) return(NULL)
    st <- fit$best$fit_status
    comp <- fit$best$components
    se_cols <- if (is.data.frame(comp))
      intersect(c("amp_se", "mu_se", "fwhm_se", "eta_se"), names(comp)) else character(0)
    se_vals <- if (length(se_cols)) suppressWarnings(as.numeric(unlist(comp[se_cols], use.names = FALSE))) else numeric(0)
    nls_se_lab <- if (any(is.finite(se_vals)))
      "Fit method: nlsLM (minpack.lm, bounded LM) \u2014 local, model-conditional SEs shown where estimable"
    else
      "Fit method: nlsLM (minpack.lm, bounded LM) \u2014 model-conditional SEs unavailable for this fit"
    lab <- if (!is.null(st) && !is.na(st)) {
      switch(st,
        "nlsLM" = nls_se_lab,
        "lbfgs_no_minpack" = "L-BFGS-B fallback \u2014 no standard errors (install minpack.lm for SEs)",
        "lbfgs_nonconvergence" = { .kb <- suppressWarnings(as.integer((fit$best_K %||% NA)[1]))
          if (is.na(.kb)) .kb <- suppressWarnings(as.integer((fit$raw_best_K %||% NA)[1]))
          if (is.na(.kb)) .kb <- suppressWarnings(as.integer((fit$best$K %||% NA)[1]))
          if (is.na(.kb)) "L-BFGS-B fallback \u2014 the bounded Levenberg\u2013Marquardt fit did not converge; standard errors are unavailable. Try a smaller K or k_max."
          else sprintf("L-BFGS-B fallback \u2014 the bounded Levenberg\u2013Marquardt fit did not converge at K = %d; standard errors are unavailable. Try a smaller K or k_max.", .kb) },
        # Defensive: unknown status string falls back to method-string logic.
        if (identical(fit$best$method, "nlsLM"))
          nls_se_lab
        else
          "Fit method: L-BFGS-B fallback \u2014 no standard errors (install minpack.lm for SEs)")
    } else {
      # Defensive fallback when fit_status is NULL/NA.
      if (identical(fit$best$method, "nlsLM"))
        nls_se_lab
      else
        "Fit method: L-BFGS-B fallback \u2014 no standard errors (install minpack.lm for SEs)"
    }
    div(style = "margin:6px 0 10px;", tags$span(class = "decon-method-badge", lab))
  })

  # --- Overlay plot: observed / total fit / components ----------------------
  output$decon_overlay_plot <- renderPlot({
    fit <- decon_fit()
    validate(need(!inherits(fit, "decon_error"), ""))
    p <- .decon_overlay_ggplot(fit, show_scatter = isTRUE(input$decon_scatter_on) &&
                                              isTRUE(input$decon_scatter_overlay))
    p
  }, alt = "Deconvolution overlay: the measured spectrum, the total pseudo-Voigt fit, and the individual fitted band components versus wavelength.")

  # --- Residual plot --------------------------------------------------------
  output$decon_residual_plot <- renderPlot({
    fit <- decon_fit()
    validate(need(!inherits(fit, "decon_error"), ""))
    .decon_resid_ggplot(fit)
  }, alt = "Deconvolution residual plot: fit residual (observed minus total fit) versus wavelength.")

 # --- Enlarge modals for both decon charts () ------------------------
  observeEvent(input$decon_enlarge_overlay, {
    showModal(modalDialog(
      tags$style(HTML(".modal-xl{max-width:95vw !important;} .modal-xl .modal-body{padding:6px;}")),
      title = "Deconvolution \u2014 fit overlay", size = "xl", easyClose = TRUE,
      footer = modalButton("Close"),
      plotOutput("decon_overlay_big", height = "95vh", width = "100%")
    ))
  })
  output$decon_overlay_big <- renderPlot({
    fit <- decon_fit(); req(!inherits(fit, "decon_error"))
    .decon_overlay_ggplot(fit, show_scatter = isTRUE(input$decon_scatter_on) &&
                                              isTRUE(input$decon_scatter_overlay))
  }, bg = "transparent")

  observeEvent(input$decon_enlarge_resid, {
    showModal(modalDialog(
      tags$style(HTML(".modal-xl{max-width:95vw !important;} .modal-xl .modal-body{padding:6px;}")),
      title = "Deconvolution \u2014 residuals", size = "xl", easyClose = TRUE,
      footer = modalButton("Close"),
      plotOutput("decon_resid_big", height = "95vh", width = "100%")
    ))
  })
  output$decon_resid_big <- renderPlot({
    fit <- decon_fit(); req(!inherits(fit, "decon_error"))
    .decon_resid_ggplot(fit)
  }, bg = "transparent")

  # --- K-selection comparison table -----------------------------------------
  output$decon_comparison_table <- renderTable({
    fit <- decon_fit()
    validate(need(!inherits(fit, "decon_error"), ""))
    .decon_comparison_df(fit)
  }, striped = TRUE, bordered = TRUE, spacing = "xs", width = "auto")

  # --- Component table with uncertainties (NA -> "—") -----------------------
  output$decon_components_table <- renderTable({
    lab <- decon_labeled()
    validate(need(!inherits(lab, "decon_error"), ""))
    comp <- lab$components
    fmt <- function(val, se, digits = 3) {
      v <- ifelse(is.finite(val), formatC(val, format = "f", digits = digits), "\u2014")
      s <- ifelse(is.finite(se),  formatC(se,  format = "f", digits = digits), "\u2014")
      paste0(v, " \u00b1 ", s)
    }
    data.frame(
      Component = comp$component,
      Band      = ifelse(is.na(comp$band), "\u2014", comp$band),
      `Center (nm)` = paste0(fmt(comp$mu_nm, comp$mu_se, 2),
                             .decon_center_oow_suffix(comp$mu_nm, lab$fit$best$nm)),
      `FWHM (nm)`   = fmt(comp$fwhm,  comp$fwhm_se, 2),
      Amplitude     = fmt(comp$amp,   comp$amp_se, 4),
      `eta (shared)` = fmt(comp$eta,  comp$eta_se, 3),
      `Area (in-window)` = ifelse(is.finite(comp$area),
                             formatC(comp$area, format = "g", digits = 4), "\u2014"),
      `Full-profile area` = if (!is.null(comp$area_analytic_se))
                              fmt(comp$area_analytic, comp$area_analytic_se, 4)
                            else ifelse(is.finite(comp$area_analytic),
                                        formatC(comp$area_analytic, format = "g", digits = 4), "\u2014"),
      `Area %`      = ifelse(is.finite(comp$area_frac),
                             paste0(formatC(100 * comp$area_frac, format = "f", digits = 1), "%"), "\u2014"),
      check.names = FALSE
    )
  }, striped = TRUE, bordered = TRUE, spacing = "xs", width = "auto")

  output$decon_components_title <- renderUI({
    fit <- tryCatch(decon_fit(), error = function(e) NULL)
    ttl <- if (is.null(fit) || inherits(fit, "decon_error"))
             "Fitted components (+/- standard error)"
           else .decon_presentation(fit)$component_title
    h5(gsub("+/-", "±", ttl, fixed = TRUE),
       .tip_icon("Per-component center, FWHM, amplitude and full-profile area. Finite local-curvature and delta-method SEs from the nlsLM path, when available, are multiplied by a heuristic scalar derived from the plug-in lag-1 residual correlation; this is not a calibrated AR(1) covariance model or coverage guarantee. Values are conditional on K, seeds, bounds, shared eta, preprocessing, and the fitted model, and omit selection and baseline uncertainty. The fallback reports no SEs. A width-at-bound or resolution-limited component must not be interpreted as a measured molecular band."))
  })

  output$decon_display_role_banner <- renderUI({
    fit <- tryCatch(decon_fit(), error = function(e) NULL)
    if (is.null(fit) || inherits(fit, "decon_error")) return(NULL)
    pres <- .decon_presentation(fit)
    if (identical(pres$display_role, "selected")) return(NULL)
    tagList(
      div(class = "decon-baseline-warn", role = "status", `aria-live` = "polite",
          style = "margin:4px 0;padding:7px 10px;border-radius:6px;font-size:0.85em;",
          tags$b("⚠ "), pres$display_note),
      div(class = "decon-caption", pres$table_caption))
  })

  # --- Dynamic, result-specific interpretation notes ------------------------
  # DETERMINISTIC rule engine: each note is emitted ONLY when its condition is
  # actually met by the fit just produced, and every note injects the real
  # numbers from that live fit object. Same result in -> identical notes out.
  # No RNG, no hardcoded scenario list, no regenerated free-form text. The
  # permanent honesty caveat below this panel is unaffected; these notes sit
  # alongside it. Analysis range is fixed at 350-750 nm.
  # Built as a REACTIVE so both the on-screen panel and the PDF/Copy export can
  # read the SAME deterministic notes (no divergence). renderUI just prints it.
  decon_notes_ui <- reactive({
    fit <- decon_fit()
    if (inherits(fit, "decon_error")) return(NULL)
    .pres <- .decon_presentation(fit)
    .guard_div <- if (nzchar(.pres$interpretation_guard))
        div(class = "decon-note decon-note-warn",
            tags$b("Not a selected model. "), .pres$interpretation_guard)
      else NULL
    b     <- fit$best
    comp  <- b$components
    gof   <- b$gof
    cmp   <- fit$comparison
    if (is.null(comp) || !nrow(comp)) {
      # A no-displayable-fit result still renders its guard: an ABSENT panel would leave the reader with no statement
      # at all, when the honest statement is "no component-level claim can be made".
      if (is.null(.guard_div)) return(NULL)
      return(div(class = "decon-notes",
                 div(class = "decon-notes-title", "Interpretation notes"),
                 list(.guard_div)))
    }

    rms    <- gof$rmse                 # residual RMS used as an operational residual-scale threshold
    r2     <- gof$r2
    bestK  <- fit$best_K
    # Highest component count represented in this completed fit. Use the comparison
    # table rather than the live input so the note remains bound to the displayed
    # result if k_max is edited after the run. The effective search can be lower than
    # the request because of the numerical feasibility cap, and component counts
    # whose fits failed are absent from the comparison table.
    kmax <- suppressWarnings(as.integer(fit$effective[["k_max"]]))
    if (length(kmax) != 1L || !is.finite(kmax)) kmax <- max(cmp$K)
    .fit_nm <- tryCatch(fit$best$nm, error = function(e) NULL)
    edge_lo <- if (length(.fit_nm)) min(.fit_nm, na.rm = TRUE) else 350
    edge_hi <- if (length(.fit_nm)) max(.fit_nm, na.rm = TRUE) else 750

    notes <- list()
    add <- function(sev, ...) notes[[length(notes) + 1L]] <<-
      div(class = paste("decon-note", switch(sev,
            warn = "decon-note-warn", ok = "decon-note-ok", "decon-note-info")),
          ...)

    # Track which components rule #1 flags (feeds the self-scaling rule #7).
    flagged_small <- rep(FALSE, nrow(comp))

    { eff_km <- suppressWarnings(as.integer(fit$effective[["k_max"]]))
      req_km <- suppressWarnings(as.integer(fit$requested[["k_max"]]))
      if (is.finite(eff_km) && is.finite(req_km) && eff_km < req_km)
        add("warn", tags$b("Search range was narrowed. "),
          sprintf("This spectrum has too few fitting points to support the requested K: the feasibility limit here is K = %d (it needs at least ~8 measured points per band and keeps the free parameters safely below the point count), so K was searched up to %d rather than the requested %d. Treat the result as the best of a shorter search; add points (finer grid / wider range) to search deeper.", eff_km, eff_km, req_km))
    }
    if (!is.null(fit$seed_note) && !is.na(fit$seed_note) && nzchar(fit$seed_note))
      add("warn", tags$b("Components beyond the derivative-seeded count. "), fit$seed_note)
    if (!is.null(fit$failures) && nrow(fit$failures) > 0) add("warn",
      tags$b("Some component counts failed to converge. "),
      sprintf("K = %s did not produce a usable fit and were excluded from selection.", paste(fit$failures$K, collapse = ", ")))

    { .disp  <- suppressWarnings(as.numeric(fit$recon_disp_nm %||% 0))
      .nstep <- suppressWarnings(as.numeric(fit$native_step_nm %||% NA_real_))
      .sens  <- fit$recon_sens
      .coarse   <- is.finite(.disp) && .disp >= .DECON_RECON_WARN_NM
      .stepnote <- if (is.finite(.nstep)) sprintf(" (native step ~%.3g nm)", .nstep) else ""
      .crit_lbl <- .decon_ic_display_name(fit$criterion %||% "bic")
      .evald   <- is.list(.sens) && isTRUE(.sens$evaluated)
      .fin2 <- function(a, b) is.finite(suppressWarnings(as.numeric(a))) && is.finite(suppressWarnings(as.numeric(b)))
      .sel_chg <- .evald && .fin2(.sens$k_obs,   .sens$k_recon) && !identical(as.integer(.sens$k_obs),   as.integer(.sens$k_recon))
      .raw_chg <- .evald && .fin2(.sens$kic_obs, .sens$kic_recon) && !identical(as.integer(.sens$kic_obs), as.integer(.sens$kic_recon))
      .raw_avail <- .evald && isTRUE(.sens$raw_pref_available %||% .fin2(.sens$kic_obs, .sens$kic_recon))
      .raw_unavail_clause <- if (.evald && !.raw_avail) {
        .cmp_subj <- if (.evald && isTRUE(.sens$center_material))
                       "the component count and the band centers were" else "the component count was"
        sprintf(" The raw %s model-selection minimum could not be determined on at least one axis (every candidate count fit near-perfectly), so only %s compared, not the raw criterion preference.",
                .crit_lbl, .cmp_subj)
      } else ""
      .ctr_mat <- .evald && isTRUE(.sens$center_material)
      .cmove   <- suppressWarnings(as.numeric(if (.evald) .sens$center_move_nm %||% NA_real_ else NA_real_))
      .raw_clause <- if (.raw_chg)
        sprintf(" (the raw %s-minimum K = %d on your coordinates vs %d on the reconstructed grid)",
                .crit_lbl, as.integer(.sens$kic_obs), as.integer(.sens$kic_recon)) else ""
      .ctr_clause <- if (.ctr_mat && is.finite(.cmove))
        sprintf(" A fitted band center also moves by up to %.2g nm between the two coordinate readings, so treat the reported center positions as approximate to about that scale.", .cmove) else ""
      if (is.finite(.disp) && .disp > 0) {
        if (.sel_chg) {
          # MEASURED: the SELECTED component count genuinely depends on the rounding.
          add("warn", tags$b("Component count depends on coordinate rounding. "),
              sprintf(paste0("The wavelengths are stored at a coarser precision than their spacing%s, so they ",
                             "were reconstructed to a uniform grid before fitting (labels moved up to %.2g nm). ",
                             "Re-fitting on your observed coordinates selects K = %d, but the reconstructed ",
                             "uniform grid selects K = %d%s -- so the component count here IS sensitive to the ",
                             "coordinate rounding. Treat K as approximate; supply the wavelengths at finer ",
                             "coordinate precision to resolve it.%s"),
                      .stepnote, .disp, as.integer(.sens$k_obs), as.integer(.sens$k_recon),
                      .raw_clause, .ctr_clause))
        } else if (.raw_chg) {
          .mo <- suppressWarnings(as.numeric(.sens$ic_margin_obs %||% NA_real_))
          .mr <- suppressWarnings(as.numeric(.sens$ic_margin_recon %||% NA_real_))
          .margin_clause <- if (is.finite(.mo) && is.finite(.mr))
            sprintf(paste0(" The two counts are separated by Δ%s = %.3g on your coordinates and %.3g on the ",
                           "reconstructed grid, so the coordinate rounding is enough to flip which count the raw ",
                           "criterion prefers."), .crit_lbl, .mo, .mr)
          else paste0(" The per-axis criterion gap could not be measured here (a candidate count did not yield a ",
                      "comparable fit on the other axis), so only the direction is reported: the coordinate ",
                      "rounding is enough to flip which count the raw criterion prefers.")
          add(if (.coarse) "warn" else "info",
              tags$b("Component count is stable, but its selection margin is not. "),
              sprintf(paste0("The wavelengths were reconstructed to a uniform grid before fitting%s (labels moved up ",
                             "to %.2g nm). Re-fitting on your observed coordinates selects the SAME component ",
                             "count (K = %d), so K is stable to this rounding; however the raw model-selection ",
                             "criterion's minimum shifts%s.%s K is stable only for this observed-versus-reconstructed coordinate sensitivity check; supply finer coordinate ",
                             "precision to remove the ambiguity.%s"),
                      .stepnote, .disp, as.integer(.sens$k_recon), .raw_clause, .margin_clause, .ctr_clause))
        } else if (.ctr_mat) {
          .same_pref <- if (.raw_avail) " and the same criterion preference" else ""
          add(if (.coarse) "warn" else "info",
              tags$b("Component count is stable; a fitted center shifts with the rounding. "),
              sprintf(paste0("The wavelengths were reconstructed to a uniform grid before fitting%s (labels moved up ",
                             "to %.2g nm). Re-fitting on your observed coordinates gives the SAME component count ",
                             "(K = %d)%s, but a fitted band center moves by up to ",
                             "%.2g nm between the two readings -- at or above the %.2g nm table resolution. Treat the ",
                             "reported center positions as approximate to about that scale; supply finer ",
                             "coordinate precision to pin them down.%s"),
                      .stepnote, .disp, as.integer(.sens$k_recon), .same_pref, .cmove, .DECON_CENTER_MOVE_NM,
                      .raw_unavail_clause))
        } else if (.evald) {
          .ctr_stable_txt <- if (is.finite(.cmove))
            sprintf(", and the fitted centers moved below the %.2g nm table resolution,", .DECON_CENTER_MOVE_NM) else ","
          add(if (.coarse) "warn" else "info",
              tags$b("Wavelengths were reconstructed to a uniform grid. "),
              sprintf(paste0("Stored at coarser precision than their spacing%s, the labels were snapped onto a ",
                             "uniform grid before fitting (moved up to %.2g nm). Re-fitting on your observed ",
                             "coordinates gave the SAME component count (K = %d)%s so K is stable to this ",
                             "rounding here.%s%s"),
                      .stepnote, .disp, as.integer(.sens$k_recon), .ctr_stable_txt,
                      if (.coarse) " The grid is coarse; supply finer coordinate precision when you can." else "",
                      .raw_unavail_clause))
        } else {
          # Reconstruction happened but the sensitivity could NOT be measured (observed-axis fit returned no fit).
 # the catch maps ANY error to NULL, so use a cause-agnostic phrase, not "did not converge".
          add(if (.coarse) "warn" else "info",
              tags$b("Wavelengths were reconstructed to a uniform grid. "),
              sprintf(paste0("Stored at coarser precision than their spacing%s, the labels were snapped onto a ",
                             "uniform grid before fitting (moved up to %.2g nm). Whether the component count ",
                             "depends on that rounding could not be evaluated here (the fit on the observed ",
                             "coordinates could not be completed), so treat K as approximate; supply the ",
                             "wavelengths at finer coordinate precision when you can."),
                      .stepnote, .disp))
        }
      }
    }

    # ---- Rule 0: non-informative fit (R^2 <= 0) --------------------------
    # A best fit with R^2 <= 0 does no better than a flat line at the mean, so
    # the fitted band set carries no meaningful shape information. This happens
    # for blanks, apoprotein/negative controls, and near-flat or degenerate
    # curves. Flag it prominently so the component table is not read as a real
    # decomposition.
    if (is.finite(r2) && r2 <= 0) {
      add("warn",
        tags$b(sprintf("Non-informative fit (R² = %.3f ≤ 0). ", r2)),
        "The best model explains no more variance than a flat line at the mean, ",
        "so the fitted components are NOT a meaningful decomposition of this ",
        "spectrum — expected for a blank, an apoprotein / negative control, or a ",
        "near-flat or degenerate curve. Treat the band table as uninformative for ",
        "this sample.")
    }

    # ---- Rule 1: small / near-noise component -----------------------------
    # PRIMARY operational residual-scale heuristic: amplitude below
    # 3 x residual RMS. SECONDARY pragmatic
    # guideline (stated as such, NOT a hard rule): area fraction < 2%.
    amp_thresh <- 3 * rms
    for (i in seq_len(nrow(comp))) {
      amp_i  <- comp$amp[i]
      frac_i <- comp$area_frac[i]
      near_noise <- is.finite(amp_i) && is.finite(rms) && amp_i < amp_thresh
      tiny_area  <- is.finite(frac_i) && frac_i < 0.02
      if (near_noise || tiny_area) {
        flagged_small[i] <- TRUE
        reason <- if (near_noise && tiny_area) {
          sprintf("its amplitude (%.4g) is below 3 \u00d7 the residual RMS (3 \u00d7 %.4g = %.4g) AND its area fraction is %.1f%% (below the ~2%% pragmatic guideline)",
                  amp_i, rms, amp_thresh, 100 * frac_i)
        } else if (near_noise) {
          sprintf("its amplitude (%.4g) is below 3 \u00d7 the residual RMS (3 \u00d7 %.4g = %.4g), i.e. below this operational residual-scale threshold",
                  amp_i, rms, amp_thresh)
        } else {
          sprintf("its area fraction is %.1f%%, below the ~2%% pragmatic guideline (a soft guideline, not a hard rule)",
                  100 * frac_i)
        }
        add("warn",
          tags$b(sprintf("Component %d (%.1f nm): small / near-noise. ",
                         comp$component[i], comp$mu_nm[i])),
          sprintf("This component is flagged because %s. ", reason),
          "The 3\u00d7 residual-RMS and ~2% modeled-area checks are operational ",
          "heuristics, not validated detection or concentration limits; this ",
          "component may be mathematical rather than molecular.")
      }
    }

    # ---- Rule 2: large fractional uncertainty (SE/value > 25%) ------------
    for (i in seq_len(nrow(comp))) {
      fwhm_rel <- if (is.finite(comp$fwhm_se[i]) && is.finite(comp$fwhm[i]) &&
                      comp$fwhm[i] != 0) comp$fwhm_se[i] / abs(comp$fwhm[i]) else NA_real_
      amp_rel  <- if (is.finite(comp$amp_se[i]) && is.finite(comp$amp[i]) &&
                      comp$amp[i] != 0) comp$amp_se[i] / abs(comp$amp[i]) else NA_real_
      hits <- character(0)
      if (is.finite(fwhm_rel) && fwhm_rel > 0.25)
        hits <- c(hits, sprintf("FWHM (\u00b1%.0f%% of value)", 100 * fwhm_rel))
      if (is.finite(amp_rel) && amp_rel > 0.25)
        hits <- c(hits, sprintf("amplitude (\u00b1%.0f%% of value)", 100 * amp_rel))
      if (length(hits)) {
        add("warn",
          tags$b(sprintf("Component %d (%.1f nm): poorly constrained. ",
                         comp$component[i], comp$mu_nm[i])),
          sprintf("Large fractional uncertainty on %s exceeds the 25%% guideline; ",
                  paste(hits, collapse = " and ")),
          "this parameter is not well determined by the data and should be ",
          "treated with caution.")
      }
    }

    # ---- Rule 3: selected K at or one below k_max -------------------------
    if (isTRUE(is.finite(bestK)) && (bestK == kmax || bestK == kmax - 1L)) {
      add("warn",
        tags$b("Selected K is near the k_max ceiling. "),
        sprintf("The selected K = %d sits at%s the k_max ceiling of %d, so a score minimum ",
                bestK, if (bestK == kmax) "" else " one below", kmax),
        if (max(cmp$K) < kmax)
          "could not be assessed for every searched count: higher counts up to this ceiling did not produce usable fits. Review their convergence failures before widening the range."
        else "within a wider admissible search may occur at a higher K. Consider raising k_max and re-running as a search-bound sensitivity check.")
    }

    # ---- Rules 4 & 5: guard-adjusted AIC-like vs BIC-like selection --------
    # Compare the lowest score among criterion-specific admissible candidates,
    # while retaining each raw all-candidate argmin for disclosure. The shared
    # split/optimizer predicates apply to both criteria; finiteness is rebuilt
    # from the column being compared. With one K, agreement is vacuous.
    if (!is.null(cmp) && all(c("K","aic","bic") %in% names(cmp)) && nrow(cmp) >= 2) {
      ai <- .decon_ic_admissible_min_idx(cmp, "aic"); bi <- .decon_ic_admissible_min_idx(cmp, "bic")
      k_aic <- .decon_ic_admissible_K(cmp, "aic"); k_bic <- .decon_ic_admissible_K(cmp, "bic")
      raw_aic <- .decon_ic_argmin_K(cmp, "aic"); raw_bic <- .decon_ic_argmin_K(cmp, "bic")
      .raw_ab <- sprintf("Raw all-candidate minima: AIC-like -> K = %s; BIC-like -> K = %s. ",
                         .decon_fmt_K(raw_aic), .decon_fmt_K(raw_bic))
      .aicc_ctx <- if (identical(tolower(as.character(fit$criterion %||% "")), "aicc"))
        "The current result uses the AICc-like plug-in score; this AIC-like-versus-BIC-like comparison is a separate sensitivity view." else ""
      if (is.na(k_aic) || is.na(k_bic)) {
        add("warn",
          tags$b("Guard-adjusted AIC-like and BIC-like selections could not both be made. "),
          sprintf("AIC-like admissible -> K = %s; BIC-like admissible -> K = %s. %s%s",
                  .decon_fmt_K(k_aic), .decon_fmt_K(k_bic), .raw_ab, .aicc_ctx))
      } else if (identical(k_aic, k_bic)) {
        aic_at_aic <- cmp$aic[ai]; bic_at_bic <- cmp$bic[bi]
        add("ok",
          tags$b(sprintf("Guard-adjusted AIC-like and BIC-like selections agree on K = %d for this run. ", k_aic)),
          sprintf("Among admissible candidates, the AIC-like score is %.1f at its minimum and the BIC-like score is %.1f at its minimum. %sThis is conditional agreement under the current data, preprocessing, model family, search, bounds, optimizer, and admissibility rule—not evidence of a true component count or general robustness. %s",
                  aic_at_aic, bic_at_bic, .raw_ab, .aicc_ctx))
      } else {
        add("warn",
          tags$b("Guard-adjusted AIC-like and BIC-like selections differ. "),
          sprintf("AIC-like admissible -> K = %d; BIC-like admissible -> K = %d. %sTreat this as criterion sensitivity: inspect residuals and stability under justified preprocessing, bounds, seeds, and search limits, and report the difference rather than treating either score as decisive. %s",
                  k_aic, k_bic, .raw_ab, .aicc_ctx))
      }
    }

    for (i in seq_len(nrow(comp))) {
      mu_i <- comp$mu_nm[i]; w_i <- comp$fwhm[i]
      if (!is.finite(mu_i) || !is.finite(w_i)) next
      if (mu_i < edge_lo || mu_i > edge_hi) {
        which_edge <- if (mu_i < edge_lo) sprintf("%.0f nm lower", edge_lo) else sprintf("%.0f nm upper", edge_hi)
        dist_out   <- if (mu_i < edge_lo) edge_lo - mu_i else mu_i - edge_hi
        add("warn",
          tags$b(sprintf("Component %d (%.1f nm): center lies OUTSIDE the measured range. ",
                         comp$component[i], mu_i)),
          sprintf("It sits %.1f nm beyond the %s range edge, so the band apex was not observed and the fitted center is an extrapolation ",
                  dist_out, which_edge),
          "(the optimizer only constrains a center to its seed +/- the center tolerance). ",
          "Treat this center and its width as unresolved; widen the analysis range to capture the apex if the feature is real.")
        next
      }
      near_lo <- (mu_i - edge_lo) < w_i
      near_hi <- (edge_hi - mu_i) < w_i
      if (near_lo || near_hi) {
        which_edge <- if (near_lo) sprintf("%.0f nm lower", edge_lo) else sprintf("%.0f nm upper", edge_hi)
        dist <- if (near_lo) mu_i - edge_lo else edge_hi - mu_i
        add("warn",
          tags$b(sprintf("Component %d (%.1f nm): close to the %s range edge. ",
                         comp$component[i], mu_i, which_edge)),
          sprintf("Its center lies %.1f nm from the edge, within its own FWHM (%.1f nm), ",
                  dist, w_i),
          "so it may be absorbing residual baseline or edge slope rather than a stable interior modeled feature. Widen the analysis range if the numerical feature extends beyond it.")
      }
    }

    # ---- Rule 7: over-resolution caution (self-scaling) -------------------
    # Fires on a very high R^2 ONLY when rule #1 has already flagged at least
    # one component - the trigger scales with the spectrum, not a fixed K.
    if (is.finite(r2) && r2 > 0.999 && any(flagged_small)) {
      add("warn",
        tags$b("Possible over-resolution. "),
        sprintf("R\u00b2 = %.5f is very high, yet %d of the %d components were flagged as small / near-noise above. ",
                r2, sum(flagged_small), nrow(comp)),
        "An excellent fit can come from over-resolving noise into extra bands; ",
        "a high R\u00b2 does NOT prove the number of molecular species. Examine whether conclusions change across admissible lower-K alternatives, report that sensitivity, and require independent evidence for any physical band interpretation.")
    }

    # ---- Rule 8: heavily overlapping pair (closer than mean FWHM) ---------
    if (nrow(comp) >= 2) {
      ord <- order(comp$mu_nm)
      for (j in seq_len(length(ord) - 1L)) {
        a <- ord[j]; bb <- ord[j + 1L]
        mu_a <- comp$mu_nm[a]; mu_b <- comp$mu_nm[bb]
        w_a  <- comp$fwhm[a];  w_b  <- comp$fwhm[bb]
        if (!all(is.finite(c(mu_a, mu_b, w_a, w_b)))) next
        sep <- abs(mu_b - mu_a); mean_fwhm <- (w_a + w_b) / 2
        if (sep < mean_fwhm) {
          add("warn",
            tags$b(sprintf("Components %d (%.1f nm) and %d (%.1f nm) overlap heavily. ",
                           comp$component[a], mu_a, comp$component[bb], mu_b)),
            sprintf("Their separation (%.1f nm) is smaller than their mean FWHM (%.1f nm), ",
                    sep, mean_fwhm),
            "so their individual parameters may be strongly correlated. Report the combined modeled area as a less partition-sensitive descriptive quantity, not as validated truth.")
        }
      }
    }

    # ---- Empty state: positive confirmation when NO rule fired ------------
    if (!length(notes)) {
      # Absence of a programmed flag is not positive evidence of detection,
      # identifiability, physical reality, or calibrated uncertainty.
      ses_available <- any(is.finite(c(comp$amp_se, comp$mu_se, comp$fwhm_se)))
      add("ok",
        tags$b("No programmed interpretation flags. "),
        sprintf("All %d components exceeded the operational amplitude screen (each amplitude \u2265 3 \u00d7 residual RMSE = %.4g); this is not a detection limit or evidence of molecular identity",
                nrow(comp), amp_thresh),
        if (ses_available)
          "; no relative-SE rule fired, but the reported SEs are local, model-conditional approximations with uncalibrated coverage"
        else ". Standard errors were unavailable on the L-BFGS-B fallback, so per-parameter uncertainty was not evaluated",
        ". Absence of these flags is not evidence that the fit is identifiable or physically correct; read the residuals, sensitivity results, and permanent caveat below.")
    }

    if (!is.null(.guard_div)) notes <- c(list(.guard_div), notes)
    div(class = "decon-notes",
      div(class = "decon-notes-title",
          "Interpretation notes",
          .tip_icon("Result-specific notes generated by deterministic rules against THIS fit. Only conditions actually met are shown; numbers are read live from the current result. The same result always yields the same notes.")),
      notes)
  })

  output$decon_interpretation_notes <- renderUI({ decon_notes_ui() })

  # Plain-text version of the interpretation notes (one string per note) for the
  # PDF export and the Copy-Entire-Tab summary. Reads the SAME reactive.
  decon_notes_text <- reactive({
    ui <- decon_notes_ui()
    if (is.null(ui)) return(character(0))
    # The note divs are the children of the container's last child slot.
    note_divs <- ui$children[[2]]
    txts <- vapply(note_divs, function(nd) .decon_tags_to_text(nd), character(1))
    txts[nzchar(trimws(txts))]
  })

  # Plain-text status headline (mirrors output$decon_status, ASCII-safe) reused
  # by the PDF subtitle and the Copy-Entire-Tab summary so all three agree.
  decon_headline_text <- reactive({
    fit <- tryCatch(decon_fit(), error = function(e) NULL)
    if (is.null(fit) || inherits(fit, "decon_error")) return("")
    pres <- .decon_presentation(fit)
    if (is.null(fit$best)) return(pres$export_status_line)
    g <- fit$best$gof
    cmp <- fit$comparison
    .crit_summary_h <- .decon_ic_selection_summary(cmp)
    dual <- if (nzchar(.crit_summary_h)) paste0(" | ", .crit_summary_h) else ""
    .crit_lc_h  <- tolower(as.character(fit$criterion %||% "bic"))
    .crit_col_h <- suppressWarnings(as.numeric(cmp[[.crit_lc_h]]))
    .ic_unavail_h <- is.null(cmp) || !length(.crit_col_h) || !any(is.finite(.crit_col_h))
    .kic_h <- suppressWarnings(as.numeric(fit$best_K_ic))
    sel_phrase <- if (!identical(pres$display_role, "selected")) {
        .nadh <- .decon_no_adm_cause(fit)
        sprintf("No admissible component count (%s) -- %s", .nadh$raw_phrase, .nadh$detail)
      }
    else if (!.ic_unavail_h && length(.kic_h) == 1L && is.finite(.kic_h) && !is.na(pres$selected_K) && .kic_h != pres$selected_K)
      sprintf("Selected K = %d (lowest %s among admissible candidates; raw all-candidate minimum K = %d was not admissible: %s)",
              pres$selected_K, .decon_ic_display_name(fit$criterion), as.integer(.kic_h), .decon_ic_exclusion_phrase(fit))
    else if (.ic_unavail_h)
      sprintf("Diagnostic display K = %d (%s could not rank candidates; no criterion-based K selection)", pres$display_K, .decon_ic_display_name(fit$criterion))
    else sprintf("Selected K = %d (lowest %s among admissible candidates; %s)", pres$selected_K, .decon_ic_display_name(fit$criterion), .DECON_IC_LABEL)
    sprintf("%s | R-squared = %.4f | RMSE = %.4g | n = %d points%s%s",
            sel_phrase, g$r2, g$rmse, g$n_points, dual,
            if (is.finite(g$r2) && g$r2 <= 0) " | NON-INFORMATIVE (R-squared <= 0)" else "")
  })

  # Assemble the human-readable context that the tab shows above the results:
  # the "What this shows" paragraph, the exact input-provenance line, and the
  # Advanced-fit-settings values — so the Copy / PDF / ZIP exports are
  # self-documenting and a saved fit can be understood later. Returns a character
  # vector of plain-text lines (ASCII-safe, same wording as the on-screen tab).
  decon_context_text <- reactive({
    what <- paste0(
      "Optional, advanced resolution-enhancement of one processed spectrum into ",
      "overlapping pseudo-Voigt bands (derivative-seeded, reproducibly fit). Use it to ",
      "explore phenomenological band representations; the simpler default ",
      "metric remains Band AUC. Fits run on demand (the Run button) on processed analysis-curve ",
      "values at native measured wavelength coordinates, before display resampling and smoothing, ",
      "so display density and display smoothing do not enter component-count selection.")
    fit <- tryCatch(decon_fit(), error = function(e) NULL)
    rm  <- if (is.list(fit) && !inherits(fit, "decon_error")) fit$run_meta else NULL
    gvf <- function(x, d = "(unset)") { if (is.null(x) || !length(x) || (length(x)==1 && is.na(x))) d else as.character(x)[1] }
    if (!is.null(rm)) {
      base_on   <- isTRUE(rm$apply_baseline)
      norm_on   <- isTRUE(rm$norm_applied)
      norm_req  <- isTRUE(rm$norm_requested) || (isTruthy(rm$norm_method) && rm$norm_method != "none")
      prov_units <- paste0(
        "Fit on processed analysis-curve values at native measured wavelength coordinates ",
        if (base_on) "after baseline correction and dilution scaling, "
        else "after dilution scaling with baseline correction OFF, ",
        if (norm_on) "normalized. Fitted amplitudes/areas are in normalized units."
        else if (norm_req) sprintf("UN-NORMALIZED because normalization was not applied (%s); this state is retained for provenance and the fit is refused.", gvf(rm$norm_reason, "unrecorded"))
        else "un-normalized. Amplitudes/areas are in the curve's OD units.")
      settings <- c(
        "Advanced fit settings (as run):",
        sprintf("  Sample to fit:  %s", gvf(rm$sample, "(none)")),
        sprintf("  Sample class:   %s", gvf(rm$sample_class, "(default)")),
        sprintf("  k_min / k_max:  %s / %s", gvf(rm$kmin), gvf(rm$kmax)),
        sprintf("  Selection criterion:  %s (%s)", .decon_ic_display_name(gvf(rm$criterion, "bic")), .DECON_IC_LABEL),
        sprintf("  mu tolerance (nm):    %s", gvf(rm$mu_tol)),
        sprintf("  FWHM min / max (nm):  %s / %s", gvf(rm$fwhm_min), gvf(rm$fwhm_max)),
        sprintf("  Seeding window (nm):  %s", gvf(rm$seed_win)),
        sprintf("  Red-edge limit requested (nm): %s", gvf(rm$red_clip, "disabled")),
        if (is.list(rm$red_clip_effective)) c(
          sprintf("  Red-edge operation: %s; retained %d of %d finite input points; effective range %.8g to %.8g nm",
            rm$red_clip_effective$status, rm$red_clip_effective$retained_points,
            rm$red_clip_effective$finite_points, rm$red_clip_effective$effective_range_nm[1],
            rm$red_clip_effective$effective_range_nm[2]),
          sprintf("  Feasible K ceiling after clipping: %d", rm$red_clip_effective$effective_k_max))
        else "  Red-edge effective status: unavailable in this legacy result.",
        if (is.list(rm$blank_alignment)) c(
          sprintf("  Blank identity: %s", rm$blank_alignment$content_identity),
          sprintf("  Blank alignment: %d exact nodes; %d interpolated nodes; %s; gap limit %.8g nm",
            rm$blank_alignment$exact_nodes, rm$blank_alignment$interpolated_nodes,
            rm$blank_alignment$interpolation, rm$blank_alignment$coverage_gap_nm)),
        sprintf("  Native-fit normalization: requested=%s; applied=%s; reason=%s; divisor=%s",
                if (isTRUE(rm$norm_requested)) "yes" else "no",
                if (isTRUE(rm$norm_applied)) "yes" else "no",
                gvf(rm$norm_reason, "unrecorded"), gvf(rm$norm_divisor, "NA")),
        if (isTRUE(rm$scatter_on))
          (if (isTRUE(rm$blank_used))
             c(sprintf("  Measured-blank subtraction: ON  (direct subtraction; no inverse-power tail fit)"),
               sprintf("    equation applied:   dilution x measured - blank   (effective dilution for this sample = %s)",
                       gvf(rm$dilution_effective, "1")),
               "    blank basis:        ASSUMED to be undiluted-equivalent units; the input records no blank basis.",
               "                        If the blank was measured on the SAME acquisition scale as the diluted",
               "                        sample, the correct form is dilution x (measured - blank); these values",
               "                        then UNDER-subtract the blank and OVERESTIMATE absorbance by",
               "                        blank x (dilution - 1). At dilution 1 the two bases coincide.")
           else sprintf("  Empirical inverse-power baseline correction: ON  (tail fit %s - %s nm)",
                        gvf(rm$scatter_start, "730"), gvf(rm$scatter_end, "800")))
        else "  Local baseline pre-processing: OFF",
        { .bs <- as.character(rm$bootstrap_status %||% (if (isTRUE(rm$bootstrap)) "requested" else "not_requested"))
          if (identical(.bs, "ran")) "  K-selection bootstrap: ON (ran)"
          else if (isTRUE(rm$bootstrap))
            sprintf("  K-selection bootstrap: REQUESTED but NOT RUN - %s",
                    if (is.na(rm$bootstrap_skip_reason %||% NA_character_))
                      "the fit did not reach the resample stage" else rm$bootstrap_skip_reason)
          else "  K-selection bootstrap: OFF" })
      prov <- sprintf("Input fed to deconvolution: native-grid analysis-curve values for sample \"%s\".", gvf(rm$sample, "(none)"))
    } else {
      prov_units <- "No fit has been run yet; press Run to fit the selected sample."
      settings <- c("Advanced fit settings: (no fit run yet)")
      prov <- "Input fed to deconvolution: (pending Run)."
    }
    c("What this shows:", what, "",
      prov, prov_units, "",
      settings)
  })

  # Assemble the complete deconvolution export text (context plus results), shared
  # by the Copy-Entire-Tab clipboard AND the Download-everything ZIP so they never
  # diverge. Returns "" when there is no valid fit.
  decon_export_text <- reactive({
    fit <- tryCatch(decon_fit(), error = function(e) NULL)
    if (is.null(fit) || inherits(fit, "decon_error")) return("")
    df_to_tsv <- function(df) paste(
      paste(names(df), collapse = "\t"),
      paste(.pasa_tsv_rows(df), collapse = "\n"),
      sep = "\n")
    pres    <- .decon_presentation(fit)
    cmp_df  <- .decon_comparison_df(fit, include_legacy_fields = TRUE)
    comp_df <- if (is.null(fit$best)) NULL
               else .decon_components_df(decon_labeled()$components, nm_measured = fit$best$nm)   # Lens A: flag out-of-range centers
    notes   <- decon_notes_text()
    scat_block <- if (!is.null(fit$scatter)) {
      s <- fit$scatter
      if (identical(s$method, "measured_blank"))
        c("", "Measured-blank subtraction (direct; offset baseline bypassed)",
          sprintf("method = measured_blank\tcoverage = %d/%d wavelengths finite\t%s",
                  sum(is.finite(s$scattering)), length(s$scattering), s$interpretation),
          local({
            .de <- suppressWarnings(as.numeric((fit$run_meta$dilution_effective %||% NA_real_)[1]))
            if (!length(.de) || !is.finite(.de)) .de <- NA_real_
            sprintf("blank basis (ASSUMED, not recorded in the input): equation applied = dilution x measured - blank%s",
                    if (is.finite(.de) && .de > 1) sprintf(" (effective dilution for this sample = %s)", format(.de))
                    else if (is.finite(.de)) " (dilution = 1; the two bases coincide)"
                    else " (dilution unavailable in the run snapshot)")
          }),
          paste0("blank basis assumption: the uploaded blank is already in UNDILUTED-EQUIVALENT units. ",
                 "If it was instead measured on the SAME acquisition scale as the diluted sample, the ",
                 "physically consistent correction is dilution x (measured - blank), and these values ",
                 "UNDER-subtract the blank and OVERESTIMATE absorbance by blank x (dilution - 1). ",
                 "The app cannot infer which basis applies; record it with your results."))
      else if (isTRUE(s$fit_ok))
        c("", "Empirical inverse-power baseline correction (offset baseline bypassed)",
          sprintf("b = %.3f\ta = %.4g\tc = %.4g\ttail = %.0f-%.0f nm (%d pts)\t%s",
                  s$b, s$a, s$c, s$fit_start, s$fit_end, s$n_tail, s$interpretation))
      else
        c("", "Empirical inverse-power baseline fit (FELL BACK to flat-median offset)",
          sprintf("c = %.4g\ttail = %.0f-%.0f nm (%d pts)\t%s",
                  s$c, s$fit_start, s$fit_end, s$n_tail, s$interpretation))
    } else character(0)
    boot_block <- c("", .decon_bootstrap_text(fit))
    .boot_summary <- .decon_bootstrap_summary_df(fit)
    .boot_draws <- .decon_bootstrap_draws_df(fit)
    if (!is.null(.boot_summary)) boot_block <- c(boot_block, "", "Bootstrap counts and denominators", df_to_tsv(.boot_summary))
    if (!is.null(.boot_draws)) boot_block <- c(boot_block, "", "Every requested bootstrap draw", df_to_tsv(.boot_draws))
    paste(
      c(tryCatch(decon_context_text(), error = function(e) character(0)),
        "",
        "====================================================================",
        "",
        decon_headline_text(),
        "",
        "Selection status (machine-readable)",
        paste0("presentation_schema\t", pres$schema_version),
        paste0("selection_status\t",    pres$selection_status),
        paste0("display_role\t",        pres$display_role),
        paste0("raw_best_K\t",    if (is.na(pres$raw_best_K)) "NA" else as.character(pres$raw_best_K)),
        paste0("selected_K\t",    if (is.na(pres$selected_K)) "NA" else as.character(pres$selected_K)),
        paste0("display_K\t",     if (is.na(pres$display_K))  "NA" else as.character(pres$display_K)),
        scat_block,
        boot_block,
        "",
        "K-selection comparison",
        df_to_tsv(cmp_df),
        "",
        pres$export_status_line,
        "",
        pres$component_title,
        if (is.null(comp_df)) pres$display_note else df_to_tsv(comp_df),
        "",
        "Interpretation notes",
        if (length(notes)) paste(paste0("- ", notes), collapse = "\n") else "(none)",
        "",
        tryCatch(.release_identity_lines(), error = function(e)
          c(PASA_IDENTITY_BLOCK_HEADER,
            paste0("  - Release identity: UNAVAILABLE - ", conditionMessage(e))))),
      collapse = "\n")
  })

 # --- : Download the entire deconvolution result as a multi-page PDF ---
  # Reuses the ONE shared .decon_render_pdf() so the file never diverges from the
  # on-screen plots/tables/notes. Guarded against the error result.
  output$decon_dl_pdf <- downloadHandler(
    filename = function() paste0("PASA_decon_", ts(), ".pdf"),
    content  = function(file) {
      tryCatch({
        fit <- decon_fit()
        if (inherits(fit, "decon_error")) stop(fit$error %||% "No usable deconvolution fit is available.")
        .decon_render_pdf(file, fit, decon_labeled(),
                          headline = decon_headline_text(),
                          criterion = if (isTruthy(input$decon_criterion)) input$decon_criterion else "aic",
                          notes_text = decon_notes_text(),
                          context_text = tryCatch(decon_context_text(), error = function(e) character(0)))
      }, error = function(e) {
        grDevices::pdf(file, width = 11, height = 8.5)
        grid::grid.newpage()
        grid::grid.text(paste("PDF error:", conditionMessage(e)), x = 0.5, y = 0.5)
        grDevices::dev.off()
      })
    }
  )

 # --- : Copy Entire Tab -> populate hidden textarea with a text summary.
  # Built from the SAME ASCII-safe data.frames the PDF uses, so the clipboard
  # text and the PDF never disagree. The JS in the button reads decon_tsv_data.
  observe({
    # Single source of truth for the tab's export text (context plus results).
    session$sendCustomMessage("update_decon_tsv",
                              list(value = tryCatch(decon_export_text(), error = function(e) "")))
  })

  output$decon_copy_notify <- renderUI({
    status <- input$decon_copy_status
    if (is.null(status)) return(NULL)
    if (status == "ok") {
      div(class = "alert alert-success", style = "padding:4px 10px;font-size:0.85em;margin:4px 0;",
          "\u2713 Tab summary copied to clipboard as tab-separated text. Paste into Excel or similar.")
    } else {
      div(class = "alert alert-warning", style = "padding:4px 10px;font-size:0.85em;margin:4px 0;",
          "\u26a0 Could not copy automatically. Use Download as PDF instead, or select the text manually.")
    }
  })


  # Keep only dynamic control surfaces active while their tab or settings region is
  # hidden. Analysis tables and plots use Shiny's normal on-demand suspension;
  # forcing every tab to recompute after a session restore needlessly queues
  # Metrics, AUC, color, QC, peaks, and Summary work in the single R session.
  for (.oid in c("controls_ui", "samples_ui", "sample_type_ui", "norm_band_ui",
                 "per_sample_dilution_ui", "band3_label", "band3_slider_ui",
                 "qy_slider_ui", "chlb_qy_slider_ui", "pe_slider_ui",
                 "growth_gate_banner", "growth_body", "growth_manual_grid", "growth_rep_mapping",
                 "copy_metrics_notify")) {
    outputOptions(output, .oid, suspendWhenHidden = FALSE)
  }
  outputOptions(output, "sim_auth_ack", suspendWhenHidden = FALSE)

}

shinyApp(ui, server)
